{"sha": "5a9c9bc71553d37a17b89654bec0b6e98b5679b9", "filename": "src/core/network-openssl.c", "status": "modified", "additions": 152, "deletions": 5, "changes": 157, "blob_url": "https://github.com/ensc/irssi-proxy/blob/85bbc05b21678e80423815d2ef1dfe26208491ab/src/core/network-openssl.c", "raw_url": "https://github.com/ensc/irssi-proxy/raw/85bbc05b21678e80423815d2ef1dfe26208491ab/src/core/network-openssl.c", "contents_url": "https://api.github.com/repos/ensc/irssi-proxy/contents/src/core/network-openssl.c?ref=85bbc05b21678e80423815d2ef1dfe26208491ab", "patch": "@@ -26,6 +26,7 @@

 #include <openssl/crypto.h>
 #include <openssl/x509.h>
+#include <openssl/x509v3.h>
 #include <openssl/pem.h>
 #include <openssl/ssl.h>
 #include <openssl/err.h>
@@ -39,6 +40,7 @@ typedef struct
