 }"}<_**next**_>{"sha": "8583724c99c1210ab22de05fecf10df355c6a4bf", "filename": "src/core/network.h", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/ensc/irssi-proxy/blob/85bbc05b21678e80423815d2ef1dfe26208491ab/src/core/network.h", "raw_url": "https://github.com/ensc/irssi-proxy/raw/85bbc05b21678e80423815d2ef1dfe26208491ab/src/core/network.h", "contents_url": "https://api.github.com/repos/ensc/irssi-proxy/contents/src/core/network.h?ref=85bbc05b21678e80423815d2ef1dfe26208491ab", "patch": "@@ -47,7 +47,7 @@ int net_ip_compare(IPADDR *ip1, IPADDR *ip2);
