{"sha": "64cfef1b0a4c556ccf63c2f912c86ec3a1599b82", "filename": "net/ipv6/reassembly.c", "status": "modified", "additions": 15, "deletions": 56, "changes": 71, "blob_url": "https://github.com/torvalds/linux/blob/70789d7052239992824628db8133de08dc78e593/net/ipv6/reassembly.c", "raw_url": "https://github.com/torvalds/linux/raw/70789d7052239992824628db8133de08dc78e593/net/ipv6/reassembly.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/ipv6/reassembly.c?ref=70789d7052239992824628db8133de08dc78e593", "patch": "@@ -149,13 +149,6 @@ int ip6_frag_match(struct inet_frag_queue *q, void *a)
 }
