{"sha": "96f77013d3f038ea03b688c448e2ef69a77aee06", "filename": "kernel/tsacct.c", "status": "modified", "additions": 7, "deletions": 3, "changes": 10, "blob_url": "https://github.com/torvalds/linux/blob/f0ec1aaf54caddd21c259aea8b2ecfbde4ee4fb9/kernel/tsacct.c", "raw_url": "https://github.com/torvalds/linux/raw/f0ec1aaf54caddd21c259aea8b2ecfbde4ee4fb9/kernel/tsacct.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/tsacct.c?ref=f0ec1aaf54caddd21c259aea8b2ecfbde4ee4fb9", "patch": "@@ -80,13 +80,17 @@ void bacct_add_tsk(struct taskstats *stats, struct task_struct *tsk)
  */
 void xacct_add_tsk(struct taskstats *stats, struct task_struct *p)
 {
+	struct mm_struct *mm;
+
 	/* convert pages-jiffies to Mbyte-usec */
 	stats->coremem = jiffies_to_usecs(p->acct_rss_mem1) * PAGE_SIZE / MB;
 	stats->virtmem = jiffies_to_usecs(p->acct_vm_mem1) * PAGE_SIZE / MB;
-	if (p->mm) {
+	mm = get_task_mm(p);
+	if (mm) {
 		/* adjust to KB unit */
