{"sha": "e7e8fa915a8ede594548012dd6de92bddbc29ab5", "filename": "taglib/ogg/xiphcomment.cpp", "status": "modified", "additions": 13, "deletions": 3, "changes": 16, "blob_url": "https://github.com/taglib/taglib/blob/b3646a07348ffa276ea41a9dae03ddc63ea6c532/taglib/ogg/xiphcomment.cpp", "raw_url": "https://github.com/taglib/taglib/raw/b3646a07348ffa276ea41a9dae03ddc63ea6c532/taglib/ogg/xiphcomment.cpp", "contents_url": "https://api.github.com/repos/taglib/taglib/contents/taglib/ogg/xiphcomment.cpp?ref=b3646a07348ffa276ea41a9dae03ddc63ea6c532", "patch": "@@ -295,21 +295,31 @@ void Ogg::XiphComment::parse(const ByteVector &data)

   // Next the number of fields in the comment vector.

-  int commentFields = data.mid(pos, 4).toUInt(false);
+  uint commentFields = data.mid(pos, 4).toUInt(false);
   pos += 4;

-  for(int i = 0; i < commentFields; i++) {
+  if(commentFields > (data.size() - 8) / 4) {
+    return;
+  }
+
+  for(uint i = 0; i < commentFields; i++) {

     // Each comment field is in the format "KEY=value" in a UTF8 string and has
     // 4 bytes before the text starts that gives the length.

-    int commentLength = data.mid(pos, 4).toUInt(false);
+    uint commentLength = data.mid(pos, 4).toUInt(false);
     pos += 4;

     String comment = String(data.mid(pos, commentLength), String::UTF8);
     pos += commentLength;
+    if(pos > data.size()) {
+      break;
+    }

     int commentSeparatorPosition = comment.find("=");
+    if(commentSeparatorPosition == -1) {
+      break;
+    }

     String key = comment.substr(0, commentSeparatorPosition);
     String value = comment.substr(commentSeparatorPosition + 1);"}

