{"sha": "01865c6fb6a0c4739a18a5f4b746a5b8da038680", "filename": "kernel/sys.c", "status": "modified", "additions": 7, "deletions": 5, "changes": 12, "blob_url": "https://github.com/torvalds/linux/blob/2702b1526c7278c4d65d78de209a465d4de2885e/kernel/sys.c", "raw_url": "https://github.com/torvalds/linux/raw/2702b1526c7278c4d65d78de209a465d4de2885e/kernel/sys.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/sys.c?ref=2702b1526c7278c4d65d78de209a465d4de2885e", "patch": "@@ -1265,15 +1265,16 @@ DECLARE_RWSEM(uts_sem);
