{"sha": "7626fa78e1f8b254cf5cf87d84829da728c1704b", "filename": "arch/powerpc/include/asm/reg.h", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/torvalds/linux/blob/0837e3242c73566fc1c0196b4ec61779c25ffc93/arch/powerpc/include/asm/reg.h", "raw_url": "https://github.com/torvalds/linux/raw/0837e3242c73566fc1c0196b4ec61779c25ffc93/arch/powerpc/include/asm/reg.h", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/powerpc/include/asm/reg.h?ref=0837e3242c73566fc1c0196b4ec61779c25ffc93", "patch": "@@ -880,6 +880,7 @@
 #define PV_970		0x0039
 #define PV_POWER5	0x003A
 #define PV_POWER5p	0x003B
+#define PV_POWER7	0x003F
 #define PV_970FX	0x003C
 #define PV_630		0x0040
 #define PV_630p	0x0041"}<_**next**_>{"sha": "97e0ae414940ee30c6a0a297f9c15dd53b5a0470", "filename": "arch/powerpc/kernel/perf_event.c", "status": "modified", "additions": 23, "deletions": 1, "changes": 24, "blob_url": "https://github.com/torvalds/linux/blob/0837e3242c73566fc1c0196b4ec61779c25ffc93/arch/powerpc/kernel/perf_event.c", "raw_url": "https://github.com/torvalds/linux/raw/0837e3242c73566fc1c0196b4ec61779c25ffc93/arch/powerpc/kernel/perf_event.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/powerpc/kernel/perf_event.c?ref=0837e3242c73566fc1c0196b4ec61779c25ffc93", "patch": "@@ -1269,6 +1269,28 @@ unsigned long perf_instruction_pointer(struct pt_regs *regs)
 	return ip;
 }

+static bool pmc_overflow(unsigned long val)
+{
+	if ((int)val < 0)
+		return true;
+
+	/*
+	 * Events on POWER7 can roll back if a speculative event doesn't
+	 * eventually complete. Unfortunately in some rare cases they will
+	 * raise a performance monitor exception. We need to catch this to
+	 * ensure we reset the PMC. In all cases the PMC will be 256 or less
+	 * cycles from overflow.
+	 *
+	 * We only do this if the first pass fails to find any overflowing
+	 * PMCs because a user might set a period of less than 256 and we
+	 * don't want to mistakenly reset them.
+	 */
+	if (__is_processor(PV_POWER7) && ((0x80000000 - val) <= 256))
+		return true;
+
+	return false;
+}
+
 /*
  * Performance monitor interrupt stuff
  */
@@ -1316,7 +1338,7 @@ static void perf_event_interrupt(struct pt_regs *regs)
 			if (is_limited_pmc(i + 1))
 				continue;
 			val = read_pmc(i + 1);
-			if ((int)val < 0)
+			if (pmc_overflow(val))
 				write_pmc(i + 1, 0);
 		}
 	}"}

