{"sha": "7835b8fc94db6d69b9e93c1806d677e8ea390736", "filename": "crypto/ghash-generic.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/torvalds/linux/blob/7ed47b7d142ec99ad6880bbbec51e9f12b3af74c/crypto/ghash-generic.c", "raw_url": "https://github.com/torvalds/linux/raw/7ed47b7d142ec99ad6880bbbec51e9f12b3af74c/crypto/ghash-generic.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/crypto/ghash-generic.c?ref=7ed47b7d142ec99ad6880bbbec51e9f12b3af74c", "patch": "@@ -67,6 +67,9 @@ static int ghash_update(struct shash_desc *desc,
 	struct ghash_ctx *ctx = crypto_shash_ctx(desc->tfm);
 	u8 *dst = dctx->buffer;

+	if (!ctx->gf128)
+		return -ENOKEY;
+
 	if (dctx->bytes) {
 		int n = min(srclen, dctx->bytes);
 		u8 *pos = dst + (GHASH_BLOCK_SIZE - dctx->bytes);
@@ -119,6 +122,9 @@ static int ghash_final(struct shash_desc *desc, u8 *dst)
 	struct ghash_ctx *ctx = crypto_shash_ctx(desc->tfm);
 	u8 *buf = dctx->buffer;

+	if (!ctx->gf128)
+		return -ENOKEY;
+
 	ghash_flush(ctx, dctx);
 	memcpy(dst, buf, GHASH_BLOCK_SIZE);
 "}

{"sha": "c0bb32414b174d575f836c9eb779f2e30cb793dd", "filename": "kernel/sysctl.c", "status": "modified", "additions": 17, "deletions": 1, "changes": 18, "blob_url": "https://github.com/torvalds/linux/blob/bfdc0b497faa82a0ba2f9dddcf109231dd519fcc/kernel/sysctl.c", "raw_url": "https://github.com/torvalds/linux/raw/bfdc0b497faa82a0ba2f9dddcf109231dd519fcc/kernel/sysctl.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/sysctl.c?ref=bfdc0b497faa82a0ba2f9dddcf109231dd519fcc", "patch": "@@ -170,6 +170,11 @@ static int proc_taint(struct ctl_table *table, int write,
 			       void __user *buffer, size_t *lenp, loff_t *ppos);
 #endif

+#ifdef CONFIG_PRINTK
+static int proc_dmesg_restrict(struct ctl_table *table, int write,
+				void __user *buffer, size_t *lenp, loff_t *ppos);
+#endif
+
 #ifdef CONFIG_MAGIC_SYSRQ
 /* Note: sysrq code uses it's own private copy */
 static int __sysrq_enabled = SYSRQ_DEFAULT_ENABLE;
@@ -707,7 +712,7 @@ static struct ctl_table kern_table[] = {
 		.data		= &kptr_restrict,
 		.maxlen		= sizeof(int),
 		.mode		= 0644,
