{"sha": "5f55373dd53bac20ec24554144fb81dd18e1d64d", "filename": "Documentation/acpi/method-customizing.txt", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/torvalds/linux/blob/526b4af47f44148c9d665e57723ed9f86634c6e3/Documentation/acpi/method-customizing.txt", "raw_url": "https://github.com/torvalds/linux/raw/526b4af47f44148c9d665e57723ed9f86634c6e3/Documentation/acpi/method-customizing.txt", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/Documentation/acpi/method-customizing.txt?ref=526b4af47f44148c9d665e57723ed9f86634c6e3", "patch": "@@ -66,3 +66,8 @@ Note: We can use a kernel with multiple custom ACPI method running,
       But each individual write to debugfs can implement a SINGLE
       method override. i.e. if we want to insert/override multiple
       ACPI methods, we need to redo step c) ~ g) for multiple times.
+
+Note: Be aware that root can mis-use this driver to modify arbitrary
+      memory and gain additional rights, if root's privileges got
+      restricted (for example if root is not allowed to load additional
+      modules after boot)."}<_**next**_>{"sha": "d918e130bef37340fe07813878e556b6176a610f", "filename": "drivers/acpi/Kconfig", "status": "modified", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/torvalds/linux/blob/526b4af47f44148c9d665e57723ed9f86634c6e3/drivers/acpi/Kconfig", "raw_url": "https://github.com/torvalds/linux/raw/526b4af47f44148c9d665e57723ed9f86634c6e3/drivers/acpi/Kconfig", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/acpi/Kconfig?ref=526b4af47f44148c9d665e57723ed9f86634c6e3", "patch": "@@ -380,6 +380,21 @@ config ACPI_HED
 	  which is used to report some hardware errors notified via
 	  SCI, mainly the corrected errors.

+config ACPI_CUSTOM_METHOD
+	tristate "Allow ACPI methods to be inserted/replaced at run time"
+	depends on DEBUG_FS
+	default n
+	help
+	  This debug facility allows ACPI AML methods to me inserted and/or
+	  replaced without rebooting the system. For details refer to:
+	  Documentation/acpi/method-customizing.txt.
+
+	  NOTE: This option is security sensitive, because it allows arbitrary
+	  kernel memory to be written to by root (uid=0) users, allowing them
+	  to bypass certain security measures (e.g. if root is not allowed to
+	  load additional kernel modules after boot, this feature may be used
+	  to override that restriction).
+
 source "drivers/acpi/apei/Kconfig"

 endif	# ACPI"}<_**next**_>{"sha": "cba0b2334b9b83cc653a3670199d4de64557c659", "filename": "drivers/acpi/Makefile", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/torvalds/linux/blob/526b4af47f44148c9d665e57723ed9f86634c6e3/drivers/acpi/Makefile", "raw_url": "https://github.com/torvalds/linux/raw/526b4af47f44148c9d665e57723ed9f86634c6e3/drivers/acpi/Makefile", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/acpi/Makefile?ref=526b4af47f44148c9d665e57723ed9f86634c6e3", "patch": "@@ -62,6 +62,7 @@ obj-$(CONFIG_ACPI_SBS)		+= sbs.o
