{"sha": "0bdf21c6814ef8118be3ae56196b85f11b7b3ac2", "filename": "ipc/shm.c", "status": "modified", "additions": 23, "deletions": 5, "changes": 28, "blob_url": "https://github.com/torvalds/linux/blob/a399b29dfbaaaf91162b2dc5a5875dd51bbfa2a1/ipc/shm.c", "raw_url": "https://github.com/torvalds/linux/raw/a399b29dfbaaaf91162b2dc5a5875dd51bbfa2a1/ipc/shm.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/ipc/shm.c?ref=a399b29dfbaaaf91162b2dc5a5875dd51bbfa2a1", "patch": "@@ -208,15 +208,18 @@ static void shm_open(struct vm_area_struct *vma)
