 }

@@ -983,6 +986,13 @@ SYSCALL_DEFINE3(shmctl, int, shmid, int, cmd, struct shmid_ds __user *, buf)
 		}

 		shm_file = shp->shm_file;
+
+		/* check if shm_destroy() is tearing down shp */
