{"sha": "2d2b1b7588d7e476b7fc814a63c82bad2edb1ed6", "filename": "drivers/md/dm-snap-persistent.c", "status": "modified", "additions": 12, "deletions": 6, "changes": 18, "blob_url": "https://github.com/torvalds/linux/blob/e9c6a182649f4259db704ae15a91ac820e63b0ca/drivers/md/dm-snap-persistent.c", "raw_url": "https://github.com/torvalds/linux/raw/e9c6a182649f4259db704ae15a91ac820e63b0ca/drivers/md/dm-snap-persistent.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/md/dm-snap-persistent.c?ref=e9c6a182649f4259db704ae15a91ac820e63b0ca", "patch": "@@ -269,6 +269,14 @@ static chunk_t area_location(struct pstore *ps, chunk_t area)
 	return NUM_SNAPSHOT_HDR_CHUNKS + ((ps->exceptions_per_area + 1) * area);
 }

+static void skip_metadata(struct pstore *ps)
+{
+	uint32_t stride = ps->exceptions_per_area + 1;
+	chunk_t next_free = ps->next_free;
+	if (sector_div(next_free, stride) == NUM_SNAPSHOT_HDR_CHUNKS)
+		ps->next_free++;
+}
+
 /*
  * Read or write a metadata area.  Remembering to skip the first
  * chunk which holds the header.
@@ -502,6 +510,8 @@ static int read_exceptions(struct pstore *ps,

 	ps->current_area--;

+	skip_metadata(ps);
+
 	return 0;
 }

@@ -616,8 +626,6 @@ static int persistent_prepare_exception(struct dm_exception_store *store,
 					struct dm_exception *e)
 {
 	struct pstore *ps = get_info(store);
-	uint32_t stride;
-	chunk_t next_free;
 	sector_t size = get_dev_size(dm_snap_cow(store->snap)->bdev);

 	/* Is there enough room ? */
@@ -630,10 +638,8 @@ static int persistent_prepare_exception(struct dm_exception_store *store,
 	 * Move onto the next free pending, making sure to take
 	 * into account the location of the metadata chunks.
 	 */
-	stride = (ps->exceptions_per_area + 1);
-	next_free = ++ps->next_free;
-	if (sector_div(next_free, stride) == 1)
-		ps->next_free++;
+	ps->next_free++;
+	skip_metadata(ps);

 	atomic_inc(&ps->pending_count);
 	return 0;"}

{"sha": "e7000be321b0148469264524ed6fce75c3952955", "filename": "net/sysctl_net.c", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/torvalds/linux/blob/2433c8f094a008895e66f25bd1773cdb01c91d01/net/sysctl_net.c", "raw_url": "https://github.com/torvalds/linux/raw/2433c8f094a008895e66f25bd1773cdb01c91d01/net/sysctl_net.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/sysctl_net.c?ref=2433c8f094a008895e66f25bd1773cdb01c91d01", "patch": "@@ -47,12 +47,12 @@ static int net_ctl_permissions(struct ctl_table_header *head,

