{"sha": "f30852d28590358c6780a22c14049f92a124bdb8", "filename": "arch/arm64/kernel/traps.c", "status": "modified", "additions": 9, "deletions": 3, "changes": 12, "blob_url": "https://github.com/torvalds/linux/blob/9955ac47f4ba1c95ecb6092aeaefb40a22e99268/arch/arm64/kernel/traps.c", "raw_url": "https://github.com/torvalds/linux/raw/9955ac47f4ba1c95ecb6092aeaefb40a22e99268/arch/arm64/kernel/traps.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/arm64/kernel/traps.c?ref=9955ac47f4ba1c95ecb6092aeaefb40a22e99268", "patch": "@@ -311,14 +311,20 @@ asmlinkage long do_ni_syscall(struct pt_regs *regs)
