{"sha": "122d056d96d570c2d59762fda22e0e973ac081b5", "filename": "drivers/usb/class/cdc-wdm.c", "status": "modified", "additions": 20, "deletions": 3, "changes": 23, "blob_url": "https://github.com/torvalds/linux/blob/c0f5ecee4e741667b2493c742b60b6218d40b3aa/drivers/usb/class/cdc-wdm.c", "raw_url": "https://github.com/torvalds/linux/raw/c0f5ecee4e741667b2493c742b60b6218d40b3aa/drivers/usb/class/cdc-wdm.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/usb/class/cdc-wdm.c?ref=c0f5ecee4e741667b2493c742b60b6218d40b3aa", "patch": "@@ -56,6 +56,7 @@ MODULE_DEVICE_TABLE (usb, wdm_ids);
 #define WDM_RESPONDING		7
 #define WDM_SUSPENDING		8
 #define WDM_RESETTING		9
+#define WDM_OVERFLOW		10

 #define WDM_MAX			16

@@ -155,6 +156,7 @@ static void wdm_in_callback(struct urb *urb)
 {
 	struct wdm_device *desc = urb->context;
 	int status = urb->status;
+	int length = urb->actual_length;

 	spin_lock(&desc->iuspin);
 	clear_bit(WDM_RESPONDING, &desc->flags);
@@ -185,9 +187,17 @@ static void wdm_in_callback(struct urb *urb)
 	}

 	desc->rerr = status;
-	desc->reslength = urb->actual_length;
