  out_put_task_struct:
 	put_task_struct(child);"}<_**next**_>{"sha": "3d09cf6cde756671655c96f2f81a43438eb62b7e", "filename": "kernel/signal.c", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/torvalds/linux/blob/9899d11f654474d2d54ea52ceaa2a1f4db3abd68/kernel/signal.c", "raw_url": "https://github.com/torvalds/linux/raw/9899d11f654474d2d54ea52ceaa2a1f4db3abd68/kernel/signal.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/signal.c?ref=9899d11f654474d2d54ea52ceaa2a1f4db3abd68", "patch": "@@ -1794,6 +1794,10 @@ static inline int may_ptrace_stop(void)
