{"sha": "667c1d4ca9847c627127dc633e19c7c94f354188", "filename": "net/ipv4/cipso_ipv4.c", "status": "modified", "additions": 4, "deletions": 2, "changes": 6, "blob_url": "https://github.com/torvalds/linux/blob/89d7ae34cdda4195809a5a987f697a517a2a3177/net/ipv4/cipso_ipv4.c", "raw_url": "https://github.com/torvalds/linux/raw/89d7ae34cdda4195809a5a987f697a517a2a3177/net/ipv4/cipso_ipv4.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/ipv4/cipso_ipv4.c?ref=89d7ae34cdda4195809a5a987f697a517a2a3177", "patch": "@@ -1725,8 +1725,10 @@ int cipso_v4_validate(const struct sk_buff *skb, unsigned char **option)
 		case CIPSO_V4_TAG_LOCAL:
 			/* This is a non-standard tag that we only allow for
 			 * local connections, so if the incoming interface is
-			 * not the loopback device drop the packet. */
-			if (!(skb->dev->flags & IFF_LOOPBACK)) {
+			 * not the loopback device drop the packet. Further,
+			 * there is no legitimate reason for setting this from
+			 * userspace so reject it if skb is NULL. */
+			if (skb == NULL || !(skb->dev->flags & IFF_LOOPBACK)) {
 				err_offset = opt_iter;
 				goto validate_return_locked;
 			}"}

