{"sha": "2e4a8646dbc389dcb55fcce1cf6b3ad0f608af0d", "filename": "net/sctp/input.c", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/torvalds/linux/blob/ae53b5bd77719fed58086c5be60ce4f22bffe1c6/net/sctp/input.c", "raw_url": "https://github.com/torvalds/linux/raw/ae53b5bd77719fed58086c5be60ce4f22bffe1c6/net/sctp/input.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/sctp/input.c?ref=ae53b5bd77719fed58086c5be60ce4f22bffe1c6", "patch": "@@ -249,6 +249,19 @@ int sctp_rcv(struct sk_buff *skb)
 	 */
 	sctp_bh_lock_sock(sk);

+	if (sk != rcvr->sk) {
+		/* Our cached sk is different from the rcvr->sk.  This is
+		 * because migrate()/accept() may have moved the association
+		 * to a new socket and released all the sockets.  So now we
+		 * are holding a lock on the old socket while the user may
+		 * be doing something with the new socket.  Switch our veiw
+		 * of the current sk.
+		 */
+		sctp_bh_unlock_sock(sk);
+		sk = rcvr->sk;
+		sctp_bh_lock_sock(sk);
+	}
+
 	if (sock_owned_by_user(sk)) {
 		SCTP_INC_STATS_BH(SCTP_MIB_IN_PKT_BACKLOG);
 		sctp_add_backlog(sk, skb);"}

