{"sha": "31751868de8856cbe4ee909ef09915e6a9a9c679", "filename": "kernel/signal.c", "status": "modified", "additions": 12, "deletions": 4, "changes": 16, "blob_url": "https://github.com/torvalds/linux/blob/da48524eb20662618854bb3df2db01fc65f3070c/kernel/signal.c", "raw_url": "https://github.com/torvalds/linux/raw/da48524eb20662618854bb3df2db01fc65f3070c/kernel/signal.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/signal.c?ref=da48524eb20662618854bb3df2db01fc65f3070c", "patch": "@@ -2421,9 +2421,13 @@ SYSCALL_DEFINE3(rt_sigqueueinfo, pid_t, pid, int, sig,
 		return -EFAULT;

 	/* Not even root can pretend to send signals from the kernel.
-	   Nor can they impersonate a kill(), which adds source info.  */
-	if (info.si_code >= 0)
+	 * Nor can they impersonate a kill()/tgkill(), which adds source info.
+	 */
+	if (info.si_code != SI_QUEUE) {
+		/* We used to allow any < 0 si_code */
+		WARN_ON_ONCE(info.si_code < 0);
 		return -EPERM;
+	}
 	info.si_signo = sig;

 	/* POSIX.1b doesn't mention process groups.  */
@@ -2437,9 +2441,13 @@ long do_rt_tgsigqueueinfo(pid_t tgid, pid_t pid, int sig, siginfo_t *info)
 		return -EINVAL;

 	/* Not even root can pretend to send signals from the kernel.
-	   Nor can they impersonate a kill(), which adds source info.  */
