{"sha": "7d1fe46a5e7be506d06310e188404bab8c8b8253", "filename": "src/core/cipher.cpp", "status": "modified", "additions": 10, "deletions": 1, "changes": 11, "blob_url": "https://github.com/quassel/quassel/blob/8b5ecd226f9208af3074b33d3b7cf5e14f55b138/src/core/cipher.cpp", "raw_url": "https://github.com/quassel/quassel/raw/8b5ecd226f9208af3074b33d3b7cf5e14f55b138/src/core/cipher.cpp", "contents_url": "https://api.github.com/repos/quassel/quassel/contents/src/core/cipher.cpp?ref=8b5ecd226f9208af3074b33d3b7cf5e14f55b138", "patch": "@@ -364,6 +364,10 @@ QByteArray Cipher::blowfishECB(QByteArray cipherText, bool direction)
     }
     else
     {
+        // ECB Blowfish encodes in blocks of 12 chars, so anything else is malformed input
+        if ((temp.length() % 12) != 0)
+            return cipherText;
+
         temp = b64ToByte(temp);
         while ((temp.length() % 8) != 0) temp.append('\0');
     }
@@ -376,8 +380,13 @@ QByteArray Cipher::blowfishECB(QByteArray cipherText, bool direction)
     if (!cipher.ok())
         return cipherText;

-    if (direction)
+    if (direction) {
+        // Sanity check
+        if ((temp2.length() % 8) != 0)
+            return cipherText;
+
         temp2 = byteToB64(temp2);
+    }

     return temp2;
 }"}

