{"sha": "8563081e8da38fb81e0335d2589c9fcebcd81266", "filename": "lib/lzo/lzo1x_decompress_safe.c", "status": "modified", "additions": 41, "deletions": 21, "changes": 62, "blob_url": "https://github.com/torvalds/linux/blob/206a81c18401c0cde6e579164f752c4b147324ce/lib/lzo/lzo1x_decompress_safe.c", "raw_url": "https://github.com/torvalds/linux/raw/206a81c18401c0cde6e579164f752c4b147324ce/lib/lzo/lzo1x_decompress_safe.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/lib/lzo/lzo1x_decompress_safe.c?ref=206a81c18401c0cde6e579164f752c4b147324ce", "patch": "@@ -19,11 +19,31 @@
