{"sha": "b3d2f0b30265e4966b68a183e3be4fd0ced431d6", "filename": "util.c", "status": "modified", "additions": 9, "deletions": 2, "changes": 11, "blob_url": "https://github.com/sgminer-dev/sgminer/blob/910c36089940e81fb85c65b8e63dcd2fac71470c/util.c", "raw_url": "https://github.com/sgminer-dev/sgminer/raw/910c36089940e81fb85c65b8e63dcd2fac71470c/util.c", "contents_url": "https://api.github.com/repos/sgminer-dev/sgminer/contents/util.c?ref=910c36089940e81fb85c65b8e63dcd2fac71470c", "patch": "@@ -1600,24 +1600,31 @@ static bool parse_notify(struct pool *pool, json_t *val)
