{"sha": "77f204318cb0e8955031c4ba076a1c944ff33029", "filename": "util.c", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/sgminer-dev/sgminer/blob/b65574bef233474e915fdf18614aa211e31cc6c2/util.c", "raw_url": "https://github.com/sgminer-dev/sgminer/raw/b65574bef233474e915fdf18614aa211e31cc6c2/util.c", "contents_url": "https://api.github.com/repos/sgminer-dev/sgminer/contents/util.c?ref=b65574bef233474e915fdf18614aa211e31cc6c2", "patch": "@@ -1219,6 +1219,13 @@ bool extract_sockaddr(char *url, char **sockaddr_url, char **sockaddr_port)

 	if (url_len < 1)
 		return false;
+	
+	if (url_len >= sizeof(url_address))
+	{
+		applog(LOG_WARNING, "%s: Truncating overflowed address '%.*s'",
+		       __func__, url_len, url_begin);
+		url_len = sizeof(url_address) - 1;
+	}

 	sprintf(url_address, "%.*s", url_len, url_begin);
 "}

