{"sha": "214a7dc7e92faf55a2f69be27adbb8ea99ab403f", "filename": "ext/standard/dns.c", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/php/php-src/blob/b34d7849ed90ced9345f8ea1c59bc8d101c18468/ext/standard/dns.c", "raw_url": "https://github.com/php/php-src/raw/b34d7849ed90ced9345f8ea1c59bc8d101c18468/ext/standard/dns.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/standard/dns.c?ref=b34d7849ed90ced9345f8ea1c59bc8d101c18468", "patch": "@@ -517,6 +517,10 @@ static u_char *php_parserr(u_char *cp, querybuf *answer, int type_to_fetch, int

 				while (ll < dlen) {
 					n = cp[ll];
+					if ((ll + n) >= dlen) {
+						// Invalid chunk length, truncate
+						n = dlen - (ll + 1);
+					}
 					memcpy(tp + ll , cp + ll + 1, n);
