{"sha": "681e7a950a8f16f2e367903efdc6801228381fff", "filename": "ChangeLog", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/file/file/blob/39c7ac1106be844a5296d3eb5971946cc09ffda0/ChangeLog", "raw_url": "https://github.com/file/file/raw/39c7ac1106be844a5296d3eb5971946cc09ffda0/ChangeLog", "contents_url": "https://api.github.com/repos/file/file/contents/ChangeLog?ref=39c7ac1106be844a5296d3eb5971946cc09ffda0", "patch": "@@ -1,3 +1,7 @@
+2014-10-17  11:48  Christos Zoulas <christos@zoulas.com>
