{"sha": "0acac81f198b0b03c83b4f4f9ef86178fa84f821", "filename": "arch/x86/kvm/vmx.c", "status": "modified", "additions": 14, "deletions": 2, "changes": 16, "blob_url": "https://github.com/torvalds/linux/blob/d974baa398f34393db76be45f7d4d04fbdbb4a0a/arch/x86/kvm/vmx.c", "raw_url": "https://github.com/torvalds/linux/raw/d974baa398f34393db76be45f7d4d04fbdbb4a0a/arch/x86/kvm/vmx.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/x86/kvm/vmx.c?ref=d974baa398f34393db76be45f7d4d04fbdbb4a0a", "patch": "@@ -472,6 +472,7 @@ struct vcpu_vmx {
