{"sha": "6d694192121d0651a46eb737926457a3b014fcab", "filename": "src/softmagic.c", "status": "modified", "additions": 12, "deletions": 4, "changes": 16, "blob_url": "https://github.com/file/file/blob/27a14bc7ba285a0a5ebfdb55e54001aa11932b08/src/softmagic.c", "raw_url": "https://github.com/file/file/raw/27a14bc7ba285a0a5ebfdb55e54001aa11932b08/src/softmagic.c", "contents_url": "https://api.github.com/repos/file/file/contents/src/softmagic.c?ref=27a14bc7ba285a0a5ebfdb55e54001aa11932b08", "patch": "@@ -32,7 +32,7 @@
 #include "file.h"

 #ifndef	lint
-FILE_RCSID("@(#)$File: softmagic.c,v 1.189 2014/05/30 16:47:44 christos Exp $")
+FILE_RCSID("@(#)$File: softmagic.c,v 1.190 2014/06/03 19:01:34 christos Exp $")
 #endif	/* lint */

 #include "magic.h"
@@ -940,10 +940,18 @@ mconvert(struct magic_set *ms, struct magic *m, int flip)
 		return 1;
 	}
 	case FILE_PSTRING: {
-		char *ptr1 = p->s, *ptr2 = ptr1 + file_pstring_length_size(m);
+		size_t sz = file_pstring_length_size(m);
+		char *ptr1 = p->s, *ptr2 = ptr1 + sz;
 		size_t len = file_pstring_get_length(m, ptr1);
-		if (len >= sizeof(p->s))
-			len = sizeof(p->s) - 1;
+		if (len >= sizeof(p->s)) {
+			/*
+			 * The size of the pascal string length (sz)
+			 * is 1, 2, or 4. We need at least 1 byte for NUL
+			 * termination, but we've already truncated the
+			 * string by p->s, so we need to deduct sz.
+			 */ 
+			len = sizeof(p->s) - sz;
+		}
 		while (len--)
 			*ptr1++ = *ptr2++;
 		*ptr1 = '\0';"}

