{"sha": "6c3734d2b45a7a9ca24557a586ba10135b7cadb3", "filename": "drivers/usb/serial/whiteheat.c", "status": "modified", "additions": 6, "deletions": 1, "changes": 7, "blob_url": "https://github.com/torvalds/linux/blob/6817ae225cd650fb1c3295d769298c38b1eba818/drivers/usb/serial/whiteheat.c", "raw_url": "https://github.com/torvalds/linux/raw/6817ae225cd650fb1c3295d769298c38b1eba818/drivers/usb/serial/whiteheat.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/usb/serial/whiteheat.c?ref=6817ae225cd650fb1c3295d769298c38b1eba818", "patch": "@@ -514,6 +514,10 @@ static void command_port_read_callback(struct urb *urb)
