{"sha": "29a74c1efcb85fa727536c4b72be844f9963cd70", "filename": "drivers/hid/hid-magicmouse.c", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/torvalds/linux/blob/c54def7bd64d7c0b6993336abcffb8444795bf38/drivers/hid/hid-magicmouse.c", "raw_url": "https://github.com/torvalds/linux/raw/c54def7bd64d7c0b6993336abcffb8444795bf38/drivers/hid/hid-magicmouse.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/hid/hid-magicmouse.c?ref=c54def7bd64d7c0b6993336abcffb8444795bf38", "patch": "@@ -290,6 +290,11 @@ static int magicmouse_raw_event(struct hid_device *hdev,
 		if (size < 4 || ((size - 4) % 9) != 0)
 			return 0;
 		npoints = (size - 4) / 9;
+		if (npoints > 15) {
+			hid_warn(hdev, "invalid size value (%d) for TRACKPAD_REPORT_ID\n",
+					size);
+			return 0;
+		}
 		msc->ntouches = 0;
 		for (ii = 0; ii < npoints; ii++)
 			magicmouse_emit_touch(msc, ii, data + ii * 9 + 4);
@@ -307,6 +312,11 @@ static int magicmouse_raw_event(struct hid_device *hdev,
 		if (size < 6 || ((size - 6) % 8) != 0)
 			return 0;
 		npoints = (size - 6) / 8;
+		if (npoints > 15) {
+			hid_warn(hdev, "invalid size value (%d) for MOUSE_REPORT_ID\n",
+					size);
+			return 0;
+		}
 		msc->ntouches = 0;
 		for (ii = 0; ii < npoints; ii++)
 			magicmouse_emit_touch(msc, ii, data + ii * 8 + 6);"}

