{"sha": "af064d28b36524c5ce9c8fc982a58eec65ebbfc7", "filename": "arch/powerpc/kernel/process.c", "status": "modified", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/torvalds/linux/blob/621b5060e823301d0cba4cb52a7ee3491922d291/arch/powerpc/kernel/process.c", "raw_url": "https://github.com/torvalds/linux/raw/621b5060e823301d0cba4cb52a7ee3491922d291/arch/powerpc/kernel/process.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/powerpc/kernel/process.c?ref=621b5060e823301d0cba4cb52a7ee3491922d291", "patch": "@@ -1048,6 +1048,15 @@ int arch_dup_task_struct(struct task_struct *dst, struct task_struct *src)
 	flush_altivec_to_thread(src);
 	flush_vsx_to_thread(src);
 	flush_spe_to_thread(src);
+	/*
+	 * Flush TM state out so we can copy it.  __switch_to_tm() does this
+	 * flush but it removes the checkpointed state from the current CPU and
+	 * transitions the CPU out of TM mode.  Hence we need to call
+	 * tm_recheckpoint_new_task() (on the same task) to restore the
+	 * checkpointed state back and the TM mode.
+	 */
+	__switch_to_tm(src);
+	tm_recheckpoint_new_task(src);

 	*dst = *src;
 "}

