{"sha": "fc4e6be5484cd80d7c441edfd093d835c9aaac45", "filename": "src/Imap/Tasks/OpenConnectionTask.cpp", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/jktjkt/trojita/blob/25fffa3e25cbad85bbca804193ad336b090a9ce1/src/Imap/Tasks/OpenConnectionTask.cpp", "raw_url": "https://github.com/jktjkt/trojita/raw/25fffa3e25cbad85bbca804193ad336b090a9ce1/src/Imap/Tasks/OpenConnectionTask.cpp", "contents_url": "https://api.github.com/repos/jktjkt/trojita/contents/src/Imap/Tasks/OpenConnectionTask.cpp?ref=25fffa3e25cbad85bbca804193ad336b090a9ce1", "patch": "@@ -153,6 +153,17 @@ bool OpenConnectionTask::handleStateHelper(const Imap::Responses::State *const r
     {
         switch (resp->kind) {
         case PREAUTH:
+            if (model->m_startTls) {
+                // Oops, we cannot send STARTTLS when the connection is already authenticated.
+                // This is serious enough to warrant an error; an attacker might be going after a plaintext
+                // of a message we're going to APPEND, etc.
+                // Thanks to Arnt Gulbrandsen on the imap-protocol ML for asking what happens when we're configured
+                // to request STARTTLS and a PREAUTH is received, and to Michael M Slusarz for starting that discussion.
+                logout(tr("Configuration requires sending STARTTLS, but the IMAP server greets us with PREAUTH. "
+                          "Encryption cannot be established. If this configuration worked previously, someone "
+                          "is after your data and they are pretty smart."));
+                return true;
+            }
             // Cool, we're already authenticated. Now, let's see if we have to issue CAPABILITY or if we already know that
             if (model->accessParser(parser).capabilitiesFresh) {
                 // We're alsmost done here, apart from compression"}<_**next**_>{"sha": "f186c68cda1b234c29ddd135ec51323544c381e6", "filename": "tests/Imap/test_Imap_Tasks_OpenConnection.cpp", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/jktjkt/trojita/blob/25fffa3e25cbad85bbca804193ad336b090a9ce1/tests/Imap/test_Imap_Tasks_OpenConnection.cpp", "raw_url": "https://github.com/jktjkt/trojita/raw/25fffa3e25cbad85bbca804193ad336b090a9ce1/tests/Imap/test_Imap_Tasks_OpenConnection.cpp", "contents_url": "https://api.github.com/repos/jktjkt/trojita/contents/tests/Imap/test_Imap_Tasks_OpenConnection.cpp?ref=25fffa3e25cbad85bbca804193ad336b090a9ce1", "patch": "@@ -129,6 +129,19 @@ void ImapModelOpenConnectionTest::testPreauthWithCapability()
     QVERIFY(startTlsUpgradeSpy->isEmpty());
 }

+/** @short What happens when the server responds with PREAUTH and we want STARTTLS? */
+void ImapModelOpenConnectionTest::testPreauthWithStartTlsWanted()
+{
+    cleanup(); init(true); // yuck, but I can't come up with anything better...
+
+    cEmpty();
+    cServer("* PREAUTH hi there\r\n");
+    QCOMPARE(failedSpy->size(), 1);
+    QVERIFY(completedSpy->isEmpty());
+    QVERIFY(authSpy->isEmpty());
+    QVERIFY(startTlsUpgradeSpy->isEmpty());
