{"sha": "a44a87268a6ef640c454600873489cc4e4e1e058", "filename": "fs/nfs/write.c", "status": "modified", "additions": 6, "deletions": 5, "changes": 11, "blob_url": "https://github.com/torvalds/linux/blob/263b4509ec4d47e0da3e753f85a39ea12d1eff24/fs/nfs/write.c", "raw_url": "https://github.com/torvalds/linux/raw/263b4509ec4d47e0da3e753f85a39ea12d1eff24/fs/nfs/write.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/nfs/write.c?ref=263b4509ec4d47e0da3e753f85a39ea12d1eff24", "patch": "@@ -922,19 +922,20 @@ static bool nfs_write_pageuptodate(struct page *page, struct inode *inode)
  * extend the write to cover the entire page in order to avoid fragmentation
  * inefficiencies.
  *
- * If the file is opened for synchronous writes or if we have a write delegation
- * from the server then we can just skip the rest of the checks.
+ * If the file is opened for synchronous writes then we can just skip the rest
+ * of the checks.
  */
 static int nfs_can_extend_write(struct file *file, struct page *page, struct inode *inode)
 {
 	if (file->f_flags & O_DSYNC)
 		return 0;
+	if (!nfs_write_pageuptodate(page, inode))
+		return 0;
 	if (NFS_PROTO(inode)->have_delegation(inode, FMODE_WRITE))
 		return 1;
-	if (nfs_write_pageuptodate(page, inode) && (inode->i_flock == NULL ||
-			(inode->i_flock->fl_start == 0 &&
+	if (inode->i_flock == NULL || (inode->i_flock->fl_start == 0 &&
 			inode->i_flock->fl_end == OFFSET_MAX &&
-			inode->i_flock->fl_type != F_RDLCK)))
+			inode->i_flock->fl_type != F_RDLCK))
 		return 1;
 	return 0;
 }"}

