+						m2[i] = Z_DVAL(dval);
+					}
 					break;
 				default:
 					php_error_docref(NULL TSRMLS_CC, E_WARNING, "Invalid type for element %i", i);"}<_**next**_>{"sha": "f881494716402338847ab4ff23619f4f633fc384", "filename": "ext/gd/tests/bug66356.phpt", "status": "added", "additions": 22, "deletions": 0, "changes": 22, "blob_url": "https://github.com/php/php-src/blob/2938329ce19cb8c4197dec146c3ec887c6f61d01/ext/gd/tests/bug66356.phpt", "raw_url": "https://github.com/php/php-src/raw/2938329ce19cb8c4197dec146c3ec887c6f61d01/ext/gd/tests/bug66356.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/gd/tests/bug66356.phpt?ref=2938329ce19cb8c4197dec146c3ec887c6f61d01", "patch": "@@ -0,0 +1,22 @@
+--TEST--
+Bug #66356 (Heap Overflow Vulnerability in imagecrop())
+--SKIPIF--
+<?php
+	if(!extension_loaded('gd')){ die('skip gd extension not available'); }
+?>
+--FILE--
+<?php
+$img = imagecreatetruecolor(10, 10);
+$img = imagecrop($img, array("x" => "a", "y" => 0, "width" => 10, "height" => 10));
+$arr = array("x" => "a", "y" => "12b", "width" => 10, "height" => 10);
+$img = imagecrop($img, $arr);
+print_r($arr);
+?>
+--EXPECTF--
+Array
+(
+    [x] => a
+    [y] => 12b
+    [width] => 10
+    [height] => 10
+)"}<_**next**_>{"sha": "d9ea4aab3cd61f5dbff50d8113875e70834728b3", "filename": "main/php_version.h", "status": "modified", "additions": 3, "deletions": 3, "changes": 6, "blob_url": "https://github.com/php/php-src/blob/2938329ce19cb8c4197dec146c3ec887c6f61d01/main/php_version.h", "raw_url": "https://github.com/php/php-src/raw/2938329ce19cb8c4197dec146c3ec887c6f61d01/main/php_version.h", "contents_url": "https://api.github.com/repos/php/php-src/contents/main/php_version.h?ref=2938329ce19cb8c4197dec146c3ec887c6f61d01", "patch": "@@ -2,7 +2,7 @@
