{"sha": "91060218b75f6d2cc2a85f476748723eb938ecbb", "filename": "hphp/runtime/ext/ext_simplexml.cpp", "status": "modified", "additions": 15, "deletions": 10, "changes": 25, "blob_url": "https://github.com/facebook/hhvm/blob/95f96e7287effe2fcdfb9a5338d1a7e4f55b083b/hphp/runtime/ext/ext_simplexml.cpp", "raw_url": "https://github.com/facebook/hhvm/raw/95f96e7287effe2fcdfb9a5338d1a7e4f55b083b/hphp/runtime/ext/ext_simplexml.cpp", "contents_url": "https://api.github.com/repos/facebook/hhvm/contents/hphp/runtime/ext/ext_simplexml.cpp?ref=95f96e7287effe2fcdfb9a5338d1a7e4f55b083b", "patch": "@@ -1246,6 +1246,9 @@ void c_LibXMLError::t___construct() {
