 ///////////////////////////////////////////////////////////////////////////////"}<_**next**_>{"sha": "95872eb89901b6f348f38a0f1cef6ad3bb3ad370", "filename": "hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/facebook/hhvm/blob/95f96e7287effe2fcdfb9a5338d1a7e4f55b083b/hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php", "raw_url": "https://github.com/facebook/hhvm/raw/95f96e7287effe2fcdfb9a5338d1a7e4f55b083b/hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php", "contents_url": "https://api.github.com/repos/facebook/hhvm/contents/hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php?ref=95f96e7287effe2fcdfb9a5338d1a7e4f55b083b", "patch": "@@ -0,0 +1,25 @@
+<?php
+
+$xml = <<<EOT
+<?xml version="1.0" encoding="UTF-8"?>
+<!DOCTYPE test [<!ENTITY xxe SYSTEM "XXE_URI">]>
+<foo>&xxe;</foo>
+EOT;
+
+$xml = str_replace('XXE_URI', __DIR__ . '/libxml_disable_entity_loader_payload.txt', $xml);
+
+function parseXML($xml) {
+  $doc = new DOMDocument();
+  $doc->resolveExternals = true;
+  $doc->substituteEntities = true;
+  $doc->validateOnParse = false;
+  $doc->loadXML($xml, 0);
+  return $doc->saveXML();
+}
+
+var_dump(strpos(parseXML($xml), 'SECRET_DATA') !== false);
+var_dump(libxml_disable_entity_loader(true));
+var_dump(strpos(parseXML($xml), 'SECRET_DATA') === false);
+
+echo "Done\n";
+?>"}<_**next**_>{"sha": "54de637bce48c00dd1ffa7a946290e1f0a08f5a4", "filename": "hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php.expectf", "status": "added", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/facebook/hhvm/blob/95f96e7287effe2fcdfb9a5338d1a7e4f55b083b/hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php.expectf", "raw_url": "https://github.com/facebook/hhvm/raw/95f96e7287effe2fcdfb9a5338d1a7e4f55b083b/hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php.expectf", "contents_url": "https://api.github.com/repos/facebook/hhvm/contents/hphp/test/zend/good/ext/libxml/tests/libxml_disable_entity_loader.php.expectf?ref=95f96e7287effe2fcdfb9a5338d1a7e4f55b083b", "patch": "@@ -0,0 +1,7 @@
