{"sha": "cea1c76d49bf5b04344bb17c353bab35869cf01a", "filename": "arch/x86/include/asm/fpu-internal.h", "status": "modified", "additions": 7, "deletions": 6, "changes": 13, "blob_url": "https://github.com/torvalds/linux/blob/26bef1318adc1b3a530ecc807ef99346db2aa8b0/arch/x86/include/asm/fpu-internal.h", "raw_url": "https://github.com/torvalds/linux/raw/26bef1318adc1b3a530ecc807ef99346db2aa8b0/arch/x86/include/asm/fpu-internal.h", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/x86/include/asm/fpu-internal.h?ref=26bef1318adc1b3a530ecc807ef99346db2aa8b0", "patch": "@@ -293,12 +293,13 @@ static inline int restore_fpu_checking(struct task_struct *tsk)
 	/* AMD K7/K8 CPUs don't save/restore FDP/FIP/FOP unless an exception
 	   is pending.  Clear the x87 state here by setting it to fixed
 	   values. "m" is a random variable that should be in L1 */
-	alternative_input(
-		ASM_NOP8 ASM_NOP2,
-		"emms\n\t"		/* clear stack tags */
-		"fildl %P[addr]",	/* set F?P to defined value */
-		X86_FEATURE_FXSAVE_LEAK,
-		[addr] "m" (tsk->thread.fpu.has_fpu));
+	if (unlikely(static_cpu_has(X86_FEATURE_FXSAVE_LEAK))) {
+		asm volatile(
+			"fnclex\n\t"
+			"emms\n\t"
+			"fildl %P[addr]"	/* set F?P to defined value */
+			: : [addr] "m" (tsk->thread.fpu.has_fpu));
+	}

 	return fpu_restore_checking(&tsk->thread.fpu);
 }"}

{"sha": "d065b61fbaa7ab97fcb7fc573a3a2c5b27a2fadb", "filename": "lib/cgraph/scan.l", "status": "modified", "additions": 26, "deletions": 9, "changes": 35, "blob_url": "https://github.com/ellson/MOTHBALLED-graphviz/blob/1d1bdec6318746f6f19f245db589eddc887ae8ff/lib/cgraph/scan.l", "raw_url": "https://github.com/ellson/MOTHBALLED-graphviz/raw/1d1bdec6318746f6f19f245db589eddc887ae8ff/lib/cgraph/scan.l", "contents_url": "https://api.github.com/repos/ellson/MOTHBALLED-graphviz/contents/lib/cgraph/scan.l?ref=1d1bdec6318746f6f19f245db589eddc887ae8ff", "patch": "@@ -129,15 +129,32 @@ static void ppDirective (void)
