{"sha": "005cc9da147fc0adcfc85b82f6805bb399d28284", "filename": "src/plugins/Makefile.am", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/abrt/abrt/blob/50ee8130fb4cd4ef1af7682a2c85dd99cb99424e/src/plugins/Makefile.am", "raw_url": "https://github.com/abrt/abrt/raw/50ee8130fb4cd4ef1af7682a2c85dd99cb99424e/src/plugins/Makefile.am", "contents_url": "https://api.github.com/repos/abrt/abrt/contents/src/plugins/Makefile.am?ref=50ee8130fb4cd4ef1af7682a2c85dd99cb99424e", "patch": "@@ -371,6 +371,7 @@ abrt_action_install_debuginfo_to_abrt_cache_CPPFLAGS = \
