{"sha": "ddeff4844a100de83b52ef9dae9f42974666dc23", "filename": "arch/x86/net/bpf_jit_comp.c", "status": "modified", "additions": 6, "deletions": 1, "changes": 7, "blob_url": "https://github.com/torvalds/linux/blob/3f7352bf21f8fd7ba3e2fcef9488756f188e12be/arch/x86/net/bpf_jit_comp.c", "raw_url": "https://github.com/torvalds/linux/raw/3f7352bf21f8fd7ba3e2fcef9488756f188e12be/arch/x86/net/bpf_jit_comp.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/x86/net/bpf_jit_comp.c?ref=3f7352bf21f8fd7ba3e2fcef9488756f188e12be", "patch": "@@ -966,7 +966,12 @@ void bpf_int_jit_compile(struct bpf_prog *prog)
 	}
 	ctx.cleanup_addr = proglen;

-	for (pass = 0; pass < 10; pass++) {
+	/* JITed image shrinks with every pass and the loop iterates
+	 * until the image stops shrinking. Very large bpf programs
+	 * may converge on the last pass. In such case do one more
+	 * pass to emit the final image
+	 */
+	for (pass = 0; pass < 10 || image; pass++) {
 		proglen = do_jit(prog, addrs, image, oldproglen, &ctx);
 		if (proglen <= 0) {
 			image = NULL;"}

