{"sha": "d43202a1a489142bda1bba37263ee560db269ada", "filename": "CHANGELOG.md", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/bblanchon/ArduinoJson/blob/5e7b9ec688d79e7b16ec7064e1d37e8481a31e72/CHANGELOG.md", "raw_url": "https://github.com/bblanchon/ArduinoJson/raw/5e7b9ec688d79e7b16ec7064e1d37e8481a31e72/CHANGELOG.md", "contents_url": "https://api.github.com/repos/bblanchon/ArduinoJson/contents/CHANGELOG.md?ref=5e7b9ec688d79e7b16ec7064e1d37e8481a31e72", "patch": "@@ -1,6 +1,13 @@
