 "}<_**next**_>{"sha": "45a6c488fc5c4c54859d9505d7a340e979f526f1", "filename": "src/Internals/QuotedString.cpp", "status": "modified", "additions": 15, "deletions": 17, "changes": 32, "blob_url": "https://github.com/bblanchon/ArduinoJson/blob/5e7b9ec688d79e7b16ec7064e1d37e8481a31e72/src/Internals/QuotedString.cpp", "raw_url": "https://github.com/bblanchon/ArduinoJson/raw/5e7b9ec688d79e7b16ec7064e1d37e8481a31e72/src/Internals/QuotedString.cpp", "contents_url": "https://api.github.com/repos/bblanchon/ArduinoJson/contents/src/Internals/QuotedString.cpp?ref=5e7b9ec688d79e7b16ec7064e1d37e8481a31e72", "patch": "@@ -58,46 +58,44 @@ static char unescapeChar(char c) {
 static inline bool isQuote(char c) { return c == '\"' || c == '\''; }

 char *QuotedString::extractFrom(char *input, char **endPtr) {
-  char firstChar = *input;
-
-  if (!isQuote(firstChar)) {
-    // must start with a quote
-    return NULL;
-  }
-
-  char stopChar = firstChar;  // closing quote is the same as opening quote
-
   char *startPtr = input + 1;  // skip the quote
   char *readPtr = startPtr;
   char *writePtr = startPtr;
   char c;

+  char firstChar = *input;
+  char stopChar = firstChar;  // closing quote is the same as opening quote
+
+  if (!isQuote(firstChar)) goto ERROR_OPENING_QUOTE_MISSING;
+
   for (;;) {
     c = *readPtr++;

-    if (c == '\0') {
-      // premature ending
-      return NULL;
-    }
+    if (c == '\0') goto ERROR_CLOSING_QUOTE_MISSING;

-    if (c == stopChar) {
-      // closing quote
-      break;
-    }
+    if (c == stopChar) goto SUCCESS;

     if (c == '\\') {
       // replace char
       c = unescapeChar(*readPtr++);
+      if (c == '\0') goto ERROR_ESCAPE_SEQUENCE_INTERRUPTED;
     }

     *writePtr++ = c;
   }

+SUCCESS:
   // end the string here
   *writePtr = '\0';

   // update end ptr
   *endPtr = readPtr;

+  // return pointer to unquoted string
   return startPtr;
+
+ERROR_OPENING_QUOTE_MISSING:
+ERROR_CLOSING_QUOTE_MISSING:
+ERROR_ESCAPE_SEQUENCE_INTERRUPTED:
+  return NULL;
 }"}<_**next**_>{"sha": "94d062613ca8674e755756efa490db17fa00b230", "filename": "test/QuotedString_ExtractFrom_Tests.cpp", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/bblanchon/ArduinoJson/blob/5e7b9ec688d79e7b16ec7064e1d37e8481a31e72/test/QuotedString_ExtractFrom_Tests.cpp", "raw_url": "https://github.com/bblanchon/ArduinoJson/raw/5e7b9ec688d79e7b16ec7064e1d37e8481a31e72/test/QuotedString_ExtractFrom_Tests.cpp", "contents_url": "https://api.github.com/repos/bblanchon/ArduinoJson/contents/test/QuotedString_ExtractFrom_Tests.cpp?ref=5e7b9ec688d79e7b16ec7064e1d37e8481a31e72", "patch": "@@ -16,6 +16,11 @@ class QuotedString_ExtractFrom_Tests : public testing::Test {
