{"sha": "29b927938b8ce9c78af99d0f9c8f5af5a294cefd", "filename": "fs/namei.c", "status": "modified", "additions": 25, "deletions": 2, "changes": 27, "blob_url": "https://github.com/torvalds/linux/blob/397d425dc26da728396e66d392d5dcb8dac30c37/fs/namei.c", "raw_url": "https://github.com/torvalds/linux/raw/397d425dc26da728396e66d392d5dcb8dac30c37/fs/namei.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/namei.c?ref=397d425dc26da728396e66d392d5dcb8dac30c37", "patch": "@@ -560,6 +560,24 @@ static int __nd_alloc_stack(struct nameidata *nd)
