{"sha": "0b9318bfd1251628470cccb28017cfefeb61f8e8", "filename": "rw.cpp", "status": "modified", "additions": 7, "deletions": 1, "changes": 8, "blob_url": "https://github.com/weidai11/cryptopp/blob/9425e16437439e68c7d96abef922167d68fafaff/rw.cpp", "raw_url": "https://github.com/weidai11/cryptopp/raw/9425e16437439e68c7d96abef922167d68fafaff/rw.cpp", "contents_url": "https://api.github.com/repos/weidai11/cryptopp/contents/rw.cpp?ref=9425e16437439e68c7d96abef922167d68fafaff", "patch": "@@ -126,10 +126,16 @@ Integer InvertibleRWFunction::CalculateInverse(RandomNumberGenerator &rng, const
