 "}<_**next**_>{"sha": "729a12011b5f512d199b9b11d2946741efb87fe6", "filename": "ext/standard/tests/strings/bug68710.phpt", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/php/php-src/blob/b585a3aed7880a5fa5c18e2b838fc96f40e075bd/ext/standard/tests/strings/bug68710.phpt", "raw_url": "https://github.com/php/php-src/raw/b585a3aed7880a5fa5c18e2b838fc96f40e075bd/ext/standard/tests/strings/bug68710.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/standard/tests/strings/bug68710.phpt?ref=b585a3aed7880a5fa5c18e2b838fc96f40e075bd", "patch": "@@ -0,0 +1,25 @@
+--TEST--
+Bug #68710 Use after free vulnerability in unserialize() (bypassing the
+CVE-2014-8142 fix)
+--FILE--
+<?php
+for ($i=4; $i<100; $i++) {
+    $m = new StdClass();
+
+    $u = array(1);
+
+    $m->aaa = array(1,2,&$u,4,5);
+    $m->bbb = 1;
+    $m->ccc = &$u;
+    $m->ddd = str_repeat("A", $i);
+
+    $z = serialize($m);
+    $z = str_replace("aaa", "123", $z);
+    $z = str_replace("bbb", "123", $z);
+    $y = unserialize($z);
+    $z = serialize($y);
+}
+?>
+===DONE===
+--EXPECTF--
+===DONE==="}<_**next**_>{"sha": "f114080b86e5c7e05746f03457b0a2d9245d5c6b", "filename": "ext/standard/var_unserializer.c", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/php/php-src/blob/b585a3aed7880a5fa5c18e2b838fc96f40e075bd/ext/standard/var_unserializer.c", "raw_url": "https://github.com/php/php-src/raw/b585a3aed7880a5fa5c18e2b838fc96f40e075bd/ext/standard/var_unserializer.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/standard/var_unserializer.c?ref=b585a3aed7880a5fa5c18e2b838fc96f40e075bd", "patch": "@@ -1,4 +1,4 @@
