+/*
+    Test directory traversal
+ */
+
+const HTTP: Uri = App.config.uris.http || "127.0.0.1:8080"
+
+http = new Http
+http.get(HTTP + "/../../appweb.conf")
+assert(http.status == 400)
+http.close()
+
+http.get(HTTP + "/../../index.html")
+assert(http.status == 400)
+http.close()
+
+/* Test windows '\' delimiter */
+http.get(HTTP + "/..%5Cappweb.conf")
+if (Config.OS == 'windows') {
+    /* for windows, the "..\\" is an invalid filename */
+    assert(http.status == 404)
+} else {
+    assert(http.status == 400)
+}
+http.close()
+
+http.get(HTTP + "/../../../../../.x/.x/.x/.x/.x/.x/etc/passwd")
+assert(http.status == 400)
+http.close()
+"}<_**next**_>{"sha": "6f143b141eb2122b36d039bc7240cde3644a0810", "filename": "test/security/uri.tst", "status": "added", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/embedthis/goahead/blob/eed4a7d177bf94a54c7b06ccce88507fbd76fb77/test/security/uri.tst", "raw_url": "https://github.com/embedthis/goahead/raw/eed4a7d177bf94a54c7b06ccce88507fbd76fb77/test/security/uri.tst", "contents_url": "https://api.github.com/repos/embedthis/goahead/contents/test/security/uri.tst?ref=eed4a7d177bf94a54c7b06ccce88507fbd76fb77", "patch": "@@ -0,0 +1,32 @@
+/*
+    Uri validation
+ */
+
+const HTTP: Uri = App.config.uris.http || "127.0.0.1:8080"
+
+function get(uri): String {
+    let s = new Socket
+    s.connect(HTTP.address)
+    let count = 0
+    try {
+        count += s.write("GET " + uri + " HTTP/1.0\r\n\r\n")
+    } catch {
+        tfail("Write failed. Wrote  " + count + " of " + data.length + " bytes.")
+    }
+    let response = new ByteArray
+    while ((n = s.read(response, -1)) != null ) {}
+    s.close()
+    return response.toString()
+}
+
+/*
+let response
+response = get('index.html')
+assert(response.toString().contains('Not Found'))
+
+response = get('/\x01index.html')
+assert(response.toString().contains('Bad Request'))
+*/
+
+response = get('\\index.html')
+assert(response.toString().contains('Bad Request'))"}

