 	}
 }

+FileType
+getFileTypeNoFollowSymlinks(const StaticString &filename) {
+	struct stat buf;
+	int ret;
+	
+	ret = lstat(filename.c_str(), &buf);
+	if (ret == 0) {
+		if (S_ISREG(buf.st_mode)) {
+			return FT_REGULAR;
+		} else if (S_ISDIR(buf.st_mode)) {
+			return FT_DIRECTORY;
+		} else if (S_ISLNK(buf.st_mode)) {
+			return FT_SYMLINK;
+		} else {
+			return FT_OTHER;
+		}
+	} else {
+		if (errno == ENOENT) {
+			return FT_NONEXISTANT;
+		} else {
+			int e = errno;
+			string message("Cannot lstat '");
+			message.append(filename);
+			message.append("'");
+			throw FileSystemException(message, e, filename);
+		}
+	}
+}
+
 void
 createFile(const string &filename, const StaticString &contents, mode_t permissions, uid_t owner,
 	gid_t group, bool overwrite)"}<_**next**_>{"sha": "5cfaf9210e112f67b1c764873c5da92df0da2632", "filename": "ext/common/Utils.h", "status": "modified", "additions": 7, "deletions": 1, "changes": 8, "blob_url": "https://github.com/phusion/passenger/blob/34b1087870c2bf85ebfd72c30b78577e10ab9744/ext/common/Utils.h", "raw_url": "https://github.com/phusion/passenger/raw/34b1087870c2bf85ebfd72c30b78577e10ab9744/ext/common/Utils.h", "contents_url": "https://api.github.com/repos/phusion/passenger/contents/ext/common/Utils.h?ref=34b1087870c2bf85ebfd72c30b78577e10ab9744", "patch": "@@ -65,6 +65,8 @@ typedef enum {
