{"sha": "123979fe12bf780b50ed0967d8ba289c63f798a3", "filename": "include/net/tcp.h", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/torvalds/linux/blob/ac6e780070e30e4c35bd395acfe9191e6268bdd3/include/net/tcp.h", "raw_url": "https://github.com/torvalds/linux/raw/ac6e780070e30e4c35bd395acfe9191e6268bdd3/include/net/tcp.h", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/include/net/tcp.h?ref=ac6e780070e30e4c35bd395acfe9191e6268bdd3", "patch": "@@ -1220,6 +1220,7 @@ static inline void tcp_prequeue_init(struct tcp_sock *tp)

 bool tcp_prequeue(struct sock *sk, struct sk_buff *skb);
 bool tcp_add_backlog(struct sock *sk, struct sk_buff *skb);
+int tcp_filter(struct sock *sk, struct sk_buff *skb);

 #undef STATE_TRACE
 "}<_**next**_>{"sha": "2259114c7242c72cadc149073c8101101c198483", "filename": "net/ipv4/tcp_ipv4.c", "status": "modified", "additions": 18, "deletions": 1, "changes": 19, "blob_url": "https://github.com/torvalds/linux/blob/ac6e780070e30e4c35bd395acfe9191e6268bdd3/net/ipv4/tcp_ipv4.c", "raw_url": "https://github.com/torvalds/linux/raw/ac6e780070e30e4c35bd395acfe9191e6268bdd3/net/ipv4/tcp_ipv4.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/ipv4/tcp_ipv4.c?ref=ac6e780070e30e4c35bd395acfe9191e6268bdd3", "patch": "@@ -1564,6 +1564,21 @@ bool tcp_add_backlog(struct sock *sk, struct sk_buff *skb)
 }
 EXPORT_SYMBOL(tcp_add_backlog);

+int tcp_filter(struct sock *sk, struct sk_buff *skb)
+{
+	struct tcphdr *th = (struct tcphdr *)skb->data;
+	unsigned int eaten = skb->len;
+	int err;
+
+	err = sk_filter_trim_cap(sk, skb, th->doff * 4);
+	if (!err) {
+		eaten -= skb->len;
+		TCP_SKB_CB(skb)->end_seq -= eaten;
+	}
+	return err;
+}
+EXPORT_SYMBOL(tcp_filter);
+
 /*
  *	From tcp_input.c
  */
@@ -1676,8 +1691,10 @@ int tcp_v4_rcv(struct sk_buff *skb)

 	nf_reset(skb);

-	if (sk_filter(sk, skb))
+	if (tcp_filter(sk, skb))
 		goto discard_and_relse;
+	th = (const struct tcphdr *)skb->data;
+	iph = ip_hdr(skb);

 	skb->dev = NULL;
 "}<_**next**_>{"sha": "b9f1fee9a8862a5bc17a20e17bdb402adc418cde", "filename": "net/ipv6/tcp_ipv6.c", "status": "modified", "additions": 4, "deletions": 2, "changes": 6, "blob_url": "https://github.com/torvalds/linux/blob/ac6e780070e30e4c35bd395acfe9191e6268bdd3/net/ipv6/tcp_ipv6.c", "raw_url": "https://github.com/torvalds/linux/raw/ac6e780070e30e4c35bd395acfe9191e6268bdd3/net/ipv6/tcp_ipv6.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/ipv6/tcp_ipv6.c?ref=ac6e780070e30e4c35bd395acfe9191e6268bdd3", "patch": "@@ -1229,7 +1229,7 @@ static int tcp_v6_do_rcv(struct sock *sk, struct sk_buff *skb)
 	if (skb->protocol == htons(ETH_P_IP))
 		return tcp_v4_do_rcv(sk, skb);

-	if (sk_filter(sk, skb))
+	if (tcp_filter(sk, skb))
 		goto discard;

 	/*
@@ -1457,8 +1457,10 @@ static int tcp_v6_rcv(struct sk_buff *skb)
 	if (tcp_v6_inbound_md5_hash(sk, skb))
 		goto discard_and_relse;

-	if (sk_filter(sk, skb))
+	if (tcp_filter(sk, skb))
 		goto discard_and_relse;
+	th = (const struct tcphdr *)skb->data;
+	hdr = ipv6_hdr(skb);

 	skb->dev = NULL;
 "}

{"sha": "cbaa8d776d83505c1d298b061970b1c44ef10456", "filename": "drivers/firewire/net.c", "status": "modified", "additions": 35, "deletions": 16, "changes": 51, "blob_url": "https://github.com/torvalds/linux/blob/667121ace9dbafb368618dbabcf07901c962ddac/drivers/firewire/net.c", "raw_url": "https://github.com/torvalds/linux/raw/667121ace9dbafb368618dbabcf07901c962ddac/drivers/firewire/net.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/firewire/net.c?ref=667121ace9dbafb368618dbabcf07901c962ddac", "patch": "@@ -578,6 +578,9 @@ static int fwnet_incoming_packet(struct fwnet_device *dev, __be32 *buf, int len,
 	int retval;
 	u16 ether_type;

+	if (len <= RFC2374_UNFRAG_HDR_SIZE)
+		return 0;
+
 	hdr.w0 = be32_to_cpu(buf[0]);
 	lf = fwnet_get_hdr_lf(&hdr);
 	if (lf == RFC2374_HDR_UNFRAG) {
@@ -602,7 +605,12 @@ static int fwnet_incoming_packet(struct fwnet_device *dev, __be32 *buf, int len,
 		return fwnet_finish_incoming_packet(net, skb, source_node_id,
 						    is_broadcast, ether_type);
 	}
+
 	/* A datagram fragment has been received, now the fun begins. */
+
+	if (len <= RFC2374_FRAG_HDR_SIZE)
+		return 0;
+
 	hdr.w1 = ntohl(buf[1]);
 	buf += 2;
 	len -= RFC2374_FRAG_HDR_SIZE;
@@ -616,6 +624,9 @@ static int fwnet_incoming_packet(struct fwnet_device *dev, __be32 *buf, int len,
 	datagram_label = fwnet_get_hdr_dgl(&hdr);
 	dg_size = fwnet_get_hdr_dg_size(&hdr); /* ??? + 1 */

+	if (fg_off + len > dg_size)
+		return 0;
+
 	spin_lock_irqsave(&dev->lock, flags);

 	peer = fwnet_peer_find_by_node_id(dev, source_node_id, generation);
@@ -722,6 +733,22 @@ static void fwnet_receive_packet(struct fw_card *card, struct fw_request *r,
 	fw_send_response(card, r, rcode);
 }

+static int gasp_source_id(__be32 *p)
+{
+	return be32_to_cpu(p[0]) >> 16;
+}
+
+static u32 gasp_specifier_id(__be32 *p)
+{
+	return (be32_to_cpu(p[0]) & 0xffff) << 8 |
+	       (be32_to_cpu(p[1]) & 0xff000000) >> 24;
+}
+
+static u32 gasp_version(__be32 *p)
+{
+	return be32_to_cpu(p[1]) & 0xffffff;
+}
+
 static void fwnet_receive_broadcast(struct fw_iso_context *context,
 		u32 cycle, size_t header_length, void *header, void *data)
 {
@@ -731,9 +758,6 @@ static void fwnet_receive_broadcast(struct fw_iso_context *context,
 	__be32 *buf_ptr;
 	int retval;
 	u32 length;
-	u16 source_node_id;
-	u32 specifier_id;
-	u32 ver;
 	unsigned long offset;
 	unsigned long flags;

@@ -750,22 +774,17 @@ static void fwnet_receive_broadcast(struct fw_iso_context *context,

 	spin_unlock_irqrestore(&dev->lock, flags);

-	specifier_id =    (be32_to_cpu(buf_ptr[0]) & 0xffff) << 8
-			| (be32_to_cpu(buf_ptr[1]) & 0xff000000) >> 24;
-	ver = be32_to_cpu(buf_ptr[1]) & 0xffffff;
-	source_node_id = be32_to_cpu(buf_ptr[0]) >> 16;
-
-	if (specifier_id == IANA_SPECIFIER_ID &&
-	    (ver == RFC2734_SW_VERSION
+	if (length > IEEE1394_GASP_HDR_SIZE &&
+	    gasp_specifier_id(buf_ptr) == IANA_SPECIFIER_ID &&
+	    (gasp_version(buf_ptr) == RFC2734_SW_VERSION
 #if IS_ENABLED(CONFIG_IPV6)
-	     || ver == RFC3146_SW_VERSION
+	     || gasp_version(buf_ptr) == RFC3146_SW_VERSION
 #endif
-	    )) {
-		buf_ptr += 2;
-		length -= IEEE1394_GASP_HDR_SIZE;
-		fwnet_incoming_packet(dev, buf_ptr, length, source_node_id,
+	    ))
+		fwnet_incoming_packet(dev, buf_ptr + 2,
+				      length - IEEE1394_GASP_HDR_SIZE,
+				      gasp_source_id(buf_ptr),
 				      context->card->generation, true);
-	}

 	packet.payload_length = dev->rcv_buffer_size;
 	packet.interrupt = 1;"}

