{"sha": "01b8116298a13b5463e7969ce66c0b037bcfccd5", "filename": "block/ioprio.c", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/torvalds/linux/blob/8ba8682107ee2ca3347354e018865d8e1967c5f4/block/ioprio.c", "raw_url": "https://github.com/torvalds/linux/raw/8ba8682107ee2ca3347354e018865d8e1967c5f4/block/ioprio.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/block/ioprio.c?ref=8ba8682107ee2ca3347354e018865d8e1967c5f4", "patch": "@@ -150,8 +150,10 @@ static int get_task_ioprio(struct task_struct *p)
 	if (ret)
 		goto out;
 	ret = IOPRIO_PRIO_VALUE(IOPRIO_CLASS_NONE, IOPRIO_NORM);
+	task_lock(p);
 	if (p->io_context)
 		ret = p->io_context->ioprio;
+	task_unlock(p);
 out:
 	return ret;
 }"}

