{"sha": "aa301aa8382714a92bebece493fcceaf988bf307", "filename": "ext/wddx/tests/bug73065.phpt", "status": "added", "additions": 98, "deletions": 0, "changes": 98, "blob_url": "https://github.com/php/php-src/blob/c4cca4c20e75359c9a13a1f9a36cb7b4e9601d29/ext/wddx/tests/bug73065.phpt", "raw_url": "https://github.com/php/php-src/raw/c4cca4c20e75359c9a13a1f9a36cb7b4e9601d29/ext/wddx/tests/bug73065.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/tests/bug73065.phpt?ref=c4cca4c20e75359c9a13a1f9a36cb7b4e9601d29", "patch": "@@ -0,0 +1,98 @@
+--TEST--
+Bug #73065: Out-Of-Bounds Read in php_wddx_push_element of wddx.c
+--SKIPIF--
+<?php
+if (!extension_loaded('wddx')) {
+    die('skip. wddx not available');
+}
+?>
+--FILE--
+<?php
+
+$xml1 = <<<XML
+<?xml version='1.0' ?>
+    <!DOCTYPE et SYSTEM 'w'>
+    <wddxPacket ven='1.0'>
+        <array>
+            <var Name="name">
+                <boolean value="keliu"></boolean>
+            </var>
+            <var name="1111">
+                <var name="2222">
+                    <var name="3333"></var>
+                </var>
+            </var>
+        </array>
+    </wddxPacket>
+XML;
+    
+$xml2 = <<<XML
+<?xml version='1.0' ?>
+    <!DOCTYPE et SYSTEM 'w'>
+    <wddxPacket ven='1.0'>
+        <array>
+            <char Name="code">
+                <boolean value="keliu"></boolean>
+            </char>
+        </array>
+    </wddxPacket>
+XML;
+
+$xml3 = <<<XML
+<?xml version='1.0' ?>
+    <!DOCTYPE et SYSTEM 'w'>
+    <wddxPacket ven='1.0'>
+        <array>
+            <boolean Name="value">
+                <boolean value="keliu"></boolean>
+            </boolean>
+        </array>
+    </wddxPacket>
+XML;
+
+$xml4 = <<<XML
+<?xml version='1.0' ?>
+    <!DOCTYPE et SYSTEM 'w'>
+    <wddxPacket ven='1.0'>
+        <array>
+            <recordset Name="fieldNames">
+                <boolean value="keliu"></boolean>
+            </recordset>
+        </array>
+    </wddxPacket>
+XML;
+
+$xml5 = <<<XML
+<?xml version='1.0' ?>
+    <!DOCTYPE et SYSTEM 'w'>
+    <wddxPacket ven='1.0'>
+        <array>
+            <field Name="name">
+                <boolean value="keliu"></boolean>
+            </field>
+        </array>
+    </wddxPacket>
+XML;
+
+for($i=1;$i<=5;$i++) {
+	$xmlvar = "xml$i";
+    $array = wddx_deserialize($$xmlvar);
+    var_dump($array);
+}
+?>
+DONE
+--EXPECTF--
+array(0) {
+}
+array(0) {
+}
+array(0) {
+}
+array(1) {
+  [0]=>
+  array(0) {
+  }
+}
+array(0) {
+}
+DONE
\ No newline at end of file"}<_**next**_>{"sha": "0e77826ce8476ea0cb0186dd7cec95b0c0129685", "filename": "ext/wddx/wddx.c", "status": "modified", "additions": 10, "deletions": 9, "changes": 19, "blob_url": "https://github.com/php/php-src/blob/c4cca4c20e75359c9a13a1f9a36cb7b4e9601d29/ext/wddx/wddx.c", "raw_url": "https://github.com/php/php-src/raw/c4cca4c20e75359c9a13a1f9a36cb7b4e9601d29/ext/wddx/wddx.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/wddx.c?ref=c4cca4c20e75359c9a13a1f9a36cb7b4e9601d29", "patch": "@@ -780,10 +780,10 @@ static void php_wddx_push_element(void *user_data, const XML_Char *name, const X
