{"sha": "6385457e8ee41b58082462379a87030b1e2cfe23", "filename": "ext/wddx/tests/bug72860.phpt", "status": "added", "additions": 27, "deletions": 0, "changes": 27, "blob_url": "https://github.com/php/php-src/blob/b88393f08a558eec14964a55d3c680fe67407712/ext/wddx/tests/bug72860.phpt", "raw_url": "https://github.com/php/php-src/raw/b88393f08a558eec14964a55d3c680fe67407712/ext/wddx/tests/bug72860.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/tests/bug72860.phpt?ref=b88393f08a558eec14964a55d3c680fe67407712", "patch": "@@ -0,0 +1,27 @@
+--TEST--
+Bug #72860: wddx_deserialize use-after-free
+--SKIPIF--
+<?php
+if (!extension_loaded('wddx')) {
+    die('skip. wddx not available');
+}
+?>
+--FILE--
+<?php
+
+$xml=<<<XML
+<?xml version='1.0'?>
+<!DOCTYPE wddxPacket SYSTEM 'wddx_0100.dtd'>
+<wddxPacket version='1.0'>
+       <recordset fieldNames='F'>
+               <field name='F'>
+       </recordset>
+</wddxPacket>
+XML;
+
+var_dump(wddx_deserialize($xml));
+?>
+DONE
+--EXPECT--
+NULL
+DONE
\ No newline at end of file"}<_**next**_>{"sha": "b02d2f07ded469c5ed8256e422428d3ce8bee637", "filename": "ext/wddx/wddx.c", "status": "modified", "additions": 2, "deletions": 1, "changes": 3, "blob_url": "https://github.com/php/php-src/blob/b88393f08a558eec14964a55d3c680fe67407712/ext/wddx/wddx.c", "raw_url": "https://github.com/php/php-src/raw/b88393f08a558eec14964a55d3c680fe67407712/ext/wddx/wddx.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/wddx.c?ref=b88393f08a558eec14964a55d3c680fe67407712", "patch": "@@ -230,7 +230,8 @@ static int wddx_stack_destroy(wddx_stack *stack)

