+ * THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT
+ * (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF
+ * THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
+ */
+#include "test.h"
+
+DEFINE_TEST(test_read_too_many_filters)
+{
+	const char *name = "test_read_too_many_filters.gz";
+	struct archive *a;
+	int r;
+
+	assert((a = archive_read_new()) != NULL);
+	r = archive_read_support_filter_gzip(a);
+	if (r == ARCHIVE_WARN) {
+		skipping("gzip reading not fully supported on this platform");
+	}
+	assertEqualIntA(a, ARCHIVE_OK, archive_read_support_format_all(a));
+	extract_reference_file(name);
+	assertEqualIntA(a, ARCHIVE_FATAL,
+	    archive_read_open_filename(a, name, 200));
+
+	assertEqualInt(ARCHIVE_OK, archive_read_close(a));
+	assertEqualInt(ARCHIVE_OK, archive_read_free(a));
+}"}<_**next**_>{"sha": "6bf6614f3b197978ccf928b72dd9819bbf3c5336", "filename": "libarchive/test/test_read_too_many_filters.gz.uu", "status": "added", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/libarchive/libarchive/blob/6e06b1c89dd0d16f74894eac4cfc1327a06ee4a0/libarchive/test/test_read_too_many_filters.gz.uu", "raw_url": "https://github.com/libarchive/libarchive/raw/6e06b1c89dd0d16f74894eac4cfc1327a06ee4a0/libarchive/test/test_read_too_many_filters.gz.uu", "contents_url": "https://api.github.com/repos/libarchive/libarchive/contents/libarchive/test/test_read_too_many_filters.gz.uu?ref=6e06b1c89dd0d16f74894eac4cfc1327a06ee4a0", "patch": "@@ -0,0 +1,15 @@
