{"sha": "a60524bdaf19e37f9326b6111092a6423832dbf3", "filename": "ext/wddx/tests/bug72790.phpt", "status": "added", "additions": 35, "deletions": 0, "changes": 35, "blob_url": "https://github.com/php/php-src/blob/a14fdb9746262549bbbb96abb87338bacd147e1b/ext/wddx/tests/bug72790.phpt", "raw_url": "https://github.com/php/php-src/raw/a14fdb9746262549bbbb96abb87338bacd147e1b/ext/wddx/tests/bug72790.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/tests/bug72790.phpt?ref=a14fdb9746262549bbbb96abb87338bacd147e1b", "patch": "@@ -0,0 +1,35 @@
+--TEST--
+Bug 72790: wddx_deserialize null dereference with invalid xml
+--SKIPIF--
+<?php
+if (!extension_loaded('wddx')) {
+    die('skip. wddx not available');
+}
+?>
+--FILE--
+<?php
+
+$xml = <<< XML
+<?xml version='1.0' ?>
+<!DOCTYPE wddxPacket SYSTEM 'wddx_0100.dtd'>
+<wddxPacket version='1.0'>
+        |array>
+                <var name="XXXX">
+                        <boolean value="this">
+                        </boolean>
+                </var>
+                <var name="YYYY">
+                        <var name="UUUU">
+                                <var name="EZEZ">
+                                </var>
+                        </var>
+                </var>
+        </array>
+</wddxPacket>
+XML;
+
+$array = wddx_deserialize($xml);
+var_dump($array);
+?>
+--EXPECT--
+NULL
\ No newline at end of file"}<_**next**_>{"sha": "5861d5538f49fd61939d8239601bca57328f5982", "filename": "ext/wddx/tests/bug72799.phpt", "status": "added", "additions": 28, "deletions": 0, "changes": 28, "blob_url": "https://github.com/php/php-src/blob/a14fdb9746262549bbbb96abb87338bacd147e1b/ext/wddx/tests/bug72799.phpt", "raw_url": "https://github.com/php/php-src/raw/a14fdb9746262549bbbb96abb87338bacd147e1b/ext/wddx/tests/bug72799.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/tests/bug72799.phpt?ref=a14fdb9746262549bbbb96abb87338bacd147e1b", "patch": "@@ -0,0 +1,28 @@
