+/*
+We test that a 8bpp TGA file will be gracefully rejected by
+gdImageCreateFromTga().
+*/
+
+#include <stdio.h>
+
+#include "gd.h"
+#include "gdtest.h"
+
+int main(int argc, char **argv)
+{
+    gdImagePtr im;
+    FILE *fp = gdTestFileOpen("tga/bug00247a.tga");
+    im = gdImageCreateFromTga(fp);
+    gdTestAssert(im == NULL);
+    fclose(fp);
+    return gdNumFailures();
+}"}<_**next**_>{"sha": "65e55abeae2204d745f1e2a5eb45bb64f8e0bf7c", "filename": "tests/tga/bug00247a.tga", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/libgd/libgd/blob/10ef1dca63d62433fda13309b4a228782db823f7/tests/tga/bug00247a.tga", "raw_url": "https://github.com/libgd/libgd/raw/10ef1dca63d62433fda13309b4a228782db823f7/tests/tga/bug00247a.tga", "contents_url": "https://api.github.com/repos/libgd/libgd/contents/tests/tga/bug00247a.tga?ref=10ef1dca63d62433fda13309b4a228782db823f7"}

