{"sha": "7798e1608f4f4bb429c94017e2c6f73b07a7afc9", "filename": "security/apparmor/lsm.c", "status": "modified", "additions": 19, "deletions": 17, "changes": 36, "blob_url": "https://github.com/torvalds/linux/blob/30a46a4647fd1df9cf52e43bf467f0d9265096ca/security/apparmor/lsm.c", "raw_url": "https://github.com/torvalds/linux/raw/30a46a4647fd1df9cf52e43bf467f0d9265096ca/security/apparmor/lsm.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/security/apparmor/lsm.c?ref=30a46a4647fd1df9cf52e43bf467f0d9265096ca", "patch": "@@ -500,34 +500,34 @@ static int apparmor_setprocattr(struct task_struct *task, char *name,
