{"sha": "8abd80dbcbed7974b4ace4265dd9dad1bca89edd", "filename": "drivers/platform/chrome/cros_ec_dev.c", "status": "modified", "additions": 7, "deletions": 1, "changes": 8, "blob_url": "https://github.com/torvalds/linux/blob/096cdc6f52225835ff503f987a0d68ef770bb78e/drivers/platform/chrome/cros_ec_dev.c", "raw_url": "https://github.com/torvalds/linux/raw/096cdc6f52225835ff503f987a0d68ef770bb78e/drivers/platform/chrome/cros_ec_dev.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/platform/chrome/cros_ec_dev.c?ref=096cdc6f52225835ff503f987a0d68ef770bb78e", "patch": "@@ -151,13 +151,19 @@ static long ec_device_ioctl_xcmd(struct cros_ec_dev *ec, void __user *arg)
