{"sha": "ea607a4a1bddaf3e41165aebed1fd787b87d754e", "filename": "drivers/s390/char/sclp_ctl.c", "status": "modified", "additions": 7, "deletions": 5, "changes": 12, "blob_url": "https://github.com/torvalds/linux/blob/532c34b5fbf1687df63b3fcd5b2846312ac943c6/drivers/s390/char/sclp_ctl.c", "raw_url": "https://github.com/torvalds/linux/raw/532c34b5fbf1687df63b3fcd5b2846312ac943c6/drivers/s390/char/sclp_ctl.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/s390/char/sclp_ctl.c?ref=532c34b5fbf1687df63b3fcd5b2846312ac943c6", "patch": "@@ -56,6 +56,7 @@ static int sclp_ctl_ioctl_sccb(void __user *user_area)
