+		<var name="YYYYYYYY"><var name="ZZZZZZZZ"><var name="EZEZEZEZ">
+		</var></var></var>
+	</array>
+</wddxPacket>
+EOF;
+$array = wddx_deserialize($xml);
+var_dump($array);
+?>
+--EXPECT--
+array(0) {
+}"}<_**next**_>{"sha": "311d6aa4a567f1e04462413300342a86b5436c6c", "filename": "ext/wddx/wddx.c", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/php/php-src/blob/a44c89e8af7c2410f4bfc5e097be2a5d0639a60c/ext/wddx/wddx.c", "raw_url": "https://github.com/php/php-src/raw/a44c89e8af7c2410f4bfc5e097be2a5d0639a60c/ext/wddx/wddx.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/wddx/wddx.c?ref=a44c89e8af7c2410f4bfc5e097be2a5d0639a60c", "patch": "@@ -1096,6 +1096,9 @@ static void php_wddx_process_data(void *user_data, const XML_Char *s, int len)
