{"sha": "63e3aefc3f16819c7e72f1b65f273174dda79bbe", "filename": "ext/gd/libgd/gd_gd2.c", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/php/php-src/blob/7722455726bec8c53458a32851d2a87982cf0eac/ext/gd/libgd/gd_gd2.c", "raw_url": "https://github.com/php/php-src/raw/7722455726bec8c53458a32851d2a87982cf0eac/ext/gd/libgd/gd_gd2.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/gd/libgd/gd_gd2.c?ref=7722455726bec8c53458a32851d2a87982cf0eac", "patch": "@@ -138,11 +138,18 @@ static int _gd2GetHeader(gdIOCtxPtr in, int *sx, int *sy, int *cs, int *vers, in
 	if (gd2_compressed(*fmt)) {
 		nc = (*ncx) * (*ncy);
 		GD2_DBG(php_gd_error("Reading %d chunk index entries", nc));
+		if (overflow2(sidx, nc)) {
+			goto fail1;
+		}
 		sidx = sizeof(t_chunk_info) * nc;
 		if (sidx <= 0) {
 			goto fail1;
