+
 		for (i = 0; i < nc; i++) {
 			if (gdGetInt(&cidx[i].offset, in) != 1) {
 				gdFree(cidx);"}<_**next**_>{"sha": "0634c990050f339dbbdd50cc748a027b344b6ddd", "filename": "ext/gd/tests/bug72339.gd", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/php/php-src/blob/7722455726bec8c53458a32851d2a87982cf0eac/ext/gd/tests/bug72339.gd", "raw_url": "https://github.com/php/php-src/raw/7722455726bec8c53458a32851d2a87982cf0eac/ext/gd/tests/bug72339.gd", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/gd/tests/bug72339.gd?ref=7722455726bec8c53458a32851d2a87982cf0eac"}<_**next**_>{"sha": "763ae71000a681eb0a67056906b2b623c0fb1114", "filename": "ext/gd/tests/bug72339.phpt", "status": "added", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/php/php-src/blob/7722455726bec8c53458a32851d2a87982cf0eac/ext/gd/tests/bug72339.phpt", "raw_url": "https://github.com/php/php-src/raw/7722455726bec8c53458a32851d2a87982cf0eac/ext/gd/tests/bug72339.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/gd/tests/bug72339.phpt?ref=7722455726bec8c53458a32851d2a87982cf0eac", "patch": "@@ -0,0 +1,11 @@
+--TEST--
+Bug #72339 Integer Overflow in _gd2GetHeader() resulting in heap overflow 
+--SKIPIF--
+<?php if (!function_exists("imagecreatefromgd2")) print "skip"; ?>
+--FILE--
+<?php imagecreatefromgd2(dirname(__FILE__) . DIRECTORY_SEPARATOR . "bug72339.gd"); ?>
+--EXPECTF--	
+Warning: imagecreatefromgd2(): gd warning: product of memory allocation multiplication would exceed INT_MAX, failing operation gracefully
+ in %sbug72339.php on line %d
+
+Warning: imagecreatefromgd2(): '%sbug72339.gd' is not a valid GD2 file in %sbug72339.php on line %d"}

{"sha": "88e45234d527518e0d449d598c5f04a5be5538a1", "filename": "drivers/misc/mic/vop/vop_vringh.c", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/torvalds/linux/blob/9bf292bfca94694a721449e3fd752493856710f6/drivers/misc/mic/vop/vop_vringh.c", "raw_url": "https://github.com/torvalds/linux/raw/9bf292bfca94694a721449e3fd752493856710f6/drivers/misc/mic/vop/vop_vringh.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/misc/mic/vop/vop_vringh.c?ref=9bf292bfca94694a721449e3fd752493856710f6", "patch": "@@ -945,6 +945,11 @@ static long vop_ioctl(struct file *f, unsigned int cmd, unsigned long arg)
