{"sha": "b09db0e9a59b2be4d04c8c318f45ca7d16963285", "filename": "libarchive/archive_read_support_format_cpio.c", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/libarchive/libarchive/blob/fd7e0c02e272913a0a8b6d492c7260dfca0b1408/libarchive/archive_read_support_format_cpio.c", "raw_url": "https://github.com/libarchive/libarchive/raw/fd7e0c02e272913a0a8b6d492c7260dfca0b1408/libarchive/archive_read_support_format_cpio.c", "contents_url": "https://api.github.com/repos/libarchive/libarchive/contents/libarchive/archive_read_support_format_cpio.c?ref=fd7e0c02e272913a0a8b6d492c7260dfca0b1408", "patch": "@@ -401,6 +401,11 @@ archive_read_format_cpio_read_header(struct archive_read *a,

 	/* If this is a symlink, read the link contents. */
 	if (archive_entry_filetype(entry) == AE_IFLNK) {
+		if (cpio->entry_bytes_remaining > 1024 * 1024) {
+			archive_set_error(&a->archive, ENOMEM,
+			    "Rejecting malformed cpio archive: symlink contents exceed 1 megabyte");
+			return (ARCHIVE_FATAL);
+		}
 		h = __archive_read_ahead(a,
 			(size_t)cpio->entry_bytes_remaining, NULL);
 		if (h == NULL)"}

