{"sha": "e40da7759a0e6cd3a55bccdf90bb10284376ab11", "filename": "drivers/usb/usbip/usbip_common.c", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/torvalds/linux/blob/b348d7dddb6c4fbfc810b7a0626e8ec9e29f7cbb/drivers/usb/usbip/usbip_common.c", "raw_url": "https://github.com/torvalds/linux/raw/b348d7dddb6c4fbfc810b7a0626e8ec9e29f7cbb/drivers/usb/usbip/usbip_common.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/usb/usbip/usbip_common.c?ref=b348d7dddb6c4fbfc810b7a0626e8ec9e29f7cbb", "patch": "@@ -741,6 +741,17 @@ int usbip_recv_xbuff(struct usbip_device *ud, struct urb *urb)
 	if (!(size > 0))
 		return 0;

+	if (size > urb->transfer_buffer_length) {
+		/* should not happen, probably malicious packet */
+		if (ud->side == USBIP_STUB) {
+			usbip_event_add(ud, SDEV_EVENT_ERROR_TCP);
+			return 0;
+		} else {
+			usbip_event_add(ud, VDEV_EVENT_ERROR_TCP);
+			return -EPIPE;
+		}
+	}
+
 	ret = usbip_recv(ud->tcp_socket, urb->transfer_buffer, size);
 	if (ret != size) {
 		dev_err(&urb->dev->dev, "recv xbuf, %d\n", ret);"}

