{"sha": "f4431bc1ce430203b374ae757e627d808c6f17a4", "filename": "crypto/algif_skcipher.c", "status": "modified", "additions": 41, "deletions": 7, "changes": 48, "blob_url": "https://github.com/torvalds/linux/blob/dd504589577d8e8e70f51f997ad487a4cb6c026f/crypto/algif_skcipher.c", "raw_url": "https://github.com/torvalds/linux/raw/dd504589577d8e8e70f51f997ad487a4cb6c026f/crypto/algif_skcipher.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/crypto/algif_skcipher.c?ref=dd504589577d8e8e70f51f997ad487a4cb6c026f", "patch": "@@ -31,6 +31,11 @@ struct skcipher_sg_list {
