{"sha": "087acb569b63a4bd90982e0c9b15fc2313636c53", "filename": "arch/arm/kernel/sys_oabi-compat.c", "status": "modified", "additions": 37, "deletions": 36, "changes": 73, "blob_url": "https://github.com/torvalds/linux/blob/76cc404bfdc0d419c720de4daaf2584542734f42/arch/arm/kernel/sys_oabi-compat.c", "raw_url": "https://github.com/torvalds/linux/raw/76cc404bfdc0d419c720de4daaf2584542734f42/arch/arm/kernel/sys_oabi-compat.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/arm/kernel/sys_oabi-compat.c?ref=76cc404bfdc0d419c720de4daaf2584542734f42", "patch": "@@ -193,55 +193,56 @@ struct oabi_flock64 {
