{"sha": "68a74151fa6cf84002cd3be98a0fc29f67a40b02", "filename": "arch/arm64/kernel/perf_event.c", "status": "modified", "additions": 15, "deletions": 6, "changes": 21, "blob_url": "https://github.com/torvalds/linux/blob/8fff105e13041e49b82f92eef034f363a6b1c071/arch/arm64/kernel/perf_event.c", "raw_url": "https://github.com/torvalds/linux/raw/8fff105e13041e49b82f92eef034f363a6b1c071/arch/arm64/kernel/perf_event.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/arm64/kernel/perf_event.c?ref=8fff105e13041e49b82f92eef034f363a6b1c071", "patch": "@@ -322,22 +322,31 @@ armpmu_add(struct perf_event *event, int flags)
