{"sha": "15b3d6c4e46ac9dee9a291cc3c6041530e418809", "filename": "fs/Makefile", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/torvalds/linux/blob/f9a61eb4e2471c56a63cd804c7474128138c38ac/fs/Makefile", "raw_url": "https://github.com/torvalds/linux/raw/f9a61eb4e2471c56a63cd804c7474128138c38ac/fs/Makefile", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/Makefile?ref=f9a61eb4e2471c56a63cd804c7474128138c38ac", "patch": "@@ -41,7 +41,7 @@ obj-$(CONFIG_COMPAT_BINFMT_ELF)	+= compat_binfmt_elf.o
