{"sha": "3680422abc7fd018c9588bb5537252b7111fb305", "filename": "bin/varnishd/cache_http.c", "status": "modified", "additions": 13, "deletions": 6, "changes": 19, "blob_url": "https://github.com/varnish/Varnish-Cache/blob/29870c8fe95e4e8a672f6f28c5fbe692bea09e9c/bin/varnishd/cache_http.c", "raw_url": "https://github.com/varnish/Varnish-Cache/raw/29870c8fe95e4e8a672f6f28c5fbe692bea09e9c/bin/varnishd/cache_http.c", "contents_url": "https://api.github.com/repos/varnish/Varnish-Cache/contents/bin/varnishd/cache_http.c?ref=29870c8fe95e4e8a672f6f28c5fbe692bea09e9c", "patch": "@@ -639,21 +639,32 @@ http_splitline(struct worker *w, int fd, struct http *hp,
 /*--------------------------------------------------------------------*/

 static int
-htc_request_check_host_hdr(struct http *hp)
+htc_request_check_hdrs(struct sess *sp, struct http *hp)
 {
 	int u;
 	int seen_host = 0;
+	int seen_cl = 0;
+
 	for (u = HTTP_HDR_FIRST; u < hp->nhd; u++) {
 		if (hp->hd[u].b == NULL)
 			continue;
 		AN(hp->hd[u].b);
 		AN(hp->hd[u].e);
 		if (http_IsHdr(&hp->hd[u], H_Host)) {
 			if (seen_host) {
+				WSP(sp, SLT_Error, "Duplicated Host header");
 				return (400);
 			}
 			seen_host = 1;
 		}
+		if (http_IsHdr(&hp->hd[u], H_Content_Length)) {
+			if (seen_cl) {
+				WSP(sp, SLT_Error,
+				    "Duplicated Content-Length header");
+				return (400);
+			}
+			seen_cl = 1;
+		}
 	}
 	return (0);
 }
@@ -698,11 +709,7 @@ http_DissectRequest(struct sess *sp)
 	}
 	http_ProtoVer(hp);

-	retval = htc_request_check_host_hdr(hp);
-	if (retval != 0) {
-		WSP(sp, SLT_Error, "Duplicated Host header");
-		return (retval);
-	}
+	retval = htc_request_check_hdrs(sp, hp);
 	return (retval);
 }
 "}<_**next**_>{"sha": "292cea9493413aaccb32679339cecacdd2ca4287", "filename": "bin/varnishtest/tests/b00041.vtc", "status": "added", "additions": 23, "deletions": 0, "changes": 23, "blob_url": "https://github.com/varnish/Varnish-Cache/blob/29870c8fe95e4e8a672f6f28c5fbe692bea09e9c/bin/varnishtest/tests/b00041.vtc", "raw_url": "https://github.com/varnish/Varnish-Cache/raw/29870c8fe95e4e8a672f6f28c5fbe692bea09e9c/bin/varnishtest/tests/b00041.vtc", "contents_url": "https://api.github.com/repos/varnish/Varnish-Cache/contents/bin/varnishtest/tests/b00041.vtc?ref=29870c8fe95e4e8a672f6f28c5fbe692bea09e9c", "patch": "@@ -0,0 +1,23 @@
+varnishtest "Fail request on duplicate Content-Length headers in requests"
+
+server s1 {
+	rxreq
+	txresp
+} -start
+
+varnish v1 -vcl+backend {
+	sub vcl_deliver {
+		if (req.http.foo) {
+			set resp.http.Foo = req.http.foo;
+		}
+		if (req.http.bar) {
+			set resp.http.Bar = req.http.bar;
+		}
+	}
+} -start
+
+client c1 {
+	txreq -req POST -hdr "Content-Length: 5" -body "12345"
+	rxresp
+	expect resp.status == 400
+} -run"}<_**next**_>{"sha": "7309762d80f3349c1a615174e44dc16bc4971234", "filename": "bin/varnishtest/tests/r00102.vtc", "status": "modified", "additions": 0, "deletions": 2, "changes": 2, "blob_url": "https://github.com/varnish/Varnish-Cache/blob/29870c8fe95e4e8a672f6f28c5fbe692bea09e9c/bin/varnishtest/tests/r00102.vtc", "raw_url": "https://github.com/varnish/Varnish-Cache/raw/29870c8fe95e4e8a672f6f28c5fbe692bea09e9c/bin/varnishtest/tests/r00102.vtc", "contents_url": "https://api.github.com/repos/varnish/Varnish-Cache/contents/bin/varnishtest/tests/r00102.vtc?ref=29870c8fe95e4e8a672f6f28c5fbe692bea09e9c", "patch": "@@ -17,14 +17,12 @@ varnish v1 -vcl+backend {

