{"sha": "ddbf32d599cba4e51aeb81eea8519500a8bbea01", "filename": "drivers/usb/core/hub.c", "status": "modified", "additions": 19, "deletions": 3, "changes": 22, "blob_url": "https://github.com/torvalds/linux/blob/e50293ef9775c5f1cf3fcc093037dd6a8c5684ea/drivers/usb/core/hub.c", "raw_url": "https://github.com/torvalds/linux/raw/e50293ef9775c5f1cf3fcc093037dd6a8c5684ea/drivers/usb/core/hub.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/usb/core/hub.c?ref=e50293ef9775c5f1cf3fcc093037dd6a8c5684ea", "patch": "@@ -1035,10 +1035,20 @@ static void hub_activate(struct usb_hub *hub, enum hub_activation_type type)
 	unsigned delay;

 	/* Continue a partial initialization */
-	if (type == HUB_INIT2)
