{"sha": "195476a24148ba01d6609b72f60c98596d2065e1", "filename": "fs/fuse/file.c", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/torvalds/linux/blob/3ca8138f014a913f98e6ef40e939868e1e9ea876/fs/fuse/file.c", "raw_url": "https://github.com/torvalds/linux/raw/3ca8138f014a913f98e6ef40e939868e1e9ea876/fs/fuse/file.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/fuse/file.c?ref=3ca8138f014a913f98e6ef40e939868e1e9ea876", "patch": "@@ -1049,6 +1049,7 @@ static ssize_t fuse_fill_write_pages(struct fuse_req *req,
