{"sha": "ba670841056f1ede0929281e28e61e722e1fa990", "filename": "src/lib/kadm5/kadm_rpc_xdr.c", "status": "modified", "additions": 8, "deletions": 1, "changes": 9, "blob_url": "https://github.com/krb5/krb5/blob/df17a1224a3406f57477bcd372c61e04c0e5a5bb/src/lib/kadm5/kadm_rpc_xdr.c", "raw_url": "https://github.com/krb5/krb5/raw/df17a1224a3406f57477bcd372c61e04c0e5a5bb/src/lib/kadm5/kadm_rpc_xdr.c", "contents_url": "https://api.github.com/repos/krb5/krb5/contents/src/lib/kadm5/kadm_rpc_xdr.c?ref=df17a1224a3406f57477bcd372c61e04c0e5a5bb", "patch": "@@ -64,7 +64,14 @@ bool_t xdr_nullstring(XDR *xdrs, char **objp)
