{"sha": "acc5583764dc0925ad2f4745824d3848b743e978", "filename": "fs/namespace.c", "status": "modified", "additions": 5, "deletions": 2, "changes": 7, "blob_url": "https://github.com/torvalds/linux/blob/cd4a40174b71acd021877341684d8bb1dc8ea4ae/fs/namespace.c", "raw_url": "https://github.com/torvalds/linux/raw/cd4a40174b71acd021877341684d8bb1dc8ea4ae/fs/namespace.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/namespace.c?ref=cd4a40174b71acd021877341684d8bb1dc8ea4ae", "patch": "@@ -1669,8 +1669,11 @@ struct vfsmount *collect_mounts(struct path *path)
 {
 	struct mount *tree;
 	namespace_lock();
-	tree = copy_tree(real_mount(path->mnt), path->dentry,
-			 CL_COPY_ALL | CL_PRIVATE);
+	if (!check_mnt(real_mount(path->mnt)))
+		tree = ERR_PTR(-EINVAL);
+	else
+		tree = copy_tree(real_mount(path->mnt), path->dentry,
+				 CL_COPY_ALL | CL_PRIVATE);
 	namespace_unlock();
 	if (IS_ERR(tree))
 		return ERR_CAST(tree);"}

{"sha": "1f4f9dac6e5af8017e41ab497b92e0515e5ed71c", "filename": "fs/namespace.c", "status": "modified", "additions": 6, "deletions": 2, "changes": 8, "blob_url": "https://github.com/torvalds/linux/blob/e0c9c0afd2fc958ffa34b697972721d81df8a56f/fs/namespace.c", "raw_url": "https://github.com/torvalds/linux/raw/e0c9c0afd2fc958ffa34b697972721d81df8a56f/fs/namespace.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/namespace.c?ref=e0c9c0afd2fc958ffa34b697972721d81df8a56f", "patch": "@@ -1348,6 +1348,7 @@ static inline void namespace_lock(void)
 enum umount_tree_flags {
 	UMOUNT_SYNC = 1,
 	UMOUNT_PROPAGATE = 2,
+	UMOUNT_CONNECTED = 4,
 };
 /*
  * mount_lock must be held
@@ -1386,7 +1387,10 @@ static void umount_tree(struct mount *mnt, enum umount_tree_flags how)
 		if (how & UMOUNT_SYNC)
 			p->mnt.mnt_flags |= MNT_SYNC_UMOUNT;

-		disconnect = !IS_MNT_LOCKED_AND_LAZY(p);
