   { "test_view_sp_list_fields", test_view_sp_list_fields },
@@ -19785,6 +19893,7 @@ static struct my_tests_st my_tests[]= {
   { "test_wl6587", test_wl6587 },
   { "test_wl5928", test_wl5928 },
   { "test_wl6797", test_wl6797 },
+  { "test_wl6791", test_wl6791 },
   { 0, 0 }
 };
