{"sha": "245330ca0015c2fd2548ead861d379714151c901", "filename": "net/socket.c", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/torvalds/linux/blob/4de930efc23b92ddf88ce91c405ee645fe6e27ea/net/socket.c", "raw_url": "https://github.com/torvalds/linux/raw/4de930efc23b92ddf88ce91c405ee645fe6e27ea/net/socket.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/socket.c?ref=4de930efc23b92ddf88ce91c405ee645fe6e27ea", "patch": "@@ -1702,6 +1702,8 @@ SYSCALL_DEFINE6(sendto, int, fd, void __user *, buff, size_t, len,

 	if (len > INT_MAX)
 		len = INT_MAX;
+	if (unlikely(!access_ok(VERIFY_READ, buff, len)))
+		return -EFAULT;
 	sock = sockfd_lookup_light(fd, &err, &fput_needed);
 	if (!sock)
 		goto out;
@@ -1760,6 +1762,8 @@ SYSCALL_DEFINE6(recvfrom, int, fd, void __user *, ubuf, size_t, size,

 	if (size > INT_MAX)
 		size = INT_MAX;
+	if (unlikely(!access_ok(VERIFY_WRITE, ubuf, size)))
+		return -EFAULT;
 	sock = sockfd_lookup_light(fd, &err, &fput_needed);
 	if (!sock)
 		goto out;"}

