+////////////////////////////////////////////////////////////////////////////////
+/// Expand a pathname getting rid of special shell characters like ~.$, etc.
+/// Returned string must be freed by caller.
+
+char *RootdExpandPathName(const char *name)
+{
+   const char *patbuf = name;
+
+   // skip leading blanks
+   while (*patbuf == ' ') patbuf++;
+
+   // any shell meta characters?
