                 }
-                if (!(cd->flags & DETECT_CONTENT_RELATIVE_NEXT)) {
-                    SCLogDebug("no relative match coming up, so this is a match");
-                    goto match;
-                }

-                /* bail out if we have no next match. Technically this is an
-                 * error, as the current cd has the DETECT_CONTENT_RELATIVE_NEXT
-                 * flag set. */
+                /* if this is the last match we're done */
                 if (smd->is_last) {
-                    goto no_match;
+                    goto match;
                 }

                 SCLogDebug("content %"PRIu32, cd->id);
@@ -333,9 +332,21 @@ int DetectEngineContentInspection(DetectEngineCtx *de_ctx, DetectEngineThreadCtx
                 if (r == 1) {
                     SCReturnInt(1);
                 }
+                SCLogDebug("no match for 'next sm'");

-                if (det_ctx->discontinue_matching)
+                if (det_ctx->discontinue_matching) {
+                    SCLogDebug("'next sm' said to discontinue this right now");
                     goto no_match;
+                }
+
+                /* no match and no reason to look for another instance */
+                if ((cd->flags & DETECT_CONTENT_RELATIVE_NEXT) == 0) {
+                    SCLogDebug("'next sm' does not depend on me, so we can give up");
+                    det_ctx->discontinue_matching = 1;
+                    goto no_match;
+                }
+
+                SCLogDebug("'next sm' depends on me %p, lets see what we can do (flags %u)", cd, cd->flags);

                 /* set the previous match offset to the start of this match + 1 */
                 prev_offset = (match_offset - (cd->content_len - 1));"}

{"sha": "b400565f1f14667ec9a2ff762b2da26ab822b553", "filename": "libr/asm/arch/wasm/wasm.c", "status": "modified", "additions": 20, "deletions": 10, "changes": 30, "blob_url": "https://github.com/radareorg/radare2/blob/52b1526443c1f433087928291d1c3d37a5600515/libr/asm/arch/wasm/wasm.c", "raw_url": "https://github.com/radareorg/radare2/raw/52b1526443c1f433087928291d1c3d37a5600515/libr/asm/arch/wasm/wasm.c", "contents_url": "https://api.github.com/repos/radareorg/radare2/contents/libr/asm/arch/wasm/wasm.c?ref=52b1526443c1f433087928291d1c3d37a5600515", "patch": "@@ -416,7 +416,9 @@ int wasm_asm(const char *str, unsigned char *buf, int buf_len) {
