+                /*
+                 * IEEE 802.1Q-2014 Section 21.5.3.6: Management Address Length
+                 * This field is present if Management Address Domain Length is not 0.
+                 */
                 if (cfm_tlv_len < 1) {
-                    ND_PRINT((ndo, "\n\t  (TLV too short)"));
-                    return;
+                    ND_PRINT((ndo, " (Management Address Length is missing)"));
+                    hexdump = TRUE;
+                    break;
                 }

+                /* Here mgmt_addr_length stands for the management address length. */
                 mgmt_addr_length = *tptr;
                 tptr++;
                 tlen--;
                 cfm_tlv_len--;
+                ND_PRINT((ndo, "\n\t  Management Address Length %u", mgmt_addr_length));
                 if (mgmt_addr_length) {
+                    /* IEEE 802.1Q-2014 Section 21.5.3.7: Management Address */
                     if (cfm_tlv_len < mgmt_addr_length) {
                         ND_PRINT((ndo, "\n\t  (TLV too short)"));
                         return;
@@ -683,6 +725,7 @@ cfm_print(netdissect_options *ndo,
                     /*
                      * XXX - this is a TransportDomain; print it as such.
                      */
+                    hex_print(ndo, "\n\t  Management Address: ", tptr, mgmt_addr_length);
                     tptr += mgmt_addr_length;
                     tlen -= mgmt_addr_length;
                 }
@@ -706,6 +749,7 @@ cfm_print(netdissect_options *ndo,
         if (hexdump || ndo->ndo_vflag > 1)
             print_unknown_data(ndo, tlv_ptr, "\n\t  ", cfm_tlv_len);

+next_tlv:
         tptr+=cfm_tlv_len;
         tlen-=cfm_tlv_len;
     }"}<_**next**_>{"sha": "874876924fc50157e050d068c8cbbe0825d8e31d", "filename": "tests/TESTLIST", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/5d340a5ca6e420a70297cdbdf777333f18bfdab7/tests/TESTLIST", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/5d340a5ca6e420a70297cdbdf777333f18bfdab7/tests/TESTLIST", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/tests/TESTLIST?ref=5d340a5ca6e420a70297cdbdf777333f18bfdab7", "patch": "@@ -573,6 +573,7 @@ rsvp_uni-oobr-3	rsvp_uni-oobr-3.pcap	rsvp_uni-oobr-3.out	-v -c3
