{"sha": "90cf8ddfef9bf785395447184afafb7054dc9834", "filename": "print-vqp.c", "status": "modified", "additions": 13, "deletions": 1, "changes": 14, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/3b36ec4e713dea9266db11975066c425aa669b6c/print-vqp.c", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/3b36ec4e713dea9266db11975066c425aa669b6c/print-vqp.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/print-vqp.c?ref=3b36ec4e713dea9266db11975066c425aa669b6c", "patch": "@@ -26,6 +26,7 @@
 #include "netdissect.h"
 #include "extract.h"
 #include "addrtoname.h"
+#include "ether.h"

 #define VQP_VERSION            		1
 #define VQP_EXTRACT_VERSION(x) ((x)&0xFF)
@@ -105,13 +106,15 @@ vqp_print(netdissect_options *ndo, register const u_char *pptr, register u_int l
     const u_char *tptr;
     uint16_t vqp_obj_len;
     uint32_t vqp_obj_type;
-    int tlen;
+    u_int tlen;
     uint8_t nitems;

     tptr=pptr;
     tlen = len;
     vqp_common_header = (const struct vqp_common_header_t *)pptr;
     ND_TCHECK(*vqp_common_header);
+    if (sizeof(struct vqp_common_header_t) > tlen)
+        goto trunc;

     /*
      * Sanity checking of the header.
@@ -151,6 +154,9 @@ vqp_print(netdissect_options *ndo, register const u_char *pptr, register u_int l
     while (nitems > 0 && tlen > 0) {

         vqp_obj_tlv = (const struct vqp_obj_tlv_t *)tptr;
+        ND_TCHECK(*vqp_obj_tlv);
+        if (sizeof(struct vqp_obj_tlv_t) > tlen)
+            goto trunc;
         vqp_obj_type = EXTRACT_32BITS(vqp_obj_tlv->obj_type);
         vqp_obj_len = EXTRACT_16BITS(vqp_obj_tlv->obj_length);
         tptr+=sizeof(struct vqp_obj_tlv_t);
@@ -167,9 +173,13 @@ vqp_print(netdissect_options *ndo, register const u_char *pptr, register u_int l

         /* did we capture enough for fully decoding the object ? */
         ND_TCHECK2(*tptr, vqp_obj_len);
+        if (vqp_obj_len > tlen)
+            goto trunc;

         switch(vqp_obj_type) {
 	case VQP_OBJ_IP_ADDRESS:
+            if (vqp_obj_len != 4)
+                goto trunc;
             ND_PRINT((ndo, "%s (0x%08x)", ipaddr_string(ndo, tptr), EXTRACT_32BITS(tptr)));
             break;
             /* those objects have similar semantics - fall through */
@@ -182,6 +192,8 @@ vqp_print(netdissect_options *ndo, register const u_char *pptr, register u_int l
             /* those objects have similar semantics - fall through */
 	case VQP_OBJ_MAC_ADDRESS:
 	case VQP_OBJ_MAC_NULL:
+            if (vqp_obj_len != ETHER_ADDR_LEN)
+                goto trunc;
 	      ND_PRINT((ndo, "%s", etheraddr_string(ndo, tptr)));
               break;
         default:"}<_**next**_>{"sha": "687e92f37874ae713461fe50cc431e75d5884ead", "filename": "tests/TESTLIST", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/3b36ec4e713dea9266db11975066c425aa669b6c/tests/TESTLIST", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/3b36ec4e713dea9266db11975066c425aa669b6c/tests/TESTLIST", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/tests/TESTLIST?ref=3b36ec4e713dea9266db11975066c425aa669b6c", "patch": "@@ -562,6 +562,7 @@ isakmpv1-attr-oobr	isakmpv1-attr-oobr.pcap		isakmpv1-attr-oobr.out	-v
