{"sha": "392791e66ece40efdef49fb00d33ab84adc13ad9", "filename": "print-mptcp.c", "status": "modified", "additions": 50, "deletions": 34, "changes": 84, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/4c3aee4bb0294c232d56b6d34e9eeb74f630fe8c/print-mptcp.c", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/4c3aee4bb0294c232d56b6d34e9eeb74f630fe8c/print-mptcp.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/print-mptcp.c?ref=4c3aee4bb0294c232d56b6d34e9eeb74f630fe8c", "patch": "@@ -178,7 +178,7 @@ mp_capable_print(netdissect_options *ndo,
