+/*
+ * RFC 3561
+ */
 struct aodv_rreq {
 	uint8_t		rreq_type;	/* AODV message type (1) */
 	uint8_t		rreq_flags;	/* various flags */
@@ -178,12 +180,17 @@ aodv_extension(netdissect_options *ndo,
 {
 	const struct aodv_hello *ah;

+	ND_TCHECK(*ep);
 	switch (ep->type) {
 	case AODV_EXT_HELLO:
 		ah = (const struct aodv_hello *)(const void *)ep;
 		ND_TCHECK(*ah);
 		if (length < sizeof(struct aodv_hello))
 			goto trunc;
+		if (ep->length < 4) {
+			ND_PRINT((ndo, "\n\text HELLO - bad length %u", ep->length));
+			break;
+		}
 		ND_PRINT((ndo, "\n\text HELLO %ld ms",
 		    (unsigned long)EXTRACT_32BITS(&ah->interval)));
 		break;"}<_**next**_>{"sha": "358b5c2734700f480b5fa984ea55e05d99c06b48", "filename": "tests/TESTLIST", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/cbddb98484ea8ec1deece351abd56e063d775b38/tests/TESTLIST", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/cbddb98484ea8ec1deece351abd56e063d775b38/tests/TESTLIST", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/tests/TESTLIST?ref=cbddb98484ea8ec1deece351abd56e063d775b38", "patch": "@@ -459,6 +459,7 @@ hoobr_chdlc_print	hoobr_chdlc_print.pcap		hoobr_chdlc_print.out
