{"sha": "f2f56efb5459fdc2bd63db686afc2fba15d73144", "filename": "print-ip6.c", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/66df248b49095c261138b5a5e34d341a6bf9ac7f/print-ip6.c", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/66df248b49095c261138b5a5e34d341a6bf9ac7f/print-ip6.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/print-ip6.c?ref=66df248b49095c261138b5a5e34d341a6bf9ac7f", "patch": "@@ -280,6 +280,8 @@ ip6_print(netdissect_options *ndo, const u_char *bp, u_int length)
 	advance = sizeof(struct ip6_hdr);
 	nh = ip6->ip6_nxt;
 	while (cp < ndo->ndo_snapend && advance > 0) {
+		if (len < (u_int)advance)
+			goto trunc;
 		cp += advance;
 		len -= advance;

@@ -322,10 +324,15 @@ ip6_print(netdissect_options *ndo, const u_char *bp, u_int length)
 			 * mobility header.
 			 */
 			advance = mobility_print(ndo, cp, (const u_char *)ip6);
+			if (advance < 0)
+				return;
 			nh = *cp;
 			return;
 		case IPPROTO_ROUTING:
+			ND_TCHECK(*cp);
 			advance = rt6_print(ndo, cp, (const u_char *)ip6);
+			if (advance < 0)
+				return;
 			nh = *cp;
 			break;
 		case IPPROTO_SCTP:
@@ -345,12 +352,16 @@ ip6_print(netdissect_options *ndo, const u_char *bp, u_int length)
 			return;
 		case IPPROTO_AH:
 			advance = ah_print(ndo, cp);
+			if (advance < 0)
+				return;
 			nh = *cp;
 			break;
 		case IPPROTO_ESP:
 		    {
 			int enh, padlen;
 			advance = esp_print(ndo, cp, len, (const u_char *)ip6, &enh, &padlen);
+			if (advance < 0)
+				return;
 			nh = enh & 0xff;
 			len -= padlen;
 			break;"}<_**next**_>{"sha": "ca5541330ca981834352ab6b50cba95ad3d0f5a3", "filename": "print-mobility.c", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/66df248b49095c261138b5a5e34d341a6bf9ac7f/print-mobility.c", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/66df248b49095c261138b5a5e34d341a6bf9ac7f/print-mobility.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/print-mobility.c?ref=66df248b49095c261138b5a5e34d341a6bf9ac7f", "patch": "@@ -332,5 +332,5 @@ mobility_print(netdissect_options *ndo,

