{"sha": "2715fdf2411cad1724928ced819d0e1159234f3b", "filename": "src/bin/jp2/convertbmp.c", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/uclouvain/openjpeg/blob/baf0c1ad4572daa89caa3b12985bdd93530f0dd7/src/bin/jp2/convertbmp.c", "raw_url": "https://github.com/uclouvain/openjpeg/raw/baf0c1ad4572daa89caa3b12985bdd93530f0dd7/src/bin/jp2/convertbmp.c", "contents_url": "https://api.github.com/repos/uclouvain/openjpeg/contents/src/bin/jp2/convertbmp.c?ref=baf0c1ad4572daa89caa3b12985bdd93530f0dd7", "patch": "@@ -392,6 +392,10 @@ static OPJ_BOOL bmp_read_info_header(FILE* IN, OPJ_BITMAPINFOHEADER* header)

     header->biBitCount  = (OPJ_UINT16)getc(IN);
     header->biBitCount |= (OPJ_UINT16)((OPJ_UINT32)getc(IN) << 8);
+    if (header->biBitCount == 0) {
+        fprintf(stderr, "Error, invalid biBitCount %d\n", 0);
