{"sha": "0d6439e89acb796b9497ba6fcbb27e648981e0f5", "filename": "block/bio.c", "status": "modified", "additions": 8, "deletions": 0, "changes": 8, "blob_url": "https://github.com/torvalds/linux/blob/95d78c28b5a85bacbc29b8dba7c04babb9b0d467/block/bio.c", "raw_url": "https://github.com/torvalds/linux/raw/95d78c28b5a85bacbc29b8dba7c04babb9b0d467/block/bio.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/block/bio.c?ref=95d78c28b5a85bacbc29b8dba7c04babb9b0d467", "patch": "@@ -1383,6 +1383,7 @@ struct bio *bio_map_user_iov(struct request_queue *q,
 		offset = offset_in_page(uaddr);
 		for (j = cur_page; j < page_limit; j++) {
 			unsigned int bytes = PAGE_SIZE - offset;
+			unsigned short prev_bi_vcnt = bio->bi_vcnt;

 			if (len <= 0)
 				break;
@@ -1397,6 +1398,13 @@ struct bio *bio_map_user_iov(struct request_queue *q,
 					    bytes)
 				break;

+			/*
+			 * check if vector was merged with previous
+			 * drop page reference if needed
+			 */
+			if (bio->bi_vcnt == prev_bi_vcnt)
+				put_page(pages[j]);
+
 			len -= bytes;
 			offset = 0;
 		}"}

{"sha": "87e7e6608cd8a31e6913be8134b90e443df314cb", "filename": "arch/arm64/kvm/sys_regs.c", "status": "modified", "additions": 8, "deletions": 2, "changes": 10, "blob_url": "https://github.com/torvalds/linux/blob/9e3f7a29694049edd728e2400ab57ad7553e5aa9/arch/arm64/kvm/sys_regs.c", "raw_url": "https://github.com/torvalds/linux/raw/9e3f7a29694049edd728e2400ab57ad7553e5aa9/arch/arm64/kvm/sys_regs.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/arm64/kvm/sys_regs.c?ref=9e3f7a29694049edd728e2400ab57ad7553e5aa9", "patch": "@@ -597,16 +597,22 @@ static bool access_pmu_evcntr(struct kvm_vcpu *vcpu,

 			idx = ARMV8_PMU_CYCLE_IDX;
 		} else {
-			BUG();
+			return false;
 		}
+	} else if (r->CRn == 0 && r->CRm == 9) {
+		/* PMCCNTR */
+		if (pmu_access_event_counter_el0_disabled(vcpu))
+			return false;
+
+		idx = ARMV8_PMU_CYCLE_IDX;
 	} else if (r->CRn == 14 && (r->CRm & 12) == 8) {
 		/* PMEVCNTRn_EL0 */
 		if (pmu_access_event_counter_el0_disabled(vcpu))
 			return false;

 		idx = ((r->CRm & 3) << 3) | (r->Op2 & 7);
 	} else {
-		BUG();
+		return false;
 	}

 	if (!pmu_counter_idx_valid(vcpu, idx))"}

