 	}

-	if (!eof) {
+	if (!eof && vars->str.c != vars->ptr) {
 		memmove(vars->str.c, vars->ptr, vars->str.len = vars->end - vars->ptr);
 	}
 	return SUCCESS;"}

{"sha": "e589b8c54beac2916cd99b4c096255c244eaf712", "filename": "src/core/misc.c", "status": "modified", "additions": 3, "deletions": 0, "changes": 3, "blob_url": "https://github.com/irssi/irssi/blob/5e26325317c72a04c1610ad952974e206384d291/src/core/misc.c", "raw_url": "https://github.com/irssi/irssi/raw/5e26325317c72a04c1610ad952974e206384d291/src/core/misc.c", "contents_url": "https://api.github.com/repos/irssi/irssi/contents/src/core/misc.c?ref=5e26325317c72a04c1610ad952974e206384d291", "patch": "@@ -556,6 +556,9 @@ char *my_asctime(time_t t)
