{"sha": "013d8d1170fe02e16ebb364f54cd19a6421e8250", "filename": "sound/isa/msnd/msnd_midi.c", "status": "modified", "additions": 15, "deletions": 15, "changes": 30, "blob_url": "https://github.com/torvalds/linux/blob/20e2b791796bd68816fa115f12be5320de2b8021/sound/isa/msnd/msnd_midi.c", "raw_url": "https://github.com/torvalds/linux/raw/20e2b791796bd68816fa115f12be5320de2b8021/sound/isa/msnd/msnd_midi.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/sound/isa/msnd/msnd_midi.c?ref=20e2b791796bd68816fa115f12be5320de2b8021", "patch": "@@ -120,24 +120,24 @@ void snd_msndmidi_input_read(void *mpuv)
