{"sha": "2b744675e78ae1e27a7e5f8f01f479b167b66e79", "filename": "CHANGES", "status": "modified", "additions": 3, "deletions": 0, "changes": 3, "blob_url": "https://github.com/apache/httpd/blob/29afdd2550b3d30a8defece2b95ae81edcf66ac9/CHANGES", "raw_url": "https://github.com/apache/httpd/raw/29afdd2550b3d30a8defece2b95ae81edcf66ac9/CHANGES", "contents_url": "https://api.github.com/repos/apache/httpd/contents/CHANGES?ref=29afdd2550b3d30a8defece2b95ae81edcf66ac9", "patch": "@@ -1,6 +1,9 @@
                                                          -*- coding: utf-8 -*-
 Changes with Apache 2.5.0

+  *) core: Disallow Methods' registration at runtime (.htaccess), they may be
+     used only if registered at init time (httpd.conf).  [Yann Ylavic]
+
   *) mod_md: v0.9.1:
      - various fixes in MDRenewWindow handling when specifying percent. Serialization changed. If 
        someone already used percent configurations, it is advised to change these to a new value,"}<_**next**_>{"sha": "c9b6837bd41e86da5816cbe1f6693674df0f97f8", "filename": "server/core.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/apache/httpd/blob/29afdd2550b3d30a8defece2b95ae81edcf66ac9/server/core.c", "raw_url": "https://github.com/apache/httpd/raw/29afdd2550b3d30a8defece2b95ae81edcf66ac9/server/core.c", "contents_url": "https://api.github.com/repos/apache/httpd/contents/server/core.c?ref=29afdd2550b3d30a8defece2b95ae81edcf66ac9", "patch": "@@ -2331,6 +2331,12 @@ AP_CORE_DECLARE_NONSTD(const char *) ap_limit_section(cmd_parms *cmd,
             /* method has not been registered yet, but resource restriction
              * is always checked before method handling, so register it.
              */
+            if (cmd->pool == cmd->temp_pool) {
+                /* In .htaccess, we can't globally register new methods. */
+                return apr_psprintf(cmd->pool, "Could not register method '%s' "
+                                   "for %s from .htaccess configuration",
+                                    method, cmd->cmd->name);
+            }
             methnum = ap_method_register(cmd->pool,
                                          apr_pstrdup(cmd->pool, method));
         }"}

