{"sha": "19bc1ad4b2bb5103803a6a813567031cab2cdc78", "filename": "src/gc.c", "status": "modified", "additions": 7, "deletions": 6, "changes": 13, "blob_url": "https://github.com/mruby/mruby/blob/5c114c91d4ff31859fcd84cf8bf349b737b90d99/src/gc.c", "raw_url": "https://github.com/mruby/mruby/raw/5c114c91d4ff31859fcd84cf8bf349b737b90d99/src/gc.c", "contents_url": "https://api.github.com/repos/mruby/mruby/contents/src/gc.c?ref=5c114c91d4ff31859fcd84cf8bf349b737b90d99", "patch": "@@ -544,6 +544,7 @@ mark_context_stack(mrb_state *mrb, struct mrb_context *c)
