+SIZED_STRING* sized_string_dup(
+    SIZED_STRING* s)
+{
+  SIZED_STRING* result = (SIZED_STRING*) yr_malloc(
+      sizeof(SIZED_STRING) + s->length);
+
+  if (result == NULL)
+    return NULL;
+
+  result->length = s->length;
+  result->flags = s->flags;
+
+  strncpy(result->c_string, s->c_string, s->length + 1);
+
+  return result;
+}"}<_**next**_>{"sha": "2a28c005067abdd6471a60278eb4a2b61757cea4", "filename": "tests/test-rules.c", "status": "modified", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/VirusTotal/yara/blob/053e67e3ec81cc9268ce30eaf0d6663d8639ed1e/tests/test-rules.c", "raw_url": "https://github.com/VirusTotal/yara/raw/053e67e3ec81cc9268ce30eaf0d6663d8639ed1e/tests/test-rules.c", "contents_url": "https://api.github.com/repos/VirusTotal/yara/contents/tests/test-rules.c?ref=053e67e3ec81cc9268ce30eaf0d6663d8639ed1e", "patch": "@@ -1439,6 +1439,20 @@ static void test_modules()
