{"sha": "1d1372fb4360abf6a030671ed00e4a191556952e", "filename": "target/i386/translate.c", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/qemu/qemu/blob/30663fd26c0307e414622c7a8607fbc04f92ec14/target/i386/translate.c", "raw_url": "https://github.com/qemu/qemu/raw/30663fd26c0307e414622c7a8607fbc04f92ec14/target/i386/translate.c", "contents_url": "https://api.github.com/repos/qemu/qemu/contents/target/i386/translate.c?ref=30663fd26c0307e414622c7a8607fbc04f92ec14", "patch": "@@ -4418,6 +4418,13 @@ static target_ulong disas_insn(CPUX86State *env, DisasContext *s,
     s->vex_l = 0;
     s->vex_v = 0;
  next_byte:
+    /* x86 has an upper limit of 15 bytes for an instruction. Since we
+     * do not want to decode and generate IR for an illegal
+     * instruction, the following check limits the instruction size to
+     * 25 bytes: 14 prefix + 1 opc + 6 (modrm+sib+ofs) + 4 imm */
+    if (s->pc - pc_start > 14) {
+        goto illegal_op;
+    }
     b = cpu_ldub_code(env, s->pc);
     s->pc++;
     /* Collect prefixes.  */"}

