{"sha": "36674484c6fb9b73011619824f7bc60c50b9c1ad", "filename": "drivers/net/usb/pegasus.c", "status": "modified", "additions": 25, "deletions": 4, "changes": 29, "blob_url": "https://github.com/torvalds/linux/blob/5593523f968bc86d42a035c6df47d5e0979b5ace/drivers/net/usb/pegasus.c", "raw_url": "https://github.com/torvalds/linux/raw/5593523f968bc86d42a035c6df47d5e0979b5ace/drivers/net/usb/pegasus.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/net/usb/pegasus.c?ref=5593523f968bc86d42a035c6df47d5e0979b5ace", "patch": "@@ -126,40 +126,61 @@ static void async_ctrl_callback(struct urb *urb)

 static int get_registers(pegasus_t *pegasus, __u16 indx, __u16 size, void *data)
 {
+	u8 *buf;
 	int ret;

+	buf = kmalloc(size, GFP_NOIO);
+	if (!buf)
+		return -ENOMEM;
+
 	ret = usb_control_msg(pegasus->usb, usb_rcvctrlpipe(pegasus->usb, 0),
 			      PEGASUS_REQ_GET_REGS, PEGASUS_REQT_READ, 0,
-			      indx, data, size, 1000);
+			      indx, buf, size, 1000);
 	if (ret < 0)
 		netif_dbg(pegasus, drv, pegasus->net,
 			  "%s returned %d\n", __func__, ret);
+	else if (ret <= size)
+		memcpy(data, buf, ret);
+	kfree(buf);
 	return ret;
 }

-static int set_registers(pegasus_t *pegasus, __u16 indx, __u16 size, void *data)
+static int set_registers(pegasus_t *pegasus, __u16 indx, __u16 size,
+			 const void *data)
 {
+	u8 *buf;
 	int ret;

+	buf = kmemdup(data, size, GFP_NOIO);
+	if (!buf)
+		return -ENOMEM;
+
 	ret = usb_control_msg(pegasus->usb, usb_sndctrlpipe(pegasus->usb, 0),
 			      PEGASUS_REQ_SET_REGS, PEGASUS_REQT_WRITE, 0,
-			      indx, data, size, 100);
+			      indx, buf, size, 100);
 	if (ret < 0)
 		netif_dbg(pegasus, drv, pegasus->net,
 			  "%s returned %d\n", __func__, ret);
+	kfree(buf);
 	return ret;
 }

 static int set_register(pegasus_t *pegasus, __u16 indx, __u8 data)
 {
+	u8 *buf;
 	int ret;

+	buf = kmemdup(&data, 1, GFP_NOIO);
+	if (!buf)
+		return -ENOMEM;
+
 	ret = usb_control_msg(pegasus->usb, usb_sndctrlpipe(pegasus->usb, 0),
 			      PEGASUS_REQ_SET_REG, PEGASUS_REQT_WRITE, data,
-			      indx, &data, 1, 1000);
+			      indx, buf, 1, 1000);
 	if (ret < 0)
 		netif_dbg(pegasus, drv, pegasus->net,
 			  "%s returned %d\n", __func__, ret);
+	kfree(buf);
 	return ret;
 }
 "}

{"sha": "e9b7e0b3cabe60d3be3ab8a092159b137854d8ec", "filename": "drivers/char/virtio_console.c", "status": "modified", "additions": 10, "deletions": 2, "changes": 12, "blob_url": "https://github.com/torvalds/linux/blob/c4baad50297d84bde1a7ad45e50c73adae4a2192/drivers/char/virtio_console.c", "raw_url": "https://github.com/torvalds/linux/raw/c4baad50297d84bde1a7ad45e50c73adae4a2192/drivers/char/virtio_console.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/char/virtio_console.c?ref=c4baad50297d84bde1a7ad45e50c73adae4a2192", "patch": "@@ -1136,6 +1136,8 @@ static int put_chars(u32 vtermno, const char *buf, int count)
