{"sha": "51620e02292f588b6643862c3207aa6d5cd75948", "filename": "drivers/media/usb/dvb-usb/cxusb.c", "status": "modified", "additions": 8, "deletions": 7, "changes": 15, "blob_url": "https://github.com/torvalds/linux/blob/3f190e3aec212fc8c61e202c51400afa7384d4bc/drivers/media/usb/dvb-usb/cxusb.c", "raw_url": "https://github.com/torvalds/linux/raw/3f190e3aec212fc8c61e202c51400afa7384d4bc/drivers/media/usb/dvb-usb/cxusb.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/media/usb/dvb-usb/cxusb.c?ref=3f190e3aec212fc8c61e202c51400afa7384d4bc", "patch": "@@ -59,23 +59,24 @@ static int cxusb_ctrl_msg(struct dvb_usb_device *d,
 			  u8 cmd, u8 *wbuf, int wlen, u8 *rbuf, int rlen)
 {
 	struct cxusb_state *st = d->priv;
-	int ret, wo;
+	int ret;

 	if (1 + wlen > MAX_XFER_SIZE) {
 		warn("i2c wr: len=%d is too big!\n", wlen);
 		return -EOPNOTSUPP;
 	}

-	wo = (rbuf == NULL || rlen == 0); /* write-only */
+	if (rlen > MAX_XFER_SIZE) {
+		warn("i2c rd: len=%d is too big!\n", rlen);
+		return -EOPNOTSUPP;
+	}

 	mutex_lock(&d->data_mutex);
 	st->data[0] = cmd;
 	memcpy(&st->data[1], wbuf, wlen);
-	if (wo)
-		ret = dvb_usb_generic_write(d, st->data, 1 + wlen);
