{"sha": "889e7619a0914d87ad49dbb5b960933e5dd316ad", "filename": "arch/x86/mm/init.c", "status": "modified", "additions": 30, "deletions": 11, "changes": 41, "blob_url": "https://github.com/torvalds/linux/blob/a4866aa812518ed1a37d8ea0c881dc946409de94/arch/x86/mm/init.c", "raw_url": "https://github.com/torvalds/linux/raw/a4866aa812518ed1a37d8ea0c881dc946409de94/arch/x86/mm/init.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/x86/mm/init.c?ref=a4866aa812518ed1a37d8ea0c881dc946409de94", "patch": "@@ -643,21 +643,40 @@ void __init init_mem_mapping(void)
  * devmem_is_allowed() checks to see if /dev/mem access to a certain address
  * is valid. The argument is a physical page number.
  *
- *
- * On x86, access has to be given to the first megabyte of ram because that area
- * contains BIOS code and data regions used by X and dosemu and similar apps.
- * Access has to be given to non-kernel-ram areas as well, these contain the PCI
- * mmio resources as well as potential bios/acpi data regions.
+ * On x86, access has to be given to the first megabyte of RAM because that
+ * area traditionally contains BIOS code and data regions used by X, dosemu,
+ * and similar apps. Since they map the entire memory range, the whole range
+ * must be allowed (for mapping), but any areas that would otherwise be
+ * disallowed are flagged as being "zero filled" instead of rejected.
+ * Access has to be given to non-kernel-ram areas as well, these contain the
+ * PCI mmio resources as well as potential bios/acpi data regions.
  */
 int devmem_is_allowed(unsigned long pagenr)
 {
-	if (pagenr < 256)
-		return 1;
-	if (iomem_is_exclusive(pagenr << PAGE_SHIFT))
+	if (page_is_ram(pagenr)) {
+		/*
+		 * For disallowed memory regions in the low 1MB range,
+		 * request that the page be shown as all zeros.
+		 */
+		if (pagenr < 256)
+			return 2;
+
+		return 0;
+	}
+
+	/*
+	 * This must follow RAM test, since System RAM is considered a
+	 * restricted resource under CONFIG_STRICT_IOMEM.
+	 */
+	if (iomem_is_exclusive(pagenr << PAGE_SHIFT)) {
+		/* Low 1MB bypasses iomem restrictions. */
+		if (pagenr < 256)
+			return 1;
+
 		return 0;
-	if (!page_is_ram(pagenr))
-		return 1;
-	return 0;
+	}
+
+	return 1;
 }

 void free_init_pages(char *what, unsigned long begin, unsigned long end)"}<_**next**_>{"sha": "7e4a9d1296bb7fb666f6b37ced2757a8585b7d75", "filename": "drivers/char/mem.c", "status": "modified", "additions": 52, "deletions": 30, "changes": 82, "blob_url": "https://github.com/torvalds/linux/blob/a4866aa812518ed1a37d8ea0c881dc946409de94/drivers/char/mem.c", "raw_url": "https://github.com/torvalds/linux/raw/a4866aa812518ed1a37d8ea0c881dc946409de94/drivers/char/mem.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/char/mem.c?ref=a4866aa812518ed1a37d8ea0c881dc946409de94", "patch": "@@ -60,6 +60,10 @@ static inline int valid_mmap_phys_addr_range(unsigned long pfn, size_t size)
