{"sha": "831f3a9a8f05282b8ba9aae9c6ed963334b9b8f3", "filename": "fs/dcache.c", "status": "modified", "additions": 27, "deletions": 0, "changes": 27, "blob_url": "https://github.com/torvalds/linux/blob/49d31c2f389acfe83417083e1208422b4091cd9e/fs/dcache.c", "raw_url": "https://github.com/torvalds/linux/raw/49d31c2f389acfe83417083e1208422b4091cd9e/fs/dcache.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/dcache.c?ref=49d31c2f389acfe83417083e1208422b4091cd9e", "patch": "@@ -277,6 +277,33 @@ static inline int dname_external(const struct dentry *dentry)
 	return dentry->d_name.name != dentry->d_iname;
 }

+void take_dentry_name_snapshot(struct name_snapshot *name, struct dentry *dentry)
+{
+	spin_lock(&dentry->d_lock);
+	if (unlikely(dname_external(dentry))) {
+		struct external_name *p = external_name(dentry);
+		atomic_inc(&p->u.count);
+		spin_unlock(&dentry->d_lock);
+		name->name = p->name;
+	} else {
+		memcpy(name->inline_name, dentry->d_iname, DNAME_INLINE_LEN);
+		spin_unlock(&dentry->d_lock);
+		name->name = name->inline_name;
+	}
+}
+EXPORT_SYMBOL(take_dentry_name_snapshot);
+
+void release_dentry_name_snapshot(struct name_snapshot *name)
+{
+	if (unlikely(name->name != name->inline_name)) {
+		struct external_name *p;
+		p = container_of(name->name, struct external_name, name[0]);
+		if (unlikely(atomic_dec_and_test(&p->u.count)))
+			kfree_rcu(p, u.head);
+	}
+}
+EXPORT_SYMBOL(release_dentry_name_snapshot);
+
 static inline void __d_set_inode_and_type(struct dentry *dentry,
 					  struct inode *inode,
 					  unsigned type_flags)"}<_**next**_>{"sha": "acd3be2cc691bb577916aa552668d2c1d179ed69", "filename": "fs/debugfs/inode.c", "status": "modified", "additions": 5, "deletions": 5, "changes": 10, "blob_url": "https://github.com/torvalds/linux/blob/49d31c2f389acfe83417083e1208422b4091cd9e/fs/debugfs/inode.c", "raw_url": "https://github.com/torvalds/linux/raw/49d31c2f389acfe83417083e1208422b4091cd9e/fs/debugfs/inode.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/debugfs/inode.c?ref=49d31c2f389acfe83417083e1208422b4091cd9e", "patch": "@@ -766,7 +766,7 @@ struct dentry *debugfs_rename(struct dentry *old_dir, struct dentry *old_dentry,
