{"sha": "250c2df04a92c5feee85c6e07c75940dc0af5392", "filename": "fs/ext4/inode.c", "status": "modified", "additions": 15, "deletions": 9, "changes": 24, "blob_url": "https://github.com/torvalds/linux/blob/06bd3c36a733ac27962fea7d6f47168841376824/fs/ext4/inode.c", "raw_url": "https://github.com/torvalds/linux/raw/06bd3c36a733ac27962fea7d6f47168841376824/fs/ext4/inode.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/ext4/inode.c?ref=06bd3c36a733ac27962fea7d6f47168841376824", "patch": "@@ -684,6 +684,21 @@ int ext4_map_blocks(handle_t *handle, struct inode *inode,
