{"sha": "6e535bbb7a66d5babfc08807099ecd7a6d80a5da", "filename": "modules/mod_auth.c", "status": "modified", "additions": 58, "deletions": 15, "changes": 73, "blob_url": "https://github.com/proftpd/proftpd/blob/349addc3be4fcdad9bd4ec01ad1ccd916c898ed8/modules/mod_auth.c", "raw_url": "https://github.com/proftpd/proftpd/raw/349addc3be4fcdad9bd4ec01ad1ccd916c898ed8/modules/mod_auth.c", "contents_url": "https://api.github.com/repos/proftpd/proftpd/contents/modules/mod_auth.c?ref=349addc3be4fcdad9bd4ec01ad1ccd916c898ed8", "patch": "@@ -804,6 +804,59 @@ static const char *get_default_chdir(pool *p, xaset_t *conf) {
   return dir;
 }

+static int is_symlink_path(pool *p, const char *path, size_t pathlen) {
+  int res, xerrno = 0;
+  struct stat st;
+  char *ptr;
+
+  if (pathlen == 0) {
+    return 0;
+  }
+
+  pr_fs_clear_cache2(path);
+  res = pr_fsio_lstat(path, &st);
+  if (res < 0) {
+    xerrno = errno;
+
+    pr_log_pri(PR_LOG_WARNING, "error: unable to check %s: %s", path,
+      strerror(xerrno));
+
+    errno = xerrno;
+    return -1;
+  }
+
+  if (S_ISLNK(st.st_mode)) {
+    errno = EPERM;
+    return -1;
+  }
+
+  /* To handle the case where a component further up the path might be a
+   * symlink (which lstat(2) will NOT handle), we walk the path backwards,
+   * calling ourselves recursively.
+   */
+
+  ptr = strrchr(path, '/');
+  if (ptr != NULL) {
+    char *new_path;
+    size_t new_pathlen;
+
+    pr_signals_handle();
+
+    new_pathlen = ptr - path;
+    new_path = pstrndup(p, path, new_pathlen);
+
+    pr_log_debug(DEBUG10,
+      "AllowChrootSymlink: path '%s' not a symlink, checking '%s'", path,
+      new_path);
+    res = is_symlink_path(p, new_path, new_pathlen);
+    if (res < 0) {
+      return -1;
+    }
+  }
+
+  return 0;
+}
+
