           errno = EPERM;
           return -1;
         }"}<_**next**_>{"sha": "8872231db18a970369799ece823cc1d8325aafde", "filename": "tests/t/lib/ProFTPD/TestSuite/Utils.pm", "status": "modified", "additions": 14, "deletions": 9, "changes": 23, "blob_url": "https://github.com/proftpd/proftpd/blob/349addc3be4fcdad9bd4ec01ad1ccd916c898ed8/tests/t/lib/ProFTPD/TestSuite/Utils.pm", "raw_url": "https://github.com/proftpd/proftpd/raw/349addc3be4fcdad9bd4ec01ad1ccd916c898ed8/tests/t/lib/ProFTPD/TestSuite/Utils.pm", "contents_url": "https://api.github.com/repos/proftpd/proftpd/contents/tests/t/lib/ProFTPD/TestSuite/Utils.pm?ref=349addc3be4fcdad9bd4ec01ad1ccd916c898ed8", "patch": "@@ -1198,6 +1198,7 @@ sub test_setup {
