{"sha": "b1fbd1958eb6387137f77bc53a1f31dd952b21c8", "filename": "net/core/skbuff.c", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/torvalds/linux/blob/8605330aac5a5785630aec8f64378a54891937cc/net/core/skbuff.c", "raw_url": "https://github.com/torvalds/linux/raw/8605330aac5a5785630aec8f64378a54891937cc/net/core/skbuff.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/net/core/skbuff.c?ref=8605330aac5a5785630aec8f64378a54891937cc", "patch": "@@ -3694,6 +3694,15 @@ static void sock_rmem_free(struct sk_buff *skb)
