{"sha": "594756db6b7cd43d0a2c6e93cb5ab2686ac1507f", "filename": "ext/standard/tests/streams/parseip-001.phpt", "status": "added", "additions": 37, "deletions": 0, "changes": 37, "blob_url": "https://github.com/php/php-src/blob/bab0b99f376dac9170ac81382a5ed526938d595a/ext/standard/tests/streams/parseip-001.phpt", "raw_url": "https://github.com/php/php-src/raw/bab0b99f376dac9170ac81382a5ed526938d595a/ext/standard/tests/streams/parseip-001.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/standard/tests/streams/parseip-001.phpt?ref=bab0b99f376dac9170ac81382a5ed526938d595a", "patch": "@@ -0,0 +1,37 @@
+--TEST--
+Use of double-port in fsockopen()
+--FILE--
+<?php
+
+$try = [
+  '127.0.0.1:80',
+  'tcp://127.0.0.1:80',
+  '[::1]:80',
+  'tcp://[::1]:80',
+  'localhost:80',
+  'tcp://localhost:80',
+];
+
+foreach ($try as $addr) {
+  echo "== $addr ==\n";
+  var_dump(@fsockopen($addr, 81, $errno, $errstr), $errstr);
+}
+--EXPECTF--
+== 127.0.0.1:80 ==
+bool(false)
+string(41) "Failed to parse address "127.0.0.1:80:81""
+== tcp://127.0.0.1:80 ==
+bool(false)
+string(41) "Failed to parse address "127.0.0.1:80:81""
+== [::1]:80 ==
+bool(false)
+string(37) "Failed to parse address "[::1]:80:81""
+== tcp://[::1]:80 ==
+bool(false)
+string(37) "Failed to parse address "[::1]:80:81""
+== localhost:80 ==
+bool(false)
+string(41) "Failed to parse address "localhost:80:81""
+== tcp://localhost:80 ==
+bool(false)
+string(41) "Failed to parse address "localhost:80:81""
\ No newline at end of file"}<_**next**_>{"sha": "3ff64787aa147968261ad03c2daf85920784be81", "filename": "main/streams/xp_socket.c", "status": "modified", "additions": 18, "deletions": 11, "changes": 29, "blob_url": "https://github.com/php/php-src/blob/bab0b99f376dac9170ac81382a5ed526938d595a/main/streams/xp_socket.c", "raw_url": "https://github.com/php/php-src/raw/bab0b99f376dac9170ac81382a5ed526938d595a/main/streams/xp_socket.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/main/streams/xp_socket.c?ref=bab0b99f376dac9170ac81382a5ed526938d595a", "patch": "@@ -571,37 +571,44 @@ static inline char *parse_ip_address_ex(const char *str, size_t str_len, int *po
