{"sha": "79d93e7f7b55838b76177f3a958a88a87f1f7f4d", "filename": "ChangeLog", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/ImageMagick/ImageMagick/blob/3358f060fc182551822576b2c0a8850faab5d543/ChangeLog", "raw_url": "https://github.com/ImageMagick/ImageMagick/raw/3358f060fc182551822576b2c0a8850faab5d543/ChangeLog", "contents_url": "https://api.github.com/repos/ImageMagick/ImageMagick/contents/ChangeLog?ref=3358f060fc182551822576b2c0a8850faab5d543", "patch": "@@ -1,3 +1,7 @@
+2017-02-09  6.9.7-8 Dirk Lemstra <dirk@lem.....org>
+  * Fixed memory leak when creating nested exceptions in Magick++ (reference
+    https://www.imagemagick.org/discourse-server/viewtopic.php?f=23&p=142634)
+
 2017-02-06  6.9.7-8 Cristy  <quetzlzacatenango@image...>
   * Eliminate bogus assertion (reference
     https://github.com/ImageMagick/ImageMagick/issues/372)."}<_**next**_>{"sha": "8ef34bc0a06a11d81474ca8634ec8791beb9108f", "filename": "Magick++/lib/Exception.cpp", "status": "modified", "additions": 10, "deletions": 4, "changes": 14, "blob_url": "https://github.com/ImageMagick/ImageMagick/blob/3358f060fc182551822576b2c0a8850faab5d543/Magick++/lib/Exception.cpp", "raw_url": "https://github.com/ImageMagick/ImageMagick/raw/3358f060fc182551822576b2c0a8850faab5d543/Magick++/lib/Exception.cpp", "contents_url": "https://api.github.com/repos/ImageMagick/ImageMagick/contents/Magick++/lib/Exception.cpp?ref=3358f060fc182551822576b2c0a8850faab5d543", "patch": "@@ -852,12 +852,18 @@ MagickPPExport void Magick::throwException(ExceptionInfo *exception_,
             exception_->description) != 0))
           {
             if (nestedException == (Exception *) NULL)
-              nestedException=createException(p);
+              {
+                nestedException=createException(p);
+                q=nestedException;
+              }
             else
               {
-                q=createException(p);
-                nestedException->nested(q);
-                nestedException=q;
+                Exception
+                  *r;
+
+                r=createException(p);
+                q->nested(r);
+                q=r;
               }
           }
       }"}

