{"sha": "20e5090e6755052a72fd939ca9ea53aa5ca8ba29", "filename": "src/bplist.c", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/libimobiledevice/libplist/blob/fbd8494d5e4e46bf2e90cb6116903e404374fb56/src/bplist.c", "raw_url": "https://github.com/libimobiledevice/libplist/raw/fbd8494d5e4e46bf2e90cb6116903e404374fb56/src/bplist.c", "contents_url": "https://api.github.com/repos/libimobiledevice/libplist/contents/src/bplist.c?ref=fbd8494d5e4e46bf2e90cb6116903e404374fb56", "patch": "@@ -289,6 +289,11 @@ static plist_t parse_string_node(const char **bnode, uint64_t size)

     data->type = PLIST_STRING;
     data->strval = (char *) malloc(sizeof(char) * (size + 1));
+    if (!data->strval) {
+        plist_free_data(data);
+        PLIST_BIN_ERR("%s: Could not allocate %" PRIu64 " bytes\n", __func__, sizeof(char) * (size + 1));
+        return NULL;
+    }
     memcpy(data->strval, *bnode, size);
     data->strval[size] = '\0';
     data->length = strlen(data->strval);"}

