{"sha": "c23909c5c1f3f08321428ad7f920e4a0b89ee023", "filename": "src/alloc.c", "status": "modified", "additions": 39, "deletions": 16, "changes": 55, "blob_url": "https://github.com/verdammelt/tnef/blob/c5044689e50039635e7700fe2472fd632ac77176/src/alloc.c", "raw_url": "https://github.com/verdammelt/tnef/raw/c5044689e50039635e7700fe2472fd632ac77176/src/alloc.c", "contents_url": "https://api.github.com/repos/verdammelt/tnef/contents/src/alloc.c?ref=c5044689e50039635e7700fe2472fd632ac77176", "patch": "@@ -40,14 +40,23 @@ get_alloc_limit()
     return alloc_limit;
 }

+size_t
+check_mul_overflow(size_t a, size_t b, size_t* res)
+{
+    size_t tmp = a * b;
+    if (a != 0 && tmp / a != b) return 1;
+    *res = tmp;
+    return 0;
+}
+
 static void
 alloc_limit_failure (char *fn_name, size_t size)
 {
-    fprintf (stderr, 
+    fprintf (stderr,
              "%s: Maximum allocation size exceeded "
              "(maxsize = %lu; size = %lu).\n",
              fn_name,
-             (unsigned long)alloc_limit, 
+             (unsigned long)alloc_limit,
              (unsigned long)size);
 }

@@ -56,17 +65,21 @@ alloc_limit_assert (char *fn_name, size_t size)
 {
     if (alloc_limit && size > alloc_limit)
     {
-	alloc_limit_failure (fn_name, size);
-	exit (-1);
+        alloc_limit_failure (fn_name, size);
+        exit (-1);
     }
 }

 /* attempts to malloc memory, if fails print error and call abort */
 void*
-xmalloc (size_t size)
+xmalloc (size_t num, size_t size)
 {
-    void *ptr = malloc (size);
-    if (!ptr 
+    size_t res;
+    if (check_mul_overflow(num, size, &res))
+        abort();
+
+    void *ptr = malloc (res);
+    if (!ptr
         && (size != 0))         /* some libc don't like size == 0 */
     {
         perror ("xmalloc: Memory allocation failure");
@@ -77,20 +90,29 @@ xmalloc (size_t size)

 /* Allocates memory but only up to a limit */
 void*
-checked_xmalloc (size_t size)
+checked_xmalloc (size_t num, size_t size)
 {
-    alloc_limit_assert ("checked_xmalloc", size);
-    return xmalloc (size);
+    size_t res;
+    if (check_mul_overflow(num, size, &res))
+        abort();
+
+    alloc_limit_assert ("checked_xmalloc", res);
+    return xmalloc (num, size);
 }

 /* xmallocs memory and clears it out */
 void*
 xcalloc (size_t num, size_t size)
 {
-    void *ptr = malloc(num * size);
+    size_t res;
+    if (check_mul_overflow(num, size, &res))
+        abort();
+
+    void *ptr;
+    ptr = malloc(res);
     if (ptr)
     {
-        memset (ptr, '\0', (num * size));
+        memset (ptr, '\0', (res));
     }
     return ptr;
 }
@@ -99,9 +121,10 @@ xcalloc (size_t num, size_t size)
 void*
 checked_xcalloc (size_t num, size_t size)
 {
-    alloc_limit_assert ("checked_xcalloc", (num *size));
+    size_t res;
+    if (check_mul_overflow(num, size, &res))
+        abort();
+
+    alloc_limit_assert ("checked_xcalloc", (res));
     return xcalloc (num, size);
 }
-
-
-"}<_**next**_>{"sha": "8fbd6bf97e6192728c0f3fd82b35a9403ec054e0", "filename": "src/alloc.h", "status": "modified", "additions": 5, "deletions": 5, "changes": 10, "blob_url": "https://github.com/verdammelt/tnef/blob/c5044689e50039635e7700fe2472fd632ac77176/src/alloc.h", "raw_url": "https://github.com/verdammelt/tnef/raw/c5044689e50039635e7700fe2472fd632ac77176/src/alloc.h", "contents_url": "https://api.github.com/repos/verdammelt/tnef/contents/src/alloc.h?ref=c5044689e50039635e7700fe2472fd632ac77176", "patch": "@@ -35,20 +35,20 @@ extern void free (void*);
