{"sha": "c7013e26e7ead68a98796f39bb93ad00b7990322", "filename": "ChangeLog", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/ImageMagick/ImageMagick/blob/c073a7712d82476b5fbee74856c46b88af9c3175/ChangeLog", "raw_url": "https://github.com/ImageMagick/ImageMagick/raw/c073a7712d82476b5fbee74856c46b88af9c3175/ChangeLog", "contents_url": "https://api.github.com/repos/ImageMagick/ImageMagick/contents/ChangeLog?ref=c073a7712d82476b5fbee74856c46b88af9c3175", "patch": "@@ -1,3 +1,7 @@
+2017-01-04  6.9.7-3 Cristy  <quetzlzacatenango@image...>
