{"sha": "b9a982d776a62e8200bbf0db7916d8ccece262a4", "filename": "RELNOTES", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/netblue30/firejail/blob/5d43fdcd215203868d440ffc42036f5f5ffc89fc/RELNOTES", "raw_url": "https://github.com/netblue30/firejail/raw/5d43fdcd215203868d440ffc42036f5f5ffc89fc/RELNOTES", "contents_url": "https://api.github.com/repos/netblue30/firejail/contents/RELNOTES?ref=5d43fdcd215203868d440ffc42036f5f5ffc89fc", "patch": "@@ -1,5 +1,6 @@
 firejail (0.9.45) baseline; urgency=low
   * development version, work in progress
+  * security: --bandwidth root shel found by Martin Carpenter
   * security: disabled --allow-debuggers when running on kernel
