{"sha": "36da0100f301b3b6c7ef861b1163699e2c8b6942", "filename": "RELNOTES", "status": "modified", "additions": 3, "deletions": 0, "changes": 3, "blob_url": "https://github.com/netblue30/firejail/blob/6b8dba29d73257311564ee7f27b9b14758cc693e/RELNOTES", "raw_url": "https://github.com/netblue30/firejail/raw/6b8dba29d73257311564ee7f27b9b14758cc693e/RELNOTES", "contents_url": "https://api.github.com/repos/netblue30/firejail/contents/RELNOTES?ref=6b8dba29d73257311564ee7f27b9b14758cc693e", "patch": "@@ -1,5 +1,8 @@
 firejail (0.9.44.3) baseline; urgency=low
   * development version
+  * security: disabled --allow-debuggers when running on kernel
+    versions prior to 4.8; a kernel bug in ptrace system call
+    allows a full bypass of seccomp filter; problem reported by Lizzie Dixon
   * security: root exploit found by Sebastian Krahmer
  -- netblue30 <netblue30@yahoo.com>  Wed, 4 Jan 2017 11:00:00 -0500
 "}<_**next**_>{"sha": "e67290911c494cea20055ae442737e31ae69185d", "filename": "src/firejail/main.c", "status": "modified", "additions": 19, "deletions": 0, "changes": 19, "blob_url": "https://github.com/netblue30/firejail/blob/6b8dba29d73257311564ee7f27b9b14758cc693e/src/firejail/main.c", "raw_url": "https://github.com/netblue30/firejail/raw/6b8dba29d73257311564ee7f27b9b14758cc693e/src/firejail/main.c", "contents_url": "https://api.github.com/repos/netblue30/firejail/contents/src/firejail/main.c?ref=6b8dba29d73257311564ee7f27b9b14758cc693e", "patch": "@@ -35,6 +35,7 @@
 #include <signal.h>
 #include <time.h>
 #include <net/if.h>
+#include <sys/utsname.h>

 #if 0
 #include <sys/times.h>
@@ -802,6 +803,24 @@ static void detect_allow_debuggers(int argc, char **argv) {
 	// detect --allow-debuggers
 	for (i = 1; i < argc; i++) {
 		if (strcmp(argv[i], "--allow-debuggers") == 0) {
+			// check kernel version
+			struct utsname u;
+			int rv = uname(&u);
+			if (rv != 0)
+				errExit("uname");
+			int major;
+			int minor;
+			if (2 != sscanf(u.release, "%d.%d", &major, &minor)) {
+				fprintf(stderr, "Error: cannot extract Linux kernel version: %s\n", u.version);
+				exit(1);
+			}
+			if (major < 4 || (major == 4 && minor < 8)) {
+				fprintf(stderr, "Error: --allow-debuggers is disabled on Linux kernels prior to 4.8. "
+					"A bug in ptrace call allows a full bypass of the seccomp filter. "
+					"Your current kernel version is %d.%d.\n", major, minor);
+				exit(1);
+			}
+			
 			arg_allow_debuggers = 1;
 			break;
 		}"}<_**next**_>{"sha": "332f510c65415579eccfeee648030fc4dc0f6207", "filename": "src/man/firejail.txt", "status": "modified", "additions": 3, "deletions": 1, "changes": 4, "blob_url": "https://github.com/netblue30/firejail/blob/6b8dba29d73257311564ee7f27b9b14758cc693e/src/man/firejail.txt", "raw_url": "https://github.com/netblue30/firejail/raw/6b8dba29d73257311564ee7f27b9b14758cc693e/src/man/firejail.txt", "contents_url": "https://api.github.com/repos/netblue30/firejail/contents/src/man/firejail.txt?ref=6b8dba29d73257311564ee7f27b9b14758cc693e", "patch": "@@ -76,7 +76,9 @@ $ firejail [OPTIONS] firefox        # starting Mozilla Firefox
 Signal the end of options and disables further option processing.
 .TP
 \fB\-\-allow-debuggers
-Allow tools such as strace and gdb inside the sandbox.
+Allow tools such as strace and gdb inside the sandbox. This option is only available
+when running on Linux kernels 4.8 or newer - a kernel bug in ptrace system call allows a full
+bypass of the seccomp filter.
 .br

 .br"}

