{"sha": "9dbc7a0cff92bd8d43b4151b30f7d27995a506f8", "filename": "ChangeLog", "status": "modified", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/vadz/libtiff/blob/9a72a69e035ee70ff5c41541c8c61cd97990d018/ChangeLog", "raw_url": "https://github.com/vadz/libtiff/raw/9a72a69e035ee70ff5c41541c8c61cd97990d018/ChangeLog", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/ChangeLog?ref=9a72a69e035ee70ff5c41541c8c61cd97990d018", "patch": "@@ -1,3 +1,18 @@
+2016-12-03 Even Rouault <even.rouault at spatialys.com>
+
+	* libtiff/tif_dirread.c: modify ChopUpSingleUncompressedStrip() to
+	instanciate compute ntrips as TIFFhowmany_32(td->td_imagelength, rowsperstrip),
+	instead of a logic based on the total size of data. Which is faulty is
+	the total size of data is not sufficient to fill the whole image, and thus
+	results in reading outside of the StripByCounts/StripOffsets arrays when
+	using TIFFReadScanline().
+	Reported by Agostino Sarubbo.
+	Fixes http://bugzilla.maptools.org/show_bug.cgi?id=2608.
+
+	* libtiff/tif_strip.c: revert the change in TIFFNumberOfStrips() done
+	for http://bugzilla.maptools.org/show_bug.cgi?id=2587 / CVE-2016-9273 since
+	the above change is a better fix that makes it unnecessary.
+
 2016-12-03 Even Rouault <even.rouault at spatialys.com>

 	* libtiff/tif_pixarlog.c, libtiff/tif_luv.c: fix heap-based buffer"}<_**next**_>{"sha": "570d0c3273890de73dc12df871e22eaed2a0695b", "filename": "libtiff/tif_dirread.c", "status": "modified", "additions": 10, "deletions": 12, "changes": 22, "blob_url": "https://github.com/vadz/libtiff/blob/9a72a69e035ee70ff5c41541c8c61cd97990d018/libtiff/tif_dirread.c", "raw_url": "https://github.com/vadz/libtiff/raw/9a72a69e035ee70ff5c41541c8c61cd97990d018/libtiff/tif_dirread.c", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/libtiff/tif_dirread.c?ref=9a72a69e035ee70ff5c41541c8c61cd97990d018", "patch": "@@ -5502,8 +5502,7 @@ ChopUpSingleUncompressedStrip(TIFF* tif)
 	uint64 rowblockbytes;
 	uint64 stripbytes;
 	uint32 strip;
-	uint64 nstrips64;
-	uint32 nstrips32;
+	uint32 nstrips;
 	uint32 rowsperstrip;
 	uint64* newcounts;
 	uint64* newoffsets;
@@ -5534,18 +5533,17 @@ ChopUpSingleUncompressedStrip(TIFF* tif)
 	    return;

 	/*
-	 * never increase the number of strips in an image
+	 * never increase the number of rows per strip
 	 */
 	if (rowsperstrip >= td->td_rowsperstrip)
 		return;
-	nstrips64 = TIFFhowmany_64(bytecount, stripbytes);
-	if ((nstrips64==0)||(nstrips64>0xFFFFFFFF)) /* something is wonky, do nothing. */
-	    return;
-	nstrips32 = (uint32)nstrips64;
+        nstrips = TIFFhowmany_32(td->td_imagelength, rowsperstrip);
+        if( nstrips == 0 )
+            return;

-	newcounts = (uint64*) _TIFFCheckMalloc(tif, nstrips32, sizeof (uint64),
+	newcounts = (uint64*) _TIFFCheckMalloc(tif, nstrips, sizeof (uint64),
 				"for chopped \"StripByteCounts\" array");
-	newoffsets = (uint64*) _TIFFCheckMalloc(tif, nstrips32, sizeof (uint64),
+	newoffsets = (uint64*) _TIFFCheckMalloc(tif, nstrips, sizeof (uint64),
 				"for chopped \"StripOffsets\" array");
 	if (newcounts == NULL || newoffsets == NULL) {
 		/*
@@ -5562,18 +5560,18 @@ ChopUpSingleUncompressedStrip(TIFF* tif)
 	 * Fill the strip information arrays with new bytecounts and offsets
 	 * that reflect the broken-up format.
 	 */
-	for (strip = 0; strip < nstrips32; strip++) {
+	for (strip = 0; strip < nstrips; strip++) {
 		if (stripbytes > bytecount)
 			stripbytes = bytecount;
 		newcounts[strip] = stripbytes;
-		newoffsets[strip] = offset;
+		newoffsets[strip] = stripbytes ? offset : 0;
 		offset += stripbytes;
 		bytecount -= stripbytes;
 	}
 	/*
 	 * Replace old single strip info with multi-strip info.
 	 */
-	td->td_stripsperimage = td->td_nstrips = nstrips32;
+	td->td_stripsperimage = td->td_nstrips = nstrips;
 	TIFFSetField(tif, TIFFTAG_ROWSPERSTRIP, rowsperstrip);

 	_TIFFfree(td->td_stripbytecount);"}<_**next**_>{"sha": "1676e47d34311adf2302d4136c6fe6ed85aff2f9", "filename": "libtiff/tif_strip.c", "status": "modified", "additions": 0, "deletions": 9, "changes": 9, "blob_url": "https://github.com/vadz/libtiff/blob/9a72a69e035ee70ff5c41541c8c61cd97990d018/libtiff/tif_strip.c", "raw_url": "https://github.com/vadz/libtiff/raw/9a72a69e035ee70ff5c41541c8c61cd97990d018/libtiff/tif_strip.c", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/libtiff/tif_strip.c?ref=9a72a69e035ee70ff5c41541c8c61cd97990d018", "patch": "@@ -63,15 +63,6 @@ TIFFNumberOfStrips(TIFF* tif)
 	TIFFDirectory *td = &tif->tif_dir;
 	uint32 nstrips;

-    /* If the value was already computed and store in td_nstrips, then return it,
-       since ChopUpSingleUncompressedStrip might have altered and resized the
-       since the td_stripbytecount and td_stripoffset arrays to the new value
-       after the initial affectation of td_nstrips = TIFFNumberOfStrips() in
-       tif_dirread.c ~line 3612.
-       See http://bugzilla.maptools.org/show_bug.cgi?id=2587 */
-    if( td->td_nstrips )
-        return td->td_nstrips;
-
 	nstrips = (td->td_rowsperstrip == (uint32) -1 ? 1 :
 	     TIFFhowmany_32(td->td_imagelength, td->td_rowsperstrip));
 	if (td->td_planarconfig == PLANARCONFIG_SEPARATE)"}

{"sha": "93c01f80edf83e0a0d25b8f587a481492f322a80", "filename": "ChangeLog", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/vadz/libtiff/blob/1044b43637fa7f70fb19b93593777b78bd20da86/ChangeLog", "raw_url": "https://github.com/vadz/libtiff/raw/1044b43637fa7f70fb19b93593777b78bd20da86/ChangeLog", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/ChangeLog?ref=1044b43637fa7f70fb19b93593777b78bd20da86", "patch": "@@ -1,3 +1,13 @@
+2016-12-03 Even Rouault <even.rouault at spatialys.com>
+
+	* libtiff/tif_pixarlog.c, libtiff/tif_luv.c: fix heap-based buffer
+	overflow on generation of PixarLog / LUV compressed files, with
+	ColorMap, TransferFunction attached and nasty plays with bitspersample.
+	The fix for LUV has not been tested, but suffers from the same kind
+	of issue of PixarLog.
+	Reported by Agostino Sarubbo.
+	Fixes http://bugzilla.maptools.org/show_bug.cgi?id=2604
+
 2016-12-02 Even Rouault <even.rouault at spatialys.com>

 	* tools/tiffcp.c: avoid uint32 underflow in cpDecodedStrips that "}<_**next**_>{"sha": "e6783db5674c31c9699240001fb54c16e518cda7", "filename": "libtiff/tif_luv.c", "status": "modified", "additions": 14, "deletions": 4, "changes": 18, "blob_url": "https://github.com/vadz/libtiff/blob/1044b43637fa7f70fb19b93593777b78bd20da86/libtiff/tif_luv.c", "raw_url": "https://github.com/vadz/libtiff/raw/1044b43637fa7f70fb19b93593777b78bd20da86/libtiff/tif_luv.c", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/libtiff/tif_luv.c?ref=1044b43637fa7f70fb19b93593777b78bd20da86", "patch": "@@ -158,6 +158,7 @@
 typedef struct logLuvState LogLuvState;

 struct logLuvState {
+        int                     encoder_state;  /* 1 if encoder correctly initialized */
 	int                     user_datafmt;   /* user data format */
 	int                     encode_meth;    /* encoding method */
 	int                     pixel_size;     /* bytes per pixel */
@@ -1552,6 +1553,7 @@ LogLuvSetupEncode(TIFF* tif)
 		    td->td_photometric, "must be either LogLUV or LogL");
 		break;
 	}
+	sp->encoder_state = 1;
 	return (1);
 notsupported:
 	TIFFErrorExt(tif->tif_clientdata, module,
@@ -1563,19 +1565,27 @@ LogLuvSetupEncode(TIFF* tif)
 static void
 LogLuvClose(TIFF* tif)
 {
+        LogLuvState* sp = (LogLuvState*) tif->tif_data;
 	TIFFDirectory *td = &tif->tif_dir;

+	assert(sp != 0);
 	/*
 	 * For consistency, we always want to write out the same
 	 * bitspersample and sampleformat for our TIFF file,
 	 * regardless of the data format being used by the application.
 	 * Since this routine is called after tags have been set but
 	 * before they have been recorded in the file, we reset them here.
+         * Note: this is really a nasty approach. See PixarLogClose
 	 */
-	td->td_samplesperpixel =
