 static void"}<_**next**_>{"sha": "aa99bc92038fada3f1a77f3cd9cd9865c7bac1fb", "filename": "libtiff/tif_pixarlog.c", "status": "modified", "additions": 15, "deletions": 2, "changes": 17, "blob_url": "https://github.com/vadz/libtiff/blob/1044b43637fa7f70fb19b93593777b78bd20da86/libtiff/tif_pixarlog.c", "raw_url": "https://github.com/vadz/libtiff/raw/1044b43637fa7f70fb19b93593777b78bd20da86/libtiff/tif_pixarlog.c", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/libtiff/tif_pixarlog.c?ref=1044b43637fa7f70fb19b93593777b78bd20da86", "patch": "@@ -1233,8 +1233,10 @@ PixarLogPostEncode(TIFF* tif)
 static void
 PixarLogClose(TIFF* tif)
 {
+        PixarLogState* sp = (PixarLogState*) tif->tif_data;
 	TIFFDirectory *td = &tif->tif_dir;

+	assert(sp != 0);
 	/* In a really sneaky (and really incorrect, and untruthful, and
 	 * troublesome, and error-prone) maneuver that completely goes against
 	 * the spirit of TIFF, and breaks TIFF, on close, we covertly
@@ -1243,8 +1245,19 @@ PixarLogClose(TIFF* tif)
 	 * readers that don't know about PixarLog, or how to set
 	 * the PIXARLOGDATFMT pseudo-tag.
 	 */
-	td->td_bitspersample = 8;
-	td->td_sampleformat = SAMPLEFORMAT_UINT;
+
+        if (sp->state&PLSTATE_INIT) {
+            /* We test the state to avoid an issue such as in
+             * http://bugzilla.maptools.org/show_bug.cgi?id=2604
+             * What appends in that case is that the bitspersample is 1 and
+             * a TransferFunction is set. The size of the TransferFunction
+             * depends on 1<<bitspersample. So if we increase it, an access
+             * out of the buffer will happen at directory flushing.
+             * Another option would be to clear those targs. 
+             */
+            td->td_bitspersample = 8;
+            td->td_sampleformat = SAMPLEFORMAT_UINT;
+        }
 }

 static void"}

{"sha": "0f154d66245de17fb6b67bff5f307864de9c8fec", "filename": "ChangeLog", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/vadz/libtiff/blob/5397a417e61258c69209904e652a1f409ec3b9df/ChangeLog", "raw_url": "https://github.com/vadz/libtiff/raw/5397a417e61258c69209904e652a1f409ec3b9df/ChangeLog", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/ChangeLog?ref=5397a417e61258c69209904e652a1f409ec3b9df", "patch": "@@ -1,3 +1,10 @@
