{"sha": "5b23665b1730e31dea0f6ca7e1fb403612a973d6", "filename": "ChangeLog", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/vadz/libtiff/blob/43bc256d8ae44b92d2734a3c5bc73957a4d7c1ec/ChangeLog", "raw_url": "https://github.com/vadz/libtiff/raw/43bc256d8ae44b92d2734a3c5bc73957a4d7c1ec/ChangeLog", "contents_url": "https://api.github.com/repos/vadz/libtiff/contents/ChangeLog?ref=43bc256d8ae44b92d2734a3c5bc73957a4d7c1ec", "patch": "@@ -1,3 +1,10 @@
