+/*
+too_few_image_data.gd2 claims to have a size of 12336x48 pixels, but doesn't
+provide as much image data. We test that gdImageCreateFromGd2Ctx() returns NULL
+in this case.
+*/
+
+#include "gd.h"
+#include "gdtest.h"
+
+int main()
+{
+    gdImagePtr im;
+    FILE *fp;
+
+    fp = gdTestFileOpen2("gd2", "too_few_image_data.gd2");
+    gdTestAssert(fp != NULL);
+    im = gdImageCreateFromGd2(fp);
+    gdTestAssert(im == NULL);
+    fclose(fp);
+
+    return gdNumFailures();
+}"}<_**next**_>{"sha": "1c797d1acfae114be5505962f9f3201f01bca420", "filename": "tests/gd2/too_few_image_data.gd2", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/libgd/libgd/blob/fe9ed49dafa993e3af96b6a5a589efeea9bfb36f/tests/gd2/too_few_image_data.gd2", "raw_url": "https://github.com/libgd/libgd/raw/fe9ed49dafa993e3af96b6a5a589efeea9bfb36f/tests/gd2/too_few_image_data.gd2", "contents_url": "https://api.github.com/repos/libgd/libgd/contents/tests/gd2/too_few_image_data.gd2?ref=fe9ed49dafa993e3af96b6a5a589efeea9bfb36f"}

