{"sha": "c7328b9999826069e919f57bed4fef69210e5173", "filename": "src/cmstypes.c", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/mm2/Little-CMS/blob/5ca71a7bc18b6897ab21d815d15e218e204581e2/src/cmstypes.c", "raw_url": "https://github.com/mm2/Little-CMS/raw/5ca71a7bc18b6897ab21d815d15e218e204581e2/src/cmstypes.c", "contents_url": "https://api.github.com/repos/mm2/Little-CMS/contents/src/cmstypes.c?ref=5ca71a7bc18b6897ab21d815d15e218e204581e2", "patch": "@@ -1460,6 +1460,7 @@ void *Type_MLU_Read(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsU

         // Check for overflow
         if (Offset < (SizeOfHeader + 8)) goto Error;
