{"sha": "c207458d62993350d9a0cfca5e1deca573b09c8c", "filename": "crypto/mcryptd.c", "status": "modified", "additions": 12, "deletions": 7, "changes": 19, "blob_url": "https://github.com/torvalds/linux/blob/48a992727d82cb7db076fa15d372178743b1f4cd/crypto/mcryptd.c", "raw_url": "https://github.com/torvalds/linux/raw/48a992727d82cb7db076fa15d372178743b1f4cd/crypto/mcryptd.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/crypto/mcryptd.c?ref=48a992727d82cb7db076fa15d372178743b1f4cd", "patch": "@@ -254,18 +254,22 @@ static void *mcryptd_alloc_instance(struct crypto_alg *alg, unsigned int head,
