{"sha": "79a081cfa72e3483f7d5a4a5f9121829c5120da0", "filename": "NEWS", "status": "modified", "additions": 3, "deletions": 0, "changes": 3, "blob_url": "https://github.com/SchedMD/slurm/blob/92362a92fffe60187df61f99ab11c249d44120ee/NEWS", "raw_url": "https://github.com/SchedMD/slurm/raw/92362a92fffe60187df61f99ab11c249d44120ee/NEWS", "contents_url": "https://api.github.com/repos/SchedMD/slurm/contents/NEWS?ref=92362a92fffe60187df61f99ab11c249d44120ee", "patch": "@@ -28,6 +28,9 @@ documents those changes that are of interest to users and administrators.
