{"sha": "9c143739b8d73f0c7982be06eb0e5cdb902bfc81", "filename": "kernel/trace/ring_buffer.c", "status": "modified", "additions": 4, "deletions": 5, "changes": 9, "blob_url": "https://github.com/torvalds/linux/blob/59643d1535eb220668692a5359de22545af579f6/kernel/trace/ring_buffer.c", "raw_url": "https://github.com/torvalds/linux/raw/59643d1535eb220668692a5359de22545af579f6/kernel/trace/ring_buffer.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/trace/ring_buffer.c?ref=59643d1535eb220668692a5359de22545af579f6", "patch": "@@ -1657,14 +1657,13 @@ int ring_buffer_resize(struct ring_buffer *buffer, unsigned long size,
