+/**
+ * Test that a too large image doesn't trigger an double-free when written
+ * to memory.
+ */
+
+
+#include "gd.h"
+#include "gdtest.h"
+
+
+int main()
+{
+    gdImagePtr im1, im2;
+    FILE *fp;
+    int size;
+
+    fp = gdTestFileOpen2("webp", "bug_double_free.jpg");
+    gdTestAssert(fp != NULL);
+    im1 = gdImageCreateFromJpeg(fp);
+    gdTestAssert(im1 != NULL);
+    fclose(fp);
+
+    im2 = gdImageWebpPtr(im1, &size);
+    gdTestAssert(im2 == NULL);
+
+    gdImageDestroy(im1);
+
+    return gdNumFailures();
+}"}<_**next**_>{"sha": "9b792fb4a7d17578b445af1ba530e4df7ac47df1", "filename": "tests/webp/bug_double_free.jpg", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/libgd/libgd/blob/a49feeae76d41959d85ee733925a4cf40bac61b2/tests/webp/bug_double_free.jpg", "raw_url": "https://github.com/libgd/libgd/raw/a49feeae76d41959d85ee733925a4cf40bac61b2/tests/webp/bug_double_free.jpg", "contents_url": "https://api.github.com/repos/libgd/libgd/contents/tests/webp/bug_double_free.jpg?ref=a49feeae76d41959d85ee733925a4cf40bac61b2"}

