+/*
+We're testing that reading corrupt TIFF files doesn't cause any memory issues,
+and that the operation gracefully fails (i.e. gdImageCreateFromTiffPtr() returns
+NULL).
+*/
+
+#include "gd.h"
+#include "gdtest.h"
+
+
+static void check_file(char *basename);
+static size_t read_test_file(char **buffer, char *basename);
+
+
+int main()
+{
+    check_file("tiff_invalid_read_1.tiff");
+    check_file("tiff_invalid_read_2.tiff");
+    check_file("tiff_invalid_read_3.tiff");
+
+    return gdNumFailures();
+}
+
+
+static void check_file(char *basename)
+{
+    gdImagePtr im;
+    char *buffer;
+    size_t size;
+
+    size = read_test_file(&buffer, basename);
+    im = gdImageCreateFromTiffPtr(size, (void *) buffer);
+    gdTestAssert(im == NULL);
+    free(buffer);
+}
+
+
+static size_t read_test_file(char **buffer, char *basename)
+{
+    char *filename;
+    FILE *fp;
+    size_t exp_size, act_size;
+
+    filename = gdTestFilePath2("tiff", basename);
+    fp = fopen(filename, "rb");
+    gdTestAssert(fp != NULL);
+
+	fseek(fp, 0, SEEK_END);
+	exp_size = ftell(fp);
+	fseek(fp, 0, SEEK_SET);
+
+    *buffer = malloc(exp_size);
+    gdTestAssert(*buffer != NULL);
+    act_size = fread(*buffer, sizeof(**buffer), exp_size, fp);
+    gdTestAssert(act_size == exp_size);
+
+    fclose(fp);
+    free(filename);
+
+    return act_size;
+}"}<_**next**_>{"sha": "b3877e337b3c0a7ccdee988647a907749d7c8ad7", "filename": "tests/tiff/tiff_invalid_read_1.tiff", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/libgd/libgd/blob/4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae/tests/tiff/tiff_invalid_read_1.tiff", "raw_url": "https://github.com/libgd/libgd/raw/4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae/tests/tiff/tiff_invalid_read_1.tiff", "contents_url": "https://api.github.com/repos/libgd/libgd/contents/tests/tiff/tiff_invalid_read_1.tiff?ref=4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae"}<_**next**_>{"sha": "f9967e542178cfbab902ec55c85479588dfb099e", "filename": "tests/tiff/tiff_invalid_read_2.tiff", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/libgd/libgd/blob/4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae/tests/tiff/tiff_invalid_read_2.tiff", "raw_url": "https://github.com/libgd/libgd/raw/4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae/tests/tiff/tiff_invalid_read_2.tiff", "contents_url": "https://api.github.com/repos/libgd/libgd/contents/tests/tiff/tiff_invalid_read_2.tiff?ref=4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae"}<_**next**_>{"sha": "67ca2a7c6e1a7834bee9f15a632a3cf2d7d52819", "filename": "tests/tiff/tiff_invalid_read_3.tiff", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/libgd/libgd/blob/4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae/tests/tiff/tiff_invalid_read_3.tiff", "raw_url": "https://github.com/libgd/libgd/raw/4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae/tests/tiff/tiff_invalid_read_3.tiff", "contents_url": "https://api.github.com/repos/libgd/libgd/contents/tests/tiff/tiff_invalid_read_3.tiff?ref=4859d69e07504d4b0a4bdf9bcb4d9e3769ca35ae"}

