+--TEST--
+Buffer overflow in HTTP url parsing functions
+--SKIPIF--
+<?php
+include "skipif.inc";
+?>
+--FILE--
+<?php
+
+echo "Test\n";
+try {
+	echo new http\Message(file_get_contents(__DIR__."/data/bug71719.bin"), false);
+} catch (Exception $e) {
+	echo $e;
+}
+?>
+
+===DONE===
+--EXPECTF--
+Test
+%r(exception ')?%rhttp\Exception\BadMessageException%r(' with message '|: )%rhttp\Message::__construct(): Could not parse HTTP protocol version 'HTTP/%s.0'%r'?%r in %sbug71719.php:5
+Stack trace:
+#0 %sbug71719.php(5): http\Message->__construct('\x80\xACTd 5 HTTP/1.1...', false)
+#1 {main}
+===DONE==="}<_**next**_>{"sha": "245db2801206e2c93107cccc89229cd4a02f0a08", "filename": "tests/data/bug71719.bin", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/m6w6/ext-http/blob/3724cd76a28be1d6049b5537232e97ac567ae1f5/tests/data/bug71719.bin", "raw_url": "https://github.com/m6w6/ext-http/raw/3724cd76a28be1d6049b5537232e97ac567ae1f5/tests/data/bug71719.bin", "contents_url": "https://api.github.com/repos/m6w6/ext-http/contents/tests/data/bug71719.bin?ref=3724cd76a28be1d6049b5537232e97ac567ae1f5"}

