{"sha": "c98a959b3b6d8af3c2df6a90e60cb9df64c94b74", "filename": "src/nss-mymachines/nss-mymachines.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/keszybz/systemd/blob/cb31827d62066a04b02111df3052949fda4b6888/src/nss-mymachines/nss-mymachines.c", "raw_url": "https://github.com/keszybz/systemd/raw/cb31827d62066a04b02111df3052949fda4b6888/src/nss-mymachines/nss-mymachines.c", "contents_url": "https://api.github.com/repos/keszybz/systemd/contents/src/nss-mymachines/nss-mymachines.c?ref=cb31827d62066a04b02111df3052949fda4b6888", "patch": "@@ -416,6 +416,9 @@ enum nss_status _nss_mymachines_getpwnam_r(
