{"sha": "6287bce2e6f545faf1441257f29a5be1aa1f9715", "filename": "ChangeLog.txt", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/eclipse/mosquitto/blob/9097577b49b7fdcf45d30975976dd93808ccc0c4/ChangeLog.txt", "raw_url": "https://github.com/eclipse/mosquitto/raw/9097577b49b7fdcf45d30975976dd93808ccc0c4/ChangeLog.txt", "contents_url": "https://api.github.com/repos/eclipse/mosquitto/contents/ChangeLog.txt?ref=9097577b49b7fdcf45d30975976dd93808ccc0c4", "patch": "@@ -1,6 +1,11 @@
 1.5.5 - 201812xx
 ================

+Security:
+- If `per_listener_settings` is set to true, then the `acl_file` setting was
+  ignored for the "default listener" only. This has been fixed. This does not
+  affect any listeners defined with the `listener` option. Closes #1073.
+
 Broker:
 - Add `socket_domain` option to allow listeners to disable IPv6 support.
   This is required to work around a problem in libwebsockets that means"}<_**next**_>{"sha": "87294680a2148529c86f520a1cbb68bd754d531c", "filename": "src/conf.c", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/eclipse/mosquitto/blob/9097577b49b7fdcf45d30975976dd93808ccc0c4/src/conf.c", "raw_url": "https://github.com/eclipse/mosquitto/raw/9097577b49b7fdcf45d30975976dd93808ccc0c4/src/conf.c", "contents_url": "https://api.github.com/repos/eclipse/mosquitto/contents/src/conf.c?ref=9097577b49b7fdcf45d30975976dd93808ccc0c4", "patch": "@@ -497,6 +497,7 @@ int config__parse_args(struct mosquitto_db *db, struct mosquitto__config *config
 		config->listeners[config->listener_count-1].use_identity_as_username = config->default_listener.use_identity_as_username;
 		config->listeners[config->listener_count-1].use_subject_as_username = config->default_listener.use_subject_as_username;
 #endif
+		config->listeners[config->listener_count-1].security_options.acl_file = config->default_listener.security_options.acl_file;
 		config->listeners[config->listener_count-1].security_options.password_file = config->default_listener.security_options.password_file;
 		config->listeners[config->listener_count-1].security_options.psk_file = config->default_listener.security_options.psk_file;
 		config->listeners[config->listener_count-1].security_options.auth_plugin_configs = config->default_listener.security_options.auth_plugin_configs;"}

