{"sha": "eec14f24ac801188da28ff1f38a0bce051e5bd6e", "filename": "src/mod_alias.c", "status": "modified", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/lighttpd/lighttpd1.4/blob/2105dae0f9d7a964375ce681e53cb165375f84c1/src/mod_alias.c", "raw_url": "https://github.com/lighttpd/lighttpd1.4/raw/2105dae0f9d7a964375ce681e53cb165375f84c1/src/mod_alias.c", "contents_url": "https://api.github.com/repos/lighttpd/lighttpd1.4/contents/src/mod_alias.c?ref=2105dae0f9d7a964375ce681e53cb165375f84c1", "patch": "@@ -181,6 +181,21 @@ PHYSICALPATH_FUNC(mod_alias_physical_handler) {
