 {"}<_**next**_>{"sha": "19682d02546d7329c410a77ad1c9569a144b5434", "filename": "lib/utils.h", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/acassen/keepalived/blob/04f2d32871bb3b11d7dc024039952f2fe2750306/lib/utils.h", "raw_url": "https://github.com/acassen/keepalived/raw/04f2d32871bb3b11d7dc024039952f2fe2750306/lib/utils.h", "contents_url": "https://api.github.com/repos/acassen/keepalived/contents/lib/utils.h?ref=04f2d32871bb3b11d7dc024039952f2fe2750306", "patch": "@@ -182,6 +182,7 @@ extern int inet_inaddrcmp(int, const void *, const void *);
