{"sha": "3088463bafc1fa2681fa6c371883e22cc8351330", "filename": "arch/arm64/kvm/guest.c", "status": "modified", "additions": 45, "deletions": 0, "changes": 45, "blob_url": "https://github.com/torvalds/linux/blob/d26c25a9d19b5976b319af528886f89cf455692d/arch/arm64/kvm/guest.c", "raw_url": "https://github.com/torvalds/linux/raw/d26c25a9d19b5976b319af528886f89cf455692d/arch/arm64/kvm/guest.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/arch/arm64/kvm/guest.c?ref=d26c25a9d19b5976b319af528886f89cf455692d", "patch": "@@ -57,6 +57,45 @@ static u64 core_reg_offset_from_id(u64 id)
 	return id & ~(KVM_REG_ARCH_MASK | KVM_REG_SIZE_MASK | KVM_REG_ARM_CORE);
 }

+static int validate_core_offset(const struct kvm_one_reg *reg)
+{
+	u64 off = core_reg_offset_from_id(reg->id);
+	int size;
+
+	switch (off) {
+	case KVM_REG_ARM_CORE_REG(regs.regs[0]) ...
+	     KVM_REG_ARM_CORE_REG(regs.regs[30]):
+	case KVM_REG_ARM_CORE_REG(regs.sp):
+	case KVM_REG_ARM_CORE_REG(regs.pc):
+	case KVM_REG_ARM_CORE_REG(regs.pstate):
+	case KVM_REG_ARM_CORE_REG(sp_el1):
+	case KVM_REG_ARM_CORE_REG(elr_el1):
+	case KVM_REG_ARM_CORE_REG(spsr[0]) ...
+	     KVM_REG_ARM_CORE_REG(spsr[KVM_NR_SPSR - 1]):
+		size = sizeof(__u64);
+		break;
+
+	case KVM_REG_ARM_CORE_REG(fp_regs.vregs[0]) ...
+	     KVM_REG_ARM_CORE_REG(fp_regs.vregs[31]):
+		size = sizeof(__uint128_t);
+		break;
+
+	case KVM_REG_ARM_CORE_REG(fp_regs.fpsr):
+	case KVM_REG_ARM_CORE_REG(fp_regs.fpcr):
+		size = sizeof(__u32);
+		break;
+
+	default:
+		return -EINVAL;
+	}
+
+	if (KVM_REG_SIZE(reg->id) == size &&
+	    IS_ALIGNED(off, size / sizeof(__u32)))
+		return 0;
+
+	return -EINVAL;
+}
+
 static int get_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
 {
 	/*
@@ -76,6 +115,9 @@ static int get_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
 	    (off + (KVM_REG_SIZE(reg->id) / sizeof(__u32))) >= nr_regs)
 		return -ENOENT;

+	if (validate_core_offset(reg))
+		return -EINVAL;
+
 	if (copy_to_user(uaddr, ((u32 *)regs) + off, KVM_REG_SIZE(reg->id)))
 		return -EFAULT;

@@ -98,6 +140,9 @@ static int set_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
 	    (off + (KVM_REG_SIZE(reg->id) / sizeof(__u32))) >= nr_regs)
 		return -ENOENT;

+	if (validate_core_offset(reg))
+		return -EINVAL;
+
 	if (KVM_REG_SIZE(reg->id) > sizeof(tmp))
 		return -EINVAL;
 "}

{"sha": "904a5185e0db3c0b55d3a3fc59b602b3f09472c8", "filename": "ChangeLog", "status": "modified", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/coreutils/gnulib/blob/278b4175c9d7dd47c1a3071554aac02add3b3c35/ChangeLog", "raw_url": "https://github.com/coreutils/gnulib/raw/278b4175c9d7dd47c1a3071554aac02add3b3c35/ChangeLog", "contents_url": "https://api.github.com/repos/coreutils/gnulib/contents/ChangeLog?ref=278b4175c9d7dd47c1a3071554aac02add3b3c35", "patch": "@@ -1,3 +1,12 @@
+2018-09-23  Bruno Haible  <bruno@clisp.org>
+
+	vasnprintf: Fix heap memory overrun bug.
+	Reported by Ben Pfaff <blp@cs.stanford.edu> in
+	<https://lists.gnu.org/archive/html/bug-gnulib/2018-09/msg00107.html>.
+	* lib/vasnprintf.c (convert_to_decimal): Allocate one more byte of
+	memory.
+	* tests/test-vasnprintf.c (test_function): Add another test.
+
 2018-09-19  Paul Eggert  <eggert@cs.ucla.edu>

 	maint: mktime.c now shared with glibc"}<_**next**_>{"sha": "30d021b2847d47ee73611f4f52c7028d0b999d9a", "filename": "lib/vasnprintf.c", "status": "modified", "additions": 3, "deletions": 1, "changes": 4, "blob_url": "https://github.com/coreutils/gnulib/blob/278b4175c9d7dd47c1a3071554aac02add3b3c35/lib/vasnprintf.c", "raw_url": "https://github.com/coreutils/gnulib/raw/278b4175c9d7dd47c1a3071554aac02add3b3c35/lib/vasnprintf.c", "contents_url": "https://api.github.com/repos/coreutils/gnulib/contents/lib/vasnprintf.c?ref=278b4175c9d7dd47c1a3071554aac02add3b3c35", "patch": "@@ -860,7 +860,9 @@ convert_to_decimal (mpn_t a, size_t extra_zeroes)
   size_t a_len = a.nlimbs;
   /* 0.03345 is slightly larger than log(2)/(9*log(10)).  */
   size_t c_len = 9 * ((size_t)(a_len * (GMP_LIMB_BITS * 0.03345f)) + 1);
-  char *c_ptr = (char *) malloc (xsum (c_len, extra_zeroes));
+  /* We need extra_zeroes bytes for zeroes, followed by c_len bytes for the
+     digits of a, followed by 1 byte for the terminating NUL.  */
+  char *c_ptr = (char *) malloc (xsum (xsum (extra_zeroes, c_len), 1));
   if (c_ptr != NULL)
     {
       char *d_ptr = c_ptr;"}<_**next**_>{"sha": "93d81d7041c58a5384d7ca06c0917ab70bc1509b", "filename": "tests/test-vasnprintf.c", "status": "modified", "additions": 20, "deletions": 1, "changes": 21, "blob_url": "https://github.com/coreutils/gnulib/blob/278b4175c9d7dd47c1a3071554aac02add3b3c35/tests/test-vasnprintf.c", "raw_url": "https://github.com/coreutils/gnulib/raw/278b4175c9d7dd47c1a3071554aac02add3b3c35/tests/test-vasnprintf.c", "contents_url": "https://api.github.com/repos/coreutils/gnulib/contents/tests/test-vasnprintf.c?ref=278b4175c9d7dd47c1a3071554aac02add3b3c35", "patch": "@@ -53,7 +53,26 @@ test_function (char * (*my_asnprintf) (char *, size_t *, const char *, ...))
       ASSERT (result != NULL);
       ASSERT (strcmp (result, "12345") == 0);
       ASSERT (length == 5);
-      if (size < 6)
+      if (size < 5 + 1)
+        ASSERT (result != buf);
+      ASSERT (memcmp (buf + size, &"DEADBEEF"[size], 8 - size) == 0);
+      if (result != buf)
+        free (result);
+    }
+
+  /* Note: This test assumes IEEE 754 representation of 'double' floats.  */
+  for (size = 0; size <= 8; size++)
+    {
+      size_t length;
+      char *result;
+
+      memcpy (buf, "DEADBEEF", 8);
+      length = size;
+      result = my_asnprintf (buf, &length, "%2.0f", 1.6314159265358979e+125);
+      ASSERT (result != NULL);
+      ASSERT (strcmp (result, "163141592653589790215729350939528493057529598899734151772468186268423257777068536614838678161083520756952076273094236944990208") == 0);
+      ASSERT (length == 126);
+      if (size < 126 + 1)
         ASSERT (result != buf);
       ASSERT (memcmp (buf + size, &"DEADBEEF"[size], 8 - size) == 0);
       if (result != buf)"}

{"sha": "fa42b0a51780eded7a6884e1db5541c4ccd34fd7", "filename": "network/nw_buf.c", "status": "modified", "additions": 8, "deletions": 2, "changes": 10, "blob_url": "https://github.com/viabtc/viabtc_exchange_server/blob/4a7c27bfe98f409623d4d857894d017ff0672cc9/network/nw_buf.c", "raw_url": "https://github.com/viabtc/viabtc_exchange_server/raw/4a7c27bfe98f409623d4d857894d017ff0672cc9/network/nw_buf.c", "contents_url": "https://api.github.com/repos/viabtc/viabtc_exchange_server/contents/network/nw_buf.c?ref=4a7c27bfe98f409623d4d857894d017ff0672cc9", "patch": "@@ -8,7 +8,9 @@
 # include "nw_buf.h"

 # define NW_BUF_POOL_INIT_SIZE 64
+# define NW_BUF_POOL_MAX_SIZE  65535
 # define NW_CACHE_INIT_SIZE    64
