{"sha": "3be40eaa1ac9b2caf493a8fd21e8980982b5d9a1", "filename": "drivers/usb/misc/yurex.c", "status": "modified", "additions": 6, "deletions": 17, "changes": 23, "blob_url": "https://github.com/torvalds/linux/blob/f1e255d60ae66a9f672ff9a207ee6cd8e33d2679/drivers/usb/misc/yurex.c", "raw_url": "https://github.com/torvalds/linux/raw/f1e255d60ae66a9f672ff9a207ee6cd8e33d2679/drivers/usb/misc/yurex.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/usb/misc/yurex.c?ref=f1e255d60ae66a9f672ff9a207ee6cd8e33d2679", "patch": "@@ -396,35 +396,24 @@ static ssize_t yurex_read(struct file *file, char __user *buffer, size_t count,
