{"sha": "7f0fb90fb4969167958f8d2b332d56c4150f6f22", "filename": "lib/liboswkeys/signatures.c", "status": "modified", "additions": 15, "deletions": 2, "changes": 17, "blob_url": "https://github.com/xelerance/Openswan/blob/9eaa6c2a823c1d2b58913506a15f9474bf857a3d/lib/liboswkeys/signatures.c", "raw_url": "https://github.com/xelerance/Openswan/raw/9eaa6c2a823c1d2b58913506a15f9474bf857a3d/lib/liboswkeys/signatures.c", "contents_url": "https://api.github.com/repos/xelerance/Openswan/contents/lib/liboswkeys/signatures.c?ref=9eaa6c2a823c1d2b58913506a15f9474bf857a3d", "patch": "@@ -157,8 +157,21 @@ err_t verify_signed_hash(const struct RSA_public_key *k
 	return "3""SIG padding does not check out";
     }

-    s += padlen + 3;
-    (*psig) = s;
+    /* signature starts after ASN wrapped padding [00,01,FF..FF,00] */
+    (*psig) = s + padlen + 3;
+
+    /* verify padding contents */
+    {
+        const u_char *p;
+        size_t cnt_ffs = 0;
+
+        for (p = s+2; p < s+padlen+2; p++)
+            if (*p == 0xFF)
+                cnt_ffs ++;
+
+        if (cnt_ffs != padlen)
+            return "4" "invalid Padding String";
+    }

     /* return SUCCESS */
     return NULL;"}

{"sha": "e4863f1fc73cf1e596080b5e207f702b35a59564", "filename": "libavformat/flvenc.c", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/FFmpeg/FFmpeg/blob/6b67d7f05918f7a1ee8fc6ff21355d7e8736aa10/libavformat/flvenc.c", "raw_url": "https://github.com/FFmpeg/FFmpeg/raw/6b67d7f05918f7a1ee8fc6ff21355d7e8736aa10/libavformat/flvenc.c", "contents_url": "https://api.github.com/repos/FFmpeg/FFmpeg/contents/libavformat/flvenc.c?ref=6b67d7f05918f7a1ee8fc6ff21355d7e8736aa10", "patch": "@@ -883,6 +883,11 @@ static int flv_write_packet(AVFormatContext *s, AVPacket *pkt)
