{"sha": "26c01349e0c24b2b074a171137f37f8edc4a438e", "filename": "src/mpr/mprLib.c", "status": "modified", "additions": 32, "deletions": 1, "changes": 33, "blob_url": "https://github.com/embedthis/appweb/blob/66067ae6d1fa08b37a270e7dc1821df52ed2daef/src/mpr/mprLib.c", "raw_url": "https://github.com/embedthis/appweb/raw/66067ae6d1fa08b37a270e7dc1821df52ed2daef/src/mpr/mprLib.c", "contents_url": "https://api.github.com/repos/embedthis/appweb/contents/src/mpr/mprLib.c?ref=66067ae6d1fa08b37a270e7dc1821df52ed2daef", "patch": "@@ -27583,13 +27583,40 @@ static void validateTime(struct tm *tp, struct tm *defaults)
         swapDayMonth(tp);
     }

+    /*
+        Check for overflow. Underflow validated below.
+     */
+    if (tp->tm_sec > 60) {
+        tp->tm_sec = -1;
+    }
+    if (tp->tm_min > 60) {
+        tp->tm_sec = -1;
+    }
+    if (tp->tm_hour > 24) {
+        tp->tm_sec = -1;
+    }
+    if (tp->tm_mday > 31) {
+        tp->tm_sec = -1;
+    }
+    if (tp->tm_mon > 11) {
+        tp->tm_sec = -1;
+    }
+    if (tp->tm_wday > 6) {
+        tp->tm_sec = -1;
+    }
+    if (tp->tm_yday > 366) {
+        tp->tm_sec = -1;
+    }
+
+#if UNUSED
     if (tp->tm_year != -MAXINT && tp->tm_mon >= 0 && tp->tm_mday >= 0 && tp->tm_hour >= 0) {
         /*  Everything defined */
         return;
     }
+#endif

     /*
-        Use empty time if missing
+        Use empty time if defaults missing
      */
     if (defaults == NULL) {
         memset(&empty, 0, sizeof(empty));
@@ -27640,8 +27667,12 @@ static void validateTime(struct tm *tp, struct tm *defaults)
         tp->tm_mday = defaults->tm_mday;
     }
