+        if (tp->tm_mon <= 11) {
         tp->tm_yday = (leapYear(tp->tm_year + 1900) ?
             leapMonthStart[tp->tm_mon] : normalMonthStart[tp->tm_mon]) + tp->tm_mday - 1;
+        } else {
+            tp->tm_yday = defaults->tm_yday;
+        }
     }
     if (tp->tm_hour < 0) {
         tp->tm_hour = defaults->tm_hour;"}

