{"sha": "d10d6c68faea8abc28669ea0bd6cb5570cd82377", "filename": "src/transports/smart_pkt.c", "status": "modified", "additions": 8, "deletions": 2, "changes": 10, "blob_url": "https://github.com/libgit2/libgit2/blob/1f9a8510e1d2f20ed7334eeeddb92c4dd8e7c649/src/transports/smart_pkt.c", "raw_url": "https://github.com/libgit2/libgit2/raw/1f9a8510e1d2f20ed7334eeeddb92c4dd8e7c649/src/transports/smart_pkt.c", "contents_url": "https://api.github.com/repos/libgit2/libgit2/contents/src/transports/smart_pkt.c?ref=1f9a8510e1d2f20ed7334eeeddb92c4dd8e7c649", "patch": "@@ -299,8 +299,11 @@ static int ng_pkt(git_pkt **out, const char *line, size_t len)
