{"sha": "0068a3edb1c6bac289637617d9d0b0e227be95ad", "filename": "ext/standard/link_win32.c", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/php/php-src/blob/f151e048ed27f6f4eef729f3310d053ab5da71d4/ext/standard/link_win32.c", "raw_url": "https://github.com/php/php-src/raw/f151e048ed27f6f4eef729f3310d053ab5da71d4/ext/standard/link_win32.c", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/standard/link_win32.c?ref=f151e048ed27f6f4eef729f3310d053ab5da71d4", "patch": "@@ -87,6 +87,7 @@ PHP_FUNCTION(readlink)
 PHP_FUNCTION(linkinfo)
 {
 	char *link;
+	char *dirname;
 	size_t link_len;
 	zend_stat_t sb;
 	int ret;
@@ -95,12 +96,22 @@ PHP_FUNCTION(linkinfo)
 		return;
 	}

+	dirname = estrndup(link, link_len);
+	php_dirname(dirname, link_len);
+
+	if (php_check_open_basedir(dirname)) {
+		efree(dirname);
+		RETURN_FALSE;
+	}
+
 	ret = VCWD_STAT(link, &sb);
 	if (ret == -1) {
 		php_error_docref(NULL, E_WARNING, "%s", strerror(errno));
+		efree(dirname);
 		RETURN_LONG(Z_L(-1));
 	}

+	efree(dirname);
 	RETURN_LONG((zend_long) sb.st_dev);
 }
 /* }}} */"}

{"sha": "29472452dd3855faeb22c900dbe4c41226f7f90c", "filename": "pango/pango-emoji.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/GNOME/pango/blob/71aaeaf020340412b8d012fe23a556c0420eda5f/pango/pango-emoji.c", "raw_url": "https://github.com/GNOME/pango/raw/71aaeaf020340412b8d012fe23a556c0420eda5f/pango/pango-emoji.c", "contents_url": "https://api.github.com/repos/GNOME/pango/contents/pango/pango-emoji.c?ref=71aaeaf020340412b8d012fe23a556c0420eda5f", "patch": "@@ -253,6 +253,12 @@ _pango_emoji_iter_next (PangoEmojiIter *iter)
     if (iter->is_emoji == PANGO_EMOJI_TYPE_IS_EMOJI (current_emoji_type))
     {
       iter->is_emoji = !PANGO_EMOJI_TYPE_IS_EMOJI (current_emoji_type);
+
+      /* Make sure we make progress.  Weird sequences, like a VC15 followed
+       * by VC16, can trick us into stalling otherwise. */
+      if (iter->start == iter->end)
+        iter->end = g_utf8_next_char (iter->end);
+
       return TRUE;
     }
   }"}

