+test_kwajd_test_LDADD = 	libmspack.la"}<_**next**_>{"sha": "50be257023303ca8a46af8c8a71b7d306b821f95", "filename": "libmspack/mspack/kwajd.c", "status": "modified", "additions": 19, "deletions": 13, "changes": 32, "blob_url": "https://github.com/kyz/libmspack/blob/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/mspack/kwajd.c", "raw_url": "https://github.com/kyz/libmspack/raw/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/mspack/kwajd.c", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/mspack/kwajd.c?ref=0b0ef9344255ff5acfac6b7af09198ac9c9756c8", "patch": "@@ -198,30 +198,36 @@ static int kwajd_read_headers(struct mspack_system *sys,

     /* filename and extension */
