 0, "changes": 0, "blob_url": "https://github.com/kyz/libmspack/blob/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f91.kwj", "raw_url": "https://github.com/kyz/libmspack/raw/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f91.kwj", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/test/test_files/kwajd/f91.kwj?ref=0b0ef9344255ff5acfac6b7af09198ac9c9756c8"}<_**next**_>{"sha": "c8a99ae9c0437b9f64fe07829ddfe828c09176db", "filename": "libmspack/test/test_files/kwajd/f92.kwj", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/kyz/libmspack/blob/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f92.kwj", "raw_url": "https://github.com/kyz/libmspack/raw/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f92.kwj", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/test/test_files/kwajd/f92.kwj?ref=0b0ef9344255ff5acfac6b7af09198ac9c9756c8"}<_**next**_>{"sha": "559faa9a7e5188b4da9b14fda99d9dfef1ebf8ef", "filename": "libmspack/test/test_files/kwajd/f93.kwj", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/kyz/libmspack/blob/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f93.kwj", "raw_url": "https://github.com/kyz/libmspack/raw/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f93.kwj", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/test/test_files/kwajd/f93.kwj?ref=0b0ef9344255ff5acfac6b7af09198ac9c9756c8"}<_**next**_>{"sha": "c52dfeb0d929c3838a3d24654a4a009c527b08c7", "filename": "libmspack/test/test_files/kwajd/f94.kwj", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/kyz/libmspack/blob/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f94.kwj", "raw_url": "https://github.com/kyz/libmspack/raw/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/f94.kwj", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/test/test_files/kwajd/f94.kwj?ref=0b0ef9344255ff5acfac6b7af09198ac9c9756c8"}<_**next**_>{"sha": "ae73038e25e80433264008d364c92a82313d0cc0", "filename": "libmspack/test/test_files/kwajd/make.pl", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/kyz/libmspack/blob/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/make.pl", "raw_url": "https://github.com/kyz/libmspack/raw/0b0ef9344255ff5acfac6b7af09198ac9c9756c8/libmspack/test/test_files/kwajd/make.pl", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/test/test_files/kwajd/make.pl?ref=0b0ef9344255ff5acfac6b7af09198ac9c9756c8", "patch": "@@ -0,0 +1,17 @@
+#!/usr/bin/perl -w
+use strict;
+my $name = '123456789';
+for my $file (0 .. 9) {
+    for my $ext (0 .. 4) {
+	open my $fh, '>', "f$file$ext.kwj";
+        my $offset = 14  + $file + $ext;
+	my $flags  = ($file > 0 ? 8 : 0) | ($ext > 0 ? 16 : 0);
+	print $fh pack 'A4Vvvv', 'KWAJ', 0xD127F088, 0, $offset, $flags;
+	print $fh substr $name, 0, $file if $file > 0;
+	print $fh "\0" if $file > 0 && $file < 9;
+	print $fh substr $name, 0, $ext if $ext > 0;
+	print $fh "\0" if $ext > 0 && $ext < 4;
+        print $fh "\xFF";
+	close $fh;
+    }
+}"}

{"sha": "fab3a55d9d11bb76ccfddef8700212a3bbca2fdf", "filename": "libmspack/ChangeLog", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/kyz/libmspack/blob/72e70a921f0f07fee748aec2274b30784e1d312a/libmspack/ChangeLog", "raw_url": "https://github.com/kyz/libmspack/raw/72e70a921f0f07fee748aec2274b30784e1d312a/libmspack/ChangeLog", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/ChangeLog?ref=72e70a921f0f07fee748aec2274b30784e1d312a", "patch": "@@ -1,3 +1,13 @@
+2018-04-26  Stuart Caie <kyzer@cabextract.org.uk>
+
+	* read_chunk(): the test that chunk numbers are in bounds was off
+	by one, so read_chunk() returned a pointer taken from outside
+	allocated memory that usually crashes libmspack when accessed.
+	Thanks to Hanno Böck for finding the issue and providing a sample.
+
+	* chmd_read_headers(): reject files with blank filenames. Thanks
+	again to Hanno Böck for finding the issue and providing a sample file.
+
 2018-02-06  Stuart Caie <kyzer@cabextract.org.uk>

 	* chmd.c: fixed an off-by-one error in the TOLOWER() macro, reported"}<_**next**_>{"sha": "9c3265862e0b59a3d37c0164622c092ac59f11ac", "filename": "libmspack/mspack/chmd.c", "status": "modified", "additions": 6, "deletions": 3, "changes": 9, "blob_url": "https://github.com/kyz/libmspack/blob/72e70a921f0f07fee748aec2274b30784e1d312a/libmspack/mspack/chmd.c", "raw_url": "https://github.com/kyz/libmspack/raw/72e70a921f0f07fee748aec2274b30784e1d312a/libmspack/mspack/chmd.c", "contents_url": "https://api.github.com/repos/kyz/libmspack/contents/libmspack/mspack/chmd.c?ref=72e70a921f0f07fee748aec2274b30784e1d312a", "patch": "@@ -1,5 +1,5 @@
