{"sha": "4d5f027b85c659fff555bb52ac941ded92d292e7", "filename": "deps/lua/src/lua_struct.c", "status": "modified", "additions": 6, "deletions": 2, "changes": 8, "blob_url": "https://github.com/antirez/redis/blob/e89086e09a38cc6713bcd4b9c29abf92cf393936/deps/lua/src/lua_struct.c", "raw_url": "https://github.com/antirez/redis/raw/e89086e09a38cc6713bcd4b9c29abf92cf393936/deps/lua/src/lua_struct.c", "contents_url": "https://api.github.com/repos/antirez/redis/contents/deps/lua/src/lua_struct.c?ref=e89086e09a38cc6713bcd4b9c29abf92cf393936", "patch": "@@ -293,14 +293,18 @@ static int b_unpack (lua_State *L) {
