{"sha": "8676e7a8f2ab7430ad2d4ae3c92a88dded55775b", "filename": "src/delta.c", "status": "modified", "additions": 10, "deletions": 8, "changes": 18, "blob_url": "https://github.com/libgit2/libgit2/blob/9844d38bed10e9ff17174434b3421b227ae710f3/src/delta.c", "raw_url": "https://github.com/libgit2/libgit2/raw/9844d38bed10e9ff17174434b3421b227ae710f3/src/delta.c", "contents_url": "https://api.github.com/repos/libgit2/libgit2/contents/src/delta.c?ref=9844d38bed10e9ff17174434b3421b227ae710f3", "patch": "@@ -568,15 +568,17 @@ int git_delta_apply(
 			/* cmd is a copy instruction; copy from the base. */
 			size_t off = 0, len = 0;

-			if (cmd & 0x01) off = *delta++;
-			if (cmd & 0x02) off |= *delta++ << 8UL;
-			if (cmd & 0x04) off |= *delta++ << 16UL;
-			if (cmd & 0x08) off |= ((unsigned) *delta++ << 24UL);
-
-			if (cmd & 0x10) len = *delta++;
-			if (cmd & 0x20) len |= *delta++ << 8UL;
-			if (cmd & 0x40) len |= *delta++ << 16UL;
+#define ADD_DELTA(o, shift) { if (delta < delta_end) (o) |= ((unsigned) *delta++ << shift); else goto fail; }
+			if (cmd & 0x01) ADD_DELTA(off, 0UL);
+			if (cmd & 0x02) ADD_DELTA(off, 8UL);
+			if (cmd & 0x04) ADD_DELTA(off, 16UL);
+			if (cmd & 0x08) ADD_DELTA(off, 24UL);
+
+			if (cmd & 0x10) ADD_DELTA(len, 0UL);
+			if (cmd & 0x20) ADD_DELTA(len, 8UL);
+			if (cmd & 0x40) ADD_DELTA(len, 16UL);
 			if (!len)       len = 0x10000;
+#undef ADD_DELTA

 			if (base_len < off + len || res_sz < len)
 				goto fail;"}<_**next**_>{"sha": "5bb95a28345bec09d12a79c861701ed5282ce038", "filename": "tests/delta/apply.c", "status": "modified", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/libgit2/libgit2/blob/9844d38bed10e9ff17174434b3421b227ae710f3/tests/delta/apply.c", "raw_url": "https://github.com/libgit2/libgit2/raw/9844d38bed10e9ff17174434b3421b227ae710f3/tests/delta/apply.c", "contents_url": "https://api.github.com/repos/libgit2/libgit2/contents/tests/delta/apply.c?ref=9844d38bed10e9ff17174434b3421b227ae710f3", "patch": "@@ -10,3 +10,12 @@ void test_delta_apply__read_at_off(void)

 	cl_git_fail(git_delta_apply(&out, &outlen, base, sizeof(base), delta, sizeof(delta)));
 }
+
+void test_delta_apply__read_after_limit(void)
+{
