+	cl_git_fail(git_delta_apply(&out, &outlen, base, sizeof(base), delta, sizeof(delta)));
+}"}

{"sha": "b9352b8ee0d62f44ef97b8805c2de16f283e4b09", "filename": "src/delta.c", "status": "modified", "additions": 4, "deletions": 2, "changes": 6, "blob_url": "https://github.com/libgit2/libgit2/blob/c1577110467b701dcbcf9439ac225ea851b47d22/src/delta.c", "raw_url": "https://github.com/libgit2/libgit2/raw/c1577110467b701dcbcf9439ac225ea851b47d22/src/delta.c", "contents_url": "https://api.github.com/repos/libgit2/libgit2/contents/src/delta.c?ref=c1577110467b701dcbcf9439ac225ea851b47d22", "patch": "@@ -566,7 +566,7 @@ int git_delta_apply(
 		unsigned char cmd = *delta++;
 		if (cmd & 0x80) {
 			/* cmd is a copy instruction; copy from the base. */
-			size_t off = 0, len = 0;
+			size_t off = 0, len = 0, end;

 #define ADD_DELTA(o, shift) { if (delta < delta_end) (o) |= ((unsigned) *delta++ << shift); else goto fail; }
 			if (cmd & 0x01) ADD_DELTA(off, 0UL);
@@ -580,8 +580,10 @@ int git_delta_apply(
 			if (!len)       len = 0x10000;
 #undef ADD_DELTA

-			if (base_len < off + len || res_sz < len)
