+			    base_len < end || res_sz < len)
 				goto fail;
+
 			memcpy(res_dp, base + off, len);
 			res_dp += len;
 			res_sz -= len;"}

{"sha": "32596d093dc5cca553f833b7f7d1acf50b589962", "filename": "ngiflib.c", "status": "modified", "additions": 7, "deletions": 2, "changes": 9, "blob_url": "https://github.com/miniupnp/ngiflib/blob/cf429e0a2fe26b5f01ce0c8e9b79432e94509b6e/ngiflib.c", "raw_url": "https://github.com/miniupnp/ngiflib/raw/cf429e0a2fe26b5f01ce0c8e9b79432e94509b6e/ngiflib.c", "contents_url": "https://api.github.com/repos/miniupnp/ngiflib/contents/ngiflib.c?ref=cf429e0a2fe26b5f01ce0c8e9b79432e94509b6e", "patch": "@@ -528,7 +528,8 @@ static int DecodeGifImg(struct ngiflib_img * i) {
