 /*			putchar('\n'); */"}

{"sha": "ac8dc2a54e92df0ebe18ca2e434a73af715cb0ef", "filename": "ngiflib.c", "status": "modified", "additions": 18, "deletions": 0, "changes": 18, "blob_url": "https://github.com/miniupnp/ngiflib/blob/b588a2249c7abbfc52173e32ee11d6facef82f89/ngiflib.c", "raw_url": "https://github.com/miniupnp/ngiflib/raw/b588a2249c7abbfc52173e32ee11d6facef82f89/ngiflib.c", "contents_url": "https://api.github.com/repos/miniupnp/ngiflib/contents/ngiflib.c?ref=b588a2249c7abbfc52173e32ee11d6facef82f89", "patch": "@@ -408,6 +408,24 @@ static int DecodeGifImg(struct ngiflib_img * i) {
 	i->width = GetWord(i->parent);	/* SizeX   */
 	i->height = GetWord(i->parent);	/* SizeY   */

+	if((i->width > i->parent->width) || (i->height > i->parent->height)) {
+#if !defined(NGIFLIB_NO_FILE)
+		if(i->parent->log) fprintf(i->parent->log, "*** ERROR *** Image bigger than global GIF canvas !\n");
+#endif
+		return -1;
+	}
+	if((i->posX + i->width) > i->parent->width) {
+#if !defined(NGIFLIB_NO_FILE)
+		if(i->parent->log) fprintf(i->parent->log, "*** WARNING *** Adjusting X position\n");
+#endif
+		i->posX = i->parent->width - i->width;
+	}
+	if((i->posY + i->height) > i->parent->height) {
+#if !defined(NGIFLIB_NO_FILE)
+		if(i->parent->log) fprintf(i->parent->log, "*** WARNING *** Adjusting Y position\n");
+#endif
+		i->posY = i->parent->height - i->height;
+	}
 	context.Xtogo = i->width;
 	context.curY = i->posY;
 #ifdef NGIFLIB_INDEXED_ONLY"}

