{"sha": "585750ef2e77fa449609da66cac539e24407290d", "filename": "library/ssl_cli.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/ARMmbed/mbedtls/blob/740b218386083dc708ce98ccc94a63a95cd5629e/library/ssl_cli.c", "raw_url": "https://github.com/ARMmbed/mbedtls/raw/740b218386083dc708ce98ccc94a63a95cd5629e/library/ssl_cli.c", "contents_url": "https://api.github.com/repos/ARMmbed/mbedtls/contents/library/ssl_cli.c?ref=740b218386083dc708ce98ccc94a63a95cd5629e", "patch": "@@ -2057,6 +2057,12 @@ static int ssl_parse_server_psk_hint( mbedtls_ssl_context *ssl,
      *
      * opaque psk_identity_hint<0..2^16-1>;
      */
+    if( (*p) > end - 2 )
+    {
+        MBEDTLS_SSL_DEBUG_MSG( 1, ( "bad server key exchange message "
