{"sha": "279a127ba23ecd9dc8b3695786b7acef9b0e97bb", "filename": "library/ssl_cli.c", "status": "modified", "additions": 8, "deletions": 0, "changes": 8, "blob_url": "https://github.com/ARMmbed/mbedtls/blob/a1098f81c252b317ad34ea978aea2bc47760b215/library/ssl_cli.c", "raw_url": "https://github.com/ARMmbed/mbedtls/raw/a1098f81c252b317ad34ea978aea2bc47760b215/library/ssl_cli.c", "contents_url": "https://api.github.com/repos/ARMmbed/mbedtls/contents/library/ssl_cli.c?ref=a1098f81c252b317ad34ea978aea2bc47760b215", "patch": "@@ -2478,6 +2478,14 @@ static int ssl_parse_server_key_exchange( mbedtls_ssl_context *ssl )
         /*
          * Read signature
          */
+
+        if( p > end - 2 )
+        {
+            MBEDTLS_SSL_DEBUG_MSG( 1, ( "bad server key exchange message" ) );
+            mbedtls_ssl_send_alert_message( ssl, MBEDTLS_SSL_ALERT_LEVEL_FATAL,
+                                            MBEDTLS_SSL_ALERT_MSG_DECODE_ERROR );
+            return( MBEDTLS_ERR_SSL_BAD_HS_SERVER_KEY_EXCHANGE );
+        }
         sig_len = ( p[0] << 8 ) | p[1];
         p += 2;
 "}

{"sha": "17c7a1c47452387c1b7abbcbdbe168931e440a94", "filename": "ChangeLog", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/qpdf/qpdf/blob/b4d6cf6836ce025ba1811b7bbec52680c7204223/ChangeLog", "raw_url": "https://github.com/qpdf/qpdf/raw/b4d6cf6836ce025ba1811b7bbec52680c7204223/ChangeLog", "contents_url": "https://api.github.com/repos/qpdf/qpdf/contents/ChangeLog?ref=b4d6cf6836ce025ba1811b7bbec52680c7204223", "patch": "@@ -1,3 +1,8 @@
+2018-04-15  Jay Berkenbilt  <ejb@ql.org>
+
+	* Arbitrarily limit the depth of data structures represented by
