+
 2018-03-06  Jay Berkenbilt  <ejb@ql.org>

 	* 8.0.2: release"}<_**next**_>{"sha": "149668eb4dbb8d721f16ac06ebf45b33e73b68a4", "filename": "libqpdf/QPDFObjectHandle.cc", "status": "modified", "additions": 20, "deletions": 6, "changes": 26, "blob_url": "https://github.com/qpdf/qpdf/blob/b4d6cf6836ce025ba1811b7bbec52680c7204223/libqpdf/QPDFObjectHandle.cc", "raw_url": "https://github.com/qpdf/qpdf/raw/b4d6cf6836ce025ba1811b7bbec52680c7204223/libqpdf/QPDFObjectHandle.cc", "contents_url": "https://api.github.com/repos/qpdf/qpdf/contents/libqpdf/QPDFObjectHandle.cc?ref=b4d6cf6836ce025ba1811b7bbec52680c7204223", "patch": "@@ -1487,12 +1487,26 @@ QPDFObjectHandle::parseInternal(PointerHolder<InputSource> input,

