-			if (tmp_line[tmp_line_len - 1] == '\n') {
+			if (tmp_line_len >= 1 && tmp_line[tmp_line_len - 1] == '\n') {
 				--tmp_line_len;
-				if (tmp_line[tmp_line_len - 1] == '\r') {
+				if (tmp_line_len >= 1 &&tmp_line[tmp_line_len - 1] == '\r') {
 					--tmp_line_len;
 				}
 			}"}<_**next**_>{"sha": "d415de66b9007bc1b335a3ef9964fd593c1f0e1a", "filename": "ext/standard/tests/http/bug75981.phpt", "status": "added", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/php/php-src/blob/523f230c831d7b33353203fa34aee4e92ac12bba/ext/standard/tests/http/bug75981.phpt", "raw_url": "https://github.com/php/php-src/raw/523f230c831d7b33353203fa34aee4e92ac12bba/ext/standard/tests/http/bug75981.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/ext/standard/tests/http/bug75981.phpt?ref=523f230c831d7b33353203fa34aee4e92ac12bba", "patch": "@@ -0,0 +1,32 @@
+--TEST--
+Bug #75981 (stack-buffer-overflow while parsing HTTP response)
+--INI--
+allow_url_fopen=1
+--SKIPIF--
+<?php require 'server.inc'; http_server_skipif('tcp://127.0.0.1:12342'); ?>
+--FILE--
+<?php
+require 'server.inc';
+
+$options = [
+  'http' => [
+    'protocol_version' => '1.1',
+    'header' => 'Connection: Close'
+  ],
+];
+
+$ctx = stream_context_create($options);
+
+$responses = [
+	"data://text/plain,000000000100\xA\xA"
+];
+$pid = http_server('tcp://127.0.0.1:12342', $responses);
+
+echo @file_get_contents('http://127.0.0.1:12342/', false, $ctx);
+
+http_server_kill($pid);
+
+?>
+DONE
+--EXPECT--
+DONE"}

