{"sha": "40a6b17f3e0296b2b7a823405b5571cfb95535ef", "filename": "folly/Random.cpp", "status": "modified", "additions": 19, "deletions": 2, "changes": 21, "blob_url": "https://github.com/facebook/folly/blob/8e927ee48b114c8a2f90d0cbd5ac753795a6761f/folly/Random.cpp", "raw_url": "https://github.com/facebook/folly/raw/8e927ee48b114c8a2f90d0cbd5ac753795a6761f/folly/Random.cpp", "contents_url": "https://api.github.com/repos/facebook/folly/contents/folly/Random.cpp?ref=8e927ee48b114c8a2f90d0cbd5ac753795a6761f", "patch": "@@ -72,6 +72,7 @@ void readRandomDevice(void* data, size_t size) {

 class BufferedRandomDevice {
  public:
+  static once_flag flag;
   static constexpr size_t kDefaultBufferSize = 128;

   explicit BufferedRandomDevice(size_t bufferSize = kDefaultBufferSize);
@@ -97,10 +98,28 @@ class BufferedRandomDevice {
   unsigned char* ptr_;
 };

+once_flag BufferedRandomDevice::flag;
+struct RandomTag {};
+
 BufferedRandomDevice::BufferedRandomDevice(size_t bufferSize)
   : bufferSize_(bufferSize),
     buffer_(new unsigned char[bufferSize]),
     ptr_(buffer_.get() + bufferSize) {  // refill on first use
+  call_once(flag, [this]() {
+    detail::AtFork::registerHandler(
+        this,
+        /*prepare*/ []() { return true; },
+        /*parent*/ []() {},
+        /*child*/
+        []() {
+          using Single = SingletonThreadLocal<BufferedRandomDevice, RandomTag>;
+          auto& t = Single::get();
+          // Clear out buffered data on fork.
+          //
+          // Ensure child and parent do not share same entropy pool.
+          t.ptr_ = t.buffer_.get() + t.bufferSize_;
+        });
+  });
 }

 void BufferedRandomDevice::getSlow(unsigned char* data, size_t size) {
@@ -124,8 +143,6 @@ void BufferedRandomDevice::getSlow(unsigned char* data, size_t size) {
   ptr_ += size;
 }

-struct RandomTag {};
-
 } // namespace

 void Random::secureRandom(void* data, size_t size) {"}<_**next**_>{"sha": "2ee74c6de94a9d1e0165b0df18d67156cfab62f4", "filename": "folly/test/RandomTest.cpp", "status": "modified", "additions": 21, "deletions": 0, "changes": 21, "blob_url": "https://github.com/facebook/folly/blob/8e927ee48b114c8a2f90d0cbd5ac753795a6761f/folly/test/RandomTest.cpp", "raw_url": "https://github.com/facebook/folly/raw/8e927ee48b114c8a2f90d0cbd5ac753795a6761f/folly/test/RandomTest.cpp", "contents_url": "https://api.github.com/repos/facebook/folly/contents/folly/test/RandomTest.cpp?ref=8e927ee48b114c8a2f90d0cbd5ac753795a6761f", "patch": "@@ -138,3 +138,24 @@ TEST(Random, sanity) {
         std::unordered_set<uint64_t>(vals.begin(), vals.end()).size());
   }
 }
+
+TEST(Random, SecureFork) {
+  unsigned char buffer = 0;
+  // Init random buffer
+  folly::Random::secureRandom(&buffer, 1);
+
+  auto pid = fork();
+  EXPECT_NE(pid, -1);
+  if (pid) {
+    // parent
+    int status = 0;
+    folly::Random::secureRandom(&buffer, 1);
+    auto pid2 = wait(&status);
+    EXPECT_NE(WEXITSTATUS(status), buffer);
+    EXPECT_EQ(pid, pid2);
+  } else {
+    // child
+    folly::Random::secureRandom(&buffer, 1);
+    exit(buffer); // Do not print gtest results
+  }
+}"}

{"sha": "6d1d9e934f21d504c1b99cee4c8ec34b57dc5e52", "filename": "patches/proxygen-CVE-2018-6335.patch", "status": "added", "additions": 100, "deletions": 0, "changes": 100, "blob_url": "https://github.com/facebook/hhvm/blob/4cb57dd753a339654ca464c139db9871fe961d56/patches/proxygen-CVE-2018-6335.patch", "raw_url": "https://github.com/facebook/hhvm/raw/4cb57dd753a339654ca464c139db9871fe961d56/patches/proxygen-CVE-2018-6335.patch", "contents_url": "https://api.github.com/repos/facebook/hhvm/contents/patches/proxygen-CVE-2018-6335.patch?ref=4cb57dd753a339654ca464c139db9871fe961d56", "patch": "@@ -0,0 +1,100 @@
+diff --git a/third-party/proxygen/src/proxygen/lib/http/codec/HTTP2Framer.cpp b/third-party/proxygen/src/proxygen/lib/http/codec/HTTP2Framer.cpp
+index 068fea4b..9dc0c994 100644
+--- a/third-party/proxygen/src/proxygen/lib/http/codec/HTTP2Framer.cpp
++++ b/third-party/proxygen/src/proxygen/lib/http/codec/HTTP2Framer.cpp
+@@ -187,6 +187,11 @@ parsePadding(Cursor& cursor,
+   } else {
+     padding = 0;
+   }
++
++  if (header.length < padding) {
++    return ErrorCode::PROTOCOL_ERROR;
++  }
++  header.length -= padding;
+   return ErrorCode::NO_ERROR;
+ }
+ 
+@@ -259,7 +264,7 @@ parseData(Cursor& cursor,
+   // outPadding is the total number of flow-controlled pad bytes, which
+   // includes the length byte, if present.
+   outPadding = padding + ((frameHasPadding(header)) ? 1 : 0);
+-  cursor.clone(outBuf, header.length - padding);
++  cursor.clone(outBuf, header.length);
+   return skipPadding(cursor, padding, kStrictPadding);
+ }
+ 
+@@ -313,7 +318,7 @@ parseHeaders(Cursor& cursor,
+   if (header.length < padding) {
+     return ErrorCode::PROTOCOL_ERROR;
+   }
+-  cursor.clone(outBuf, header.length - padding);
++  cursor.clone(outBuf, header.length);
+   return skipPadding(cursor, padding, kStrictPadding);
+ }
+ 
+@@ -398,7 +403,7 @@ parsePushPromise(Cursor& cursor,
+   if (header.length < padding) {
+     return ErrorCode::PROTOCOL_ERROR;
+   }
+-  cursor.clone(outBuf, header.length - padding);
++  cursor.clone(outBuf, header.length);
+   return skipPadding(cursor, padding, kStrictPadding);
+ }
+ 
+@@ -470,7 +475,7 @@ parseContinuation(Cursor& cursor,
+   if (header.length < padding) {
+     return ErrorCode::PROTOCOL_ERROR;
+   }
+-  cursor.clone(outBuf, header.length - padding);
++  cursor.clone(outBuf, header.length);
+   return skipPadding(cursor, padding, kStrictPadding);
+ }
+ 
+diff --git a/third-party/proxygen/src/proxygen/lib/http/codec/test/HTTP2CodecTest.cpp b/third-party/proxygen/src/proxygen/lib/http/codec/test/HTTP2CodecTest.cpp
+index 97008421..a859861c 100644
+--- a/third-party/proxygen/src/proxygen/lib/http/codec/test/HTTP2CodecTest.cpp
++++ b/third-party/proxygen/src/proxygen/lib/http/codec/test/HTTP2CodecTest.cpp
+@@ -638,15 +638,17 @@ TEST_F(HTTP2CodecTest, MalformedPaddingLength) {
+   output_.append(badInput, sizeof(badInput));
+   EXPECT_EQ(output_.chainLength(), sizeof(badInput));
+ 
+-  bool caughtException = false;
+-  bool parseResult = true;
+-  try {
+-    parseResult = parse();
+-  } catch (const std::exception &e) {
+-    caughtException = true;
+-  }
+-  EXPECT_FALSE(caughtException);
+-  EXPECT_FALSE(parseResult);
++  EXPECT_FALSE(parse());
++}
++
++TEST_F(HTTP2CodecTest, MalformedPadding) {
++  const uint8_t badInput[] = {
++    0x00, 0x00, 0x0d, 0x01, 0xbe, 0x63, 0x0d, 0x0a, 0x0d, 0x0a, 0x00, 0x73,
++    0x00, 0x00, 0x06, 0x08, 0x72, 0x00, 0x24, 0x00, 0xfa, 0x4d, 0x0d
++  };
++  output_.append(badInput, sizeof(badInput));
++
++  EXPECT_FALSE(parse());
+ }
+ 
+ TEST_F(HTTP2CodecTest, NoAppByte) {
+@@ -659,15 +661,7 @@ TEST_F(HTTP2CodecTest, NoAppByte) {
+   output_.append(noAppByte, sizeof(noAppByte));
+   EXPECT_EQ(output_.chainLength(), sizeof(noAppByte));
+ 
+-  bool caughtException = false;
+-  bool parseResult = false;
+-  try {
+-    parseResult = parse();
+-  } catch (const std::exception &e) {
+-    caughtException = true;
+-  }
+-  EXPECT_FALSE(caughtException);
+-  EXPECT_TRUE(parseResult);
++  EXPECT_TRUE(parse());
+   EXPECT_EQ(callbacks_.messageBegin, 0);
+   EXPECT_EQ(callbacks_.headersComplete, 0);
+   EXPECT_EQ(callbacks_.messageComplete, 0);"}

