{"sha": "31cef9b673ac703048a3f6d13282131caf3ffb5b", "filename": "dcraw/dcraw.c", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/LibRaw/LibRaw/blob/8260dcf3db045923a5ca5c05170f9bc7a4bd971a/dcraw/dcraw.c", "raw_url": "https://github.com/LibRaw/LibRaw/raw/8260dcf3db045923a5ca5c05170f9bc7a4bd971a/dcraw/dcraw.c", "contents_url": "https://api.github.com/repos/LibRaw/LibRaw/contents/dcraw/dcraw.c?ref=8260dcf3db045923a5ca5c05170f9bc7a4bd971a", "patch": "@@ -15678,11 +15678,18 @@ void CLASS parse_minolta(int base)
