{"sha": "a830cc8a7d9f3e15d22e9174b8c52b28cc147240", "filename": "src/analyzer/protocol/tcp/ContentLine.cc", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/bro/bro/blob/6c0f101a62489b1c5927b4ed63b0e1d37db40282/src/analyzer/protocol/tcp/ContentLine.cc", "raw_url": "https://github.com/bro/bro/raw/6c0f101a62489b1c5927b4ed63b0e1d37db40282/src/analyzer/protocol/tcp/ContentLine.cc", "contents_url": "https://api.github.com/repos/bro/bro/contents/src/analyzer/protocol/tcp/ContentLine.cc?ref=6c0f101a62489b1c5927b4ed63b0e1d37db40282", "patch": "@@ -250,6 +250,16 @@ int ContentLine_Analyzer::DoDeliverOnce(int len, const u_char* data)
 		case '\n':
 			if ( last_char == '\r' )
 				{
+				// Weird corner-case:
+				// this can happen if we see a \r at the end of a packet where crlf is
+				// set to CR_as_EOL | LF_as_EOL, with the packet causing crlf to be set to
+				// 0 and the next packet beginning with a \n. In this case we just swallow
+				// the character and re-set last_char.
+				if ( offset == 0 )
+					{
+					last_char = c;
+					break;
+					}
 				--offset; // remove '\r'
 				EMIT_LINE
 				}"}

