 	key->magic = KEY_DEBUG_MAGIC;"}<_**next**_>{"sha": "4fa82a8a9c0e6cb778a08874724ea546cd602ade", "filename": "security/keys/keyring.c", "status": "modified", "additions": 14, "deletions": 9, "changes": 23, "blob_url": "https://github.com/torvalds/linux/blob/237bbd29f7a049d310d907f4b2716a7feef9abf3/security/keys/keyring.c", "raw_url": "https://github.com/torvalds/linux/raw/237bbd29f7a049d310d907f4b2716a7feef9abf3/security/keys/keyring.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/security/keys/keyring.c?ref=237bbd29f7a049d310d907f4b2716a7feef9abf3", "patch": "@@ -1097,15 +1097,15 @@ key_ref_t find_key_to_update(key_ref_t keyring_ref,
 /*
  * Find a keyring with the specified name.
  *
- * All named keyrings in the current user namespace are searched, provided they
- * grant Search permission directly to the caller (unless this check is
- * skipped).  Keyrings whose usage points have reached zero or who have been
- * revoked are skipped.
+ * Only keyrings that have nonzero refcount, are not revoked, and are owned by a
+ * user in the current user namespace are considered.  If @uid_keyring is %true,
+ * the keyring additionally must have been allocated as a user or user session
+ * keyring; otherwise, it must grant Search permission directly to the caller.
  *
  * Returns a pointer to the keyring with the keyring's refcount having being
  * incremented on success.  -ENOKEY is returned if a key could not be found.
  */
-struct key *find_keyring_by_name(const char *name, bool skip_perm_check)
+struct key *find_keyring_by_name(const char *name, bool uid_keyring)
 {
 	struct key *keyring;
 	int bucket;
@@ -1133,10 +1133,15 @@ struct key *find_keyring_by_name(const char *name, bool skip_perm_check)
 			if (strcmp(keyring->description, name) != 0)
 				continue;

-			if (!skip_perm_check &&
-			    key_permission(make_key_ref(keyring, 0),
