+			}

 			/* we've got a match but we might end up racing with
 			 * key_cleanup() if the keyring is currently 'dead'"}<_**next**_>{"sha": "293d3598153bf0c8611f319f4c1d7c50f364e600", "filename": "security/keys/process_keys.c", "status": "modified", "additions": 4, "deletions": 2, "changes": 6, "blob_url": "https://github.com/torvalds/linux/blob/237bbd29f7a049d310d907f4b2716a7feef9abf3/security/keys/process_keys.c", "raw_url": "https://github.com/torvalds/linux/raw/237bbd29f7a049d310d907f4b2716a7feef9abf3/security/keys/process_keys.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/security/keys/process_keys.c?ref=237bbd29f7a049d310d907f4b2716a7feef9abf3", "patch": "@@ -77,7 +77,8 @@ int install_user_keyrings(void)
