{"sha": "c1c1cdf0b8117879d55e66cb54fd752637130f76", "filename": "kernel/events/core.c", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/torvalds/linux/blob/1572e45a924f254d9570093abde46430c3172e3d/kernel/events/core.c", "raw_url": "https://github.com/torvalds/linux/raw/1572e45a924f254d9570093abde46430c3172e3d/kernel/events/core.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/events/core.c?ref=1572e45a924f254d9570093abde46430c3172e3d", "patch": "@@ -455,7 +455,7 @@ int perf_cpu_time_max_percent_handler(struct ctl_table *table, int write,
