{"sha": "d1516327b7875c9ce3e948c66a6620d9b5b8d5da", "filename": "fs/ocfs2/aops.c", "status": "modified", "additions": 18, "deletions": 8, "changes": 26, "blob_url": "https://github.com/torvalds/linux/blob/3e4c56d41eef5595035872a2ec5a483f42e8917f/fs/ocfs2/aops.c", "raw_url": "https://github.com/torvalds/linux/raw/3e4c56d41eef5595035872a2ec5a483f42e8917f/fs/ocfs2/aops.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/ocfs2/aops.c?ref=3e4c56d41eef5595035872a2ec5a483f42e8917f", "patch": "@@ -134,6 +134,19 @@ static int ocfs2_symlink_get_block(struct inode *inode, sector_t iblock,
 	return err;
 }

+static int ocfs2_lock_get_block(struct inode *inode, sector_t iblock,
+		    struct buffer_head *bh_result, int create)
+{
+	int ret = 0;
+	struct ocfs2_inode_info *oi = OCFS2_I(inode);
+
+	down_read(&oi->ip_alloc_sem);
+	ret = ocfs2_get_block(inode, iblock, bh_result, create);
+	up_read(&oi->ip_alloc_sem);
+
+	return ret;
+}
+
 int ocfs2_get_block(struct inode *inode, sector_t iblock,
 		    struct buffer_head *bh_result, int create)
 {
@@ -2128,7 +2141,7 @@ static void ocfs2_dio_free_write_ctx(struct inode *inode,
  * called like this: dio->get_blocks(dio->inode, fs_startblk,
  * 					fs_count, map_bh, dio->rw == WRITE);
