{"sha": "824f4c1c1f3103dab4596ffc287c438fbc0345b3", "filename": "drivers/input/serio/i8042.c", "status": "modified", "additions": 9, "deletions": 3, "changes": 12, "blob_url": "https://github.com/torvalds/linux/blob/340d394a789518018f834ff70f7534fc463d3226/drivers/input/serio/i8042.c", "raw_url": "https://github.com/torvalds/linux/raw/340d394a789518018f834ff70f7534fc463d3226/drivers/input/serio/i8042.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/input/serio/i8042.c?ref=340d394a789518018f834ff70f7534fc463d3226", "patch": "@@ -436,8 +436,10 @@ static int i8042_start(struct serio *serio)
 {
 	struct i8042_port *port = serio->port_data;

+	spin_lock_irq(&i8042_lock);
 	port->exists = true;
-	mb();
+	spin_unlock_irq(&i8042_lock);
+
 	return 0;
 }

@@ -450,16 +452,20 @@ static void i8042_stop(struct serio *serio)
 {
 	struct i8042_port *port = serio->port_data;

+	spin_lock_irq(&i8042_lock);
 	port->exists = false;
+	port->serio = NULL;
+	spin_unlock_irq(&i8042_lock);

 	/*
+	 * We need to make sure that interrupt handler finishes using
+	 * our serio port before we return from this function.
 	 * We synchronize with both AUX and KBD IRQs because there is
 	 * a (very unlikely) chance that AUX IRQ is raised for KBD port
 	 * and vice versa.
 	 */
 	synchronize_irq(I8042_AUX_IRQ);
 	synchronize_irq(I8042_KBD_IRQ);
-	port->serio = NULL;
 }

 /*
@@ -576,7 +582,7 @@ static irqreturn_t i8042_interrupt(int irq, void *dev_id)

