{"sha": "54c954a1317d7060e97342098bc2beca29f4761d", "filename": "dcraw/dcraw.c", "status": "modified", "additions": 31, "deletions": 1, "changes": 32, "blob_url": "https://github.com/LibRaw/LibRaw/blob/5563e6ddc3f7cb93d98b491194ceebdee7288d36/dcraw/dcraw.c", "raw_url": "https://github.com/LibRaw/LibRaw/raw/5563e6ddc3f7cb93d98b491194ceebdee7288d36/dcraw/dcraw.c", "contents_url": "https://api.github.com/repos/LibRaw/LibRaw/contents/dcraw/dcraw.c?ref=5563e6ddc3f7cb93d98b491194ceebdee7288d36", "patch": "@@ -7045,6 +7045,8 @@ void CLASS xtrans_interpolate(int passes)
