 }"}

{"sha": "1c713fd5b3e67966c3d998979d2c30eb8e14ba07", "filename": "fs/userfaultfd.c", "status": "modified", "additions": 56, "deletions": 10, "changes": 66, "blob_url": "https://github.com/torvalds/linux/blob/384632e67e0829deb8015ee6ad916b180049d252/fs/userfaultfd.c", "raw_url": "https://github.com/torvalds/linux/raw/384632e67e0829deb8015ee6ad916b180049d252/fs/userfaultfd.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/userfaultfd.c?ref=384632e67e0829deb8015ee6ad916b180049d252", "patch": "@@ -588,6 +588,12 @@ static void userfaultfd_event_wait_completion(struct userfaultfd_ctx *ctx,
