 /* }}} */"}<_**next**_>{"sha": "3cf44d11ffabc85bda71884153a6874ad6022d32", "filename": "sapi/fpm/tests/bug73342-nonblocking-stdio.phpt", "status": "added", "additions": 46, "deletions": 0, "changes": 46, "blob_url": "https://github.com/php/php-src/blob/69dee5c732fe982c82edb17d0dbc3e79a47748d8/sapi/fpm/tests/bug73342-nonblocking-stdio.phpt", "raw_url": "https://github.com/php/php-src/raw/69dee5c732fe982c82edb17d0dbc3e79a47748d8/sapi/fpm/tests/bug73342-nonblocking-stdio.phpt", "contents_url": "https://api.github.com/repos/php/php-src/contents/sapi/fpm/tests/bug73342-nonblocking-stdio.phpt?ref=69dee5c732fe982c82edb17d0dbc3e79a47748d8", "patch": "@@ -0,0 +1,46 @@
+--TEST--
+FPM: bug73342 - Non-blocking stdin
+--SKIPIF--
+<?php include "skipif.inc"; ?>
+--FILE--
+<?php
+
+require_once "tester.inc";
+
+$cfg = <<<EOT
+[global]
+error_log = {{FILE:LOG}}
+[unconfined]
+listen = {{ADDR}}
+pm = dynamic
+pm.max_children = 5
+pm.start_servers = 1
+pm.min_spare_servers = 1
+pm.max_spare_servers = 3
+EOT;
+
+$code = <<<EOT
+<?php
+echo "Before\n";
+stream_set_blocking(fopen('php://stdin', 'r'), false);
+echo "After\n";
+EOT;
+
+$tester = new FPM\Tester($cfg, $code);
+$tester->start();
+$tester->expectLogStartNotices();
+$tester->request()->expectBody("Before\nAfter");
+$tester->request()->expectBody("Before\nAfter");
+$tester->terminate();
+$tester->expectLogTerminatingNotices();
+$tester->close();
+
+?>
+Done
+--EXPECT--
+Done
+--CLEAN--
+<?php
+require_once "tester.inc";
+FPM\Tester::clean();
+?>"}

{"sha": "649e5aac56a1c8d9fa9270060bbde1d74b6571cf", "filename": "ChangeLog", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/qpdf/qpdf/blob/701b518d5c56a1449825a3a37a716c58e05e1c3e/ChangeLog", "raw_url": "https://github.com/qpdf/qpdf/raw/701b518d5c56a1449825a3a37a716c58e05e1c3e/ChangeLog", "contents_url": "https://api.github.com/repos/qpdf/qpdf/contents/ChangeLog?ref=701b518d5c56a1449825a3a37a716c58e05e1c3e", "patch": "@@ -1,5 +1,10 @@
 2017-07-26  Jay Berkenbilt  <ejb@ql.org>

+	* Detect infinite loops while resolving objects. This could happen
+	if something inside an object that had to be resolved during
+	parsing, such as a stream length, recursively referenced the
+	object being resolved.
+
 	* CVE-2017-9208: Handle references to and appearance of object 0
 	as a special case. Object 0 is not allowed, and qpdf was using it
 	internally to represent direct objects."}<_**next**_>{"sha": "4742275f9932d2b136423d36226a46d91844049c", "filename": "include/qpdf/QPDF.hh", "status": "modified", "additions": 20, "deletions": 0, "changes": 20, "blob_url": "https://github.com/qpdf/qpdf/blob/701b518d5c56a1449825a3a37a716c58e05e1c3e/include/qpdf/QPDF.hh", "raw_url": "https://github.com/qpdf/qpdf/raw/701b518d5c56a1449825a3a37a716c58e05e1c3e/include/qpdf/QPDF.hh", "contents_url": "https://api.github.com/repos/qpdf/qpdf/contents/include/qpdf/QPDF.hh?ref=701b518d5c56a1449825a3a37a716c58e05e1c3e", "patch": "@@ -603,6 +603,25 @@ class QPDF
         int gen;
     };

+    class ResolveRecorder
+    {
+      public:
+        ResolveRecorder(QPDF* qpdf, QPDFObjGen const& og) :
+            qpdf(qpdf),
+            og(og)
+        {
+            qpdf->resolving.insert(og);
+        }
+        virtual ~ResolveRecorder()
+        {
+            this->qpdf->resolving.erase(og);
+        }
+      private:
+        QPDF* qpdf;
+        QPDFObjGen og;
+    };
+    friend class ResolveRecorder;
+
     void parse(char const* password);
     void warn(QPDFExc const& e);
     void setTrailer(QPDFObjectHandle obj);
@@ -1065,6 +1084,7 @@ class QPDF
     std::map<QPDFObjGen, QPDFXRefEntry> xref_table;
     std::set<int> deleted_objects;
     std::map<QPDFObjGen, ObjCache> obj_cache;
+    std::set<QPDFObjGen> resolving;
     QPDFObjectHandle trailer;
     std::vector<QPDFObjectHandle> all_pages;
     std::map<QPDFObjGen, int> pageobj_to_pages_pos;"}<_**next**_>{"sha": "ecc134916d5c1d7767ddae2b0bfebf416d8449ff", "filename": "libqpdf/QPDF.cc", "status": "modified", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/qpdf/qpdf/blob/701b518d5c56a1449825a3a37a716c58e05e1c3e/libqpdf/QPDF.cc", "raw_url": "https://github.com/qpdf/qpdf/raw/701b518d5c56a1449825a3a37a716c58e05e1c3e/libqpdf/QPDF.cc", "contents_url": "https://api.github.com/repos/qpdf/qpdf/contents/libqpdf/QPDF.cc?ref=701b518d5c56a1449825a3a37a716c58e05e1c3e", "patch": "@@ -1471,6 +1471,21 @@ QPDF::resolve(int objid, int generation)
     // to insert things into the object cache that don't actually
     // exist in the file.
     QPDFObjGen og(objid, generation);
+    if (this->resolving.count(og))
+    {
+        // This can happen if an object references itself directly or
+        // indirectly in some key that has to be resolved during
+        // object parsing, such as stream length.
+	QTC::TC("qpdf", "QPDF recursion loop in resolve");
+	warn(QPDFExc(qpdf_e_damaged_pdf, this->file->getName(),
+		     "", this->file->getLastOffset(),
+		     "loop detected resolving object " +
+		     QUtil::int_to_string(objid) + " " +
+		     QUtil::int_to_string(generation)));
+        return new QPDF_Null;
+    }
+    ResolveRecorder rr(this, og);
+
     if (! this->obj_cache.count(og))
     {
