 		}
 "}<_**next**_>{"sha": "9eb2cf4f01cb874706d64af87a01e94e0121f7e4", "filename": "block/blk-mq-tag.h", "status": "modified", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/torvalds/linux/blob/0048b4837affd153897ed1222283492070027aa9/block/blk-mq-tag.h", "raw_url": "https://github.com/torvalds/linux/raw/0048b4837affd153897ed1222283492070027aa9/block/blk-mq-tag.h", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/block/blk-mq-tag.h?ref=0048b4837affd153897ed1222283492070027aa9", "patch": "@@ -89,4 +89,16 @@ static inline void blk_mq_tag_idle(struct blk_mq_hw_ctx *hctx)
 	__blk_mq_tag_idle(hctx);
 }

+/*
+ * This helper should only be used for flush request to share tag
+ * with the request cloned from, and both the two requests can't be
+ * in flight at the same time. The caller has to make sure the tag
+ * can't be freed.
+ */
+static inline void blk_mq_tag_set_rq(struct blk_mq_hw_ctx *hctx,
+		unsigned int tag, struct request *rq)
+{
+	hctx->tags->rqs[tag] = rq;
+}
+
 #endif"}<_**next**_>{"sha": "f2d67b4047a04d7015c3c2af16871972c3b5a720", "filename": "block/blk-mq.c", "status": "modified", "additions": 1, "deletions": 15, "changes": 16, "blob_url": "https://github.com/torvalds/linux/blob/0048b4837affd153897ed1222283492070027aa9/block/blk-mq.c", "raw_url": "https://github.com/torvalds/linux/raw/0048b4837affd153897ed1222283492070027aa9/block/blk-mq.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/block/blk-mq.c?ref=0048b4837affd153897ed1222283492070027aa9", "patch": "@@ -559,23 +559,9 @@ void blk_mq_abort_requeue_list(struct request_queue *q)
