{"sha": "29269819331b8d94f07875bb5313e59a325f55ff", "filename": "core/arch/arm/tee/entry_std.c", "status": "modified", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/OP-TEE/optee_os/blob/e3adcf566cb278444830e7badfdcc3983e334fd1/core/arch/arm/tee/entry_std.c", "raw_url": "https://github.com/OP-TEE/optee_os/raw/e3adcf566cb278444830e7badfdcc3983e334fd1/core/arch/arm/tee/entry_std.c", "contents_url": "https://api.github.com/repos/OP-TEE/optee_os/contents/core/arch/arm/tee/entry_std.c?ref=e3adcf566cb278444830e7badfdcc3983e334fd1", "patch": "@@ -101,6 +101,7 @@ static TEE_Result set_tmem_param(const struct optee_msg_param_tmem *tmem,
