{"sha": "c335fb05524c80260fc814468a5c45253582d88b", "filename": "rpcapd/daemon.c", "status": "modified", "additions": 44, "deletions": 7, "changes": 51, "blob_url": "https://github.com/the-tcpdump-group/libpcap/blob/484d60cbf7ca4ec758c3cbb8a82d68b244a78d58/rpcapd/daemon.c", "raw_url": "https://github.com/the-tcpdump-group/libpcap/raw/484d60cbf7ca4ec758c3cbb8a82d68b244a78d58/rpcapd/daemon.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/libpcap/contents/rpcapd/daemon.c?ref=484d60cbf7ca4ec758c3cbb8a82d68b244a78d58", "patch": "@@ -1176,20 +1176,33 @@ daemon_AuthUserPwd(char *username, char *password, char *errbuf)
