 	while ( size_left ) {
 		uint32_t id;

+		if ( size_left < 4 ) {
+			LogError("Process_ipfix [%u] Template withdraw size error at %s line %u" , 
+				exporter->info.id, __FILE__, __LINE__, strerror (errno));
+			size_left = 0;
+			continue;
+		}
+
+
 		// map next record.
 		ipfix_template_record = (ipfix_template_record_t *)DataPtr;
 		size_left 		-= 4;"}

{"sha": "501f49f8e529ef0fef7d818196820fff571d9fb8", "filename": "src/Importers/ImportEPUB.cpp", "status": "modified", "additions": 8, "deletions": 0, "changes": 8, "blob_url": "https://github.com/Sigil-Ebook/Sigil/blob/369eebe936e4a8c83cc54662a3412ce8bef189e4/src/Importers/ImportEPUB.cpp", "raw_url": "https://github.com/Sigil-Ebook/Sigil/raw/369eebe936e4a8c83cc54662a3412ce8bef189e4/src/Importers/ImportEPUB.cpp", "contents_url": "https://api.github.com/repos/Sigil-Ebook/Sigil/contents/src/Importers/ImportEPUB.cpp?ref=369eebe936e4a8c83cc54662a3412ce8bef189e4", "patch": "@@ -424,6 +424,14 @@ void ImportEPUB::ExtractContainer()

             // If there is no file name then we can't do anything with it.
             if (!qfile_name.isEmpty()) {
+
+	        // for security reasons we need the file path to always be inside the 
+                // target folder and not outside, so we will remove all relative upward 
+                // paths segments ".." from the file path before prepending the target 
+                // folder to create the final target path
+	        qfile_name = qfile_name.replace("../","");
+                cp437_file_name = cp437_file_name.replace("../","");
+
                 // We use the dir object to create the path in the temporary directory.
                 // Unfortunately, we need a dir ojbect to do this as it's not a static function.
                 QDir dir(m_ExtractedFolderPath);"}

