+tftpfdt=if run set_fdthigh || test ${arch} != arm; then if tftpboot ${fdt_addr_r} ${tftppath}/fdt_0x${IVM_BoardId}_0x${IVM_HWKey}.dtb; then; else tftpboot ${fdt_addr_r} ${tftppath}/${hostname}.dtb; fi; else true; fi
+tftpkernel=tftpboot ${load_addr_r} ${tftppath}/${uimage}
+tftpramfs=tftpboot ${rootfsaddr} ${tftppath}/rootfsImage
 set_uimage=printenv uimage || setenv uimage uImage
+set_tftppath=if test ${hostname} = kmcoge5un; then setenv tftppath CI5UN; else if test ${hostname} = kmcoge5ne; then setenv tftppath CI5NE; else setenv tftppath ${IVM_Symbol}; fi; fi
+try_import_rootfssize=if tftpboot 0x200000 ${tftppath}/rootfssize.txt; then env import -t 0x200000 ${filesize}; else echo no auto rootfs size; echo you can set rootfssize in /tftpboot/${tftppath}/rootfssize.txt and rerun ramfs; fi"}<_**next**_>{"sha": "b890ba51cb035cc1892707ddefd0a4d461621712", "filename": "board/ste/stemmy/Kconfig", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/u-boot/u-boot/blob/2c871f9e084b2c03d1961884228a6901387ab8d6/board/ste/stemmy/Kconfig", "raw_url": "https://github.com/u-boot/u-boot/raw/2c871f9e084b2c03d1961884228a6901387ab8d6/board/ste/stemmy/Kconfig", "contents_url": "https://api.github.com/repos/u-boot/u-boot/contents/board/ste/stemmy/Kconfig?ref=2c871f9e084b2c03d1961884228a6901387ab8d6", "patch": "@@ -0,0 +1,12 @@
