+}"}<_**next**_>{"sha": "53af04d7dc75bdef091c34f7d94c7d97ace60777", "filename": "cmd/pxe_utils.c", "status": "modified", "additions": 2, "deletions": 1, "changes": 3, "blob_url": "https://github.com/u-boot/u-boot/blob/2c871f9e084b2c03d1961884228a6901387ab8d6/cmd/pxe_utils.c", "raw_url": "https://github.com/u-boot/u-boot/raw/2c871f9e084b2c03d1961884228a6901387ab8d6/cmd/pxe_utils.c", "contents_url": "https://api.github.com/repos/u-boot/u-boot/contents/cmd/pxe_utils.c?ref=2c871f9e084b2c03d1961884228a6901387ab8d6", "patch": "@@ -1312,7 +1312,8 @@ void handle_pxe_menu(cmd_tbl_t *cmdtp, struct pxe_menu *cfg)
