 #endif

 /*
- * Overflowless variant of (block_count * mul_by / 2**div_by)
- * when div_by > mul_by
+ * Overflowless variant of (block_count * mul_by / 2**right_shift)
+ * when 2**right_shift > mul_by
  */
-static lba512_t lba512_muldiv(lba512_t block_count, lba512_t mul_by, int div_by)
+static lba512_t lba512_muldiv(lba512_t block_count, lba512_t mul_by,
+			      int right_shift)
 {
 	lba512_t bc_quot, bc_rem;

 	/* x * m / d == x / d * m + (x % d) * m / d */
-	bc_quot = block_count >> div_by;
-	bc_rem  = block_count - (bc_quot << div_by);
-	return bc_quot * mul_by + ((bc_rem * mul_by) >> div_by);
+	bc_quot = block_count >> right_shift;
+	bc_rem  = block_count - (bc_quot << right_shift);
+	return bc_quot * mul_by + ((bc_rem * mul_by) >> right_shift);
 }

 void dev_print (struct blk_desc *dev_desc)"}<_**next**_>{"sha": "4e5a70780a99864fd57dbfadd4d5509a3adb267a", "filename": "drivers/gpio/Kconfig", "status": "modified", "additions": 2, "deletions": 1, "changes": 3, "blob_url": "https://github.com/u-boot/u-boot/blob/2c871f9e084b2c03d1961884228a6901387ab8d6/drivers/gpio/Kconfig", "raw_url": "https://github.com/u-boot/u-boot/raw/2c871f9e084b2c03d1961884228a6901387ab8d6/drivers/gpio/Kconfig", "contents_url": "https://api.github.com/repos/u-boot/u-boot/contents/drivers/gpio/Kconfig?ref=2c871f9e084b2c03d1961884228a6901387ab8d6", "patch": "@@ -55,7 +55,8 @@ config ALTERA_PIO

