 	depends on TIMER"}<_**next**_>{"sha": "c22ffebcdec766ad01da70dffec0be6b26d35ede", "filename": "drivers/timer/Makefile", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/u-boot/u-boot/blob/2c871f9e084b2c03d1961884228a6901387ab8d6/drivers/timer/Makefile", "raw_url": "https://github.com/u-boot/u-boot/raw/2c871f9e084b2c03d1961884228a6901387ab8d6/drivers/timer/Makefile", "contents_url": "https://api.github.com/repos/u-boot/u-boot/contents/drivers/timer/Makefile?ref=2c871f9e084b2c03d1961884228a6901387ab8d6", "patch": "@@ -12,6 +12,7 @@ obj-$(CONFIG_ATMEL_PIT_TIMER) += atmel_pit_timer.o
 obj-$(CONFIG_CADENCE_TTC_TIMER)	+= cadence-ttc.o
 obj-$(CONFIG_DESIGNWARE_APB_TIMER)	+= dw-apb-timer.o
