 -------------------------------------"}<_**next**_>{"sha": "1ec2566732313f8427bd99b0dbcf14a49fd7c38f", "filename": "configure.ac", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/Yubico/pam-u2f/blob/7db3386fcdb454e33a3ea30dcfb8e8960d4c3aa3/configure.ac", "raw_url": "https://github.com/Yubico/pam-u2f/raw/7db3386fcdb454e33a3ea30dcfb8e8960d4c3aa3/configure.ac", "contents_url": "https://api.github.com/repos/Yubico/pam-u2f/contents/configure.ac?ref=7db3386fcdb454e33a3ea30dcfb8e8960d4c3aa3", "patch": "@@ -37,6 +37,8 @@ AC_CHECK_HEADERS([security/pam_modules.h security/_pam_macros.h security/pam_mod
