+#ifndef __PAM_U2F_DROP_PRIVS_H_INCLUDED__
+#define __PAM_U2F_DROP_PRIVS_H_INCLUDED__
+
+#ifdef HAVE_PAM_MODUTIL_DROP_PRIV
+#include <security/pam_modutil.h>
+#else
+
+#include <pwd.h>
+#include <stdio.h>
+
+#ifdef HAVE_SECURITY_PAM_APPL_H
+#include <security/pam_appl.h>
+#endif
+#ifdef HAVE_SECURITY_PAM_MODULES_H
+#include <security/pam_modules.h>
+#endif
+
+#define SAVED_GROUPS_MAX_LEN 64 /* as pam_modutil.. */
+
+struct _ykpam_privs {
+  uid_t saved_euid;
+  gid_t saved_egid;
+  gid_t *saved_groups;
+  int saved_groups_length;
+  FILE *debug_file;
+};
+
+#define PAM_MODUTIL_DEF_PRIVS(n) \
+  gid_t n##_saved_groups[SAVED_GROUPS_MAX_LEN]; \
+  struct _ykpam_privs n = {-1, -1, n##_saved_groups, SAVED_GROUPS_MAX_LEN, cfg->debug_file}
+
+int pam_modutil_drop_priv(pam_handle_t *, struct _ykpam_privs *, struct passwd *);
+int pam_modutil_regain_priv(pam_handle_t *, struct _ykpam_privs *);
+
+#endif
+#endif"}<_**next**_>{"sha": "b01697c202474a8462afbdf59ea3ccbc9d513154", "filename": "pam-u2f.c", "status": "modified", "additions": 22, "deletions": 9, "changes": 31, "blob_url": "https://github.com/Yubico/pam-u2f/blob/7db3386fcdb454e33a3ea30dcfb8e8960d4c3aa3/pam-u2f.c", "raw_url": "https://github.com/Yubico/pam-u2f/raw/7db3386fcdb454e33a3ea30dcfb8e8960d4c3aa3/pam-u2f.c", "contents_url": "https://api.github.com/repos/Yubico/pam-u2f/contents/pam-u2f.c?ref=7db3386fcdb454e33a3ea30dcfb8e8960d4c3aa3", "patch": "@@ -20,6 +20,7 @@
