{"sha": "9ec07d0609ab1bfe04a7893d0fbe7c7ea26621a9", "filename": "lib/krb5/init_creds_pw.c", "status": "modified", "additions": 20, "deletions": 0, "changes": 20, "blob_url": "https://github.com/heimdal/heimdal/blob/2f7f3d9960aa6ea21358bdf3687cee5149aa35cf/lib/krb5/init_creds_pw.c", "raw_url": "https://github.com/heimdal/heimdal/raw/2f7f3d9960aa6ea21358bdf3687cee5149aa35cf/lib/krb5/init_creds_pw.c", "contents_url": "https://api.github.com/repos/heimdal/heimdal/contents/lib/krb5/init_creds_pw.c?ref=2f7f3d9960aa6ea21358bdf3687cee5149aa35cf", "patch": "@@ -2267,6 +2267,26 @@ krb5_init_creds_step(krb5_context context,
 				       &ctx->req_buffer,
 				       NULL,
 				       NULL);
+	    if (ret == 0 && ctx->pk_init_ctx) {
+		PA_DATA *pa_pkinit_kx;
+		int idx = 0;
+
+		pa_pkinit_kx =
+		    krb5_find_padata(rep.kdc_rep.padata->val,
+				     rep.kdc_rep.padata->len,
+				     KRB5_PADATA_PKINIT_KX,
+				     &idx);
+
+		ret = _krb5_pk_kx_confirm(context, ctx->pk_init_ctx,
+					  ctx->fast_state.reply_key,
