   }"}<_**next**_>{"sha": "c6fee71a722f0154c8ebac927e0ea530810d40fe", "filename": "hphp/test/slow/string/number_format_t53795309.php", "status": "added", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/facebook/hhvm/blob/dbeb9a56a638e3fdcef8b691c2a2967132dae692/hphp/test/slow/string/number_format_t53795309.php", "raw_url": "https://github.com/facebook/hhvm/raw/dbeb9a56a638e3fdcef8b691c2a2967132dae692/hphp/test/slow/string/number_format_t53795309.php", "contents_url": "https://api.github.com/repos/facebook/hhvm/contents/hphp/test/slow/string/number_format_t53795309.php?ref=dbeb9a56a638e3fdcef8b691c2a2967132dae692", "patch": "@@ -0,0 +1,9 @@
