{"sha": "b6f2ae7b7b5220bd00475541c6c1de2f1b20b681", "filename": "libavcodec/mpeg4videodec.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/FFmpeg/FFmpeg/blob/d227ed5d598340e719eff7156b1aa0a4469e9a6a/libavcodec/mpeg4videodec.c", "raw_url": "https://github.com/FFmpeg/FFmpeg/raw/d227ed5d598340e719eff7156b1aa0a4469e9a6a/libavcodec/mpeg4videodec.c", "contents_url": "https://api.github.com/repos/FFmpeg/FFmpeg/contents/libavcodec/mpeg4videodec.c?ref=d227ed5d598340e719eff7156b1aa0a4469e9a6a", "patch": "@@ -1899,14 +1899,20 @@ static int mpeg4_decode_studio_block(MpegEncContext *s, int32_t block[64], int n
             code >>= 1;
             run = (1 << (additional_code_len - 1)) + code;
             idx += run;
+            if (idx > 63)
+                return AVERROR_INVALIDDATA;
             j = scantable[idx++];
             block[j] = sign ? 1 : -1;
         } else if (group >= 13 && group <= 20) {
             /* Level value (Table B.49) */
+            if (idx > 63)
+                return AVERROR_INVALIDDATA;
             j = scantable[idx++];
             block[j] = get_xbits(&s->gb, additional_code_len);
         } else if (group == 21) {
             /* Escape */
+            if (idx > 63)
+                return AVERROR_INVALIDDATA;
             j = scantable[idx++];
             additional_code_len = s->avctx->bits_per_raw_sample + s->dct_precision + 4;
             flc = get_bits(&s->gb, additional_code_len);"}

