{"sha": "1eaf3fbc220bfa210e2647b2bcf55e589d793376", "filename": "u2f-host/devs.c", "status": "modified", "additions": 21, "deletions": 9, "changes": 30, "blob_url": "https://github.com/Yubico/libu2f-host/blob/e4bb58cc8b6202a421e65f8230217d8ae6e16eb5/u2f-host/devs.c", "raw_url": "https://github.com/Yubico/libu2f-host/raw/e4bb58cc8b6202a421e65f8230217d8ae6e16eb5/u2f-host/devs.c", "contents_url": "https://api.github.com/repos/Yubico/libu2f-host/contents/u2f-host/devs.c?ref=e4bb58cc8b6202a421e65f8230217d8ae6e16eb5", "patch": "@@ -302,17 +302,29 @@ init_device (u2fh_devs * devs, struct u2fdevice *dev)
