-  RNDr(S, W, 61, 0xa4506ceb);
-  RNDr(S, W, 62, 0xbef9a3f7);
-  RNDr(S, W, 63, 0xc67178f2);
-
-  /* 4. Mix local working variables into global state */
-  for (i = 0; i < 8; i++)
-    state[i] += S[i];
-
-  /* Clean the stack. */
-  memset(W, 0, 256);
-  memset(S, 0, 32);
-  t0 = t1 = 0;
