{"sha": "806094ea49068717e62975bae1376a66dbb0d41c", "filename": "thrift/lib/go/thrift/binary_protocol_test.go", "status": "modified", "additions": 22, "deletions": 0, "changes": 22, "blob_url": "https://github.com/facebook/fbthrift/blob/c461c1bd1a3e130b181aa9c854da3030cd4b5156/thrift/lib/go/thrift/binary_protocol_test.go", "raw_url": "https://github.com/facebook/fbthrift/raw/c461c1bd1a3e130b181aa9c854da3030cd4b5156/thrift/lib/go/thrift/binary_protocol_test.go", "contents_url": "https://api.github.com/repos/facebook/fbthrift/contents/thrift/lib/go/thrift/binary_protocol_test.go?ref=c461c1bd1a3e130b181aa9c854da3030cd4b5156", "patch": "@@ -21,9 +21,31 @@
 package thrift

 import (
+	"strings"
 	"testing"
+	"time"
 )

 func TestReadWriteBinaryProtocol(t *testing.T) {
 	ReadWriteProtocolTest(t, NewBinaryProtocolFactoryDefault())
 }
+
+func TestSkipUnknownTypeBinaryProtocol(t *testing.T) {
+	var m MyTestStruct
+	d := NewDeserializer()
+	f := NewBinaryProtocolFactoryDefault()
+	d.Protocol = f.GetProtocol(d.Transport)
+	// skip over a map with invalid key/value type and 1.7B entries
+	data := []byte("\n\x10\rO\t6\x03\n\n\n\x10\r\n\tslice\x00")
+	start := time.Now()
+	err := d.Read(&m, data)
+	if err == nil {
+		t.Fatalf("Parsed invalid message correctly")
+	} else if !strings.Contains(err.Error(), "unknown type") {
+		t.Fatalf("Failed for reason besides unknown type")
+	}
+
+	if time.Now().Sub(start).Seconds() > 5 {
+		t.Fatalf("It should not take seconds to parse a small message")
+	}
+}"}<_**next**_>{"sha": "3a1e2547e1547cd1b5a845d98fa950a9d86e815a", "filename": "thrift/lib/go/thrift/protocol.go", "status": "modified", "additions": 3, "deletions": 3, "changes": 6, "blob_url": "https://github.com/facebook/fbthrift/blob/c461c1bd1a3e130b181aa9c854da3030cd4b5156/thrift/lib/go/thrift/protocol.go", "raw_url": "https://github.com/facebook/fbthrift/raw/c461c1bd1a3e130b181aa9c854da3030cd4b5156/thrift/lib/go/thrift/protocol.go", "contents_url": "https://api.github.com/repos/facebook/fbthrift/contents/thrift/lib/go/thrift/protocol.go?ref=c461c1bd1a3e130b181aa9c854da3030cd4b5156", "patch": "@@ -22,6 +22,7 @@ package thrift

