 }"}

{"sha": "be6f47f97dd023894cd0babc0efaaa7307605364", "filename": "wangle/codec/LineBasedFrameDecoder.cpp", "status": "modified", "additions": 3, "deletions": 2, "changes": 5, "blob_url": "https://github.com/facebook/wangle/blob/5b3bceca875e4ea4ed9d14c20b20ce46c92c13c6/wangle/codec/LineBasedFrameDecoder.cpp", "raw_url": "https://github.com/facebook/wangle/raw/5b3bceca875e4ea4ed9d14c20b20ce46c92c13c6/wangle/codec/LineBasedFrameDecoder.cpp", "contents_url": "https://api.github.com/repos/facebook/wangle/contents/wangle/codec/LineBasedFrameDecoder.cpp?ref=5b3bceca875e4ea4ed9d14c20b20ce46c92c13c6", "patch": "@@ -97,8 +97,9 @@ int64_t LineBasedFrameDecoder::findEndOfLine(IOBufQueue& buf) {
     auto b = c.read<char>();
     if (b == '\n' && terminatorType_ != TerminatorType::CARRIAGENEWLINE) {
       return i;
-    } else if (terminatorType_ != TerminatorType::NEWLINE &&
-               b == '\r' && !c.isAtEnd() && c.read<char>() == '\n') {
+    } else if (
+        terminatorType_ != TerminatorType::NEWLINE && b == '\r' &&
+        !c.isAtEnd() && *c.peekBytes().data() == '\n') {
       return i;
     }
   }"}<_**next**_>{"sha": "4d3480941329a6e01d91530d9e1644699fe36e89", "filename": "wangle/codec/test/CodecTest.cpp", "status": "modified", "additions": 34, "deletions": 0, "changes": 34, "blob_url": "https://github.com/facebook/wangle/blob/5b3bceca875e4ea4ed9d14c20b20ce46c92c13c6/wangle/codec/test/CodecTest.cpp", "raw_url": "https://github.com/facebook/wangle/raw/5b3bceca875e4ea4ed9d14c20b20ce46c92c13c6/wangle/codec/test/CodecTest.cpp", "contents_url": "https://api.github.com/repos/facebook/wangle/contents/wangle/codec/test/CodecTest.cpp?ref=5b3bceca875e4ea4ed9d14c20b20ce46c92c13c6", "patch": "@@ -606,3 +606,37 @@ TEST(LineBasedFrameDecoder, CarriageNewLineOnly) {
   pipeline->read(q);
   EXPECT_EQ(called, 1);
 }
+
+TEST(LineBasedFrameDecoder, CarriageOnly) {
+  auto pipeline = Pipeline<IOBufQueue&, std::unique_ptr<IOBuf>>::create();
+
+  (*pipeline)
+      .addBack(LineBasedFrameDecoder(
+          10, true, LineBasedFrameDecoder::TerminatorType::CARRIAGENEWLINE))
+      .addBack(test::FrameTester([&](std::unique_ptr<IOBuf>) { FAIL(); }))
+      .finalize();
+
+  IOBufQueue q(IOBufQueue::cacheChainLength());
+  q.append(IOBuf::copyBuffer("\raa"));
+  pipeline->read(q);
+}
+
+TEST(LineBasedFrameDecoder, DoubleCarriage) {
+  auto pipeline = Pipeline<IOBufQueue&, std::unique_ptr<IOBuf>>::create();
+  int called = 0;
+
+  (*pipeline)
+      .addBack(LineBasedFrameDecoder(
+          10, true, LineBasedFrameDecoder::TerminatorType::CARRIAGENEWLINE))
+      .addBack(test::FrameTester([&](std::unique_ptr<IOBuf> buf) {
+        auto sz = buf->computeChainDataLength();
+        called++;
+        EXPECT_EQ(sz, 1);
+      }))
+      .finalize();
+
+  IOBufQueue q(IOBufQueue::cacheChainLength());
+  q.append(IOBuf::copyBuffer("\r\r\na\r\n"));
+  pipeline->read(q);
+  EXPECT_EQ(called, 2);
+}"}

