{"sha": "4a6ed68e2b24f114a6307b22807112dc5d735084", "filename": "src/lib/openjp2/pi.c", "status": "modified", "additions": 11, "deletions": 8, "changes": 19, "blob_url": "https://github.com/uclouvain/openjpeg/blob/c58df149900df862806d0e892859b41115875845/src/lib/openjp2/pi.c", "raw_url": "https://github.com/uclouvain/openjpeg/raw/c58df149900df862806d0e892859b41115875845/src/lib/openjp2/pi.c", "contents_url": "https://api.github.com/repos/uclouvain/openjpeg/contents/src/lib/openjp2/pi.c?ref=c58df149900df862806d0e892859b41115875845", "patch": "@@ -748,6 +748,9 @@ static void opj_get_encoding_parameters(const opj_image_t *p_image,
     /* position in x and y of tile */
     OPJ_UINT32 p, q;

+    /* non-corrected (in regard to image offset) tile offset */
+    OPJ_UINT32 l_tx0, l_ty0;
+
     /* preconditions */
     assert(p_cp != 00);
     assert(p_image != 00);
@@ -763,14 +766,14 @@ static void opj_get_encoding_parameters(const opj_image_t *p_image,
     q = p_tileno / p_cp->tw;

