{"sha": "1ab4552faa6011408a34cba265a887f1be011652", "filename": "ChangeLog", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/uriparser/uriparser/blob/cef25028de5ff872c2e1f0a6c562eb3ea9ecbce4/ChangeLog", "raw_url": "https://github.com/uriparser/uriparser/raw/cef25028de5ff872c2e1f0a6c562eb3ea9ecbce4/ChangeLog", "contents_url": "https://api.github.com/repos/uriparser/uriparser/contents/ChangeLog?ref=cef25028de5ff872c2e1f0a6c562eb3ea9ecbce4", "patch": "@@ -4,6 +4,12 @@ NOTE: uriparser is looking for help with a few things:

