+    fix_google_param(google_sig);
+    fix_google_param(google_reqId);
+    fix_google_param(google_version);
+    fix_google_param(responseHandler);
+    fix_google_param(outFileName);
+
     if(!chart || !*chart) {
         buffer_sprintf(w->response.data, "No chart id is given at the request.");
         goto cleanup;"}

{"sha": "7b01f487dbc2de43cb1cdb19c5a017866d27d80d", "filename": "smbutil.c", "status": "modified", "additions": 8, "deletions": 1, "changes": 9, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/24182d959f661327525a20d9a94c98a8ec016778/smbutil.c", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/24182d959f661327525a20d9a94c98a8ec016778/smbutil.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/smbutil.c?ref=24182d959f661327525a20d9a94c98a8ec016778", "patch": "@@ -807,7 +807,14 @@ smb_fdata(netdissect_options *ndo,
 	    while (buf < maxbuf) {
 		const u_char *buf2;
 		depth++;
-		buf2 = smb_fdata(ndo, buf, fmt, maxbuf, unicodestr);
+		/* Not sure how this relates with the protocol specification,
+		 * but in order to avoid stack exhaustion recurse at most that
+		 * many levels.
+		 */
+		if (depth == 10)
+			ND_PRINT((ndo, "(too many nested levels, not recursing)"));
+		else
+			buf2 = smb_fdata(ndo, buf, fmt, maxbuf, unicodestr);
 		depth--;
 		if (buf2 == NULL)
 		    return(NULL);"}

{"sha": "944b8d28abfc0c4dc723f477c9e794fcb9f79ac0", "filename": "print-smb.c", "status": "modified", "additions": 8, "deletions": 3, "changes": 11, "blob_url": "https://github.com/the-tcpdump-group/tcpdump/blob/96480ab95308cd9234b4f09b175ebf60e17792c6/print-smb.c", "raw_url": "https://github.com/the-tcpdump-group/tcpdump/raw/96480ab95308cd9234b4f09b175ebf60e17792c6/print-smb.c", "contents_url": "https://api.github.com/repos/the-tcpdump-group/tcpdump/contents/print-smb.c?ref=96480ab95308cd9234b4f09b175ebf60e17792c6", "patch": "@@ -371,16 +371,21 @@ print_trans(netdissect_options *ndo,
