{"sha": "2693ba84ec2541072396d138fbf970bca90a597c", "filename": "fs/xfs/xfs_aops.c", "status": "modified", "additions": 20, "deletions": 2, "changes": 22, "blob_url": "https://github.com/torvalds/linux/blob/04197b341f23b908193308b8d63d17ff23232598/fs/xfs/xfs_aops.c", "raw_url": "https://github.com/torvalds/linux/raw/04197b341f23b908193308b8d63d17ff23232598/fs/xfs/xfs_aops.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/xfs/xfs_aops.c?ref=04197b341f23b908193308b8d63d17ff23232598", "patch": "@@ -1361,6 +1361,26 @@ __xfs_get_blocks(
 	if (error)
 		goto out_unlock;

+	/*
+	 * The only time we can ever safely find delalloc blocks on direct I/O
+	 * is a dio write to post-eof speculative preallocation. All other
+	 * scenarios are indicative of a problem or misuse (such as mixing
+	 * direct and mapped I/O).
+	 *
+	 * The file may be unmapped by the time we get here so we cannot
+	 * reliably fail the I/O based on mapping. Instead, fail the I/O if this
+	 * is a read or a write within eof. Otherwise, carry on but warn as a
+	 * precuation if the file happens to be mapped.
+	 */
+	if (direct && imap.br_startblock == DELAYSTARTBLOCK) {
+		if (!create || offset < i_size_read(VFS_I(ip))) {
+			WARN_ON_ONCE(1);
+			error = -EIO;
+			goto out_unlock;
+		}
+		WARN_ON_ONCE(mapping_mapped(VFS_I(ip)->i_mapping));
+	}
+
 	/* for DAX, we convert unwritten extents directly */
 	if (create &&
 	    (!nimaps ||
@@ -1450,8 +1470,6 @@ __xfs_get_blocks(
 	     (new || ISUNWRITTEN(&imap))))
 		set_buffer_new(bh_result);

-	BUG_ON(direct && imap.br_startblock == DELAYSTARTBLOCK);
-
 	return 0;

 out_unlock:"}

