{"sha": "1789135a8cafd2826c0b410c61b0801c3f03fa91", "filename": "memcached.c", "status": "modified", "additions": 29, "deletions": 2, "changes": 31, "blob_url": "https://github.com/memcached/memcached/blob/75cc83685e103bc8ba380a57468c8f04413033f9/memcached.c", "raw_url": "https://github.com/memcached/memcached/raw/75cc83685e103bc8ba380a57468c8f04413033f9/memcached.c", "contents_url": "https://api.github.com/repos/memcached/memcached/contents/memcached.c?ref=75cc83685e103bc8ba380a57468c8f04413033f9", "patch": "@@ -3127,9 +3127,27 @@ static int try_read_command(conn *c) {

