{"sha": "717057431d43906a9422074ebed510c42d4456bd", "filename": "nedmalloc.c", "status": "modified", "additions": 6, "deletions": 2, "changes": 8, "blob_url": "https://github.com/ned14/nedmalloc/blob/2965eca30c408c13473c4146a9d47d547d288db1/nedmalloc.c", "raw_url": "https://github.com/ned14/nedmalloc/raw/2965eca30c408c13473c4146a9d47d547d288db1/nedmalloc.c", "contents_url": "https://api.github.com/repos/ned14/nedmalloc/contents/nedmalloc.c?ref=2965eca30c408c13473c4146a9d47d547d288db1", "patch": "@@ -2018,8 +2018,12 @@ NEDMALLOCNOALIASATTR NEDMALLOCPTRATTR void * nedpmalloc(nedpool *p, size_t size)
 }
 NEDMALLOCNOALIASATTR NEDMALLOCPTRATTR void * nedpcalloc(nedpool *p, size_t no, size_t size) THROWSPEC
 {
-	unsigned flags=NEDMALLOC_FORCERESERVE(p, 0, no*size);
-	return nedpmalloc2(p, size*no, 0, M2_ZERO_MEMORY|flags);
+	size_t bytes=no*size;
+	/* Avoid multiplication overflow. */
+	if(size && no!=bytes/size)
+		return 0;
+	unsigned flags=NEDMALLOC_FORCERESERVE(p, 0, bytes);
+	return nedpmalloc2(p, bytes, 0, M2_ZERO_MEMORY|flags);
 }
 NEDMALLOCNOALIASATTR NEDMALLOCPTRATTR void * nedprealloc(nedpool *p, void *mem, size_t size) THROWSPEC
 {"}

