{"sha": "9a56ca2fa25744940050255aa13edeb8fe270543", "filename": "virt/kvm/kvm_main.c", "status": "modified", "additions": 11, "deletions": 8, "changes": 19, "blob_url": "https://github.com/torvalds/linux/blob/e40f193f5bb022e927a57a4f5d5194e4f12ddb74/virt/kvm/kvm_main.c", "raw_url": "https://github.com/torvalds/linux/raw/e40f193f5bb022e927a57a4f5d5194e4f12ddb74/virt/kvm/kvm_main.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/virt/kvm/kvm_main.c?ref=e40f193f5bb022e927a57a4f5d5194e4f12ddb74", "patch": "@@ -822,6 +822,8 @@ int __kvm_set_memory_region(struct kvm *kvm,
