{"sha": "5bc71d9a674a7e5dfc3ff882ee61a2591a328c7b", "filename": "fs/udf/inode.c", "status": "modified", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/torvalds/linux/blob/e159332b9af4b04d882dbcfe1bb0117f0a6d4b58/fs/udf/inode.c", "raw_url": "https://github.com/torvalds/linux/raw/e159332b9af4b04d882dbcfe1bb0117f0a6d4b58/fs/udf/inode.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/fs/udf/inode.c?ref=e159332b9af4b04d882dbcfe1bb0117f0a6d4b58", "patch": "@@ -1489,6 +1489,20 @@ static int udf_read_inode(struct inode *inode, bool hidden_inode)
