{"sha": "10798128c03fc64881c5a437df3510f016461b7c", "filename": "drivers/net/usb/usbnet.c", "status": "modified", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/torvalds/linux/blob/1666984c8625b3db19a9abc298931d35ab7bc64b/drivers/net/usb/usbnet.c", "raw_url": "https://github.com/torvalds/linux/raw/1666984c8625b3db19a9abc298931d35ab7bc64b/drivers/net/usb/usbnet.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/drivers/net/usb/usbnet.c?ref=1666984c8625b3db19a9abc298931d35ab7bc64b", "patch": "@@ -1769,6 +1769,13 @@ usbnet_probe (struct usb_interface *udev, const struct usb_device_id *prod)
 	if (info->unbind)
 		info->unbind (dev, udev);
 out1:
+	/* subdrivers must undo all they did in bind() if they
+	 * fail it, but we may fail later and a deferred kevent
+	 * may trigger an error resubmitting itself and, worse,
+	 * schedule a timer. So we kill it all just in case.
+	 */
+	cancel_work_sync(&dev->kevent);
+	del_timer_sync(&dev->delay);
 	free_netdev(net);
 out:
 	return status;"}

