+varnishtest "Do not consider CR as a valid line separator"
+
+server s1 {
+	rxreq
+	txresp
+} -start
+
+varnish v1 -vcl+backend {
+	sub vcl_deliver {
+		if (req.http.foo) {
+			set resp.http.Foo = req.http.foo;
+		}
+		if (req.http.bar) {
+			set resp.http.Bar = req.http.bar;
+		}
+	}
+} -start
+
+client c1 {
+	send "GET / HTTP/1.1\r\nFoo: foo\rBar: bar\r\n\r\n"
+	rxresp
+	expect resp.http.foo == "foo\rBar: bar"
+	expect resp.http.bar == "<undef>"
+} -run"}<_**next**_>{"sha": "dd2c804fb56eb1cd9cda4f11bcf57f957cb434d9", "filename": "bin/varnishtest/vtc_http.c", "status": "modified", "additions": 8, "deletions": 8, "changes": 16, "blob_url": "https://github.com/varnish/Varnish-Cache/blob/85e8468bec9416bd7e16b0d80cb820ecd2b330c3/bin/varnishtest/vtc_http.c", "raw_url": "https://github.com/varnish/Varnish-Cache/raw/85e8468bec9416bd7e16b0d80cb820ecd2b330c3/bin/varnishtest/vtc_http.c", "contents_url": "https://api.github.com/repos/varnish/Varnish-Cache/contents/bin/varnishtest/vtc_http.c?ref=85e8468bec9416bd7e16b0d80cb820ecd2b330c3", "patch": "@@ -283,17 +283,17 @@ http_splitheader(struct http *hp, int req)
