{"sha": "c76a0accf8525280c7d7cf2006c0b5699a5cad23", "filename": "src/readelf.c", "status": "modified", "additions": 18, "deletions": 4, "changes": 22, "blob_url": "https://github.com/file/file/blob/9611f31313a93aa036389c5f3b15eea53510d4d1/src/readelf.c", "raw_url": "https://github.com/file/file/raw/9611f31313a93aa036389c5f3b15eea53510d4d1/src/readelf.c", "contents_url": "https://api.github.com/repos/file/file/contents/src/readelf.c?ref=9611f31313a93aa036389c5f3b15eea53510d4d1", "patch": "@@ -27,7 +27,7 @@
