{"sha": "bd95357190a01d087a527ca039f112ab6a358641", "filename": "mongoose.c", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/cesanta/mongoose/blob/b8402ed0733e3f244588b61ad5fedd093e3cf9cc/mongoose.c", "raw_url": "https://github.com/cesanta/mongoose/raw/b8402ed0733e3f244588b61ad5fedd093e3cf9cc/mongoose.c", "contents_url": "https://api.github.com/repos/cesanta/mongoose/contents/mongoose.c?ref=b8402ed0733e3f244588b61ad5fedd093e3cf9cc", "patch": "@@ -5961,6 +5961,12 @@ static int mg_http_multipart_wait_for_boundary(struct mg_connection *c) {
