{"sha": "bf9fef6d1bfef80c39c5043943a150437028cb2e", "filename": "kernel/fork.c", "status": "modified", "additions": 13, "deletions": 1, "changes": 14, "blob_url": "https://github.com/torvalds/linux/blob/f106eee10038c2ee5b6056aaf3f6d5229be6dcdd/kernel/fork.c", "raw_url": "https://github.com/torvalds/linux/raw/f106eee10038c2ee5b6056aaf3f6d5229be6dcdd/kernel/fork.c", "contents_url": "https://api.github.com/repos/torvalds/linux/contents/kernel/fork.c?ref=f106eee10038c2ee5b6056aaf3f6d5229be6dcdd", "patch": "@@ -1338,15 +1338,27 @@ noinline struct pt_regs * __cpuinit __attribute__((weak)) idle_regs(struct pt_re
 	return regs;
 }

+static inline void init_idle_pids(struct pid_link *links)
+{
+	enum pid_type type;
+
+	for (type = PIDTYPE_PID; type < PIDTYPE_MAX; ++type) {
+		INIT_HLIST_NODE(&links[type].node); /* not really needed */
+		links[type].pid = &init_struct_pid;
+	}
+}
+
 struct task_struct * __cpuinit fork_idle(int cpu)
 {
 	struct task_struct *task;
 	struct pt_regs regs;

 	task = copy_process(CLONE_VM, 0, idle_regs(&regs), 0, NULL,
 			    &init_struct_pid, 0);
-	if (!IS_ERR(task))
+	if (!IS_ERR(task)) {
+		init_idle_pids(task->pids);
 		init_idle(task, cpu);
+	}

 	return task;
 }"}

