{"sha": "8d9e6146e74b66f9680855bdad7b984263a72782", "filename": "src/delta.c", "status": "modified", "additions": 15, "deletions": 17, "changes": 32, "blob_url": "https://github.com/libgit2/libgit2/blob/3f461902dc1072acb8b7607ee65d0a0458ffac2a/src/delta.c", "raw_url": "https://github.com/libgit2/libgit2/raw/3f461902dc1072acb8b7607ee65d0a0458ffac2a/src/delta.c", "contents_url": "https://api.github.com/repos/libgit2/libgit2/contents/src/delta.c?ref=3f461902dc1072acb8b7607ee65d0a0458ffac2a", "patch": "@@ -539,10 +539,11 @@ int git_delta_apply(
