 			delta += cmd;
 			res_dp += cmd;
 			res_sz -= cmd;

-		}
-		else {
-			/* cmd == 0 is reserved for future encodings.
-			*/
+		} else {
+			/* cmd == 0 is reserved for future encodings. */
 			goto fail;
 		}
 	}"}<_**next**_>{"sha": "24513e040d2fc2bc1e630fb0e845647938936fbc", "filename": "tests/delta/apply.c", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/libgit2/libgit2/blob/3f461902dc1072acb8b7607ee65d0a0458ffac2a/tests/delta/apply.c", "raw_url": "https://github.com/libgit2/libgit2/raw/3f461902dc1072acb8b7607ee65d0a0458ffac2a/tests/delta/apply.c", "contents_url": "https://api.github.com/repos/libgit2/libgit2/contents/tests/delta/apply.c?ref=3f461902dc1072acb8b7607ee65d0a0458ffac2a", "patch": "@@ -0,0 +1,12 @@
