{"sha": "97412ca553579db69905022cccc07648a49b4641", "filename": "docs/root/intro/version_history.rst", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/envoyproxy/envoy/blob/afc39bea36fd436e54262f150c009e8d72db5014/docs/root/intro/version_history.rst", "raw_url": "https://github.com/envoyproxy/envoy/raw/afc39bea36fd436e54262f150c009e8d72db5014/docs/root/intro/version_history.rst", "contents_url": "https://api.github.com/repos/envoyproxy/envoy/contents/docs/root/intro/version_history.rst?ref=afc39bea36fd436e54262f150c009e8d72db5014", "patch": "@@ -85,6 +85,10 @@ Version history
 * upstream: added :ref:`fail_traffic_on_panic <envoy_api_field_Cluster.CommonLbConfig.ZoneAwareLbConfig.fail_traffic_on_panic>` to allow failing all requests to a cluster during panic state.
 * zookeeper: parse responses and emit latency stats.

+1.11.2 (October 8, 2019)
+========================
+* http: fixed CVE-2019-15226 by adding a cached byte size in HeaderMap.
+
 1.11.1 (August 13, 2019)
 ========================
 * http: added mitigation of client initiated attacks that result in flooding of the downstream HTTP/2 connections. Those attacks can be logged at the "warning" level when the runtime feature `http.connection_manager.log_flood_exception` is enabled. The runtime setting defaults to disabled to avoid log spam when under attack."}<_**next**_>{"sha": "394df8f26ccb715076eb83e670db92ed3db76694", "filename": "include/envoy/access_log/access_log.h", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/envoyproxy/envoy/blob/afc39bea36fd436e54262f150c009e8d72db5014/include/envoy/access_log/access_log.h", "raw_url": "https://github.com/envoyproxy/envoy/raw/afc39bea36fd436e54262f150c009e8d72db5014/include/envoy/access_log/access_log.h", "contents_url": "https://api.github.com/repos/envoyproxy/envoy/contents/include/envoy/access_log/access_log.h?ref=afc39bea36fd436e54262f150c009e8d72db5014", "patch": "@@ -78,6 +78,10 @@ class Instance {

   /**
    * Log a completed request.
+   * Prior to logging, call refreshByteSize() on HeaderMaps to ensure that an accurate byte size
+   * count is logged.
+   * TODO(asraa): Remove refreshByteSize() requirement when entries in HeaderMap can no longer be
+   * modified by reference and headerMap holds an accurate internal byte size count.
    * @param request_headers supplies the incoming request headers after filtering.
    * @param response_headers supplies response headers.
    * @param response_trailers supplies response trailers."}<_**next**_>{"sha": "0fa45cdfd5ea04e24e01c1f9da06301b28000c73", "filename": "include/envoy/http/header_map.h", "status": "modified", "additions": 33, "deletions": 1, "changes": 34, "blob_url": "https://github.com/envoyproxy/envoy/blob/afc39bea36fd436e54262f150c009e8d72db5014/include/envoy/http/header_map.h", "raw_url": "https://github.com/envoyproxy/envoy/raw/afc39bea36fd436e54262f150c009e8d72db5014/include/envoy/http/header_map.h", "contents_url": "https://api.github.com/repos/envoyproxy/envoy/contents/include/envoy/http/header_map.h?ref=afc39bea36fd436e54262f150c009e8d72db5014", "patch": "@@ -457,9 +457,41 @@ class HeaderMap {
   virtual void setReferenceKey(const LowerCaseString& key, const std::string& value) PURE;

   /**
+   * HeaderMap contains an internal byte size count, updated as entries are added, removed, or
+   * modified through the HeaderMap interface. However, HeaderEntries can be accessed and modified
+   * by reference so that the HeaderMap can no longer accurately update the internal byte size
+   * count.
+   *
+   * Calling byteSize before a HeaderEntry is accessed will return the internal byte size count. The
+   * value is cleared when a HeaderEntry is accessed, and the value is updated and set again when
+   * refreshByteSize is called.
+   *
+   * To guarantee an accurate byte size count, call refreshByteSize.
+   *
+   * @return uint64_t the approximate size of the header map in bytes if valid.
+   */
+  virtual absl::optional<uint64_t> byteSize() const PURE;
+
+  /**
+   * This returns the sum of the byte sizes of the keys and values in the HeaderMap. This also
+   * updates and sets the byte size count.
+   *
+   * To guarantee an accurate byte size count, use this. If it is known HeaderEntries have not been
