{"sha": "2f5c25f40564ed9043f8de6462e82c136de2e145", "filename": "src/Importers/ImportEPUB.cpp", "status": "modified", "additions": 35, "deletions": 6, "changes": 41, "blob_url": "https://github.com/Sigil-Ebook/Sigil/blob/04e2f280cc4a0766bedcc7b9eb56449ceecc2ad4/src/Importers/ImportEPUB.cpp", "raw_url": "https://github.com/Sigil-Ebook/Sigil/raw/04e2f280cc4a0766bedcc7b9eb56449ceecc2ad4/src/Importers/ImportEPUB.cpp", "contents_url": "https://api.github.com/repos/Sigil-Ebook/Sigil/contents/src/Importers/ImportEPUB.cpp?ref=04e2f280cc4a0766bedcc7b9eb56449ceecc2ad4", "patch": "@@ -425,12 +425,41 @@ void ImportEPUB::ExtractContainer()
             // If there is no file name then we can't do anything with it.
             if (!qfile_name.isEmpty()) {

-	        // for security reasons we need the file path to always be inside the 
-                // target folder and not outside, so we will remove all relative upward 
-                // paths segments ".." from the file path before prepending the target 
-                // folder to create the final target path
-	        qfile_name = qfile_name.replace("../","");
-                cp437_file_name = cp437_file_name.replace("../","");
+	        // for security reasons against maliciously crafted zip archives
+                // we need the file path to always be inside the target folder 
+                // and not outside, so we will remove all illegal backslashes
+                // and all relative upward paths segments "/../" from the zip's local 
+                // file name/path before prepending the target folder to create 
+                // the final path
+
+	        QString original_path = qfile_name;
+	        bool evil_or_corrupt_epub = false;
+
+                if (qfile_name.contains("\\")) evil_or_corrupt_epub = true; 
+	        qfile_name = "/" + qfile_name.replace("\\","");
+
+                if (qfile_name.contains("/../")) evil_or_corrupt_epub = true;
+	        qfile_name = qfile_name.replace("/../","/");
+
+                while(qfile_name.startsWith("/")) { 
+		    qfile_name = qfile_name.remove(0,1);
+		}
+
+                if (cp437_file_name.contains("\\")) evil_or_corrupt_epub = true; 
+                cp437_file_name = "/" + cp437_file_name.replace("\\","");
+
+                if (cp437_file_name.contains("/../")) evil_or_corrupt_epub = true;
+	        cp437_file_name = cp437_file_name.replace("/../","/");
+
+                while(cp437_file_name.startsWith("/")) { 
+		    cp437_file_name = cp437_file_name.remove(0,1);
+		}
+
+                if (evil_or_corrupt_epub) {
+                    unzCloseCurrentFile(zfile);
+                    unzClose(zfile);
+                    throw (EPUBLoadParseError(QString(QObject::tr("Possible evil or corrupt epub file name: %1")).arg(original_path).toStdString()));
+                }

                 // We use the dir object to create the path in the temporary directory.
                 // Unfortunately, we need a dir ojbect to do this as it's not a static function."}

{"sha": "ae4441e6cc7afc6a81b178dde1f5ffbcd6b170d6", "filename": "src/EbmlElement.cpp", "status": "modified", "additions": 7, "deletions": 1, "changes": 8, "blob_url": "https://github.com/Matroska-Org/libebml/blob/05beb69ba60acce09f73ed491bb76f332849c3a0/src/EbmlElement.cpp", "raw_url": "https://github.com/Matroska-Org/libebml/raw/05beb69ba60acce09f73ed491bb76f332849c3a0/src/EbmlElement.cpp", "contents_url": "https://api.github.com/repos/Matroska-Org/libebml/contents/src/EbmlElement.cpp?ref=05beb69ba60acce09f73ed491bb76f332849c3a0", "patch": "@@ -404,12 +404,14 @@ EbmlElement * EbmlElement::FindNextElement(IOCallback & DataStream, const EbmlSe
