{"sha": "377ae5b33fe0cbb9f11921d174b3fc444dcbab7c", "filename": "fizz/record/EncryptedRecordLayer.cpp", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/facebookincubator/fizz/blob/3eaddb33619eaaf74a760872850c550ad8f5c52f/fizz/record/EncryptedRecordLayer.cpp", "raw_url": "https://github.com/facebookincubator/fizz/raw/3eaddb33619eaaf74a760872850c550ad8f5c52f/fizz/record/EncryptedRecordLayer.cpp", "contents_url": "https://api.github.com/repos/facebookincubator/fizz/contents/fizz/record/EncryptedRecordLayer.cpp?ref=3eaddb33619eaaf74a760872850c550ad8f5c52f", "patch": "@@ -113,7 +113,7 @@ folly::Optional<TLSMessage> EncryptedReadRecordLayer::read(
     return folly::none;
   }

-  TLSMessage msg;
+  TLSMessage msg{};
   // Iterate over the buffers while trying to find
   // the first non-zero octet. This is much faster than
   // first iterating and then trimming."}<_**next**_>{"sha": "f608d907e33c7980ebb56f5a02450b0e20326eac", "filename": "fizz/record/RecordLayer.cpp", "status": "modified", "additions": 25, "deletions": 1, "changes": 26, "blob_url": "https://github.com/facebookincubator/fizz/blob/3eaddb33619eaaf74a760872850c550ad8f5c52f/fizz/record/RecordLayer.cpp", "raw_url": "https://github.com/facebookincubator/fizz/raw/3eaddb33619eaaf74a760872850c550ad8f5c52f/fizz/record/RecordLayer.cpp", "contents_url": "https://api.github.com/repos/facebookincubator/fizz/contents/fizz/record/RecordLayer.cpp?ref=3eaddb33619eaaf74a760872850c550ad8f5c52f", "patch": "@@ -49,7 +49,31 @@ folly::Optional<Param> ReadRecordLayer::readEvent(
         }
       }
       case ContentType::handshake: {
-        unparsedHandshakeData_.append(std::move(message->fragment));
+        std::unique_ptr<folly::IOBuf> handshakeMessage =
+            unparsedHandshakeData_.move();
+        // It is possible that a peer might send us records in a manner such
+        // that there is a 16KB record and only 1 byte of handshake message in
+        // each record. Since we normally just trim the IOBuf, we would end up
+        // holding 16K of data. To prevent this we allocate a contiguous
+        // buffer to copy over these bytes. We supply kExtraAlloc bytes in
+        // order to avoid needing to re-allocate a lot of times if we receive
+        // a lot of small messages. There might be more optimal reallocation
+        // policies, but this should be fine.
+        message->fragment->coalesce();
+        constexpr size_t kExtraAlloc = 1024;
+        if (!handshakeMessage) {
+          handshakeMessage =
+              folly::IOBuf::create(message->fragment->length() + kExtraAlloc);
+        } else if (handshakeMessage->tailroom() < message->fragment->length()) {
+          handshakeMessage->reserve(
+              0, message->fragment->length() + kExtraAlloc);
+        }
+        memcpy(
+            handshakeMessage->writableTail(),
+            message->fragment->data(),
+            message->fragment->length());
+        handshakeMessage->append(message->fragment->length());
+        unparsedHandshakeData_.append(std::move(handshakeMessage));
         auto param = decodeHandshakeMessage(unparsedHandshakeData_);
         if (param) {
           VLOG(8) << "Received handshake message ""}

