+<?xml version="1.0" encoding="ISO-8859-1"?>
+<html xmlns="http://www.w3.org/1999/xhtml">
+<body>
+<div id="description">This test checks to see if setting innerHTML to a single non-breaking space works.</div>
+<div id="test" style="display:none"></div>
+<div id="console"></div>
+
+<script>
+if (window.layoutTestController)
+    layoutTestController.dumpAsText();
+
+function log(message) {
+    var console = document.getElementById("console");
+    console.appendChild(document.createTextNode(message));
+    console.appendChild(document.createElement('br'));
+}
+
+var html = "\u00A0";
+var testElement = document.getElementById("test");
+try {
+    testElement.innerHTML = html;
+} catch(e) {
+    log("FAIL, exception thrown: " + e);
+}
+
+if (html == testElement.innerHTML)
+    log("PASSED");
+else {
+    log("FAIL, expected: " + html + " actual: " + testElement.innerHTML);
+}
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "10b7476f5fec0b80d32fdc4edbdbce9cf9da900d", "filename": "third_party/WebKit/WebCore/ChangeLog", "status": "modified", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/chromium/chromium/blob/a1ce1b69e269a7e61ea0bf0691b90be0cbe9b4c5/third_party/WebKit/WebCore/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/a1ce1b69e269a7e61ea0bf0691b90be0cbe9b4c5/third_party/WebKit/WebCore/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/WebCore/ChangeLog?ref=a1ce1b69e269a7e61ea0bf0691b90be0cbe9b4c5", "patch": "@@ -1,3 +1,17 @@
+2009-05-04  Kai Brüning  <kai@granus.net>
+
+        Reviewed by Eric Seidel.
+        
+        https://bugs.webkit.org/show_bug.cgi?id=24883
+        24883: Bad success test in parseXMLDocumentFragment in XMLTokenizerLibxml2.cpp
+        
+        Fixed test whether all the chunk has been processed to correctly count utf8 bytes.
+
+        Test: fast/innerHTML/innerHTML-nbsp.xhtml
+
+        * dom/XMLTokenizerLibxml2.cpp:
+        (WebCore::parseXMLDocumentFragment):
+
 2009-05-04  Darin Adler  <darin@apple.com>

         Reviewed by Eric Seidel."}<_**next**_>{"sha": "aa9f65c1c824a844de297916f052ed546a3e3c11", "filename": "third_party/WebKit/WebCore/dom/XMLTokenizerLibxml2.cpp", "status": "modified", "additions": 3, "deletions": 2, "changes": 5, "blob_url": "https://github.com/chromium/chromium/blob/a1ce1b69e269a7e61ea0bf0691b90be0cbe9b4c5/third_party/WebKit/WebCore/dom/XMLTokenizerLibxml2.cpp", "raw_url": "https://github.com/chromium/chromium/raw/a1ce1b69e269a7e61ea0bf0691b90be0cbe9b4c5/third_party/WebKit/WebCore/dom/XMLTokenizerLibxml2.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/WebCore/dom/XMLTokenizerLibxml2.cpp?ref=a1ce1b69e269a7e61ea0bf0691b90be0cbe9b4c5", "patch": "@@ -1292,15 +1292,16 @@ bool parseXMLDocumentFragment(const String& chunk, DocumentFragment* fragment, E

     XMLTokenizer tokenizer(fragment, parent);

-    tokenizer.initializeParserContext(chunk.utf8().data());
+    CString chunkAsUtf8 = chunk.utf8();
+    tokenizer.initializeParserContext(chunkAsUtf8.data());

     xmlParseContent(tokenizer.m_context);

     tokenizer.endDocument();

     // Check if all the chunk has been processed.
     long bytesProcessed = xmlByteConsumed(tokenizer.m_context);
-    if (bytesProcessed == -1 || ((unsigned long)bytesProcessed) == sizeof(UChar) * chunk.length())
+    if (bytesProcessed == -1 || ((unsigned long)bytesProcessed) != chunkAsUtf8.length())
         return false;

     // No error if the chunk is well formed or it is not but we have no error."}

