{"sha": "b92c366967b93f9c2f6241af4449327e516ff247", "filename": "third_party/WebKit/LayoutTests/ChangeLog", "status": "modified", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/chromium/chromium/blob/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/LayoutTests/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/LayoutTests/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/ChangeLog?ref=04cca6c05e4923f1b91e0dddf053e088456d8645", "patch": "@@ -1,3 +1,17 @@
+2011-03-14  David Hyatt  <hyatt@apple.com>
+
+        Reviewed by Dan Bernstein.
+
+        https://bugs.webkit.org/show_bug.cgi?id=45164
+
+        REGRESSION: <a><img align=top></a> Clickable area too large
+        
+        Make sure to clamp hit testing of quirky inline flow boxes the same way we already clamped
+        painting.
+
+        * fast/inline/inline-position-top-align-expected.txt: Added.
+        * fast/inline/inline-position-top-align.html: Added.
+
 2011-03-11  Ryosuke Niwa  <rniwa@webkit.org>

         Reviewed by Tony Chang."}<_**next**_>{"sha": "7200cb86136b0e2e1c628bad332b526b80dfd965", "filename": "third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align-expected.txt", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align-expected.txt?ref=04cca6c05e4923f1b91e0dddf053e088456d8645", "patch": "@@ -0,0 +1,12 @@
+pre-text after-text	Something
+Tests for hitTest of element 
+bug 45164: REGRESSION:  Clickable area too large
+
+On success, you will see a series of "PASS" messages, followed by "TEST COMPLETE".
+
+
+PASS successfullyParsed is true
+
+TEST COMPLETE
+PASS hitResult is false
+"}<_**next**_>{"sha": "94529034f359e79f11b6d6e94602bfaea56ea329", "filename": "third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align.html", "status": "added", "additions": 48, "deletions": 0, "changes": 48, "blob_url": "https://github.com/chromium/chromium/blob/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align.html", "raw_url": "https://github.com/chromium/chromium/raw/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/inline/inline-position-top-align.html?ref=04cca6c05e4923f1b91e0dddf053e088456d8645", "patch": "@@ -0,0 +1,48 @@
+<!DOCTYPE HTML PUBLIC "-//IETF//DTD HTML//EN">
+<html>
+<head>
+<meta charset="utf-8">
+<link rel="stylesheet" href="../js/resources/js-test-style.css">
+<style>
+	body{
+        font-size: 16px;
+        line-height: 26px;
+        margin: 0px;
+        padding: 0px;
+	}
+	table, td {
+        margin: 0px;
+        padding: 0px;
+	}
+</style>
+<script src="../js/resources/js-test-pre.js"></script>
+</head>
+
+<body onload="runTests();">
+<table>
+    <tbody><tr>
+        <td width="200">
+            pre-text<a href="https://bug-45164-attachments.webkit.org/" style="background-color:red;">
+                <img src="data:image/png;base64," align="top">
+            </a> after-text
+        </td>
+        <td>Something</td>
+    </tr></tbody>
+</table>
+<br>
+<p id="description"></p>
+<div id="console"></div>
+<script>
+description('Tests for hitTest of <a> element <br/> <a href="https://bugs.webkit.org/show_bug.cgi?id=45164">bug 45164</a>: REGRESSION: <a><img align=top></a> Clickable area too large');
+
+var hitResult;
+function runTests() {
+    var obj = document.elementFromPoint(15, 15);
+    hitResult = (obj.nodeName.toLowerCase() == "a");
+    shouldBeFalse('hitResult');
+}
+var successfullyParsed = true;
+</script>  
+<script src="../js/resources/js-test-post.js"></script>
+</body>
+</html>"}<_**next**_>{"sha": "aa2ca2f16bee4f29174e21502b54e89807379bca", "filename": "third_party/WebKit/Source/WebCore/ChangeLog", "status": "modified", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/chromium/chromium/blob/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/Source/WebCore/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/Source/WebCore/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/ChangeLog?ref=04cca6c05e4923f1b91e0dddf053e088456d8645", "patch": "@@ -1,3 +1,17 @@
+2011-03-14  David Hyatt  <hyatt@apple.com>
+
+        Reviewed by Dan Bernstein.
+
+        https://bugs.webkit.org/show_bug.cgi?id=45164
+
+        REGRESSION: <a><img align=top></a> Clickable area too large
+        
+        Make sure to clamp hit testing of quirky inline flow boxes the same way we already clamped
+        painting.
+
+        * rendering/InlineFlowBox.cpp:
+        (WebCore::InlineFlowBox::nodeAtPoint):
+
 2011-03-14  Chris Marrin  <cmarrin@apple.com>

         Reviewed by Adam Roben."}<_**next**_>{"sha": "a5f6ba6da35c9a745f1630af7d22670e59ced4bf", "filename": "third_party/WebKit/Source/WebCore/rendering/InlineFlowBox.cpp", "status": "modified", "additions": 23, "deletions": 4, "changes": 27, "blob_url": "https://github.com/chromium/chromium/blob/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/Source/WebCore/rendering/InlineFlowBox.cpp", "raw_url": "https://github.com/chromium/chromium/raw/04cca6c05e4923f1b91e0dddf053e088456d8645/third_party/WebKit/Source/WebCore/rendering/InlineFlowBox.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/rendering/InlineFlowBox.cpp?ref=04cca6c05e4923f1b91e0dddf053e088456d8645", "patch": "@@ -920,10 +920,29 @@ bool InlineFlowBox::nodeAtPoint(const HitTestRequest& request, HitTestResult& re
         }
     }

-    // Now check ourselves.
-    FloatPoint boxOrigin = locationIncludingFlipping();
-    boxOrigin.move(tx, ty);
-    FloatRect rect(boxOrigin, IntSize(width(), height()));
+    // Now check ourselves. Pixel snap hit testing.
+    IntRect frameRect = roundedFrameRect();
+    int minX = frameRect.x();
+    int minY = frameRect.y();
+    int width = frameRect.width();
+    int height = frameRect.height();
+
+    // Constrain our hit testing to the line top and bottom if necessary.
+    bool noQuirksMode = renderer()->document()->inNoQuirksMode();
+    if (!hasTextChildren() && !noQuirksMode) {
+        RootInlineBox* rootBox = root();
+        int& top = isHorizontal() ? minY : minX;
+        int& logicalHeight = isHorizontal() ? height : width;
+        int bottom = min(rootBox->lineBottom(), top + logicalHeight);
+        top = max(rootBox->lineTop(), top);
+        logicalHeight = bottom - top;
+    }
+    
+    // Move x/y to our coordinates.
+    IntRect rect(minX, minY, width, height);
+    flipForWritingMode(rect);
+    rect.move(tx, ty);
+
     if (visibleToHitTesting() && rect.intersects(result.rectForPoint(x, y))) {
         renderer()->updateHitTestResult(result, flipForWritingMode(IntPoint(x - tx, y - ty))); // Don't add in m_x or m_y here, we want coords in the containing block's space.
         if (!result.addNodeToRectBasedTestResult(renderer()->node(), x, y, rect))"}

