@@ -82,6 +106,9 @@ PrintDialogGtk::PrintDialogGtk(const FilePath& path_to_pdf)
 }

 PrintDialogGtk::~PrintDialogGtk() {
+  AutoLock lock(DialogLock());
+  DCHECK_EQ(this, g_print_dialog);
+  g_print_dialog = NULL;
 }

