         Remove deprecated calls from CookieJarCFNet.cpp"}<_**next**_>{"sha": "7407c11c6702393091daf0f92abf4f4c0638f7cf", "filename": "third_party/WebKit/Source/WebCore/fileapi/FileReader.idl", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/d74b8de894317e6a5472ad112bcf536d81a08999/third_party/WebKit/Source/WebCore/fileapi/FileReader.idl", "raw_url": "https://github.com/chromium/chromium/raw/d74b8de894317e6a5472ad112bcf536d81a08999/third_party/WebKit/Source/WebCore/fileapi/FileReader.idl", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/fileapi/FileReader.idl?ref=d74b8de894317e6a5472ad112bcf536d81a08999", "patch": "@@ -61,6 +61,16 @@ module html {

