+
+Test NPN_RemoveProperty
+
+On success, you will see a series of "PASS" messages, followed by "TEST COMPLETE".
+
+
+PASS 'property' in obj is true
+PASS 'property' in obj is false
+PASS array[1] is 2
+PASS array[1] is undefined
+"}<_**next**_>{"sha": "6e10e34e8f944a2671d944d1c671db901c6056f9", "filename": "third_party/WebKit/LayoutTests/plugins/npruntime/remove-property.html", "status": "added", "additions": 28, "deletions": 0, "changes": 28, "blob_url": "https://github.com/chromium/chromium/blob/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/LayoutTests/plugins/npruntime/remove-property.html", "raw_url": "https://github.com/chromium/chromium/raw/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/LayoutTests/plugins/npruntime/remove-property.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/plugins/npruntime/remove-property.html?ref=93dd81929416a0170935e6eeac03d10aed60df18", "patch": "@@ -0,0 +1,28 @@
+<link rel="stylesheet" href="../../fast/js/resources/js-test-style.css">
+<script src="../../fast/js/resources/js-test-pre.js"></script>
+</head>
+<script>
+function runTest() {
+    plugin = document.getElementById('plugin');
+
+    obj = { property : 'value' }
+    shouldBe("'property' in obj", "true");
+    plugin.testRemoveProperty(obj, 'property');
+    shouldBe("'property' in obj", "false");
+
+    array = [ 1, 2, 3, 4, 5];
+    shouldBe("array[1]", "2")
+    plugin.testRemoveProperty(array, 1);
+    shouldBe("array[1]", "undefined")
+}
+</script>
+<body onLoad="runTest()">
+<embed id="plugin" type="application/x-webkit-test-netscape" test="npruntime-remove-property"></embed>
+<p id="description"></p>
+<div id="console"></div>
+
+<script>
+description("Test NPN_RemoveProperty");
+
+successfullyParsed = true;
+</script>"}<_**next**_>{"sha": "0cb49195312a5b22240297381dcdf1a94d8b16c0", "filename": "third_party/WebKit/WebKit2/ChangeLog", "status": "modified", "additions": 21, "deletions": 0, "changes": 21, "blob_url": "https://github.com/chromium/chromium/blob/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/WebKit2/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/WebKit2/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/WebKit2/ChangeLog?ref=93dd81929416a0170935e6eeac03d10aed60df18", "patch": "@@ -1,3 +1,24 @@
