         Reviewed by Darin Adler."}<_**next**_>{"sha": "922ca63362a173e5a92ad22af8df97ca037a980a", "filename": "third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.cpp", "status": "modified", "additions": 37, "deletions": 1, "changes": 38, "blob_url": "https://github.com/chromium/chromium/blob/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.cpp", "raw_url": "https://github.com/chromium/chromium/raw/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.cpp?ref=93dd81929416a0170935e6eeac03d10aed60df18", "patch": "@@ -192,6 +192,37 @@ bool NPJSObject::setProperty(NPIdentifier propertyName, const NPVariant* value)
     return true;
 }

+bool NPJSObject::removeProperty(NPIdentifier propertyName)
+{
+    IdentifierRep* identifierRep = static_cast<IdentifierRep*>(propertyName);
+    
+    ExecState* exec = m_objectMap->globalExec();
+    if (!exec)
+        return false;
+
+    JSLock lock(SilenceAssertionsOnly);
+    if (identifierRep->isString()) {
+        Identifier identifier = identifierFromIdentifierRep(exec, identifierRep);
+        
+        if (!m_jsObject->hasProperty(exec, identifier)) {
+            exec->clearException();
+            return false;
+        }
+        
+        m_jsObject->deleteProperty(exec, identifier);
+    } else {
+        if (!m_jsObject->hasProperty(exec, identifierRep->number())) {
+            exec->clearException();
+            return false;
+        }
+
+        m_jsObject->deleteProperty(exec, identifierRep->number());
+    }
+
+    exec->clearException();
+    return true;
+}
+
 bool NPJSObject::enumerate(NPIdentifier** identifiers, uint32_t* identifierCount)
 {
     ExecState* exec = m_objectMap->globalExec();
@@ -280,7 +311,7 @@ NPClass* NPJSObject::npClass()
         NP_HasProperty,
         NP_GetProperty,
         NP_SetProperty,
-        0,
+        NP_RemoveProperty,
         NP_Enumerate,
         NP_Construct
     };
@@ -331,6 +362,11 @@ bool NPJSObject::NP_SetProperty(NPObject* npObject, NPIdentifier propertyName, c
     return toNPJSObject(npObject)->setProperty(propertyName, value);
 }

+bool NPJSObject::NP_RemoveProperty(NPObject* npObject, NPIdentifier propertyName)
+{
+    return toNPJSObject(npObject)->removeProperty(propertyName);
+}
+
 bool NPJSObject::NP_Enumerate(NPObject* npObject, NPIdentifier** identifiers, uint32_t* identifierCount)
 {
     return toNPJSObject(npObject)->enumerate(identifiers, identifierCount);"}<_**next**_>{"sha": "08ac9d4628e97d9b5bfbe9ce67a4563a12507c7d", "filename": "third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.h", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.h", "raw_url": "https://github.com/chromium/chromium/raw/93dd81929416a0170935e6eeac03d10aed60df18/third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/WebKit2/WebProcess/Plugins/NPJSObject.h?ref=93dd81929416a0170935e6eeac03d10aed60df18", "patch": "@@ -66,6 +66,7 @@ class NPJSObject : public NPObject, Noncopyable {
