{"sha": "b658d910e17ebc21d2ae545e3a3f1df823cd7980", "filename": "third_party/WebKit/Source/WebKit2/ChangeLog", "status": "modified", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/chromium/chromium/blob/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/ChangeLog?ref=d31f450c723ba46b53c1762e51188557447d85fd", "patch": "@@ -1,3 +1,35 @@
+2012-09-13  Balazs Kelemen  <kbalazs@webkit.org>
+
+        [WK2] LayerTreeCoordinator should release unused UpdatedAtlases
+        https://bugs.webkit.org/show_bug.cgi?id=95072
+
+        Reviewed by Jocelyn Turcotte.
+
+        Release graphic buffers that haven't been used for a while in order to save memory.
+        This way we can give back memory to the system when no user interaction happens
+        after a period of time, for example when we are in the background.
+
+        * Shared/ShareableBitmap.h:
+        * WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.cpp:
+        (WebKit::LayerTreeCoordinator::LayerTreeCoordinator):
+        (WebKit::LayerTreeCoordinator::beginContentUpdate):
+        (WebKit):
+        (WebKit::LayerTreeCoordinator::scheduleReleaseInactiveAtlases):
+        (WebKit::LayerTreeCoordinator::releaseInactiveAtlasesTimerFired):
+        * WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.h:
+        (LayerTreeCoordinator):
+        * WebProcess/WebPage/UpdateAtlas.cpp:
+        (WebKit::UpdateAtlas::UpdateAtlas):
+        (WebKit::UpdateAtlas::didSwapBuffers):
+        Don't call buildLayoutIfNeeded here. It's enought to call it in beginPaintingOnAvailableBuffer
+        and this way we can track whether this atlas is used with m_areaAllocator.
+        (WebKit::UpdateAtlas::beginPaintingOnAvailableBuffer):
+        * WebProcess/WebPage/UpdateAtlas.h:
+        (WebKit::UpdateAtlas::addTimeInactive):
+        (WebKit::UpdateAtlas::isInactive):
+        (WebKit::UpdateAtlas::isInUse):
+        (UpdateAtlas):
+
 2012-09-13  Lauro Neto  <lauro.neto@openbossa.org>

         [Qt][WK2] fast/forms/access-key-for-all-elements.html fails"}<_**next**_>{"sha": "e1ebc2e4cd0dc78b102cd6f7c9a9095965b13169", "filename": "third_party/WebKit/Source/WebKit2/Shared/ShareableBitmap.h", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/Shared/ShareableBitmap.h", "raw_url": "https://github.com/chromium/chromium/raw/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/Shared/ShareableBitmap.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/Shared/ShareableBitmap.h?ref=d31f450c723ba46b53c1762e51188557447d85fd", "patch": "@@ -60,6 +60,7 @@ namespace WebKit {
 class ShareableBitmap : public RefCounted<ShareableBitmap> {
 public:
     enum Flag {
+        NoFlags = 0,
         SupportsAlpha = 1 << 0,
     };
     typedef unsigned Flags;"}<_**next**_>{"sha": "0d2bd4d3f4c7543698ac01bd38bcb997a0a05a44", "filename": "third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.cpp", "status": "modified", "additions": 35, "deletions": 0, "changes": 35, "blob_url": "https://github.com/chromium/chromium/blob/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.cpp", "raw_url": "https://github.com/chromium/chromium/raw/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.cpp?ref=d31f450c723ba46b53c1762e51188557447d85fd", "patch": "@@ -78,6 +78,7 @@ LayerTreeCoordinator::LayerTreeCoordinator(WebPage* webPage)
     , m_shouldSyncFrame(false)
     , m_shouldSyncRootLayer(true)
     , m_layerFlushTimer(this, &LayerTreeCoordinator::layerFlushTimerFired)
+    , m_releaseInactiveAtlasesTimer(this, &LayerTreeCoordinator::releaseInactiveAtlasesTimerFired)
     , m_layerFlushSchedulingEnabled(true)
     , m_forceRepaintAsyncCallbackID(0)
 {
@@ -634,8 +635,42 @@ PassOwnPtr<WebCore::GraphicsContext> LayerTreeCoordinator::beginContentUpdate(co

     static const int ScratchBufferDimension = 1024; // Should be a power of two.
     m_updateAtlases.append(adoptPtr(new UpdateAtlas(ScratchBufferDimension, flags)));
+    scheduleReleaseInactiveAtlases();
     return m_updateAtlases.last()->beginPaintingOnAvailableBuffer(handle, size, offset);
 }

+const double ReleaseInactiveAtlasesTimerInterval = 0.5;
+
+void LayerTreeCoordinator::scheduleReleaseInactiveAtlases()
+{
+    if (!m_releaseInactiveAtlasesTimer.isActive())
+        m_releaseInactiveAtlasesTimer.startRepeating(ReleaseInactiveAtlasesTimerInterval);
+}
+
+void LayerTreeCoordinator::releaseInactiveAtlasesTimerFired(Timer<LayerTreeCoordinator>*)
+{
+    // We always want to keep one atlas for non-composited content.
+    OwnPtr<UpdateAtlas> atlasToKeepAnyway;
+    bool foundActiveAtlasForNonCompositedContent = false;
+    for (int i = m_updateAtlases.size() - 1;  i >= 0; --i) {
+        UpdateAtlas* atlas = m_updateAtlases[i].get();
+        if (!atlas->isInUse())
+            atlas->addTimeInactive(ReleaseInactiveAtlasesTimerInterval);
+        bool usableForNonCompositedContent = atlas->flags() == ShareableBitmap::NoFlags;
+        if (atlas->isInactive()) {
+            if (!foundActiveAtlasForNonCompositedContent && !atlasToKeepAnyway && usableForNonCompositedContent)
+                atlasToKeepAnyway = m_updateAtlases[i].release();
+            m_updateAtlases.remove(i);
+        } else if (usableForNonCompositedContent)
+            foundActiveAtlasForNonCompositedContent = true;
+    }
+
+    if (!foundActiveAtlasForNonCompositedContent && atlasToKeepAnyway)
+        m_updateAtlases.append(atlasToKeepAnyway.release());
+
+    if (m_updateAtlases.size() <= 1)
+        m_releaseInactiveAtlasesTimer.stop();
+}
+
 } // namespace WebKit
 #endif // USE(COORDINATED_GRAPHICS)"}<_**next**_>{"sha": "73b84e52402015950509aa0f0c55f5be7dc22b77", "filename": "third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.h", "status": "modified", "additions": 6, "deletions": 1, "changes": 7, "blob_url": "https://github.com/chromium/chromium/blob/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.h", "raw_url": "https://github.com/chromium/chromium/raw/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/CoordinatedGraphics/LayerTreeCoordinator.h?ref=d31f450c723ba46b53c1762e51188557447d85fd", "patch": "@@ -113,6 +113,11 @@ class LayerTreeCoordinator : public LayerTreeHost, WebCore::GraphicsLayerClient
