     bool m_shouldSyncFrame;
     bool m_shouldSyncRootLayer;
-    void layerFlushTimerFired(WebCore::Timer<LayerTreeCoordinator>*);
     WebCore::Timer<LayerTreeCoordinator> m_layerFlushTimer;
+    WebCore::Timer<LayerTreeCoordinator> m_releaseInactiveAtlasesTimer;
     bool m_layerFlushSchedulingEnabled;
     uint64_t m_forceRepaintAsyncCallbackID;
 };"}<_**next**_>{"sha": "27500635d275e2832de7a17923ce9896bb8833aa", "filename": "third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.cpp", "status": "modified", "additions": 2, "deletions": 1, "changes": 3, "blob_url": "https://github.com/chromium/chromium/blob/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.cpp", "raw_url": "https://github.com/chromium/chromium/raw/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.cpp?ref=d31f450c723ba46b53c1762e51188557447d85fd", "patch": "@@ -32,6 +32,7 @@ namespace WebKit {

