 "}<_**next**_>{"sha": "00e850b831bd72e99bba411a23708aba98445486", "filename": "third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.h", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.h", "raw_url": "https://github.com/chromium/chromium/raw/d31f450c723ba46b53c1762e51188557447d85fd/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/WebProcess/WebPage/UpdateAtlas.h?ref=d31f450c723ba46b53c1762e51188557447d85fd", "patch": "@@ -44,13 +44,26 @@ class UpdateAtlas {
