+
+  // Now reset the model again but load it after setting the preferences.
+  ResetModel(false);
+  SetManagedDefaultSearchPreferences(false, "", "", "", "", "", "");
+  VerifyLoad();
+  EXPECT_TRUE(model()->is_default_search_managed());
+  EXPECT_TRUE(model()->GetDefaultSearchProvider() == NULL);
 }"}

