 }

 WebInspector.StatusBarButton.prototype.__proto__ = WebInspector.Object.prototype;
+
+/**
+ * @constructor
+ * @param {?function(Event)} changeHandler
+ * @param {string=} className
+ */
+WebInspector.StatusBarComboBox = function(changeHandler, className)
+{
+    this.element = document.createElement("span");
+    this.element.className = "status-bar-select-container";
+
+    this._selectElement = this.element.createChild("select", "status-bar-item");
+    if (changeHandler)
+        this._selectElement.addEventListener("change", changeHandler, false);
+    if (className)
+        this._selectElement.addStyleClass(className);
+}
+
+WebInspector.StatusBarComboBox.prototype = {
+    /**
+     * @param {Element} option
+     */
+    addOption: function(option)
+    {
+        this._selectElement.appendChild(option);
+    },
+
+    /**
+     * @param {Element} option
+     */
+    removeOption: function(option)
+    {
+        this._selectElement.removeChild(option);
+    },
+
+    removeOptions: function()
+    {
+        this._selectElement.removeChildren();
+    },
+
+    /**
+     * @return {?Element}
+     */
+    selectedOption: function()
+    {
+        if (this._selectElement.selectedIndex >= 0)
+            return this._selectElement[this._selectElement.selectedIndex];
+        return null;
+    }
+}"}<_**next**_>{"sha": "e1e61b4a9da2f7446afe0b93d51cbc31504ef758", "filename": "third_party/WebKit/Source/WebCore/inspector/front-end/inspector.css", "status": "modified", "additions": 18, "deletions": 1, "changes": 19, "blob_url": "https://github.com/chromium/chromium/blob/e2ecf8b6e9daa6d4082f2b4f4c1454dbd70605cc/third_party/WebKit/Source/WebCore/inspector/front-end/inspector.css", "raw_url": "https://github.com/chromium/chromium/raw/e2ecf8b6e9daa6d4082f2b4f4c1454dbd70605cc/third_party/WebKit/Source/WebCore/inspector/front-end/inspector.css", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/inspector/front-end/inspector.css?ref=e2ecf8b6e9daa6d4082f2b4f4c1454dbd70605cc", "patch": "@@ -591,11 +591,28 @@ button.status-bar-item.extension {
