{"sha": "38bcf0fe25437291fd8f5b93daff8d687d778e09", "filename": "third_party/WebKit/Source/WebCore/ChangeLog", "status": "modified", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/b48b22e1a7bae061687a44e13c0dacb02721fc6f/third_party/WebKit/Source/WebCore/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/b48b22e1a7bae061687a44e13c0dacb02721fc6f/third_party/WebKit/Source/WebCore/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/ChangeLog?ref=b48b22e1a7bae061687a44e13c0dacb02721fc6f", "patch": "@@ -1,3 +1,20 @@
+2012-08-21  Tab Atkins  <tabatkins@google.com>
+
+        Track -webkit property usage.
+        https://bugs.webkit.org/show_bug.cgi?id=93420
+
+        Reviewed by Ojan Vafai.
+
+        First draft of an attempt to track all usage of -webkit prefixed properties across the web.
+        This attempt is dumb, but should provide useful data as a first-pass.
+        I plan to optimize this for better data collection in the future.
+
+        No tests added, as this is untestable currently.
+        It should have zero effect besides histogramming.
+
+        * css/CSSParser.cpp:
+        (WebCore::cssPropertyID):
+
 2012-08-21  Alec Flett  <alecflett@chromium.org>

         IndexedDB: remove old update/openCursor glue"}<_**next**_>{"sha": "ec0f1c204a28f814c17881189b25c1552f6e4751", "filename": "third_party/WebKit/Source/WebCore/css/CSSParser.cpp", "status": "modified", "additions": 11, "deletions": 1, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/b48b22e1a7bae061687a44e13c0dacb02721fc6f/third_party/WebKit/Source/WebCore/css/CSSParser.cpp", "raw_url": "https://github.com/chromium/chromium/raw/b48b22e1a7bae061687a44e13c0dacb02721fc6f/third_party/WebKit/Source/WebCore/css/CSSParser.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/css/CSSParser.cpp?ref=b48b22e1a7bae061687a44e13c0dacb02721fc6f", "patch": "@@ -62,6 +62,7 @@
 #include "FontValue.h"
 #include "HTMLParserIdioms.h"
 #include "HashTools.h"
+#include "HistogramSupport.h"
 #include "MediaList.h"
 #include "MediaQueryExp.h"
 #include "Page.h"
@@ -10124,7 +10125,16 @@ static CSSPropertyID cssPropertyID(const UChar* propertyName, unsigned length)
     }

     const Property* hashTableEntry = findProperty(name, length);
-    return hashTableEntry ? static_cast<CSSPropertyID>(hashTableEntry->id) : CSSPropertyInvalid;
+    const CSSPropertyID propertyID = hashTableEntry ? static_cast<CSSPropertyID>(hashTableEntry->id) : CSSPropertyInvalid;
+
+    // 600 is comfortably larger than numCSSProperties to allow for growth
+    static const int CSSPropertyHistogramSize = 600;
+    COMPILE_ASSERT(CSSPropertyHistogramSize > numCSSProperties, number_of_css_properties_exceed_CSSPropertyHistogramSize);
+
+    if (hasPrefix(buffer, length, "-webkit-") && propertyID != CSSPropertyInvalid)
+        HistogramSupport::histogramEnumeration("CSS.PrefixUsage", max(1, propertyID - firstCSSProperty), CSSPropertyHistogramSize);
+
+    return propertyID;
 }

 CSSPropertyID cssPropertyID(const String& string)"}

