-  virtual std::string error();
-  virtual void clear_error();
-  virtual void set_error(const std::string& error);
-
- protected:
-  ExtensionTtsPlatformImpl() {}
-  virtual ~ExtensionTtsPlatformImpl() {}
-
-  std::string error_;
-
