+  "version": "0.1",
+  "description": "browser test for chrome.experimental.tts API",
+  "background_page": "test.html",
+  "tts_engine": {
+    "voices": [
+      {
+        "voice_name": "Alice",
+        "lang": "en-US",
+        "gender": "female",
+        "event_types": [ "end" ]
+      },
+      {
+        "voice_name": "Pat",
+        "lang": "en-US",
+        "event_types": [ "end" ]
+      }
+    ]
+  },
+  "permissions": ["experimental"]
+}"}<_**next**_>{"sha": "46f4d74c30692c8ab193b54683da02bd212ef91f", "filename": "chrome/test/data/extensions/api_test/tts_engine/register_engine/test.html", "status": "added", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/register_engine/test.html", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/register_engine/test.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/tts_engine/register_engine/test.html?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -0,0 +1 @@
+<script src="test.js"></script>"}<_**next**_>{"sha": "ba9dc14dc5e5a33dfc9f1a912b344a7fea31974b", "filename": "chrome/test/data/extensions/api_test/tts_engine/register_engine/test.js", "status": "added", "additions": 170, "deletions": 0, "changes": 170, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/register_engine/test.js", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/register_engine/test.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/tts_engine/register_engine/test.js?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -0,0 +1,170 @@
+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// TTS api test for Chrome on ChromeOS.
+// browser_tests.exe --gtest_filter="TtsApiTest.*"
+
+if (!chrome.tts) {
+  chrome.tts = chrome.experimental.tts;
+}
+
+if (!chrome.ttsEngine) {
+  chrome.ttsEngine = chrome.experimental.ttsEngine;
+}
+
+chrome.test.runTests([
+  function testNoListeners() {
+    // This call should go to native speech because we haven't registered
+    // any listeners.
+    chrome.tts.speak(
+        'native speech',
+        {
+         'onevent': function(event) {
+           if (event.type == 'end') {
+             chrome.test.succeed();
+           }
+         }
+        }, function() {
+          chrome.test.assertNoLastError();
+        });
+  },
+  function testTtsEngine() {
+    var calledOurEngine = false;
+
+    // Register listeners for speech functions, enabling this extension
+    // to be a TTS engine.
+    var speakListener = function(utterance, options, sendTtsEvent) {
+        chrome.test.assertNoLastError();
+        chrome.test.assertEq('extension speech', utterance);
+        calledOurEngine = true;
+        sendTtsEvent({'type': 'end', 'charIndex': utterance.length});
+      };
+    var stopListener = function() {};
+    chrome.ttsEngine.onSpeak.addListener(speakListener);
+    chrome.ttsEngine.onStop.addListener(stopListener);
+
+    // This call should go to our own speech engine.
+    chrome.tts.speak(
+        'extension speech',
+        {
+         'onevent': function(event) {
+           if (event.type == 'end') {
+             chrome.test.assertEq(true, calledOurEngine);
+             chrome.ttsEngine.onSpeak.removeListener(speakListener);
+             chrome.ttsEngine.onStop.removeListener(stopListener);
+             chrome.test.succeed();
+           }
+         }
+        },
+        function() {
+          chrome.test.assertNoLastError();
+        });
+  },
+  function testVoiceMatching() {
+    // Count the number of times our callback functions have been called.
+    var callbacks = 0;
+    // Count the number of times our TTS engine has been called.
+    var speakListenerCalls = 0;
+
+    // Register listeners for speech functions.
+    var speakListener = function(utterance, options, sendTtsEvent) {
+      speakListenerCalls++;
+      sendTtsEvent({'type': 'end', 'charIndex': utterance.length});
+    };
+    var stopListener = function() {};
+    chrome.ttsEngine.onSpeak.addListener(speakListener);
+    chrome.ttsEngine.onStop.addListener(stopListener);
+
+    // These don't match the voices in the manifest, so they should
+    // go to native speech. The gmock assertions in TtsApiTest::RegisterEngine
+    // enforce that the native TTS handlers are called.
+    chrome.tts.speak(
+        'native speech 2',
+        {
+         'voiceName': 'George',
+         'enqueue': true,
+         'onevent': function(event) {
+           if (event.type == 'end') {
+             callbacks++;
+           }
+         }
+        }, function() {
+          chrome.test.assertNoLastError();
+        });
+    chrome.tts.speak(
+        'native speech 3',
+        {
+         'lang': 'fr-FR',
+         'enqueue': true,
+         'onevent': function(event) {
+           if (event.type == 'end') {
+             callbacks++;
+           }
+         }
+        }, function() {
+          chrome.test.assertNoLastError();
+        });
+
+    // These do match the voices in the manifest, so they should go to our
+    // own TTS engine.
+    chrome.tts.speak(
+        'extension speech 2',
+        {
+         'voiceName': 'Alice',
+         'enqueue': true,
+         'onevent': function(event) {
+           if (event.type == 'end') {
+             callbacks++;
+           }
+         }
+        }, function() {
+          chrome.test.assertNoLastError();
+        });
+    chrome.tts.speak(
+        'extension speech 3',
+        {
+         'voiceName': 'Pat',
+         'gender': 'male',
+         'enqueue': true,
+         'onevent': function(event) {
+           if (event.type == 'end') {
+             callbacks++;
+             chrome.ttsEngine.onSpeak.removeListener(speakListener);
+             chrome.ttsEngine.onStop.removeListener(stopListener);
+             if (callbacks == 4 && speakListenerCalls == 2) {
+               chrome.test.succeed();
+             }
+           }
+         }
+        }, function() {
+          chrome.test.assertNoLastError();
+        });
+  },
+  function testGetVoices() {
+    // We have to register listeners, or the voices provided
+    // by this extension won't be returned.
+    var speakListener = function(utterance, options, sendTtsEvent) {
+        chrome.test.assertNoLastError();
+        chrome.test.assertEq('extension speech', utterance);
+        sendTtsEvent({'type': 'end', 'charIndex': utterance.length});
+      };
+    var stopListener = function() {};
+    chrome.ttsEngine.onSpeak.addListener(speakListener);
+    chrome.ttsEngine.onStop.addListener(stopListener);
+
+    chrome.tts.getVoices(function(voices) {
+      chrome.test.assertEq(3, voices.length);
+
+      chrome.test.assertEq('native', voices[0].voiceName);
+
+      chrome.test.assertEq('Alice', voices[1].voiceName);
+      chrome.test.assertEq('en-US', voices[1].lang);
+      chrome.test.assertEq('female', voices[1].gender);
+
+      chrome.test.assertEq('Pat', voices[2].voiceName);
+      chrome.test.assertEq('en-US', voices[2].lang);
+      chrome.test.succeed();
+    });
+  }
+]);"}<_**next**_>{"sha": "91f1c28633225d928ba495864d5edfd4039c1e78", "filename": "chrome/test/data/extensions/manifest_tests/tts_engine_invalid_1.json", "status": "renamed", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/manifest_tests/tts_engine_invalid_1.json", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/manifest_tests/tts_engine_invalid_1.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/manifest_tests/tts_engine_invalid_1.json?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -1,5 +1,5 @@
