+<script src="common.js"></script>
+<script src="accepted.js"></script>"}<_**next**_>{"sha": "e2712d9d8a7305ecb31f433a9e211fc053442dde", "filename": "chrome/test/data/extensions/api_test/webstore_private/accepted.js", "status": "added", "additions": 65, "deletions": 0, "changes": 65, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/accepted.js", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/accepted.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/accepted.js?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,65 @@
+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// Tests where the beginInstallWithManifest dialog would be auto-accepted
+// (including a few cases where this does not matter).
+
+var tests = [
+
+  function completeBeforeBegin() {
+    var expectedError =
+        extensionId + " does not match a previous call to beginInstall";
+    chrome.webstorePrivate.completeInstall(extensionId,
+                                           callbackFail(expectedError));
+  },
+
+  function invalidID() {
+    var expectedError = "Invalid id";
+    var id = "zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz";
+    chrome.webstorePrivate.beginInstallWithManifest(
+        id, "", getManifest(), callbackFail(expectedError));
+  },
+
+  function missingVersion() {
+    var manifestObj = JSON.parse(getManifest());
+    delete manifestObj["version"];
+    var manifest = JSON.stringify(manifestObj);
+    chrome.webstorePrivate.beginInstallWithManifest(
+        extensionId,
+        "",
+        manifest,
+        callbackFail("Invalid manifest", function(result) {
+      assertEq("manifest_error", result);
+    }));
+  },
+
+  function successfulInstall() {
+    // See things through all the way to a successful install, and then we
+    // uninstall the extension to clean up.
+    listenOnce(chrome.management.onInstalled, function(info) {
+      assertEq(info.id, extensionId);
+      chrome.management.uninstall(extensionId, callbackPass());
+    });
+
+    var manifest = getManifest();
+    getIconData(function(icon) {
+
+      // Begin installing.
+      chrome.webstorePrivate.beginInstallWithManifest(extensionId,
+                                                      icon,
+                                                      manifest,
+                                                      function(result) {
+        assertNoLastError();
+        assertEq(result, "");
+
+        // Now complete the installation.
+        chrome.webstorePrivate.completeInstall(extensionId, function() {
+          assertNoLastError();
+        });
+      });
+    });
+  }
+];
+
+runTests(tests);"}<_**next**_>{"sha": "b79250aad60d7f8889473f7a8cbb010f4a59c658", "filename": "chrome/test/data/extensions/api_test/webstore_private/cancelled.html", "status": "added", "additions": 18, "deletions": 0, "changes": 18, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/cancelled.html", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/cancelled.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/cancelled.html?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,18 @@
+<script src="common.js"></script>
+<script>
+// This tests the user cancelling an install started by
+// beginInstallWithManifest.
+
+var manifest = getManifest();
+getIconData(function(icon) {
+
+  // Begin installing.
+  chrome.webstorePrivate.beginInstallWithManifest(extensionId,
+                                                  icon,
+                                                  manifest,
+                                                  function(result) {
+      assertEq(result, "user_cancelled");
+      succeed();
+  });
+});
+</script>"}<_**next**_>{"sha": "8b0deaf139bba70a573cca935b5149b5792cf939", "filename": "chrome/test/data/extensions/api_test/webstore_private/common.js", "status": "added", "additions": 61, "deletions": 0, "changes": 61, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/common.js", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/common.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/common.js?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,61 @@
+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// The id of the extension we're using for install tests.
+var extensionId = "enfkhcelefdadlmkffamgdlgplcionje";
+
+var assertEq = chrome.test.assertEq;
+var assertNoLastError = chrome.test.assertNoLastError;
+var callbackFail = chrome.test.callbackFail;
+var callbackPass = chrome.test.callbackPass;
+var listenOnce = chrome.test.listenOnce;
+var runTests = chrome.test.runTests;
+var succeed = chrome.test.succeed;
+
+// Calls |callback| with true/false indicating whether an item with an id of
+// extensionId is installed.
+function checkInstalled(callback) {
+  chrome.management.getAll(function(extensions) {
+    callback(extensions.some(function(ext) {
+      return ext.id == extensionId;
+    }));
+  });
+}
+
+var cachedIcon = null;
+
+// This returns the base64-encoded content of the extension's image.
+function getIconData(callback) {
+  if (cachedIcon) {
+    callback(cachedIcon);
+  }
+  var canvas = document.createElement("canvas");
+  canvas.style.display = "none";
+  canvas.width = 128;
+  canvas.height = 128;
+  var img = new Image();
+  img.onload = function() {
+    var ctx = canvas.getContext("2d");
+    ctx.drawImage(img, 0, 0);
+    var tmp = canvas.toDataURL();
+    // Strip the data url prefix to just get the base64-encoded bytes.
+    cachedIcon = tmp.slice(tmp.search(",")+1);
+    callback(cachedIcon);
+  };
+  img.src = "extension/icon.png";
+}
+
+var cachedManifest = null;
+
+// This returns the string contents of the extension's manifest file.
+function getManifest() {
+  if (cachedManifest)
+    return cachedManifest;
+
+  // Do a synchronous XHR to get the manifest.
+  var xhr = new XMLHttpRequest();
+  xhr.open("GET", "extension/manifest.json", false);
+  xhr.send(null);
+  return xhr.responseText;
+}"}<_**next**_>{"sha": "b140acc76c3bd127aaf0a5676871fc640d2838b1", "filename": "chrome/test/data/extensions/api_test/webstore_private/extension.crx", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/extension.crx", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/extension.crx", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/extension.crx?ref=9eb1fd426a04adac0906c81ed88f1089969702ba"}<_**next**_>{"sha": "c8a57232f60b7b747faab773b3912d0fe372ad3b", "filename": "chrome/test/data/extensions/api_test/webstore_private/extension.pem", "status": "added", "additions": 16, "deletions": 0, "changes": 16, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/extension.pem", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/extension.pem", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/extension.pem?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,16 @@
