+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// Parse the manifest, and mangle it via "alterManifest" (which should already
+// be defined before running this file).
+var manifestObj = JSON.parse(getManifest());
+var manifest = alterManifest(manifestObj);
+
+// Now cause the install to proceed - the C++ code will verify
+// that we get an install error after unpacking the crx file because the crx
+// file's manifest won't match what we provided for the confirmation dialog
+// here.
+chrome.webstorePrivate.beginInstallWithManifest(
+    extensionId,
+    "",
+    manifest,
+    function(result) {
+  assertNoLastError();
+  assertEq("", result);
+  chrome.webstorePrivate.completeInstall(extensionId,
+                                         function(){
+    assertNoLastError();
+    succeed();
+   });
+});"}<_**next**_>{"sha": "50ec12a4d2da0753a21bfe3fd619d83e28bb646e", "filename": "chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest1.html", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest1.html", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest1.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest1.html?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,12 @@
+<script src="common.js"></script>
+<script>
+
+function alterManifest(manifestObj) {
+  // Change the version to be incorrect.
+  manifestObj["version"] =
+      (parseFloat(manifestObj["version"]) + 1).toString();
+  return JSON.stringify(manifestObj);
+}
+
+</script>
+<script src="incorrect_manifest.js"></script>"}<_**next**_>{"sha": "30bf4b24df86b2c777911b0880fa86e801db4b44", "filename": "chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest2.html", "status": "added", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest2.html", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest2.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/incorrect_manifest2.html?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,11 @@
+<script src="common.js"></script>
+<script>
+
+function alterManifest(manifestObj) {
+  // Remove the permissions key.
+  delete manifestObj["permissions"];
+  return JSON.stringify(manifestObj);
+}
+
+</script>
+<script src="incorrect_manifest.js"></script>"}<_**next**_>{"sha": "1091c2c48d4f9b54b9a8ba77e01c946e5a85a66d", "filename": "chrome/test/data/extensions/api_test/webstore_private/no_user_gesture.html", "status": "added", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/no_user_gesture.html", "raw_url": "https://github.com/chromium/chromium/raw/9eb1fd426a04adac0906c81ed88f1089969702ba/chrome/test/data/extensions/api_test/webstore_private/no_user_gesture.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webstore_private/no_user_gesture.html?ref=9eb1fd426a04adac0906c81ed88f1089969702ba", "patch": "@@ -0,0 +1,11 @@
+<script src="common.js"></script>
+<script>
+// We expect that this test is called outside of a user gesture, which should
+// generate an error.
+chrome.webstorePrivate.beginInstallWithManifest(
+    extensionId, "", getManifest(), function() {
+  assertEq(chrome.extension.lastError.message,
+      "This function must be called during a user gesture");
+  succeed();
+});
+</script>"}

