{"sha": "9702de37fce3917431ac182122fefad351b064e9", "filename": "third_party/WebKit/Source/WebCore/ChangeLog", "status": "modified", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/chromium/chromium/blob/73edae623529f04c668268de49d00324b96166a2/third_party/WebKit/Source/WebCore/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/73edae623529f04c668268de49d00324b96166a2/third_party/WebKit/Source/WebCore/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/ChangeLog?ref=73edae623529f04c668268de49d00324b96166a2", "patch": "@@ -1,3 +1,35 @@
+2012-05-24  Ryosuke Niwa  <rniwa@webkit.org>
+
