+2011-06-08  Alexander Pavlov  <apavlov@chromium.org>
+
+        Reviewed by Yury Semikhatsky.
+
+        Web Inspector: node selection is slow in the Elements panel.
+        https://bugs.webkit.org/show_bug.cgi?id=60813
+
+        Schedule full style updates rather than request all node styles from the backend immediately.
+
+        * inspector/front-end/StylesSidebarPane.js:
+        (WebInspector.StylesSidebarPane.prototype.update.reloadAllStyles):
+        (WebInspector.StylesSidebarPane.prototype.update):
+
 2011-06-08  Andreas Kling  <andreas.kling@nokia.com>

         Reviewed by Laszlo Gombos."}<_**next**_>{"sha": "d1863253f5da0d5b44a66e3fa976d50521432c90", "filename": "third_party/WebKit/Source/WebCore/inspector/front-end/StylesSidebarPane.js", "status": "modified", "additions": 13, "deletions": 2, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/f3c73feb5fa49300cada382dd9304442a5674c74/third_party/WebKit/Source/WebCore/inspector/front-end/StylesSidebarPane.js", "raw_url": "https://github.com/chromium/chromium/raw/f3c73feb5fa49300cada382dd9304442a5674c74/third_party/WebKit/Source/WebCore/inspector/front-end/StylesSidebarPane.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/inspector/front-end/StylesSidebarPane.js?ref=f3c73feb5fa49300cada382dd9304442a5674c74", "patch": "@@ -235,10 +235,21 @@ WebInspector.StylesSidebarPane.prototype = {
                 this._refreshUpdate(node, computedStyle, editedSection);
         }

+        function reloadAllStyles()
+        {
+            delete this._reloadAllStylesTimer;
+            WebInspector.cssModel.getStylesAsync(this._allStylesNodeId, stylesCallback.bind(this))
+        }
+
         if (refresh)
             WebInspector.cssModel.getComputedStyleAsync(node.id, computedStyleCallback.bind(this));
-        else
-            WebInspector.cssModel.getStylesAsync(node.id, stylesCallback.bind(this));
+        else {
+            // Always refresh the node to request styles for.
+            this._allStylesNodeId = node.id;
+            if ("_reloadAllStylesTimer" in this)
+                return;
+            this._reloadAllStylesTimer = setTimeout(reloadAllStyles.bind(this), 0);
+        }
     },

     _refreshUpdate: function(node, computedStyle, editedSection)"}

