+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/test/webdriver/webdriver_logging.h"
+
+#include "base/file_path.h"
+#include "base/file_util.h"
+#include "base/logging.h"
+
+namespace {
+
+// Path to the WebDriver log file.
+const FilePath::CharType kLogPath[] = FILE_PATH_LITERAL("chromedriver.log");
+
+}  // namespace
+
+namespace webdriver {
+
+void InitWebDriverLogging(int min_log_level) {
+  bool success = InitLogging(
+      kLogPath,
+      logging::LOG_TO_BOTH_FILE_AND_SYSTEM_DEBUG_LOG,
+      logging::LOCK_LOG_FILE,
+      logging::DELETE_OLD_LOG_FILE,
+      logging::DISABLE_DCHECK_FOR_NON_OFFICIAL_RELEASE_BUILDS);
+  if (!success) {
+    PLOG(ERROR) << "Unable to initialize logging";
+  }
+  logging::SetLogItems(false,  // enable_process_id
+                       false,  // enable_thread_id
+                       true,   // enable_timestamp
+                       false); // enable_tickcount
+  logging::SetMinLogLevel(min_log_level);
+}
+
+bool GetLogContents(std::string* log_contents) {
+  return file_util::ReadFileToString(FilePath(kLogPath), log_contents);
+}
+
+}  // namespace webdriver"}<_**next**_>{"sha": "2b8ab5ed80a1df38b4cfb08ce7378fcefff33b93", "filename": "chrome/test/webdriver/webdriver_logging.h", "status": "added", "additions": 22, "deletions": 0, "changes": 22, "blob_url": "https://github.com/chromium/chromium/blob/4ab22cfc619ee8ff17a8c50e289ec3b30731ceba/chrome/test/webdriver/webdriver_logging.h", "raw_url": "https://github.com/chromium/chromium/raw/4ab22cfc619ee8ff17a8c50e289ec3b30731ceba/chrome/test/webdriver/webdriver_logging.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/webdriver/webdriver_logging.h?ref=4ab22cfc619ee8ff17a8c50e289ec3b30731ceba", "patch": "@@ -0,0 +1,22 @@
+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef CHROME_TEST_WEBDRIVER_WEBDRIVER_LOGGING_H_
+#define CHROME_TEST_WEBDRIVER_WEBDRIVER_LOGGING_H_
+
+#include <string>
+
+namespace webdriver {
+
+// Initializes logging for WebDriver. All logging below the given level
+// will be discarded.
+void InitWebDriverLogging(int min_log_level);
+
+// Retrieves the current contents of the WebDriver log file.
+// Returns true on success.
+bool GetLogContents(std::string* log_contents);
+
+}  // namespace webdriver
+
+#endif  // CHROME_TEST_WEBDRIVER_WEBDRIVER_LOGGING_H_"}

