{"sha": "271bbf4701ac09cbf0d1906a1c44f35d3502a4e8", "filename": "third_party/WebKit/Source/WebCore/ChangeLog", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/b0ce1496c71721bebd69de4b1a842c5977708d12/third_party/WebKit/Source/WebCore/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/b0ce1496c71721bebd69de4b1a842c5977708d12/third_party/WebKit/Source/WebCore/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/ChangeLog?ref=b0ce1496c71721bebd69de4b1a842c5977708d12", "patch": "@@ -1,3 +1,14 @@
+2011-06-30  Mikhail Naganov  <mnaganov@chromium.org>
+
+        Reviewed by Yury Semikhatsky.
+
+        Web Inspector: [Chromium] Fix heap snapshots in a remote debugging session from Safari.
+        https://bugs.webkit.org/show_bug.cgi?id=63703
+
+        * inspector/front-end/HeapSnapshotWorker.js:
+        (.Function.prototype.bind.return.bound):
+        (.Function.prototype.bind):
+
 2011-07-01  Dirk Schulze  <krit@webkit.org>

         Reviewed by Nikolas Zimmermann."}<_**next**_>{"sha": "434cfd2ab48bc9a7511973ad3f45247b6bb741bb", "filename": "third_party/WebKit/Source/WebCore/inspector/front-end/HeapSnapshotWorker.js", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/b0ce1496c71721bebd69de4b1a842c5977708d12/third_party/WebKit/Source/WebCore/inspector/front-end/HeapSnapshotWorker.js", "raw_url": "https://github.com/chromium/chromium/raw/b0ce1496c71721bebd69de4b1a842c5977708d12/third_party/WebKit/Source/WebCore/inspector/front-end/HeapSnapshotWorker.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/inspector/front-end/HeapSnapshotWorker.js?ref=b0ce1496c71721bebd69de4b1a842c5977708d12", "patch": "@@ -31,6 +31,19 @@
 WebInspector = {};
 WebInspector.UIString = function(s) { return s; };

+// Safari lacks 'bind'.
+if (!("bind" in Function.prototype)) {
+    Function.prototype.bind = function(thisObject)
+    {
+        var func = this;
+        var args = Array.prototype.slice.call(arguments, 1);
+        return function bound()
+        {
+            return func.apply(thisObject, args.concat(Array.prototype.slice.call(arguments, 0)));
+        };
+    };
+}
+
 importScripts("BinarySearch.js");
 importScripts("HeapSnapshot.js");
 importScripts("HeapSnapshotWorkerDispatcher.js");"}

