+    ?createNotEnoughArgumentsError@JSC@@YAPAVJSObject@1@PAVExecState@1@@Z
     ?cryptographicallyRandomNumber@WTF@@YAIXZ
     ?cryptographicallyRandomValues@WTF@@YAXPAXI@Z
     ?currentThread@WTF@@YAIXZ"}<_**next**_>{"sha": "bae07448b3118892d933958864f3a48959fdaf3d", "filename": "third_party/WebKit/Source/JavaScriptCore/runtime/Error.cpp", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/b944f670bb7a8a919daac497a4ea0536c954c201/third_party/WebKit/Source/JavaScriptCore/runtime/Error.cpp", "raw_url": "https://github.com/chromium/chromium/raw/b944f670bb7a8a919daac497a4ea0536c954c201/third_party/WebKit/Source/JavaScriptCore/runtime/Error.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/JavaScriptCore/runtime/Error.cpp?ref=b944f670bb7a8a919daac497a4ea0536c954c201", "patch": "@@ -79,6 +79,11 @@ JSObject* createTypeError(JSGlobalObject* globalObject, const UString& message)
     return ErrorInstance::create(globalObject->globalData(), globalObject->typeErrorConstructor()->errorStructure(), message);
 }

+JSObject* createNotEnoughArgumentsError(JSGlobalObject* globalObject)
+{
+    return createTypeError(globalObject, "Not enough arguments");
+}
+
 JSObject* createURIError(JSGlobalObject* globalObject, const UString& message)
 {
     ASSERT(!message.isEmpty());
@@ -115,6 +120,11 @@ JSObject* createTypeError(ExecState* exec, const UString& message)
     return createTypeError(exec->lexicalGlobalObject(), message);
