-void WebPage::gestureDidScroll(const WebCore::IntSize& size)
+void WebPage::gestureDidScroll(const IntSize& size, bool& atBeginningOrEndOfScrollableDocument)
 {
+    atBeginningOrEndOfScrollableDocument = false;
+
     if (!m_gestureTargetNode || !m_gestureTargetNode->renderer() || !m_gestureTargetNode->renderer()->enclosingLayer())
         return;

     m_gestureTargetNode->renderer()->enclosingLayer()->scrollByRecursively(size.width(), size.height());
+
+    Frame* frame = m_page->mainFrame();
+    if (!frame)
+        return;
+
+    ScrollView* view = frame->view();
+    if (!view)
+        return;
+
+    Scrollbar* verticalScrollbar = view->verticalScrollbar();
+    if (!verticalScrollbar)
+        return;
+
+    atBeginningOrEndOfScrollableDocument = !verticalScrollbar->currentPos() || verticalScrollbar->currentPos() >= verticalScrollbar->maximum();
 }

 void WebPage::gestureDidEnd()"}

{"sha": "ae10682c41d142257eccab0185046fa12f0fdb82", "filename": "net/socket/transport_client_socket_pool.h", "status": "modified", "additions": 13, "deletions": 7, "changes": 20, "blob_url": "https://github.com/chromium/chromium/blob/1332c24d517e472758aae7e25301752561da6bc5/net/socket/transport_client_socket_pool.h", "raw_url": "https://github.com/chromium/chromium/raw/1332c24d517e472758aae7e25301752561da6bc5/net/socket/transport_client_socket_pool.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/socket/transport_client_socket_pool.h?ref=1332c24d517e472758aae7e25301752561da6bc5", "patch": "@@ -48,16 +48,22 @@ class TransportSocketParams : public base::RefCounted<TransportSocketParams> {
 };

 // TransportConnectJob handles the host resolution necessary for socket creation
-// and the transport (likely TCP) connect.
+// and the transport (likely TCP) connect. TransportConnectJob also has fallback
+// logic for IPv6 connect() timeouts (which may happen due to networks / routers
+// with broken IPv6 support). Those timeouts take 20s, so rather than make the
+// user wait 20s for the timeout to fire, we use a fallback timer
+// (kIPv6FallbackTimerInMs) and start a connect() to a IPv4 address if the timer
+// fires. Then we race the IPv4 connect() against the IPv6 connect() (which has
+// a headstart) and return the one that completes first to the socket pool.
 class TransportConnectJob : public ConnectJob {
  public:
   TransportConnectJob(const std::string& group_name,
-                const scoped_refptr<TransportSocketParams>& params,
-                base::TimeDelta timeout_duration,
-                ClientSocketFactory* client_socket_factory,
-                HostResolver* host_resolver,
-                Delegate* delegate,
-                NetLog* net_log);
+                      const scoped_refptr<TransportSocketParams>& params,
+                      base::TimeDelta timeout_duration,
+                      ClientSocketFactory* client_socket_factory,
+                      HostResolver* host_resolver,
