{"sha": "552d39f4d1c8593a0c5f8b9ad70998b034b8d3d2", "filename": "chrome/installer/setup/install_worker.cc", "status": "modified", "additions": 5, "deletions": 3, "changes": 8, "blob_url": "https://github.com/chromium/chromium/blob/45bae236b03f577ed6682ef4c7ef3ee006de5e5a/chrome/installer/setup/install_worker.cc", "raw_url": "https://github.com/chromium/chromium/raw/45bae236b03f577ed6682ef4c7ef3ee006de5e5a/chrome/installer/setup/install_worker.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/installer/setup/install_worker.cc?ref=45bae236b03f577ed6682ef4c7ef3ee006de5e5a", "patch": "@@ -97,12 +97,14 @@ void AddInstallerCopyTasks(const InstallerState& installer_state,
   FilePath exe_dst(installer_dir.Append(setup_path.BaseName()));
   FilePath archive_dst(installer_dir.Append(archive_path.BaseName()));

+  install_list->AddCopyTreeWorkItem(setup_path.value(), exe_dst.value(),
+                                    temp_path.value(), WorkItem::ALWAYS);
+
   // In the past, we copied rather than moved for system level installs so that
   // the permissions of %ProgramFiles% would be picked up.  Now that |temp_path|
   // is in %ProgramFiles% for system level installs (and in %LOCALAPPDATA%
-  // otherwise), there is no need to do this.
-  install_list->AddMoveTreeWorkItem(setup_path.value(), exe_dst.value(),
-                                    temp_path.value(), WorkItem::ALWAYS_MOVE);
+  // otherwise), there is no need to do this for the archive.  Setup.exe, on
+  // the other hand, is created elsewhere so it must always be copied.
   install_list->AddMoveTreeWorkItem(archive_path.value(), archive_dst.value(),
                                     temp_path.value(), WorkItem::ALWAYS_MOVE);
 }"}

{"sha": "a13e871e7061ed9f9c834e7b10f14487b28f51d2", "filename": "third_party/WebKit/Source/WebKit2/ChangeLog", "status": "modified", "additions": 29, "deletions": 0, "changes": 29, "blob_url": "https://github.com/chromium/chromium/blob/1777aa6484af15014b8691082a8c3075418786f5/third_party/WebKit/Source/WebKit2/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/1777aa6484af15014b8691082a8c3075418786f5/third_party/WebKit/Source/WebKit2/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/ChangeLog?ref=1777aa6484af15014b8691082a8c3075418786f5", "patch": "@@ -1,3 +1,32 @@
+2012-03-08  No'am Rosenthal  <noam.rosenthal@nokia.com>
+
+        [Qt][WK2] Allow transparent WebViews
+        https://bugs.webkit.org/show_bug.cgi?id=80608
+
+        Reviewed by Tor Arne Vestbø.
+
+        Added support for transparentBackground in QQuickWebViewExperimental.
+        This uses the existing drawsTransparentBackground property in WebKit2.
+        Also, changed LayerTreeHostQt to set the contentsOpaque flag when the root layer changes,
+        otherwise the change doesn't take effect.
+
+        A new API test was added.
+
+        * UIProcess/API/qt/qquickwebview.cpp:
+        (QQuickWebViewPrivate::setTransparentBackground):
+        (QQuickWebViewPrivate::transparentBackground):
+        (QQuickWebViewExperimental::transparentBackground):
+        (QQuickWebViewExperimental::setTransparentBackground):
+        * UIProcess/API/qt/qquickwebview_p.h:
+        * UIProcess/API/qt/qquickwebview_p_p.h:
+        (QQuickWebViewPrivate):
+        * UIProcess/API/qt/tests/qquickwebview/tst_qquickwebview.cpp:
+        (tst_QQuickWebView):
+        (tst_QQuickWebView::transparentWebViews):
+        * WebProcess/WebPage/qt/LayerTreeHostQt.cpp:
+        (WebKit::LayerTreeHostQt::LayerTreeHostQt):
+        (WebKit::LayerTreeHostQt::setRootCompositingLayer):
+
 2012-03-08  Gustavo Noronha Silva  <gns@gnome.org>

         GTK+ build fix. Only try to get the backing from the layer in when"}<_**next**_>{"sha": "a1efba29d42a4d1f3ea90706da97f523d3fdbc65", "filename": "third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp", "status": "modified", "additions": 21, "deletions": 0, "changes": 21, "blob_url": "https://github.com/chromium/chromium/blob/1777aa6484af15014b8691082a8c3075418786f5/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp", "raw_url": "https://github.com/chromium/chromium/raw/1777aa6484af15014b8691082a8c3075418786f5/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp?ref=1777aa6484af15014b8691082a8c3075418786f5", "patch": "@@ -125,6 +125,16 @@ void QQuickWebViewPrivate::initialize(WKContextRef contextRef, WKPageGroupRef pa
