+        Reviewed by Joseph Pecoraro.
+
+        Web Inspector: Can't backspace from CSS value to CSS key field
+        https://bugs.webkit.org/show_bug.cgi?id=51476
+
+        * inspector/front-end/StylesSidebarPane.js:
+        (WebInspector.StylePropertyTreeElement.prototype.):
+        (WebInspector.StylePropertyTreeElement.prototype):
+
 2010-12-23  W. James MacLean  <wjmaclean@chromium.org>

         Reviewed by Kenneth Russell."}<_**next**_>{"sha": "75611a3c8e9c2d290029f8a8e9d32e4bcb4c6730", "filename": "third_party/WebKit/WebCore/inspector/front-end/StylesSidebarPane.js", "status": "modified", "additions": 8, "deletions": 1, "changes": 9, "blob_url": "https://github.com/chromium/chromium/blob/c13183661f98b29764e3db2fd3a2741dc1f1d086/third_party/WebKit/WebCore/inspector/front-end/StylesSidebarPane.js", "raw_url": "https://github.com/chromium/chromium/raw/c13183661f98b29764e3db2fd3a2741dc1f1d086/third_party/WebKit/WebCore/inspector/front-end/StylesSidebarPane.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/WebCore/inspector/front-end/StylesSidebarPane.js?ref=c13183661f98b29764e3db2fd3a2741dc1f1d086", "patch": "@@ -1559,7 +1559,14 @@ WebInspector.StylePropertyTreeElement.prototype = {
                 return "move-forward";
             } else if (event.keyCode === WebInspector.KeyboardShortcut.Keys.Esc.code)
                 return "cancel";
-            else if (event.keyIdentifier === "U+0009") // Tab key.
+            else if (!isEditingName && this._newProperty && event.keyCode === WebInspector.KeyboardShortcut.Keys.Backspace.code) {
+                // For a new property, when Backspace is pressed at the beginning of new property value, move back to the property name.
+                var selection = window.getSelection();
+                if (selection.isCollapsed && !selection.focusOffset) {
+                    event.preventDefault();
+                    return "move-backward";
+                }
+            } else if (event.keyIdentifier === "U+0009") // Tab key.
                 return "move-" + (event.shiftKey ? "backward" : "forward");
         }
