{"sha": "60888439b15cd5e731552269624afe2656cd3c68", "filename": "third_party/WebKit/Source/WebCore/ChangeLog", "status": "modified", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/chromium/chromium/blob/294474c162b13937a6474955c6594b3657379c1e/third_party/WebKit/Source/WebCore/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/294474c162b13937a6474955c6594b3657379c1e/third_party/WebKit/Source/WebCore/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/ChangeLog?ref=294474c162b13937a6474955c6594b3657379c1e", "patch": "@@ -1,3 +1,17 @@
+2011-02-13  Sam Weinig  <sam@webkit.org>
+
+        Reviewed by Dan Bernstein.
+
+        Some Scrollbar functions assume an attached ScrollableArea but can be called without one
+        https://bugs.webkit.org/show_bug.cgi?id=54262
+
+        Make sure that all calls to the scrollable area are null checked.
+
+        * platform/Scrollbar.cpp:
+        (WebCore::Scrollbar::autoscrollPressedPart):
+        (WebCore::Scrollbar::moveThumb):
+        (WebCore::Scrollbar::mouseMoved):
+
 2011-02-13  Sam Weinig  <sam@webkit.org>

         Roll out r78424. It broke a bunch of tests."}<_**next**_>{"sha": "5d9a43d8e1468252ae81c464bf754184524ac291", "filename": "third_party/WebKit/Source/WebCore/platform/Scrollbar.cpp", "status": "modified", "additions": 7, "deletions": 5, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/294474c162b13937a6474955c6594b3657379c1e/third_party/WebKit/Source/WebCore/platform/Scrollbar.cpp", "raw_url": "https://github.com/chromium/chromium/raw/294474c162b13937a6474955c6594b3657379c1e/third_party/WebKit/Source/WebCore/platform/Scrollbar.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebCore/platform/Scrollbar.cpp?ref=294474c162b13937a6474955c6594b3657379c1e", "patch": "@@ -196,7 +196,7 @@ void Scrollbar::autoscrollPressedPart(double delay)
     }

     // Handle the arrows and track.
-    if (scrollableArea()->scroll(pressedPartScrollDirection(), pressedPartScrollGranularity()))
+    if (m_scrollableArea && m_scrollableArea->scroll(pressedPartScrollDirection(), pressedPartScrollGranularity()))
         startTimerIfNeeded(delay);
 }

@@ -268,7 +268,8 @@ void Scrollbar::moveThumb(int pos)

     if (delta) {
         float newPosition = static_cast<float>(thumbPos + delta) * maximum() / (trackLen - thumbLen);
-        scrollableArea()->scrollToOffsetWithoutAnimation(m_orientation, newPosition);
+        if (m_scrollableArea)
+            m_scrollableArea->scrollToOffsetWithoutAnimation(m_orientation, newPosition);
     }
 }

@@ -300,9 +301,10 @@ void Scrollbar::setPressedPart(ScrollbarPart part)
