{"sha": "e7d5768803d8eb02a9d2fbab86031978497e7aaf", "filename": "base/pickle.cc", "status": "modified", "additions": 3, "deletions": 0, "changes": 3, "blob_url": "https://github.com/chromium/chromium/blob/137d237f941001695681ed5628a20dec84cd3b86/base/pickle.cc", "raw_url": "https://github.com/chromium/chromium/raw/137d237f941001695681ed5628a20dec84cd3b86/base/pickle.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/base/pickle.cc?ref=137d237f941001695681ed5628a20dec84cd3b86", "patch": "@@ -406,6 +406,9 @@ const char* Pickle::FindNext(size_t header_size,
   DCHECK(header_size == AlignInt(header_size, sizeof(uint32)));
   DCHECK(header_size <= static_cast<size_t>(kPayloadUnit));

+  if (static_cast<size_t>(end - start) < sizeof(Header))
