   const char* payload_end = payload_base + hdr->payload_size;"}<_**next**_>{"sha": "498ce95eaf56242990b1cae1a035dc63ca9f7e88", "filename": "base/pickle.h", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/137d237f941001695681ed5628a20dec84cd3b86/base/pickle.h", "raw_url": "https://github.com/chromium/chromium/raw/137d237f941001695681ed5628a20dec84cd3b86/base/pickle.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/base/pickle.h?ref=137d237f941001695681ed5628a20dec84cd3b86", "patch": "@@ -236,6 +236,7 @@ class Pickle {

   FRIEND_TEST_ALL_PREFIXES(PickleTest, Resize);
   FRIEND_TEST_ALL_PREFIXES(PickleTest, FindNext);
+  FRIEND_TEST_ALL_PREFIXES(PickleTest, FindNextWithIncompleteHeader);
   FRIEND_TEST_ALL_PREFIXES(PickleTest, IteratorHasRoom);
 };
 "}<_**next**_>{"sha": "39eaa1bb7936525d2ad7d685f21f09df449b3c69", "filename": "base/pickle_unittest.cc", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/137d237f941001695681ed5628a20dec84cd3b86/base/pickle_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/137d237f941001695681ed5628a20dec84cd3b86/base/pickle_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/base/pickle_unittest.cc?ref=137d237f941001695681ed5628a20dec84cd3b86", "patch": "@@ -171,6 +171,17 @@ TEST(PickleTest, FindNext) {
   EXPECT_TRUE(end == Pickle::FindNext(pickle.header_size_, start, end + 1));
 }

+TEST(PickleTest, FindNextWithIncompleteHeader) {
+  size_t header_size = sizeof(Pickle::Header);
+  scoped_array<char> buffer(new char[header_size - 1]);
+  memset(buffer.get(), 0x1, header_size - 1);
+
+  const char* start = buffer.get();
+  const char* end = start + header_size - 1;
+
+  EXPECT_TRUE(NULL == Pickle::FindNext(header_size, start, end));
+}
+
 TEST(PickleTest, IteratorHasRoom) {
   Pickle pickle;
   EXPECT_TRUE(pickle.WriteInt(1));"}

