{"sha": "d48bd362a8bf6517890cc651683a48fc1d09f8e2", "filename": "chrome/browser/ui/browser.cc", "status": "modified", "additions": 29, "deletions": 13, "changes": 42, "blob_url": "https://github.com/chromium/chromium/blob/08f0d612f2a4039aaf6733d4e8d0a67614941378/chrome/browser/ui/browser.cc", "raw_url": "https://github.com/chromium/chromium/raw/08f0d612f2a4039aaf6733d4e8d0a67614941378/chrome/browser/ui/browser.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/ui/browser.cc?ref=08f0d612f2a4039aaf6733d4e8d0a67614941378", "patch": "@@ -2847,7 +2847,7 @@ void Browser::CloseContents(TabContents* source) {
     // waiting for unload to fire. Don't actually try to close the tab as it
     // will go down the slow shutdown path instead of the fast path of killing
     // all the renderer processes.
-    ClearUnloadState(source);
+    ClearUnloadState(source, true);
     return;
   }

@@ -3208,12 +3208,10 @@ void Browser::Observe(NotificationType type,
   switch (type.value) {
     case NotificationType::TAB_CONTENTS_DISCONNECTED:
       if (is_attempting_to_close_browser_) {
-        // Need to do this asynchronously as it will close the tab, which is
-        // currently on the call stack above us.
-        MessageLoop::current()->PostTask(
-            FROM_HERE,
-            method_factory_.NewRunnableMethod(&Browser::ClearUnloadState,
-                Source<TabContents>(source).ptr()));
+        // Pass in false so that we delay processing. We need to delay the
+        // processing as it may close the tab, which is currently on the call
+        // stack above us.
+        ClearUnloadState(Source<TabContents>(source).ptr(), false);
       }
