-
-  // Layout the icon and text.
-  gfx::Size icon_ps = icon_->GetPreferredSize();
-  icon_->SetBounds(kHorizontalPadding, OffsetY(this, icon_ps), icon_ps.width(),
-                   icon_ps.height());
-
-  gfx::Size text_ps = label_->GetPreferredSize();
-  int text_width = std::min(
-      text_ps.width(),
