-ConfirmInfoBarDelegate* ConfirmInfoBar::GetDelegate() {
-  return delegate()->AsConfirmInfoBarDelegate();
-}
-
-void ConfirmInfoBar::Init() {
-  AddChildView(ok_button_);
-  AddChildView(cancel_button_);
-  AddChildView(link_);
-}
