{"sha": "a2966ff36e0ec60adc72df5e8f9f41c596166e93", "filename": "gpu/command_buffer/service/gles2_cmd_decoder.cc", "status": "modified", "additions": 19, "deletions": 0, "changes": 19, "blob_url": "https://github.com/chromium/chromium/blob/74c1ec481b33194dc7a428f2d58fc89640b313ae/gpu/command_buffer/service/gles2_cmd_decoder.cc", "raw_url": "https://github.com/chromium/chromium/raw/74c1ec481b33194dc7a428f2d58fc89640b313ae/gpu/command_buffer/service/gles2_cmd_decoder.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/gpu/command_buffer/service/gles2_cmd_decoder.cc?ref=74c1ec481b33194dc7a428f2d58fc89640b313ae", "patch": "@@ -2972,6 +2972,25 @@ void GLES2DecoderImpl::DoGetFramebufferAttachmentParameteriv(
     return;
   }
   glGetFramebufferAttachmentParameterivEXT(target, attachment, pname, params);
+  if (pname == GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME) {
+    GLint type = 0;
+    GLuint client_id = 0;
+    glGetFramebufferAttachmentParameterivEXT(
+        target, attachment, GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE, &type);
+    switch (type) {
+      case GL_RENDERBUFFER: {
+        renderbuffer_manager()->GetClientId(*params, &client_id);
+        break;
+      }
+      case GL_TEXTURE: {
+        texture_manager()->GetClientId(*params, &client_id);
+        break;
+      }
+      default:
+        break;
+    }
+    *params = client_id;
+  }
 }

