{"sha": "8c29f7c75c2bad785d6e231b1382ca01c4b0e55e", "filename": "webkit/plugins/ppapi/ppb_url_loader_impl.cc", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/a75c45bf1cad925548a75bf88f828443bc8ee27d/webkit/plugins/ppapi/ppb_url_loader_impl.cc", "raw_url": "https://github.com/chromium/chromium/raw/a75c45bf1cad925548a75bf88f828443bc8ee27d/webkit/plugins/ppapi/ppb_url_loader_impl.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/webkit/plugins/ppapi/ppb_url_loader_impl.cc?ref=a75c45bf1cad925548a75bf88f828443bc8ee27d", "patch": "@@ -85,6 +85,12 @@ PPB_URLLoader_Impl::PPB_URLLoader_Impl(PP_Instance instance,
 }

 PPB_URLLoader_Impl::~PPB_URLLoader_Impl() {
+  // There is a path whereby the destructor for the loader_ member can
+  // invoke InstanceWasDeleted() upon this PPB_URLLoader_Impl, thereby
+  // re-entering the scoped_ptr destructor with the same scoped_ptr object
+  // via loader_.reset(). Be sure that loader_ is first NULL then destroy
+  // the scoped_ptr. See http://crbug.com/159429.
+  scoped_ptr<WebKit::WebURLLoader> for_destruction_only(loader_.release());
 }

 PPB_URLLoader_API* PPB_URLLoader_Impl::AsPPB_URLLoader_API() {"}

