{"sha": "e86ccaede0d8cf29f508d71c6a58dbe80844c1c2", "filename": "content/browser/child_process_security_policy_impl.cc", "status": "modified", "additions": 11, "deletions": 2, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/8083841913b8eb8018ae52f67c923f0b3d66c466/content/browser/child_process_security_policy_impl.cc", "raw_url": "https://github.com/chromium/chromium/raw/8083841913b8eb8018ae52f67c923f0b3d66c466/content/browser/child_process_security_policy_impl.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/child_process_security_policy_impl.cc?ref=8083841913b8eb8018ae52f67c923f0b3d66c466", "patch": "@@ -148,9 +148,18 @@ class ChildProcessSecurityPolicyImpl::SecurityState {
   bool HasPermissionsForFile(const FilePath& file, int permissions) {
     FilePath current_path = file.StripTrailingSeparators();
     FilePath last_path;
+    int skip = 0;
     while (current_path != last_path) {
-      if (file_permissions_.find(current_path) != file_permissions_.end())
-        return (file_permissions_[current_path] & permissions) == permissions;
+      FilePath base_name =  current_path.BaseName();
+      if (base_name.value() == FilePath::kParentDirectory) {
+        ++skip;
+      } else if (skip > 0) {
+        if (base_name.value() != FilePath::kCurrentDirectory)
+          --skip;
+      } else {
+        if (file_permissions_.find(current_path) != file_permissions_.end())
+          return (file_permissions_[current_path] & permissions) == permissions;
+      }
       last_path = current_path;
       current_path = current_path.DirName();
     }"}<_**next**_>{"sha": "90befd6d8aae9587de14c67cbef773c03d6b356b", "filename": "content/browser/child_process_security_policy_unittest.cc", "status": "modified", "additions": 70, "deletions": 28, "changes": 98, "blob_url": "https://github.com/chromium/chromium/blob/8083841913b8eb8018ae52f67c923f0b3d66c466/content/browser/child_process_security_policy_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/8083841913b8eb8018ae52f67c923f0b3d66c466/content/browser/child_process_security_policy_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/child_process_security_policy_unittest.cc?ref=8083841913b8eb8018ae52f67c923f0b3d66c466", "patch": "@@ -347,100 +347,142 @@ TEST_F(ChildProcessSecurityPolicyTest, CanReadDirectories) {
