{"sha": "f91edcf873899bdd91ae48c0455de31815fefad1", "filename": "third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle-expected.txt", "status": "added", "additions": 3, "deletions": 0, "changes": 3, "blob_url": "https://github.com/chromium/chromium/blob/30afcc0242bd789a7b67e1ca8fe829640279a3cf/third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/30afcc0242bd789a7b67e1ca8fe829640279a3cf/third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle-expected.txt?ref=30afcc0242bd789a7b67e1ca8fe829640279a3cf", "patch": "@@ -0,0 +1,3 @@
+This page should be scrollable
+PASS
+"}<_**next**_>{"sha": "94273b34535d1c39cf8081c74d1c6edc59812e91", "filename": "third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle.html", "status": "added", "additions": 41, "deletions": 0, "changes": 41, "blob_url": "https://github.com/chromium/chromium/blob/30afcc0242bd789a7b67e1ca8fe829640279a3cf/third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle.html", "raw_url": "https://github.com/chromium/chromium/raw/30afcc0242bd789a7b67e1ca8fe829640279a3cf/third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/scrollbars/scrollbar-large-overflow-rectangle.html?ref=30afcc0242bd789a7b67e1ca8fe829640279a3cf", "patch": "@@ -0,0 +1,41 @@
+<!DOCTYPE html>
+<html>
+    <head>
+    <title>absolute positioned element with large negative top value inside tall relative positioned box does not render scrollbars</title>
+        <style>
+            body, p{
+              margin:0;
+            }
+            div{
+                position: relative;
+                height:3000px;
+            }
+            span{
+                position: absolute;
+                top:-3355400000px;
+            }
+        </style>
+        <script>
+            if (window.testRunner) {
+                testRunner.dumpAsText();
+            }
+            
+            function test() {
+              var height = document.body.scrollHeight;
+              if (height == 3000)
+                document.getElementById("result").innerHTML = "PASS";
+              else
+                document.getElementById("result").innerHTML = "<p style='color:red'>FAIL document.body.scrollHeight = " + height +"</p>";
+              }
+        </script> 
+    </head>
+    
+    <body onload="test()">
+    <div>
+      <p> This page should be scrollable </p>
+      <p id="result"> </p>
+      <span style="visibility:hidden">filler <!--abs pos with very large negative top value--></span>
+    </div>
+   
+    </body>
+</html>"}<_**next**_>{"sha": "49ad02a01414159bb732ee0e650ef8bb19de626e", "filename": "third_party/WebKit/Source/core/rendering/RenderOverflow.h", "status": "modified", "additions": 7, "deletions": 4, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/30afcc0242bd789a7b67e1ca8fe829640279a3cf/third_party/WebKit/Source/core/rendering/RenderOverflow.h", "raw_url": "https://github.com/chromium/chromium/raw/30afcc0242bd789a7b67e1ca8fe829640279a3cf/third_party/WebKit/Source/core/rendering/RenderOverflow.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/rendering/RenderOverflow.h?ref=30afcc0242bd789a7b67e1ca8fe829640279a3cf", "patch": "@@ -91,10 +91,13 @@ inline void RenderOverflow::addLayoutOverflow(const LayoutRect& rect)
 {
     LayoutUnit maxX = std::max(rect.maxX(), m_layoutOverflow.maxX());
     LayoutUnit maxY = std::max(rect.maxY(), m_layoutOverflow.maxY());
-    m_layoutOverflow.setX(std::min(rect.x(), m_layoutOverflow.x()));
-    m_layoutOverflow.setY(std::min(rect.y(), m_layoutOverflow.y()));
-    m_layoutOverflow.setWidth(maxX - m_layoutOverflow.x());
-    m_layoutOverflow.setHeight(maxY - m_layoutOverflow.y());
+    LayoutUnit minX = std::min(rect.x(), m_layoutOverflow.x());
+    LayoutUnit minY = std::min(rect.y(), m_layoutOverflow.y());
+    // In case the width/height is larger than LayoutUnit can represent, fix the right/bottom edge and shift the top/left ones
+    m_layoutOverflow.setWidth(maxX - minX);
+    m_layoutOverflow.setHeight(maxY - minY);
+    m_layoutOverflow.setX(maxX - m_layoutOverflow.width());
+    m_layoutOverflow.setY(maxY - m_layoutOverflow.height());
 }

 inline void RenderOverflow::addVisualOverflow(const LayoutRect& rect)"}

