{"sha": "eaba1f39371afb100c728a1ee78f5d5da45027ea", "filename": "third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null-expected.txt", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/7fa8bd35982700cb2cb6ce22d05128c019a2b587/third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/7fa8bd35982700cb2cb6ce22d05128c019a2b587/third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null-expected.txt?ref=7fa8bd35982700cb2cb6ce22d05128c019a2b587", "patch": "@@ -0,0 +1,12 @@
+Check if an option is removed when it is assigned null.
+
+On success, you will see a series of "PASS" messages, followed by "TEST COMPLETE".
+
+
+PASS tags.options.length is 2
+PASS tags.options.length is 1
+PASS tags.options.length is 2
+PASS successfullyParsed is true
+
+TEST COMPLETE
+"}<_**next**_>{"sha": "441d535f3b4ca7c2e0df343f630e12359bf75700", "filename": "third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null.html", "status": "added", "additions": 24, "deletions": 0, "changes": 24, "blob_url": "https://github.com/chromium/chromium/blob/7fa8bd35982700cb2cb6ce22d05128c019a2b587/third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null.html", "raw_url": "https://github.com/chromium/chromium/raw/7fa8bd35982700cb2cb6ce22d05128c019a2b587/third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/forms/select/select-assign-null.html?ref=7fa8bd35982700cb2cb6ce22d05128c019a2b587", "patch": "@@ -0,0 +1,24 @@
+<!DOCTYPE html>
+<html>
+<head>
+<script src="../../js/resources/js-test-pre.js"></script>
+</head>
+<body>
+<select id="tags">
+<option selected="selected" value="marquee">marquee</option>
+<option value="blink">blink</option>
+</select>
+<script>
+description('Check if an option is removed when it is assigned null.');
+var tags = document.getElementById('tags');
+shouldBe("tags.options.length", "2");
+
+tags[0] = null;
+shouldBe("tags.options.length", "1");
+
+tags[tags.length] = new Option("bgsound", "bgsound");
+shouldBe("tags.options.length", "2");
+</script>
+<script src="../../js/resources/js-test-post.js"></script>
+</body>
+</html>"}<_**next**_>{"sha": "694c7ba19554ea6401fd3850d6414d562a5aeeaa", "filename": "third_party/WebKit/Source/core/html/HTMLSelectElement.cpp", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/7fa8bd35982700cb2cb6ce22d05128c019a2b587/third_party/WebKit/Source/core/html/HTMLSelectElement.cpp", "raw_url": "https://github.com/chromium/chromium/raw/7fa8bd35982700cb2cb6ce22d05128c019a2b587/third_party/WebKit/Source/core/html/HTMLSelectElement.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/html/HTMLSelectElement.cpp?ref=7fa8bd35982700cb2cb6ce22d05128c019a2b587", "patch": "@@ -1579,4 +1579,10 @@ bool HTMLSelectElement::anonymousIndexedSetter(unsigned index, PassRefPtr<HTMLOp
