   WebKit::WebMouseEvent mouse_event;
   mouse_event.type = WebKit::WebInputEvent::MouseDown;
   mouse_event.button = WebKit::WebMouseEvent::ButtonLeft;
@@ -637,6 +639,66 @@ void SimulateMouseClick(content::WebContents* tab, int x, int y) {
   tab->GetRenderViewHost()->ForwardMouseEvent(mouse_event);
 }

+void BuildSimpleWebKeyEvent(WebKit::WebInputEvent::Type type,
+                            ui::KeyboardCode key,
+                            bool control,
+                            bool shift,
+                            bool alt,
+                            bool command,
+                            NativeWebKeyboardEvent* event) {
+  event->nativeKeyCode = 0;
+  event->windowsKeyCode = key;
+  event->setKeyIdentifierFromWindowsKeyCode();
+  event->type = type;
+  event->modifiers = 0;
+  event->isSystemKey = false;
+  event->timeStampSeconds = base::Time::Now().ToDoubleT();
+  event->skip_in_browser = true;
+
+  if (type == WebKit::WebInputEvent::Char ||
+      type == WebKit::WebInputEvent::RawKeyDown) {
+    event->text[0] = key;
+    event->unmodifiedText[0] = key;
+  }
+
+  if (control)
+    event->modifiers |= WebKit::WebInputEvent::ControlKey;
+
+  if (shift)
+    event->modifiers |= WebKit::WebInputEvent::ShiftKey;
+
+  if (alt)
+    event->modifiers |= WebKit::WebInputEvent::AltKey;
+
+  if (command)
+    event->modifiers |= WebKit::WebInputEvent::MetaKey;
+}
+
+void SimulateKeyPress(content::WebContents* tab,
+                      ui::KeyboardCode key,
+                      bool control,
+                      bool shift,
+                      bool alt,
+                      bool command) {
+  NativeWebKeyboardEvent event_down;
+  BuildSimpleWebKeyEvent(
+      WebKit::WebInputEvent::RawKeyDown, key, control, shift, alt, command,
+      &event_down);
+  tab->GetRenderViewHost()->ForwardKeyboardEvent(event_down);
+
+  NativeWebKeyboardEvent char_event;
+  BuildSimpleWebKeyEvent(
+      WebKit::WebInputEvent::Char, key, control, shift, alt, command,
+      &char_event);
+  tab->GetRenderViewHost()->ForwardKeyboardEvent(char_event);
+
+  NativeWebKeyboardEvent event_up;
+  BuildSimpleWebKeyEvent(
+      WebKit::WebInputEvent::KeyUp, key, control, shift, alt, command,
+      &event_up);
+  tab->GetRenderViewHost()->ForwardKeyboardEvent(event_up);
+}
+
 void RegisterAndWait(content::NotificationObserver* observer,
                      int type,
                      const content::NotificationSource& source) {"}<_**next**_>{"sha": "9b020385fe93e3f10bc5d87f5fcf2a59180a23cf", "filename": "chrome/test/base/ui_test_utils.h", "status": "modified", "additions": 11, "deletions": 2, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/2511466dd15750f2ab0e5cecc30010f0a3f7949c/chrome/test/base/ui_test_utils.h", "raw_url": "https://github.com/chromium/chromium/raw/2511466dd15750f2ab0e5cecc30010f0a3f7949c/chrome/test/base/ui_test_utils.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/base/ui_test_utils.h?ref=2511466dd15750f2ab0e5cecc30010f0a3f7949c", "patch": "@@ -218,9 +218,18 @@ int FindInPage(TabContentsWrapper* tab,
