+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/browser/autocomplete/autocomplete_provider.h"
+
+#include "base/logging.h"
+#include "base/utf_string_conversions.h"
+#include "chrome/browser/autocomplete/autocomplete_match.h"
+#include "chrome/browser/autocomplete/autocomplete_provider_listener.h"
+#include "chrome/browser/bookmarks/bookmark_model.h"
+#include "chrome/browser/prefs/pref_service.h"
+#include "chrome/browser/profiles/profile.h"
+#include "chrome/common/pref_names.h"
+#include "content/public/common/url_constants.h"
+#include "googleurl/src/gurl.h"
+#include "googleurl/src/url_util.h"
+#include "net/base/net_util.h"
+
+// static
+const size_t AutocompleteProvider::kMaxMatches = 3;
+
+AutocompleteProvider::AutocompleteProvider(
+    AutocompleteProviderListener* listener,
+    Profile* profile,
+    const char* name)
+    : profile_(profile),
+      listener_(listener),
+      done_(true),
+      name_(name) {
+}
+
+void AutocompleteProvider::Stop() {
+  done_ = true;
+}
+
+metrics::OmniboxEventProto_ProviderType AutocompleteProvider::
+    AsOmniboxEventProviderType() const {
+  if (name_ == "HistoryURL")
+    return metrics::OmniboxEventProto::HISTORY_URL;
+  if (name_ == "HistoryContents")
+    return metrics::OmniboxEventProto::HISTORY_CONTENTS;
+  if (name_ == "HistoryQuickProvider")
+    return metrics::OmniboxEventProto::HISTORY_QUICK;
+  if (name_ == "Search")
+    return metrics::OmniboxEventProto::SEARCH;
+  if (name_ == "Keyword")
+    return metrics::OmniboxEventProto::KEYWORD;
+  if (name_ == "Builtin")
+    return metrics::OmniboxEventProto::BUILTIN;
+  if (name_ == "ShortcutsProvider")
+    return metrics::OmniboxEventProto::SHORTCUTS;
+  if (name_ == "ExtensionApps")
+    return metrics::OmniboxEventProto::EXTENSION_APPS;
+
+  NOTREACHED();
+  return metrics::OmniboxEventProto::UNKNOWN_PROVIDER;
+}
+
+void AutocompleteProvider::DeleteMatch(const AutocompleteMatch& match) {
+  DLOG(WARNING) << "The AutocompleteProvider '" << name_
+                << "' has not implemented DeleteMatch.";
+}
+
+void AutocompleteProvider::AddProviderInfo(ProvidersInfo* provider_info) const {
+}
+
+string16 AutocompleteProvider::StringForURLDisplay(const GURL& url,
+                                                   bool check_accept_lang,
+                                                   bool trim_http) const {
+  std::string languages = (check_accept_lang && profile_) ?
+      profile_->GetPrefs()->GetString(prefs::kAcceptLanguages) : std::string();
+  return net::FormatUrl(url, languages,
+      net::kFormatUrlOmitAll & ~(trim_http ? 0 : net::kFormatUrlOmitHTTP),
+      net::UnescapeRule::SPACES, NULL, NULL, NULL);
+}
+
+AutocompleteProvider::~AutocompleteProvider() {
+  Stop();
+}
+
+// static
+bool AutocompleteProvider::HasHTTPScheme(const string16& input) {
+  std::string utf8_input(UTF16ToUTF8(input));
+  url_parse::Component scheme;
+  if (url_util::FindAndCompareScheme(utf8_input, chrome::kViewSourceScheme,
+                                     &scheme))
+    utf8_input.erase(0, scheme.end() + 1);
+  return url_util::FindAndCompareScheme(utf8_input, chrome::kHttpScheme, NULL);
+}
+
+void AutocompleteProvider::UpdateStarredStateOfMatches() {
+  if (matches_.empty())
+    return;
+
+  if (!profile_)
+    return;
+
+  BookmarkModel* bookmark_model = profile_->GetBookmarkModel();
+  if (!bookmark_model || !bookmark_model->IsLoaded())
+    return;
+
+  for (ACMatches::iterator i(matches_.begin()); i != matches_.end(); ++i)
+    i->starred = bookmark_model->IsBookmarked(i->destination_url);
+}"}<_**next**_>{"sha": "fce9918d61996d59a427fe272221baac6ab4ac2f", "filename": "chrome/browser/autocomplete/autocomplete_provider.h", "status": "added", "additions": 127, "deletions": 0, "changes": 127, "blob_url": "https://github.com/chromium/chromium/blob/30f5bc981921d9c0221c82f38d80bd2d5c86a022/chrome/browser/autocomplete/autocomplete_provider.h", "raw_url": "https://github.com/chromium/chromium/raw/30f5bc981921d9c0221c82f38d80bd2d5c86a022/chrome/browser/autocomplete/autocomplete_provider.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/autocomplete/autocomplete_provider.h?ref=30f5bc981921d9c0221c82f38d80bd2d5c86a022", "patch": "@@ -0,0 +1,127 @@
+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef CHROME_BROWSER_AUTOCOMPLETE_AUTOCOMPLETE_PROVIDER_H_
+#define CHROME_BROWSER_AUTOCOMPLETE_AUTOCOMPLETE_PROVIDER_H_
+#pragma once
+
+#include <string>
+
+#include "base/basictypes.h"
+#include "base/memory/ref_counted.h"
+#include "base/string16.h"
+#include "chrome/browser/autocomplete/autocomplete_types.h"
+#include "chrome/common/metrics/proto/omnibox_event.pb.h"
+
+class AutocompleteInput;
+struct AutocompleteMatch;
+class AutocompleteProviderListener;
+class GURL;
+class Profile;
+
+// A single result provider for the autocomplete system.  Given user input, the
+// provider decides what (if any) matches to return, their relevance, and their
+// classifications.
+class AutocompleteProvider
+    : public base::RefCountedThreadSafe<AutocompleteProvider> {
+ public:
+
+  AutocompleteProvider(AutocompleteProviderListener* listener,
+                       Profile* profile,
+                       const char* name);
+
+  // Called to start an autocomplete query.  The provider is responsible for
+  // tracking its matches for this query and whether it is done processing the
+  // query.  When new matches are available or the provider finishes, it
+  // calls the controller's OnProviderUpdate() method.  The controller can then
+  // get the new matches using the provider's accessors.
+  // Exception: Matches available immediately after starting the query (that
+  // is, synchronously) do not cause any notifications to be sent.  The
+  // controller is expected to check for these without prompting (since
+  // otherwise, starting each provider running would result in a flurry of
+  // notifications).
+  //
+  // Once Stop() has been called, no more notifications should be sent.
+  //
+  // |minimal_changes| is an optimization that lets the provider do less work
+  // when the |input|'s text hasn't changed.  See the body of
+  // OmniboxPopupModel::StartAutocomplete().
+  virtual void Start(const AutocompleteInput& input, bool minimal_changes) = 0;
+
+  // Called when a provider must not make any more callbacks for the current
+  // query. This will be called regardless of whether the provider is already
+  // done.
+  virtual void Stop();
+
+  // Returns the set of matches for the current query.
+  const ACMatches& matches() const { return matches_; }
+
+  // Returns whether the provider is done processing the query.
+  bool done() const { return done_; }
+
+  // Returns the name of this provider.
+  const std::string& name() const { return name_; }
+
+  // Returns the enum equivalent to the name of this provider.
+  metrics::OmniboxEventProto_ProviderType AsOmniboxEventProviderType() const;
+
+  // Called to delete a match and the backing data that produced it.  This
+  // match should not appear again in this or future queries.  This can only be
+  // called for matches the provider marks as deletable.  This should only be
+  // called when no query is running.
+  // NOTE: Remember to call OnProviderUpdate() if matches_ is updated.
+  virtual void DeleteMatch(const AutocompleteMatch& match);
+
+  // Called when an omnibox event log entry is generated.  This gives
+  // a provider the opportunity to add diagnostic information to the
+  // logs.  A provider is expected to append a single entry of whatever
+  // information it wants to |provider_info|.
+  virtual void AddProviderInfo(ProvidersInfo* provider_info) const;
+
