{"sha": "a489a9cfa8b5fe88ddbc9aa70bdc1f09ea5fac75", "filename": "chrome/browser/resources/uber/uber.js", "status": "modified", "additions": 10, "deletions": 5, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/e01b90a445d0de6a0b9b802d4acee10c6537d26a/chrome/browser/resources/uber/uber.js", "raw_url": "https://github.com/chromium/chromium/raw/e01b90a445d0de6a0b9b802d4acee10c6537d26a/chrome/browser/resources/uber/uber.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/resources/uber/uber.js?ref=e01b90a445d0de6a0b9b802d4acee10c6537d26a", "patch": "@@ -171,12 +171,17 @@ cr.define('uber', function() {
     // Cache the title for the client iframe, i.e., the iframe setting the
     // title. querySelector returns the actual iframe element, so use parentNode
     // to get back to the container.
-    var container = document.querySelector(query).parentNode;
-    container.title = title;
+    var iframe = document.querySelector(query);

-    // Only update the currently displayed title if this is the visible frame.
-    if (container == getSelectedIframe())
-      document.title = title;
+    // |iframe| may be null if the page has not lazy-loaded yet.
+    if (iframe) {
+      var container = iframe.parentNode;
+      container.title = title;
+
+      // Only update the currently displayed title if this is the visible frame.
+      if (container == getSelectedIframe())
+        document.title = title;
+    }
