{"sha": "fbacc95f38366fb040026ac47b7c645e51a3bb9f", "filename": "third_party/WebKit/Tools/ChangeLog", "status": "modified", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/b7a161633fd7ecb59093c2c56ed908416292d778/third_party/WebKit/Tools/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/b7a161633fd7ecb59093c2c56ed908416292d778/third_party/WebKit/Tools/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Tools/ChangeLog?ref=b7a161633fd7ecb59093c2c56ed908416292d778", "patch": "@@ -1,3 +1,18 @@
+2012-11-21  Zan Dobersek  <zandobersek@gmail.com>
