+        (WTR::AccessibilityUIElement::stringValue):
+
 2012-11-21  Vineet Chaudhary  <rgf748@motorola.com>

         Unreviewed. Adding myself to committers.py."}<_**next**_>{"sha": "0bfe9ac96fce9bf767d6b33991ac8d47726740ab", "filename": "third_party/WebKit/Tools/WebKitTestRunner/InjectedBundle/atk/AccessibilityUIElementAtk.cpp", "status": "modified", "additions": 27, "deletions": 2, "changes": 29, "blob_url": "https://github.com/chromium/chromium/blob/b7a161633fd7ecb59093c2c56ed908416292d778/third_party/WebKit/Tools/WebKitTestRunner/InjectedBundle/atk/AccessibilityUIElementAtk.cpp", "raw_url": "https://github.com/chromium/chromium/raw/b7a161633fd7ecb59093c2c56ed908416292d778/third_party/WebKit/Tools/WebKitTestRunner/InjectedBundle/atk/AccessibilityUIElementAtk.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Tools/WebKitTestRunner/InjectedBundle/atk/AccessibilityUIElementAtk.cpp?ref=b7a161633fd7ecb59093c2c56ed908416292d778", "patch": "@@ -35,6 +35,9 @@
 #include <wtf/Assertions.h>
 #include <wtf/gobject/GOwnPtr.h>
 #include <wtf/gobject/GRefPtr.h>
+#include <wtf/text/CString.h>
+#include <wtf/text/WTFString.h>
+#include <wtf/unicode/CharacterNames.h>

 namespace WTR {

@@ -121,6 +124,22 @@ static void alterCurrentValue(PlatformUIElement element, int factor)
     g_value_unset(&currentValue);
 }

+static gchar* replaceCharactersForResults(gchar* str)
+{
+    WTF::String uString = WTF::String::fromUTF8(str);
+
+    // The object replacement character is passed along to ATs so we need to be
+    // able to test for their presence and do so without causing test failures.
+    uString.replace(objectReplacementCharacter, "<obj>");
+
+    // The presence of newline characters in accessible text of a single object
+    // is appropriate, but it makes test results (especially the accessible tree)
+    // harder to read.
+    uString.replace("\n", "<\\n>");
+
+    return g_strdup(uString.utf8().data());
+}
+
 AccessibilityUIElement::AccessibilityUIElement(PlatformUIElement element)
     : m_element(element)
 {
@@ -406,8 +425,14 @@ JSRetainPtr<JSStringRef> AccessibilityUIElement::orientation() const

 JSRetainPtr<JSStringRef> AccessibilityUIElement::stringValue()
 {
-    // FIXME: implement
-    return JSStringCreateWithCharacters(0, 0);
+    if (!m_element || !ATK_IS_TEXT(m_element))
+        return JSStringCreateWithCharacters(0, 0);
+
+    GOwnPtr<gchar> text(atk_text_get_text(ATK_TEXT(m_element), 0, -1));
+    GOwnPtr<gchar> textWithReplacedCharacters(replaceCharactersForResults(text.get()));
+    GOwnPtr<gchar> axValue(g_strdup_printf("AXValue: %s", textWithReplacedCharacters.get()));
+
+    return JSStringCreateWithUTF8CString(axValue.get());
 }

 JSRetainPtr<JSStringRef> AccessibilityUIElement::language()"}

{"sha": "625ce12bfde4a024563113ebf30381bbe5ed156c", "filename": "webkit/plugins/ppapi/ppb_url_loader_impl.cc", "status": "modified", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/9ce8793d2a8ca2cc0cb3c26fa1ca0eef3d9bc999/webkit/plugins/ppapi/ppb_url_loader_impl.cc", "raw_url": "https://github.com/chromium/chromium/raw/9ce8793d2a8ca2cc0cb3c26fa1ca0eef3d9bc999/webkit/plugins/ppapi/ppb_url_loader_impl.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/webkit/plugins/ppapi/ppb_url_loader_impl.cc?ref=9ce8793d2a8ca2cc0cb3c26fa1ca0eef3d9bc999", "patch": "@@ -390,6 +390,8 @@ void PPB_URLLoader_Impl::SetDefersLoading(bool defers_loading) {

 void PPB_URLLoader_Impl::FinishLoading(int32_t done_status) {
   done_status_ = done_status;
+  user_buffer_ = NULL;
+  user_buffer_size_ = 0;
   // If the client hasn't called any function that takes a callback since
   // the initial call to Open, or called ReadResponseBody and got a
   // synchronous return, then the callback will be NULL.
@@ -424,6 +426,10 @@ void PPB_URLLoader_Impl::RunCallback(int32_t result) {
     CHECK(main_document_loader_);
     return;
   }
+
+  // If |user_buffer_| was set as part of registering the callback, ensure
+  // it got cleared since the callback is now free to delete it.
+  DCHECK(!user_buffer_);
   TrackedCallback::ClearAndRun(&pending_callback_, result);
 }
