+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "sync/notifier/fake_invalidation_state_tracker.h"
+
+#include "testing/gtest/include/gtest/gtest.h"
+
+namespace syncer {
+
+const int64 FakeInvalidationStateTracker::kMinVersion = kint64min;
+
+FakeInvalidationStateTracker::FakeInvalidationStateTracker() {}
+
+FakeInvalidationStateTracker::~FakeInvalidationStateTracker() {}
+
+InvalidationVersionMap
+FakeInvalidationStateTracker::GetAllMaxVersions() const {
+  return versions_;
+}
+
+void FakeInvalidationStateTracker::SetMaxVersion(
+    const invalidation::ObjectId& id, int64 max_version) {
+  InvalidationVersionMap::const_iterator it = versions_.find(id);
+  if ((it != versions_.end()) && (max_version <= it->second)) {
+    ADD_FAILURE();
+    return;
+  }
+  versions_[id] = max_version;
+}
+
+int64 FakeInvalidationStateTracker::GetMaxVersion(
+    const invalidation::ObjectId& id) const {
+  InvalidationVersionMap::const_iterator it = versions_.find(id);
+  return (it == versions_.end()) ? kMinVersion : it->second;
+}
+
+void FakeInvalidationStateTracker::SetInvalidationState(
+    const std::string& state) {
+  state_ = state;
+}
+
+std::string FakeInvalidationStateTracker::GetInvalidationState() const {
+  return state_;
+}
+
+}  // namespace syncer"}<_**next**_>{"sha": "4186f70fe9f8ca8f575ca3b8c72fa647216b6999", "filename": "sync/notifier/fake_invalidation_state_tracker.h", "status": "added", "additions": 39, "deletions": 0, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/8a50f99c25fb70ff43aaa82b6f9569db383f0ca8/sync/notifier/fake_invalidation_state_tracker.h", "raw_url": "https://github.com/chromium/chromium/raw/8a50f99c25fb70ff43aaa82b6f9569db383f0ca8/sync/notifier/fake_invalidation_state_tracker.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/sync/notifier/fake_invalidation_state_tracker.h?ref=8a50f99c25fb70ff43aaa82b6f9569db383f0ca8", "patch": "@@ -0,0 +1,39 @@
