+// found in the LICENSE file.
+
+// We're just testing that multiple scripts get added to a page in-order
+// and are run.
+chrome.test.assertEq("hi!", test);
+
+// Also test the injection point is consistent. We want to inject into body
+// because having a document.body element is convenient for some scripts.
+var scripts = document.querySelectorAll("script");
+chrome.test.assertEq(2, scripts.length);
+for (var i = 0, script; script = scripts[i]; i++) {
+  chrome.test.assertEq("BODY", script.parentElement.nodeName);
+}
+
+chrome.test.notifyPass();"}<_**next**_>{"sha": "ea6573eeb0c0f774914e7f491b302850bea5fd4b", "filename": "chrome/test/data/extensions/api_test/background_scripts/manifest.json", "status": "added", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/chromium/chromium/blob/a03d4448faf2c40f4ef444a88cb9aace5b98e8c4/chrome/test/data/extensions/api_test/background_scripts/manifest.json", "raw_url": "https://github.com/chromium/chromium/raw/a03d4448faf2c40f4ef444a88cb9aace5b98e8c4/chrome/test/data/extensions/api_test/background_scripts/manifest.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/background_scripts/manifest.json?ref=a03d4448faf2c40f4ef444a88cb9aace5b98e8c4", "patch": "@@ -0,0 +1,9 @@
