{"sha": "913f30ba6d2800bfc794f91b07b6ee04bf2e4a3a", "filename": "third_party/WebKit/Source/WebKit2/ChangeLog", "status": "modified", "additions": 23, "deletions": 0, "changes": 23, "blob_url": "https://github.com/chromium/chromium/blob/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Source/WebKit2/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Source/WebKit2/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/ChangeLog?ref=89e4098439f73cb5c16996511cbfdb171a26e173", "patch": "@@ -1,3 +1,26 @@
+2012-08-03  Hugo Parente Lima  <hugo.lima@openbossa.org>
+
+        [Qt][WK2] There's no way to test the gesture tap on WTR
+        https://bugs.webkit.org/show_bug.cgi?id=92895
+
+        Reviewed by Kenneth Rohde Christiansen.
+
+        Add an instance of QtViewportHandler to QQuickWebViewPrivate, so it's
+        now available on mobile and desktop modes, as a side effect gesture tap
+        events can now be created and sent to WebCore.
+
+        This is needed to test tap gestures and to get tap gestures working
+        when you have a WebView (in desktop mode) on notebooks equipped with
+        touch screens.
+
+        * UIProcess/API/qt/qquickwebview.cpp:
+        (QQuickWebViewPrivate::onComponentComplete):
+        (QQuickWebViewFlickablePrivate::onComponentComplete): Implementation
+        moved to QQuickWebViewPrivate::onComponentComplete.
+        * UIProcess/API/qt/qquickwebview_p_p.h:
+        (QQuickWebViewPrivate):
+        (QQuickWebViewFlickablePrivate):
+
 2012-08-02  Alexey Proskuryakov  <ap@apple.com>

         [WK2] Move some WebContext messages to WebProcessProxy"}<_**next**_>{"sha": "82a7009e2fd7dc6324fcc1f3c8bd02ac7a0b77ee", "filename": "third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp", "status": "modified", "additions": 8, "deletions": 4, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp", "raw_url": "https://github.com/chromium/chromium/raw/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview.cpp?ref=89e4098439f73cb5c16996511cbfdb171a26e173", "patch": "@@ -321,6 +321,13 @@ void QQuickWebViewPrivate::initialize(WKContextRef contextRef, WKPageGroupRef pa
     webPageProxy->initializeWebPage();
 }

+void QQuickWebViewPrivate::onComponentComplete()
+{
+    Q_Q(QQuickWebView);
+    m_viewportHandler.reset(new QtViewportHandler(webPageProxy.get(), q, pageView.data()));
+    pageView->eventHandler()->setViewportHandler(m_viewportHandler.data());
+}
+
 void QQuickWebViewPrivate::setTransparentBackground(bool enable)
 {
     webPageProxy->setDrawsTransparentBackground(enable);
@@ -852,10 +859,7 @@ void QQuickWebViewFlickablePrivate::initialize(WKContextRef contextRef, WKPageGr

 void QQuickWebViewFlickablePrivate::onComponentComplete()
 {
-    Q_Q(QQuickWebView);
-
-    m_viewportHandler.reset(new QtViewportHandler(webPageProxy.get(), q, pageView.data()));
-    pageView->eventHandler()->setViewportHandler(m_viewportHandler.data());
+    QQuickWebViewPrivate::onComponentComplete();

     // Trigger setting of correct visibility flags after everything was allocated and initialized.
     _q_onVisibleChanged();"}<_**next**_>{"sha": "78adfb385946952aa7dc83eafa07ea5a3c370e3d", "filename": "third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview_p_p.h", "status": "modified", "additions": 2, "deletions": 4, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview_p_p.h", "raw_url": "https://github.com/chromium/chromium/raw/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview_p_p.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/WebKit2/UIProcess/API/qt/qquickwebview_p_p.h?ref=89e4098439f73cb5c16996511cbfdb171a26e173", "patch": "@@ -69,7 +69,7 @@ class QQuickWebViewPrivate {

     virtual void initialize(WKContextRef contextRef = 0, WKPageGroupRef pageGroupRef = 0);

-    virtual void onComponentComplete() { }
+    virtual void onComponentComplete();

     virtual void enableMouseEvents() { }
     virtual void disableMouseEvents() { }
@@ -175,6 +175,7 @@ class QQuickWebViewPrivate {
     QScopedPointer<QQuickWebPage> pageView;
     QQuickWebView* q_ptr;

+    QScopedPointer<WebKit::QtViewportHandler> m_viewportHandler;
     FlickableAxisLocker axisLocker;

     QQmlComponent* alertDialog;
@@ -230,9 +231,6 @@ class QQuickWebViewFlickablePrivate : public QQuickWebViewPrivate {
     virtual void pageDidRequestScroll(const QPoint& pos);
     virtual void didChangeContentsSize(const QSize& newSize);
     virtual void handleMouseEvent(QMouseEvent*);
-
-private:
-    QScopedPointer<WebKit::QtViewportHandler> m_viewportHandler;
 };

 #endif // qquickwebview_p_p_h"}<_**next**_>{"sha": "f5623d90532361300cbfbbebe2b4501a0c044032", "filename": "third_party/WebKit/Tools/ChangeLog", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Tools/ChangeLog", "raw_url": "https://github.com/chromium/chromium/raw/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Tools/ChangeLog", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Tools/ChangeLog?ref=89e4098439f73cb5c16996511cbfdb171a26e173", "patch": "@@ -1,3 +1,16 @@
+2012-08-03  Hugo Parente Lima  <hugo.lima@openbossa.org>
+
+        [Qt][WK2] There's no way to test the gesture tap on WTR
+        https://bugs.webkit.org/show_bug.cgi?id=92895
+
+        Reviewed by Kenneth Rohde Christiansen.
+
+        WTR doesn't create the QQuickItem from C++, not from QML, so a call
+        to componentComplete() was added to mimic the QML behaviour.
+
+        * WebKitTestRunner/qt/PlatformWebViewQt.cpp:
+        (WTR::PlatformWebView::PlatformWebView):
+
 2012-08-03  Balazs Kelemen  <kbalazs@webkit.org>

         Unreviewed, rolling out r124567."}<_**next**_>{"sha": "8a752a831d779099686629c1170f96a9f5a39d59", "filename": "third_party/WebKit/Tools/WebKitTestRunner/qt/PlatformWebViewQt.cpp", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Tools/WebKitTestRunner/qt/PlatformWebViewQt.cpp", "raw_url": "https://github.com/chromium/chromium/raw/89e4098439f73cb5c16996511cbfdb171a26e173/third_party/WebKit/Tools/WebKitTestRunner/qt/PlatformWebViewQt.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Tools/WebKitTestRunner/qt/PlatformWebViewQt.cpp?ref=89e4098439f73cb5c16996511cbfdb171a26e173", "patch": "@@ -77,6 +77,7 @@ PlatformWebView::PlatformWebView(WKContextRef contextRef, WKPageGroupRef pageGro
     QQuickWebViewExperimental experimental(m_view);
     experimental.setRenderToOffscreenBuffer(true);
     m_view->setAllowAnyHTTPSCertificateForLocalHost(true);
+    m_view->componentComplete();
 }

 PlatformWebView::~PlatformWebView()"}

{"sha": "08065f69529efe145b71626613a57b03bd2351f8", "filename": "net/http/http_cache_unittest.cc", "status": "modified", "additions": 13, "deletions": 5, "changes": 18, "blob_url": "https://github.com/chromium/chromium/blob/9f4633c617ef393ba4709cba7d8fa23101b64025/net/http/http_cache_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/9f4633c617ef393ba4709cba7d8fa23101b64025/net/http/http_cache_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/http/http_cache_unittest.cc?ref=9f4633c617ef393ba4709cba7d8fa23101b64025", "patch": "@@ -4046,24 +4046,32 @@ TEST(HttpCache, GET_IncompleteResource_Cancel) {
   int rv = cache.http_cache()->CreateTransaction(&c->trans);
   EXPECT_EQ(net::OK, rv);

+  // Queue another request to this transaction. We have to start this request
+  // before the first one gets the response from the server and dooms the entry,
+  // otherwise it will just create a new entry without being queued to the first
+  // request.
+  Context* pending = new Context();
+  EXPECT_EQ(net::OK, cache.http_cache()->CreateTransaction(&pending->trans));
+
   rv = c->trans->Start(&request, c->callback.callback(), net::BoundNetLog());
+  EXPECT_EQ(net::ERR_IO_PENDING,
+            pending->trans->Start(&request, pending->callback.callback(),
+                                  net::BoundNetLog()));
   EXPECT_EQ(net::OK, c->callback.GetResult(rv));

   // Make sure that the entry has some data stored.
   scoped_refptr<net::IOBufferWithSize> buf(new net::IOBufferWithSize(5));
   rv = c->trans->Read(buf, buf->size(), c->callback.callback());
   EXPECT_EQ(5, c->callback.GetResult(rv));

-  // Cancel the request.
+  // Cancel the requests.
   delete c;
+  delete pending;

   EXPECT_EQ(1, cache.network_layer()->transaction_count());
   EXPECT_EQ(1, cache.disk_cache()->open_count());
-  EXPECT_EQ(1, cache.disk_cache()->create_count());
+  EXPECT_EQ(2, cache.disk_cache()->create_count());

-  // Verify that the disk entry was deleted.
-  disk_cache::Entry* entry;
-  EXPECT_FALSE(cache.OpenBackendEntry(kRangeGET_TransactionOK.url, &entry));
   MessageLoop::current()->RunAllPending();
   RemoveMockTransaction(&transaction);
 }"}

