{"sha": "87a7be2fd9db3230c6fa7f9e8488cb3d41467d64", "filename": "content/browser/renderer_host/render_view_host_unittest.cc", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/8ae91350332f188ef711228aa61b7809b74aa3a7/content/browser/renderer_host/render_view_host_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/8ae91350332f188ef711228aa61b7809b74aa3a7/content/browser/renderer_host/render_view_host_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/renderer_host/render_view_host_unittest.cc?ref=8ae91350332f188ef711228aa61b7809b74aa3a7", "patch": "@@ -9,6 +9,7 @@
 #include "content/browser/tab_contents/test_tab_contents.h"
 #include "content/common/view_messages.h"
 #include "content/public/browser/navigation_entry.h"
+#include "content/public/common/bindings_policy.h"
 #include "content/public/common/page_transition_types.h"
 #include "third_party/WebKit/Source/WebKit/chromium/public/WebDragOperation.h"
