{"sha": "353ab69b26dca94215c266ef1181f514dc4c188b", "filename": "components/password_manager/core/browser/affiliation_api.proto", "status": "modified", "additions": 21, "deletions": 1, "changes": 22, "blob_url": "https://github.com/chromium/chromium/blob/516abadc2553489ce28faeea4917280032fbe91d/components/password_manager/core/browser/affiliation_api.proto", "raw_url": "https://github.com/chromium/chromium/raw/516abadc2553489ce28faeea4917280032fbe91d/components/password_manager/core/browser/affiliation_api.proto", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/components/password_manager/core/browser/affiliation_api.proto?ref=516abadc2553489ce28faeea4917280032fbe91d", "patch": "@@ -10,13 +10,33 @@ option optimize_for = LITE_RUNTIME;

 // A collection of facets affiliated with each other, i.e. an equivalence class.
 message Affiliation {
-  repeated string facet = 1;
+  repeated Facet facet = 1;
+}
+
+message Facet {
+  // The URI of the facet.
+  optional string id = 1;
+  optional BrandingInfo branding_info = 2;
+}
+
+message BrandingInfo {
+  optional string name = 1;
+  optional string icon_url = 2;
+}
+
+// Specifies what additional information to return with the response.
+message LookupAffiliationMask {
+  // Whether or not to fill |branding_info| for returned Facets.
+  optional bool branding_info = 1;
+  // The locale to use for |branding_info.name| for returned Facets.
+  optional string locale = 2;
 }

