+<div id="container">
+<p id="description"></p>
+<div id="sample"><span contenteditable="true">foobar</span></div>
+</div>
+<div id="console"></div>
+<script src="../../fast/js/resources/js-test-pre.js"></script>
+<script>
+description('Selection should be updated after set innerHTML.');
+
+function $(id) { return document.getElementById(id); }
+
+var selection = window.getSelection();
+document.addEventListener('blur', function () {
+    selection.selectAllChildren($('sample').firstChild);
+}, true);
+
+selection.selectAllChildren($('sample').firstChild);
+$('sample').firstChild.focus();
+$('sample').innerHTML = '';
+
+shouldBe('selection.anchorOffset', '0');
+shouldBe('selection.focusOffset', '0');
+
+if (window.testRunner)
+    $('container').outerHTML = '';
+</script>
+<script src="../../fast/js/resources/js-test-post.js"></script>"}<_**next**_>{"sha": "6eaf7264f5267e96300baee4e1269817c9409381", "filename": "third_party/WebKit/LayoutTests/editing/selection/selection-change-in-mutation-event-by-remove-children-expected.txt", "status": "added", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/f084d7007f67809ef116ee6b11f251bf3c9ed895/third_party/WebKit/LayoutTests/editing/selection/selection-change-in-mutation-event-by-remove-children-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/f084d7007f67809ef116ee6b11f251bf3c9ed895/third_party/WebKit/LayoutTests/editing/selection/selection-change-in-mutation-event-by-remove-children-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/editing/selection/selection-change-in-mutation-event-by-remove-children-expected.txt?ref=f084d7007f67809ef116ee6b11f251bf3c9ed895", "patch": "@@ -0,0 +1,6 @@
