+<div id="container">
+<p id="description"></p>
+<div id="sample"><span contenteditable="true">foobar</span></div>
+</div>
+<div id="console"></div>
+<script src="../../js/resources/js-test-pre.js"></script>
+<script>
+description('Range objects should be updated after set innerHTML.');
+
+function $(id) { return document.getElementById(id); }
+
+var ranges = {};
+function eventHandler(event) {
+    if (ranges[event.type])
+        return;
+    ranges[event.type] = document.createRange();
+    ranges[event.type].selectNodeContents(sample.firstChild.firstChild);
+}
+
+document.addEventListener('blur', eventHandler, true);
+document.addEventListener('DOMNodeRemovedFromDocument', eventHandler, true);
+
+$('sample').firstChild.focus();
+$('sample').innerHTML = '';
+
+shouldBe('ranges["blur"].startOffset', '0');
+shouldBe('ranges["blur"].endOffset', '0');
+shouldBe('ranges["DOMNodeRemovedFromDocument"].startOffset', '0');
+shouldBe('ranges["DOMNodeRemovedFromDocument"].endOffset', '0');
+
+if (window.testRunner)
+    $('container').outerHTML = '';
+</script>
+<script src="../../js/resources/js-test-post.js"></script>"}<_**next**_>{"sha": "b1e0cfbc50be64fb14c006ad83422a230e84dd8d", "filename": "third_party/WebKit/Source/core/dom/ContainerNode.cpp", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/f084d7007f67809ef116ee6b11f251bf3c9ed895/third_party/WebKit/Source/core/dom/ContainerNode.cpp", "raw_url": "https://github.com/chromium/chromium/raw/f084d7007f67809ef116ee6b11f251bf3c9ed895/third_party/WebKit/Source/core/dom/ContainerNode.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/dom/ContainerNode.cpp?ref=f084d7007f67809ef116ee6b11f251bf3c9ed895", "patch": "@@ -402,8 +402,6 @@ static void willRemoveChildren(ContainerNode* container)
