+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "media/audio/audio_unittest_util.h"
+
+#include "base/command_line.h"
+#include "base/logging.h"
+#include "media/base/media_switches.h"
+
+namespace media {
+
+// For macro ABORT_AUDIO_TEST_IF_NOT.
+bool ShouldAbortAudioTest(bool requirements_satisfied,
+                          const char* requirements_expression,
+                          bool* should_fail) {
+  bool fail_if_unsatisfied = base::CommandLine::ForCurrentProcess()->HasSwitch(
+      switches::kRequireAudioHardwareForTesting);
+  if (!requirements_satisfied) {
+    LOG(WARNING) << "Requirement(s) not satisfied (" << requirements_expression
+                 << ")";
+    *should_fail = fail_if_unsatisfied;
+    return true;
+  }
+  *should_fail = false;
+  return false;
+}
+
+}  // namespace media"}<_**next**_>{"sha": "3bd0dfad676c93109e845e076abd8b5191e47bb1", "filename": "media/audio/audio_unittest_util.h", "status": "added", "additions": 34, "deletions": 0, "changes": 34, "blob_url": "https://github.com/chromium/chromium/blob/b0ddebe2ea0b00c272af7820b9c108c4438f5b88/media/audio/audio_unittest_util.h", "raw_url": "https://github.com/chromium/chromium/raw/b0ddebe2ea0b00c272af7820b9c108c4438f5b88/media/audio/audio_unittest_util.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/media/audio/audio_unittest_util.h?ref=b0ddebe2ea0b00c272af7820b9c108c4438f5b88", "patch": "@@ -0,0 +1,34 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef MEDIA_AUDIO_AUDIO_UNITTEST_UTIL_H_
+#define MEDIA_AUDIO_AUDIO_UNITTEST_UTIL_H_
+
+#include "testing/gtest/include/gtest/gtest.h"
+
+namespace media {
+
+// Use in tests to either skip or fail a test when the system is missing a
+// required audio device or library. If the --require-audio-hardware-for-testing
+// flag is set, missing requirements will cause the test to fail. Otherwise it
+// will be skipped.
+#define ABORT_AUDIO_TEST_IF_NOT(requirements_satisfied)                       \
+  do {                                                                        \
+    bool fail = false;                                                        \
+    if (ShouldAbortAudioTest(requirements_satisfied, #requirements_satisfied, \
+                             &fail)) {                                        \
+      if (fail)                                                               \
+        FAIL();                                                               \
+      else                                                                    \
+        return;                                                               \
+    }                                                                         \
+  } while (false)
+
+bool ShouldAbortAudioTest(bool requirements_satisfied,
+                          const char* requirements_expression,
+                          bool* should_fail);
+
+}  // namespace media
+
+#endif  // MEDIA_AUDIO_AUDIO_UNITTEST_UTIL_H_"}<_**next**_>{"sha": "b9c857d706c89b3cd022c4124af948958624493e", "filename": "media/audio/mac/audio_auhal_mac_unittest.cc", "status": "modified", "additions": 6, "deletions": 9, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/b0ddebe2ea0b00c272af7820b9c108c4438f5b88/media/audio/mac/audio_auhal_mac_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/b0ddebe2ea0b00c272af7820b9c108c4438f5b88/media/audio/mac/audio_auhal_mac_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/media/audio/mac/audio_auhal_mac_unittest.cc?ref=b0ddebe2ea0b00c272af7820b9c108c4438f5b88", "patch": "@@ -9,6 +9,7 @@
