+<!DOCTYPE html>
+<body>
+<script src="../js/resources/js-test-pre.js"></script>
+<script>
+jsTestIsAsync = true;
+var form1;
+var submit1;
+
+function start() {
+    form1 = document.createElement('form');
+    submit1 = document.createElement('input');
+    submit1.type = 'submit';
+    form1.addEventListener('submit', handleSubmit, false);
+    form1.action = 'javascript:gc()';
+    form1.appendChild(submit1);
+    submit1.click();
+    testPassed('if not crashed.');
+    finishJSTest();
+}
+
+function handleSubmit() {
+    form1.removeChild(submit1);
+    form1 = null;
+}
+window.onload = start;
+</script>
+<script src="../js/resources/js-test-post.js"></script>
+</body>"}<_**next**_>{"sha": "c78ee90e0a4b2bb4c13fd9b96f7dc00d2a0b28d4", "filename": "third_party/WebKit/Source/core/html/HTMLFormElement.cpp", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/4d77eed905ce1d00361282e8822a2a3be61d25c0/third_party/WebKit/Source/core/html/HTMLFormElement.cpp", "raw_url": "https://github.com/chromium/chromium/raw/4d77eed905ce1d00361282e8822a2a3be61d25c0/third_party/WebKit/Source/core/html/HTMLFormElement.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/html/HTMLFormElement.cpp?ref=4d77eed905ce1d00361282e8822a2a3be61d25c0", "patch": "@@ -259,6 +259,7 @@ bool HTMLFormElement::validateInteractively(Event* event)

