+<!doctype html>
+<!-- This tests for regression of https://crbug.com/279277 where non-adjacent, nested isolates caused a use-after-free if the elements were later removed. -->
+<script>
+window.onload = function() {
+  document.body.offsetTop;
+  b.lastChild.parentNode.removeChild(b.lastChild);
+  document.body.offsetTop;
+  a.nextSibling.parentNode.removeChild(a.nextSibling);
+  document.body.offsetTop;
+
+  document.write("PASS did not crash");
+}
+</script>
+
+<body>
+  <div id="a">foo</div><div>baz</div><div></div>
+  <div>
+    <output>
+      <span>
+        <output>bar</output>
+        <span id="b">
+          <span>
+            <div style="display:inline-block"></div>
+            <br><br>
+          </span>
+        </span>
+      </span>
+    </output>
+  </div>
+</body>
+
+<script>
+if (window.testRunner)
+    testRunner.dumpAsText();
+</script>"}<_**next**_>{"sha": "23fb022a28b1ae738517c6e24169bd22274a5c1a", "filename": "third_party/WebKit/LayoutTests/fast/text/international/unicode-bidi-isolate-nested-with-removes.html", "status": "modified", "additions": 4, "deletions": 8, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/248a92c21c20c14b5983680c50e1d8b73fc79a2f/third_party/WebKit/LayoutTests/fast/text/international/unicode-bidi-isolate-nested-with-removes.html", "raw_url": "https://github.com/chromium/chromium/raw/248a92c21c20c14b5983680c50e1d8b73fc79a2f/third_party/WebKit/LayoutTests/fast/text/international/unicode-bidi-isolate-nested-with-removes.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/text/international/unicode-bidi-isolate-nested-with-removes.html?ref=248a92c21c20c14b5983680c50e1d8b73fc79a2f", "patch": "@@ -1,19 +1,15 @@
