                 for (Frame* frame = otherPage->mainFrame(); frame; frame = frame->tree()->traverseNext())"}<_**next**_>{"sha": "ccdb0d0565af4f78dd23b29459b4e2cfeafa8207", "filename": "third_party/WebKit/Source/web/tests/WebFrameTest.cpp", "status": "modified", "additions": 33, "deletions": 0, "changes": 33, "blob_url": "https://github.com/chromium/chromium/blob/47a054e9ad826421b789097d82b44c102ab6ac97/third_party/WebKit/Source/web/tests/WebFrameTest.cpp", "raw_url": "https://github.com/chromium/chromium/raw/47a054e9ad826421b789097d82b44c102ab6ac97/third_party/WebKit/Source/web/tests/WebFrameTest.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/web/tests/WebFrameTest.cpp?ref=47a054e9ad826421b789097d82b44c102ab6ac97", "patch": "@@ -3432,6 +3432,39 @@ TEST_F(WebFrameTest, DidAccessInitialDocumentViaJavascriptUrl)
     m_webView = 0;
 }

+TEST_F(WebFrameTest, DidAccessInitialDocumentBodyBeforeModalDialog)
+{
+    TestAccessInitialDocumentWebFrameClient webFrameClient;
+    m_webView = FrameTestHelpers::createWebView(true, &webFrameClient);
+    runPendingTasks();
+    EXPECT_FALSE(webFrameClient.m_didAccessInitialDocument);
+
+    // Create another window that will try to access it.
+    WebView* newView = FrameTestHelpers::createWebView(true);
+    newView->mainFrame()->setOpener(m_webView->mainFrame());
+    runPendingTasks();
+    EXPECT_FALSE(webFrameClient.m_didAccessInitialDocument);
+
+    // Access the initial document by modifying the body. We normally set a
+    // timer to notify the client.
+    newView->mainFrame()->executeScript(
+        WebScriptSource("window.opener.document.body.innerHTML += 'Modified';"));
+    EXPECT_FALSE(webFrameClient.m_didAccessInitialDocument);
+
+    // Make sure that a modal dialog forces us to notify right away.
+    newView->mainFrame()->executeScript(
+        WebScriptSource("window.opener.confirm('Modal');"));
+    EXPECT_TRUE(webFrameClient.m_didAccessInitialDocument);
+
+    // Ensure that we don't notify again later.
+    runPendingTasks();
+    EXPECT_TRUE(webFrameClient.m_didAccessInitialDocument);
+
+    newView->close();
+    m_webView->close();
+    m_webView = 0;
+}
+
 class TestMainFrameUserOrProgrammaticScrollFrameClient : public WebFrameClient {
 public:
     TestMainFrameUserOrProgrammaticScrollFrameClient() { reset(); }"}

