+<!DOCTYPE html>
+<div>Test passes if it does not crash</div>
+<script>
+if (window.testRunner) testRunner.dumpAsText();
+var div = document.createElement('div');
+var span = document.createElement('span');
+div.appendChild(span);
+var observer = new MutationObserver(function(){});
+observer.observe(div, { attributes: true, subtree: true });
+div.removeChild(span); // cause span to become transiently observed
+div = null;
+gc(); // collect div's wrapper
+observer.disconnect();
+</script>"}<_**next**_>{"sha": "567f73037ca0fdd7da3659e7394ecc926d2e52da", "filename": "third_party/WebKit/Source/core/dom/Node.cpp", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/afea522e2f80f56fed7e54bd3d2070da358f42f2/third_party/WebKit/Source/core/dom/Node.cpp", "raw_url": "https://github.com/chromium/chromium/raw/afea522e2f80f56fed7e54bd3d2070da358f42f2/third_party/WebKit/Source/core/dom/Node.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/dom/Node.cpp?ref=afea522e2f80f56fed7e54bd3d2070da358f42f2", "patch": "@@ -2274,6 +2274,10 @@ void Node::unregisterMutationObserver(MutationObserverRegistration* registration
     if (index == notFound)
         return;

+    // Deleting the registration may cause this node to be derefed, so we must make sure the Vector operation completes
+    // before that, in case |this| is destroyed (see MutationObserverRegistration::m_registrationNodeKeepAlive).
+    // FIXME: Simplify the registration/transient registration logic to make this understandable by humans.
+    RefPtr<Node> protect(this);
     registry->remove(index);
 }
 "}

