{"sha": "e5ac8f04fd01de7801736a088afa5c1fb105fea9", "filename": "chrome/browser/extensions/api/dial/dial_api.cc", "status": "added", "additions": 125, "deletions": 0, "changes": 125, "blob_url": "https://github.com/chromium/chromium/blob/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_api.cc", "raw_url": "https://github.com/chromium/chromium/raw/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_api.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/api/dial/dial_api.cc?ref=0f05aa7e29cf814a204830c82ba2619f9c636894", "patch": "@@ -0,0 +1,125 @@
+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/browser/extensions/api/dial/dial_api.h"
+
+#include <vector>
+
+#include "chrome/browser/extensions/api/dial/dial_api_factory.h"
+#include "chrome/browser/extensions/event_names.h"
+#include "chrome/browser/extensions/event_router.h"
+#include "chrome/browser/extensions/extension_system.h"
+#include "chrome/browser/profiles/profile.h"
+#include "chrome/common/extensions/api/dial.h"
+#include "content/public/browser/browser_thread.h"
+
+namespace {
+
+const char kDialServiceError[] = "Dial service error.";
+
+}  // namespace
+
+namespace extensions {
+
+DialAPI::DialAPI(Profile* profile)
+    : RefcountedProfileKeyedService(content::BrowserThread::IO),
+      profile_(profile) {
+  ExtensionSystem::Get(profile)->event_router()->RegisterObserver(
+      this, extensions::event_names::kOnDialDeviceList);
+}
+
+DialAPI::~DialAPI() {}
+
+DialRegistry* DialAPI::dial_registry() {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::IO));
+  if (!dial_registry_.get()) {
+    dial_registry_.reset(new DialRegistry(this));
+  }
+  return dial_registry_.get();
+}
+
+void DialAPI::OnListenerAdded(const EventListenerInfo& details) {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI));
+  BrowserThread::PostTask(
+      BrowserThread::IO, FROM_HERE,
+      base::Bind(&DialAPI::NotifyListenerAddedOnIOThread, this));
+}
+
+void DialAPI::OnListenerRemoved(const EventListenerInfo& details) {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI));
+  BrowserThread::PostTask(
+      BrowserThread::IO, FROM_HERE,
+      base::Bind(&DialAPI::NotifyListenerRemovedOnIOThread, this));
+}
+
+void DialAPI::NotifyListenerAddedOnIOThread() {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::IO));
+  DVLOG(1) << "DIAL device event listener added.";
+  dial_registry()->OnListenerAdded();
+}
+
+void DialAPI::NotifyListenerRemovedOnIOThread() {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::IO));
+  DVLOG(1) << "DIAL device event listener removed";
+  dial_registry()->OnListenerRemoved();
+}
+
+void DialAPI::OnDialDeviceEvent(const DialRegistry::DeviceList& devices) {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::IO));
+  BrowserThread::PostTask(BrowserThread::UI, FROM_HERE,
+      base::Bind(&DialAPI::SendEventOnUIThread, this, devices));
+}
+
+void DialAPI::SendEventOnUIThread(const DialRegistry::DeviceList& devices) {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI));
+
+  std::vector<linked_ptr<api::dial::DialDevice> > args;
+  for (DialRegistry::DeviceList::const_iterator it = devices.begin();
+       it != devices.end(); ++it) {
+    linked_ptr<api::dial::DialDevice> api_device =
+        make_linked_ptr(new api::dial::DialDevice);
+    it->FillDialDevice(api_device.get());
+    args.push_back(api_device);
+  }
+  scoped_ptr<base::ListValue> results = api::dial::OnDeviceList::Create(args);
+
+  scoped_ptr<Event> event(
+      new Event(event_names::kOnDialDeviceList, results.Pass()));
+
+  extensions::ExtensionSystem::Get(profile_)->event_router()->
+      BroadcastEvent(event.Pass());
+}
+
+void DialAPI::ShutdownOnUIThread() {}
+
+namespace api {
+
+DialDiscoverNowFunction::DialDiscoverNowFunction()
+    : dial_(NULL), result_(false) {
+}
+
+bool DialDiscoverNowFunction::Prepare() {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI));
+  DCHECK(profile());
+  dial_ = DialAPIFactory::GetInstance()->GetForProfile(profile());
+  return true;
+}
+
+void DialDiscoverNowFunction::Work() {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::IO));
+  result_ = dial_->dial_registry()->DiscoverNow();
+}
+
+bool DialDiscoverNowFunction::Respond() {
+  DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI));
+  if (!result_)
+    error_ = kDialServiceError;
+
+  SetResult(base::Value::CreateBooleanValue(result_));
+  return true;
+}
+
+}  // namespace api
+
+}  // namespace extensions"}<_**next**_>{"sha": "ee3ba7f861ad25909e253d9594992be7060dc591", "filename": "chrome/browser/extensions/api/dial/dial_api.h", "status": "added", "additions": 98, "deletions": 0, "changes": 98, "blob_url": "https://github.com/chromium/chromium/blob/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_api.h", "raw_url": "https://github.com/chromium/chromium/raw/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_api.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/api/dial/dial_api.h?ref=0f05aa7e29cf814a204830c82ba2619f9c636894", "patch": "@@ -0,0 +1,98 @@
+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_API_H_
+#define CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_API_H_
+
+#include "base/memory/scoped_ptr.h"
+#include "chrome/browser/extensions/api/api_function.h"
+#include "chrome/browser/extensions/api/dial/dial_device_data.h"
+#include "chrome/browser/extensions/api/dial/dial_registry.h"
+#include "chrome/browser/extensions/event_router.h"
+#include "chrome/browser/profiles/refcounted_profile_keyed_service.h"
+
+namespace extensions {
+
+class DialRegistry;
+
+// Dial API which is a ref-counted ProfileKeyedService that manages the DIAL
+// registry. It takes care of creating the registry on the IO thread and
+// is an observer of the registry. It makes sure devices events are sent out
+// to extension listeners on the right thread.
+class DialAPI : public RefcountedProfileKeyedService,
+                public EventRouter::Observer,
+                public DialRegistry::Observer {
+ public:
+  explicit DialAPI(Profile* profile);
+
+  // The DialRegistry for the API. This must always be used only from the IO
+  // thread.
+  DialRegistry* dial_registry();
+
+  // Called by the DialRegistry on the IO thread so that the DialAPI dispatches
+  // the event to listeners on the UI thread.
+  void SendEventOnUIThread(const DialRegistry::DeviceList& devices);
+
+ private:
+  virtual ~DialAPI();
+
+  // RefcountedProfileKeyedService:
+  virtual void ShutdownOnUIThread() OVERRIDE;
+
+  // EventRouter::Observer:
+  virtual void OnListenerAdded(const EventListenerInfo& details) OVERRIDE;
+  virtual void OnListenerRemoved(const EventListenerInfo& details) OVERRIDE;
+
+  // DialRegistry::Observer:
+  virtual void OnDialDeviceEvent(
+      const DialRegistry::DeviceList& devices) OVERRIDE;
+
+  // Methods to notify the DialRegistry on the correct thread of new/removed
+  // listeners.
+  void NotifyListenerAddedOnIOThread();
+  void NotifyListenerRemovedOnIOThread();
+
+  Profile* profile_;
+
+  // Created lazily on first access on the IO thread.
+  scoped_ptr<DialRegistry> dial_registry_;
+
+  DISALLOW_COPY_AND_ASSIGN(DialAPI);
+};
+
+namespace api {
+
+// DiscoverNow function. This function needs a round-trip from the IO thread
+// because it needs to grab a pointer to the DIAL API in order to get a
+// reference to the DialRegistry while on the IO thread. Then, the result
+// must be returned on the UI thread.
+class DialDiscoverNowFunction : public AsyncApiFunction {
+ public:
+  DialDiscoverNowFunction();
+
+ protected:
+  virtual ~DialDiscoverNowFunction() {}
+
+  // AsyncApiFunction:
+  virtual bool Prepare() OVERRIDE;
+  virtual void Work() OVERRIDE;
+  virtual bool Respond() OVERRIDE;
+
+ private:
+  DECLARE_EXTENSION_FUNCTION_NAME("dial.discoverNow")
+
+  // Pointer to the DIAL API for this profile. We get this on the UI thread.
+  DialAPI* dial_;
+
+  // Result of the discoverNow call to the DIAL registry. This result is
+  // retrieved on the IO thread but the function result is returned on the UI
+  // thread.
+  bool result_;
+};
+
+}  // namespace api
+
+}  // namespace extensions
+
+#endif  // CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_API_H_"}<_**next**_>{"sha": "b9a60178c20c7f76bffcf014612acd61c59d3696", "filename": "chrome/browser/extensions/api/dial/dial_api_factory.cc", "status": "added", "additions": 49, "deletions": 0, "changes": 49, "blob_url": "https://github.com/chromium/chromium/blob/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_api_factory.cc", "raw_url": "https://github.com/chromium/chromium/raw/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_api_factory.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/api/dial/dial_api_factory.cc?ref=0f05aa7e29cf814a204830c82ba2619f9c636894", "patch": "@@ -0,0 +1,49 @@
+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
