+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_DEVICE_DATA_H_
+#define CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_DEVICE_DATA_H_
+
+#include <string>
+#include <vector>
+
+#include "base/time.h"
+#include "base/values.h"
+
+namespace extensions {
+
+namespace api {
+namespace dial {
+struct DialDevice;
+}  // namespace api
+}  // namespace dial
+
+// Dial device information that is used within the DialService and Registry on
+// the IO thread. It is updated as new information arrives and a list of
+// DialDeviceData is copied and sent to event listeners on the UI thread.
+class DialDeviceData {
+ public:
+  DialDeviceData();
+  DialDeviceData(const DialDeviceData& other_data);
+  ~DialDeviceData();
+
+  DialDeviceData& operator=(const DialDeviceData& other_data);
+
+  const std::string& device_id() const;
+  void set_device_id(const std::string& id);
+
+  const std::string& label() const;
+  void set_label(const std::string& label);
+
+  const std::string& device_description_url() const;
+  void set_device_description_url(const std::string& url);
+
+  const base::Time& response_time() const;
+  void set_response_time(const base::Time& response_time);
+
+  int max_age() const { return max_age_; }
+  void set_max_age(int max_age) { max_age_ = max_age; }
+  bool has_max_age() const { return max_age_ >= 0; }
+
+  int config_id() const { return config_id_; }
+  void set_config_id(int config_id) { config_id_ = config_id; }
+  bool has_config_id() const { return config_id_ >= 0; }
+
+  // Fills the |device| API struct from this instance.
+  void FillDialDevice(api::dial::DialDevice* device) const;
+
+ private:
+  // Hardware identifier from the DIAL response.  Not exposed to API clients.
+  std::string device_id_;
+
+  // Identifies this device to clients of the API.
+  std::string label_;
+
+  // The device description URL.
+  std::string device_description_url_;
+
+  // The time that the most recent response was received.
+  base::Time response_time_;
+
+  // Optional (-1 means unset).
+  int max_age_;
+
+  // Optional (-1 means unset).
+  int config_id_;
+
+  // Implementation of copy ctor and assignment operator.
+  void CopyFrom(const DialDeviceData& other_data);
+};
+
+}  // namespace extensions
+
+#endif  // CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_DEVICE_DATA_H_"}<_**next**_>{"sha": "0b064a280e72dcc77e1076525866391edb234175", "filename": "chrome/browser/extensions/api/dial/dial_registry.cc", "status": "added", "additions": 41, "deletions": 0, "changes": 41, "blob_url": "https://github.com/chromium/chromium/blob/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_registry.cc", "raw_url": "https://github.com/chromium/chromium/raw/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_registry.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/api/dial/dial_registry.cc?ref=0f05aa7e29cf814a204830c82ba2619f9c636894", "patch": "@@ -0,0 +1,41 @@
+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/browser/extensions/api/dial/dial_registry.h"
+
+#include "chrome/browser/extensions/api/dial/dial_api.h"
+#include "chrome/browser/extensions/api/dial/dial_device_data.h"
+#include "chrome/common/extensions/api/dial.h"
+
+namespace extensions {
+
+DialRegistry::DialRegistry(Observer* dial_api)
+  : num_listeners_(0), discovering_(false), dial_api_(dial_api) { }
+
+DialRegistry::~DialRegistry() {
+  DCHECK(thread_checker_.CalledOnValidThread());
+}
+
+void DialRegistry::OnListenerAdded() {
+  DCHECK(thread_checker_.CalledOnValidThread());
+  if (++num_listeners_ == 1) {
+    DVLOG(1) << "Listener added; starting periodic discovery.";
+    discovering_ = true;
+  }
+}
+
+void DialRegistry::OnListenerRemoved() {
+  DCHECK(thread_checker_.CalledOnValidThread());
+  if (--num_listeners_ == 0) {
+    DVLOG(1) << "Listeners removed; stopping periodic discovery.";
+    discovering_ = false;
+  }
+}
+
+bool DialRegistry::DiscoverNow() {
+  DCHECK(thread_checker_.CalledOnValidThread());
+  return discovering_;
+}
+
+}  // namespace extensions"}<_**next**_>{"sha": "558a2ba2c76b07690cd3c4693f4d2a384ef35d7e", "filename": "chrome/browser/extensions/api/dial/dial_registry.h", "status": "added", "additions": 70, "deletions": 0, "changes": 70, "blob_url": "https://github.com/chromium/chromium/blob/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_registry.h", "raw_url": "https://github.com/chromium/chromium/raw/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/api/dial/dial_registry.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/api/dial/dial_registry.h?ref=0f05aa7e29cf814a204830c82ba2619f9c636894", "patch": "@@ -0,0 +1,70 @@
+// Copyright (c) 2012 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_REGISTRY_H_
+#define CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_REGISTRY_H_
+
+#include <map>
+#include <string>
+#include <vector>
+
+#include "base/basictypes.h"
+#include "base/memory/scoped_ptr.h"
+#include "base/threading/thread_checker.h"
+#include "chrome/browser/extensions/api/dial/dial_device_data.h"
+
+namespace extensions {
+
+// Keeps track of devices that have responded to discovery requests and notifies
+// the observer with the set of active devices has changed.  The registry's
+// observer (i.e., the Dial API) owns the registry instance.
+class DialRegistry {
+ public:
+  typedef std::vector<DialDeviceData> DeviceList;
+
+  class Observer {
+   public:
+    // Invoked on the IO thread by the DialRegistry during a device event (new
+    // device discovered or an update triggered by dial.discoverNow).
+    virtual void OnDialDeviceEvent(const DeviceList& devices) = 0;
+
+   protected:
+    virtual ~Observer() {}
+  };
+
+  // Create the DIAL registry and pass a reference to allow it to notify on
+  // DIAL device events.
+  explicit DialRegistry(Observer *dial_api);
+  virtual ~DialRegistry();
+
+  // Called by the DIAL API when event listeners are added or removed. The dial
+  // service is started after the first listener is added and stopped after the
+  // last listener is removed.
+  void OnListenerAdded();
+  void OnListenerRemoved();
+
+  // Called by the DIAL API to try to kickoff a discovery if there is not one
+  // already active.
+  bool DiscoverNow();
+
+ private:
+  // The current number of event listeners attached to this registry.
+  int num_listeners_;
+
+  // Whether discovering is currently active.
+  bool discovering_;
+
+  // Interface from which the DIAL API is notified of DIAL device events. the
+  // DIAL API owns this DIAL registry.
+  Observer* dial_api_;
+
+  // Thread checker.
+  base::ThreadChecker thread_checker_;
+
+  DISALLOW_COPY_AND_ASSIGN(DialRegistry);
+};
+
+}  // namespace extensions
+
+#endif  // CHROME_BROWSER_EXTENSIONS_API_DIAL_DIAL_REGISTRY_H_"}<_**next**_>{"sha": "2365cc8583a454abaf5a8d3e7eebe50a059e29f9", "filename": "chrome/browser/extensions/event_names.cc", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/event_names.cc", "raw_url": "https://github.com/chromium/chromium/raw/0f05aa7e29cf814a204830c82ba2619f9c636894/chrome/browser/extensions/event_names.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/event_names.cc?ref=0f05aa7e29cf814a204830c82ba2619f9c636894", "patch": "@@ -47,6 +47,8 @@ const char kOnInputMethodChanged[] = "inputMethodPrivate.onChanged";
