{"sha": "dafdb9606e69e9b0318994a254c8b73622ff304d", "filename": "third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked-expected.txt", "status": "added", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/ed6f4545a2a345697e07908c887333f5bdcc97a3/third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/ed6f4545a2a345697e07908c887333f5bdcc97a3/third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked-expected.txt?ref=ed6f4545a2a345697e07908c887333f5bdcc97a3", "patch": "@@ -0,0 +1,11 @@
+CONSOLE ERROR: Refused to execute script from 'http://127.0.0.1:8000/security/contentTypeOptions/resources/script-with-header.pl?mime=application/json' because its MIME type ('application/json') is not executable, and strict MIME type checking is enabled.
+Check that script sent with an 'X-Content-Type-Options: nosniff' header is correctly blocked if the MIME type isn't scripty.
+
+On success, you will see a series of "PASS" messages, followed by "TEST COMPLETE".
+
+
+PASS window.scriptsSuccessfullyLoaded is 0
+PASS successfullyParsed is true
+
+TEST COMPLETE
+"}<_**next**_>{"sha": "6d0c62d8e7c1e4cf8369e76e93c00a08b7fa755b", "filename": "third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked.html", "status": "added", "additions": 23, "deletions": 0, "changes": 23, "blob_url": "https://github.com/chromium/chromium/blob/ed6f4545a2a345697e07908c887333f5bdcc97a3/third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked.html", "raw_url": "https://github.com/chromium/chromium/raw/ed6f4545a2a345697e07908c887333f5bdcc97a3/third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/contentTypeOptions/nosniff-dynamic-script-blocked.html?ref=ed6f4545a2a345697e07908c887333f5bdcc97a3", "patch": "@@ -0,0 +1,23 @@
+<!DOCTYPE html>
+<html>
+<head>
+    <title>'X-Content-Type-Options: nosniff;' blocks scripts!</title>
+<body>
+    <script src="/js-test-resources/js-test.js"></script>
+    <script>
+        description('Check that script sent with an \'X-Content-Type-Options: nosniff\' header is correctly blocked if the MIME type isn\'t scripty.');
+        window.jsTestIsAsync = true;
+
+        window.scriptsSuccessfullyLoaded = 0;
+
+        var s = document.createElement('script');
+        s.src = './resources/script-with-header.pl?mime=application/json';
+        document.querySelector('head').appendChild(s);
+
+        window.onload = function () {
+            shouldBe('window.scriptsSuccessfullyLoaded', '0');
+            finishJSTest();
+        };
+    </script>
+</body>
+</html>"}<_**next**_>{"sha": "0ee2e25f4d5c4590e7c67948543e1b56ead8b167", "filename": "third_party/WebKit/Source/core/dom/ScriptLoader.cpp", "status": "modified", "additions": 6, "deletions": 3, "changes": 9, "blob_url": "https://github.com/chromium/chromium/blob/ed6f4545a2a345697e07908c887333f5bdcc97a3/third_party/WebKit/Source/core/dom/ScriptLoader.cpp", "raw_url": "https://github.com/chromium/chromium/raw/ed6f4545a2a345697e07908c887333f5bdcc97a3/third_party/WebKit/Source/core/dom/ScriptLoader.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/dom/ScriptLoader.cpp?ref=ed6f4545a2a345697e07908c887333f5bdcc97a3", "patch": "@@ -308,9 +308,12 @@ void ScriptLoader::executeScript(const ScriptSourceCode& sourceCode)
