{"sha": "2e44dc4a46a35c44091be820233525b82e632976", "filename": "chrome/browser/chrome_content_browser_client.cc", "status": "modified", "additions": 26, "deletions": 0, "changes": 26, "blob_url": "https://github.com/chromium/chromium/blob/e9841fbdaf41b4a2baaa413f94d5c0197f9261f4/chrome/browser/chrome_content_browser_client.cc", "raw_url": "https://github.com/chromium/chromium/raw/e9841fbdaf41b4a2baaa413f94d5c0197f9261f4/chrome/browser/chrome_content_browser_client.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/chrome_content_browser_client.cc?ref=e9841fbdaf41b4a2baaa413f94d5c0197f9261f4", "patch": "@@ -975,6 +975,7 @@ void ChromeContentBrowserClient::SiteInstanceDeleting(
 }

 bool ChromeContentBrowserClient::ShouldSwapProcessesForNavigation(
+    SiteInstance* site_instance,
     const GURL& current_url,
     const GURL& new_url) {
   if (current_url.is_empty()) {
@@ -995,6 +996,31 @@ bool ChromeContentBrowserClient::ShouldSwapProcessesForNavigation(
       return true;
   }

+  // The checks below only matter if we can retrieve which extensions are
+  // installed.
+  Profile* profile =
+      Profile::FromBrowserContext(site_instance->GetBrowserContext());
+  ExtensionService* service =
+      extensions::ExtensionSystem::Get(profile)->extension_service();
+  if (!service)
+    return false;
+
+  // We must swap if the URL is for an extension and we are not using an
+  // extension process.
+  const Extension* new_extension =
+      service->extensions()->GetExtensionOrAppByURL(ExtensionURLInfo(new_url));
+  // Ignore all hosted apps except the Chrome Web Store, since they do not
+  // require their own BrowsingInstance (e.g., postMessage is ok).
+  if (new_extension &&
+      new_extension->is_hosted_app() &&
+      new_extension->id() != extension_misc::kWebStoreAppId)
+    new_extension = NULL;
+  if (new_extension &&
+      site_instance->HasProcess() &&
+      !service->process_map()->Contains(new_extension->id(),
+                                        site_instance->GetProcess()->GetID()))
+    return true;
+
   return false;
 }
