{"sha": "b73bd51d278d3a2f92a2afef713e2932bfab44e9", "filename": "content/public/common/common_param_traits.cc", "status": "modified", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/74aaa70032784e7cf00256821f29b2b53edb6589/content/public/common/common_param_traits.cc", "raw_url": "https://github.com/chromium/chromium/raw/74aaa70032784e7cf00256821f29b2b53edb6589/content/public/common/common_param_traits.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/public/common/common_param_traits.cc?ref=74aaa70032784e7cf00256821f29b2b53edb6589", "patch": "@@ -50,6 +50,23 @@ namespace IPC {

 void ParamTraits<GURL>::Write(Message* m, const GURL& p) {
   DCHECK(p.possibly_invalid_spec().length() <= content::kMaxURLChars);
+
+  // Beware of print-parse inconsistency which would change an invalid
+  // URL into a valid one. Ideally, the message would contain this flag
+  // so that the read side could make the check, but performing it here
+  // avoids changing the on-the-wire representation of such a fundamental
+  // type as GURL. See https://crbug.com/166486 for additional work in
+  // this area.
+  if (!p.is_valid()) {
+    GURL reconstructed_url(p.possibly_invalid_spec());
+    if (reconstructed_url.is_valid()) {
+      DLOG(WARNING) << "GURL string " << p.possibly_invalid_spec()
+                    << " (marked invalid) but parsed as valid.";
+      m->WriteString(std::string());
+      return;
+    }
+  }
+
   m->WriteString(p.possibly_invalid_spec());
   // TODO(brettw) bug 684583: Add encoding for query params.
 }"}

