+</html>"}<_**next**_>{"sha": "66d09e1f1e631839b421df3dbc249e8b502f03e1", "filename": "third_party/WebKit/Source/web/tests/data/pageserialization/simple_page.html", "status": "added", "additions": 50, "deletions": 0, "changes": 50, "blob_url": "https://github.com/chromium/chromium/blob/7f0126ff011142c8619b10a6e64d04d1745c503a/third_party/WebKit/Source/web/tests/data/pageserialization/simple_page.html", "raw_url": "https://github.com/chromium/chromium/raw/7f0126ff011142c8619b10a6e64d04d1745c503a/third_party/WebKit/Source/web/tests/data/pageserialization/simple_page.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/web/tests/data/pageserialization/simple_page.html?ref=7f0126ff011142c8619b10a6e64d04d1745c503a", "patch": "@@ -0,0 +1,50 @@
+<html>
+<!--
+    This page is used to test that WebPageSerializer::retrieveAllResources retrieves
+    correctly the expected resources from various HTML nodes.
+-->
+
+<head>
+<!-- Style sheet links should be retrieved -->
+<link rel="stylesheet" type="text/css" href="http://www.example.com/beautifull.css"/>
+<!-- Other link should NOT be retrieved -->
+<link rel="copyright" type="text/plain" href="http://www.example.com/copyright"/>
+<!-- Scripts should be retrieved -->
+<script src="awesome.js"></script>
+</head>
+
+<!-- Images are always retrieved -->
+<body background="bodyBackground.jpg">
+
+<!-- Twice to make sure we only report each resource once -->
+<img src="awesome.png"/>
+<img src="awesome.png"/>
+
+<form>
+  <input type="image" src="imageButton.png"/>
+</form>
+
+<table background="tableBackground.png">
+  <tr background="trBackground.png">
+    <td background="tdBackground.png"></td>
+  </tr>  
+  <tr background="trBackground.png">
+    <td background="tdBackground.png"></td>
+  </tr>
+</table>
+
+<!-- Some more obscure tags -->
+<blockquote cite="http://www.evene.fr/citations/auteur.php?ida=46"></blockquote>
+<q CITE="http://www.brainyquote.com/quotes/authors/c/charles_darwin.html"></q>
+<p>My favorite color is <del cite="why_deleted.html">blue</del> <ins>red</ins>!</p>
+<p>My favorite color is <del>blue</del> <ins cite="why_inserted.html">red</ins>!</p>
+
+<!-- Make sure we only retrieve URLs with the right schemes -->
+<img src="https://www.secure.com/https.gif"/>  <!-- HTTPS is OK -->
+<img src="file://c/my_folder/file.gif"/>  <!-- file is OK -->
+<img src="ftp://ftp.com/ftp.gif"/>  <!-- FTP is not OK -->
+<img src="unknown://unkown.com/unknown.gif"/>  <!-- Unknown schemes are not OK -->
+
+</body>
+
+</html>"}<_**next**_>{"sha": "edc8ab26af2db2dffeddfc72a0ae647c4a628f98", "filename": "third_party/WebKit/Source/web/tests/data/pageserialization/top_frame.html", "status": "added", "additions": 28, "deletions": 0, "changes": 28, "blob_url": "https://github.com/chromium/chromium/blob/7f0126ff011142c8619b10a6e64d04d1745c503a/third_party/WebKit/Source/web/tests/data/pageserialization/top_frame.html", "raw_url": "https://github.com/chromium/chromium/raw/7f0126ff011142c8619b10a6e64d04d1745c503a/third_party/WebKit/Source/web/tests/data/pageserialization/top_frame.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/web/tests/data/pageserialization/top_frame.html?ref=7f0126ff011142c8619b10a6e64d04d1745c503a", "patch": "@@ -0,0 +1,28 @@
+<html>
+<!--
+    This page is used to test that WebPageSerializer::retrieveAllResources retrieves
+    correctly the expected resources when dealing with multiple frames. 
+-->
+
+<body>
+
+<!-- Resources used by a frame and a tag should be only reported once -->
+<iframe src="awesome.png"></iframe>
+<img src="awesome.png"/>
+
+<iframe src="simple_iframe.html"></iframe>
+<iframe src="simple_iframe.html"></iframe>
+
+<!-- Object tags can be used to create iframes -->
+
+<object data="object_iframe.html"></object>
+<object data="flash.swf"></object>
+
+<!-- Embed tags can be used to create iframes as well -->
+<embed src="embed_iframe.html"></object>
+<!--
+<embed src="music.mid"></embed>
+-->
+</body>
+
+</html>"}<_**next**_>{"sha": "6dfb20499c43263cb5c246fe7e1925442cd71436", "filename": "third_party/WebKit/Source/web/tests/data/pageserializer/blank_frames.html", "status": "renamed", "additions": 4, "deletions": 3, "changes": 7, "blob_url": "https://github.com/chromium/chromium/blob/7f0126ff011142c8619b10a6e64d04d1745c503a/third_party/WebKit/Source/web/tests/data/pageserializer/blank_frames.html", "raw_url": "https://github.com/chromium/chromium/raw/7f0126ff011142c8619b10a6e64d04d1745c503a/third_party/WebKit/Source/web/tests/data/pageserializer/blank_frames.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/web/tests/data/pageserializer/blank_frames.html?ref=7f0126ff011142c8619b10a6e64d04d1745c503a", "patch": "@@ -1,7 +1,5 @@
