{"sha": "2d3f935c0fcabe4a09f1a67cbca99dea2d360f11", "filename": "content/browser/renderer_host/backing_store_gtk.cc", "status": "modified", "additions": 10, "deletions": 1, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/0bd1a6ddb5fb23dfea3e72d60e5e8df4cf5826bc/content/browser/renderer_host/backing_store_gtk.cc", "raw_url": "https://github.com/chromium/chromium/raw/0bd1a6ddb5fb23dfea3e72d60e5e8df4cf5826bc/content/browser/renderer_host/backing_store_gtk.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/renderer_host/backing_store_gtk.cc?ref=0bd1a6ddb5fb23dfea3e72d60e5e8df4cf5826bc", "patch": "@@ -519,10 +519,14 @@ bool BackingStoreGtk::CopyFromBackingStore(const gfx::Rect& rect,
