{"sha": "33b026cf5bb4a21d0d53d0bd069366225efb40a5", "filename": "content/browser/screen_orientation/screen_orientation_browsertest.cc", "status": "modified", "additions": 26, "deletions": 5, "changes": 31, "blob_url": "https://github.com/chromium/chromium/blob/bed415634f57baf1e74d94d133b251fab330919e/content/browser/screen_orientation/screen_orientation_browsertest.cc", "raw_url": "https://github.com/chromium/chromium/raw/bed415634f57baf1e74d94d133b251fab330919e/content/browser/screen_orientation/screen_orientation_browsertest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/screen_orientation/screen_orientation_browsertest.cc?ref=bed415634f57baf1e74d94d133b251fab330919e", "patch": "@@ -32,11 +32,6 @@ class ScreenOrientationBrowserTest : public ContentBrowserTest  {
