@@ -215,4 +210,30 @@ IN_PROC_BROWSER_TEST_F(ScreenOrientationBrowserTest, LockSmoke) {
   EXPECT_EQ(expected, shell()->web_contents()->GetLastCommittedURL().ref());
 }

+// Check that using screen orientation after a frame is detached doesn't crash
+// the renderer process.
+// This could be a LayoutTest if they were not using a mock screen orientation
+// controller.
+IN_PROC_BROWSER_TEST_F(ScreenOrientationBrowserTest, CrashTest_UseAfterDetach) {
+  GURL test_url = GetTestUrl("screen_orientation",
+                             "screen_orientation_use_after_detach.html");
+
+  TestNavigationObserver navigation_observer(shell()->web_contents(), 2);
+  shell()->LoadURL(test_url);
+
+#if defined(OS_WIN)
+  // Screen Orientation is currently disabled on Windows 8.
+  // When implemented, this test will break, requiring an update.
+  if (base::win::OSInfo::GetInstance()->version() >= base::win::VERSION_WIN8) {
+    EXPECT_EQ(false, ScreenOrientationSupported());
+    return;
+  }
+#endif // defined(OS_WIN)
+
+  navigation_observer.Wait();
+
+  // This is a success if the renderer process did not crash, thus, we end up
+  // here.
+}
+
 } // namespace content"}<_**next**_>{"sha": "633eaeee40dd24914f67734866aa3a5c04f66b15", "filename": "content/test/data/screen_orientation/detached-iframe.html", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/bed415634f57baf1e74d94d133b251fab330919e/content/test/data/screen_orientation/detached-iframe.html", "raw_url": "https://github.com/chromium/chromium/raw/bed415634f57baf1e74d94d133b251fab330919e/content/test/data/screen_orientation/detached-iframe.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/test/data/screen_orientation/detached-iframe.html?ref=bed415634f57baf1e74d94d133b251fab330919e", "patch": "@@ -0,0 +1,12 @@
+<!DOCTYPE html>
+<html>
+<body onload="test();">
+<script>
+
+function test() {
+  parent.iframeLoaded();
+}
+
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "7618f2bc60071886a648ce322752185cb0f667da", "filename": "content/test/data/screen_orientation/screen_orientation_use_after_detach.html", "status": "added", "additions": 21, "deletions": 0, "changes": 21, "blob_url": "https://github.com/chromium/chromium/blob/bed415634f57baf1e74d94d133b251fab330919e/content/test/data/screen_orientation/screen_orientation_use_after_detach.html", "raw_url": "https://github.com/chromium/chromium/raw/bed415634f57baf1e74d94d133b251fab330919e/content/test/data/screen_orientation/screen_orientation_use_after_detach.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/test/data/screen_orientation/screen_orientation_use_after_detach.html?ref=bed415634f57baf1e74d94d133b251fab330919e", "patch": "@@ -0,0 +1,21 @@
+<!DOCTYPE html>
+<html>
+<body>
+<script>
+
+window.iframeLoaded = function() {
+  document.location.hash = '#ready';
+
+  var iframe = document.getElementsByTagName('iframe')[0];
+  var oldScreen = iframe.contentWindow.screen;
+
+  iframe.remove();
+
+  oldScreen.orientation.unlock();
+  document.location.hash = '#done';
+}
+
+</script>
+<iframe src='detached-iframe.html'></iframe>
+</body>
+</html>"}

{"sha": "7b188b6b04cd8b255021a1d9b523b51c08d2ae29", "filename": "media/base/container_names.cc", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/b2006ac87cec58363090e7d5e10d5d9e3bbda9f9/media/base/container_names.cc", "raw_url": "https://github.com/chromium/chromium/raw/b2006ac87cec58363090e7d5e10d5d9e3bbda9f9/media/base/container_names.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/media/base/container_names.cc?ref=b2006ac87cec58363090e7d5e10d5d9e3bbda9f9", "patch": "@@ -954,7 +954,7 @@ static bool CheckMov(const uint8* buffer, int buffer_size) {

   int offset = 0;
   while (offset + 8 < buffer_size) {
-    int atomsize = Read32(buffer + offset);
+    uint32 atomsize = Read32(buffer + offset);
     uint32 atomtype = Read32(buffer + offset + 4);
     // Only need to check for ones that are valid at the top level.
     switch (atomtype) {
@@ -985,7 +985,7 @@ static bool CheckMov(const uint8* buffer, int buffer_size) {
         break;  // Offset is way past buffer size.
       atomsize = Read32(buffer + offset + 12);
     }
-    if (atomsize <= 0)
+    if (atomsize == 0 || atomsize > static_cast<size_t>(buffer_size))
       break;  // Indicates the last atom or length too big.
     offset += atomsize;
   }"}

{"sha": "0cb013b57d725807d33abe52058de247a0676aa5", "filename": "third_party/WebKit/Source/core/loader/DocumentThreadableLoader.cpp", "status": "modified", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/2571533bbb5b554ff47205c8ef1513ccc0817c3e/third_party/WebKit/Source/core/loader/DocumentThreadableLoader.cpp", "raw_url": "https://github.com/chromium/chromium/raw/2571533bbb5b554ff47205c8ef1513ccc0817c3e/third_party/WebKit/Source/core/loader/DocumentThreadableLoader.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/loader/DocumentThreadableLoader.cpp?ref=2571533bbb5b554ff47205c8ef1513ccc0817c3e", "patch": "@@ -844,17 +844,29 @@ void DocumentThreadableLoader::loadRequest(const ResourceRequest& request, Resou
             newRequest.setOriginRestriction(FetchRequest::NoOriginRestriction);
         ASSERT(!resource());

+        WeakPtr<DocumentThreadableLoader> self(m_weakFactory.createWeakPtr());
+
         if (request.requestContext() == WebURLRequest::RequestContextVideo || request.requestContext() == WebURLRequest::RequestContextAudio)
             setResource(RawResource::fetchMedia(newRequest, document().fetcher()));
         else if (request.requestContext() == WebURLRequest::RequestContextManifest)
             setResource(RawResource::fetchManifest(newRequest, document().fetcher()));
         else
             setResource(RawResource::fetch(newRequest, document().fetcher()));

+        // setResource() might call notifyFinished() synchronously, and thus
+        // clear() might be called and |this| may be dead here.
+        if (!self)
+            return;
+
         if (!resource()) {
             InspectorInstrumentation::documentThreadableLoaderFailedToStartLoadingForClient(m_document, m_client);
             ThreadableLoaderClient* client = m_client;
             clear();
+            // setResource() might call notifyFinished() and thus clear()
+            // synchronously, and in such cases ThreadableLoaderClient is
+            // already notified and |client| is null.
+            if (!client)
+                return;
             client->didFail(ResourceError(errorDomainBlinkInternal, 0, requestURL.getString(), "Failed to start loading."));
             // |this| may be dead here.
             return;"}

