+<!DOCTYPE HTML>
+Test for crbug.com/380885: images should not be requested in an SVG image context.<br><br>
+Image loaded via object should show a green background with a cross-origin image of Abe Lincoln:<br>
+<object id="precache" data="resources/image-wrapper.svg" width="100" height="100"></object>
+<br>
+Image loaded via img should show a green background without the remote image of Abe Lincoln:<br>
+<img id="image" src="" width="100" height="100">
+<script>
+if (window.testRunner)
+    testRunner.waitUntilDone();
+
+document.getElementById('precache').onload = function() {
+    // FIXME: crbug.com/382170 SVG onload event bug.
+    setTimeout(function() {
+        var image = document.getElementById('image');
+        image.onload = function() {
+            // FIXME: crbug.com/382170 SVG onload event bug.
+            setTimeout(function() {
+                if (window.testRunner)
+                    testRunner.notifyDone();
+            }, 20);
+        }
+        image.src = "resources/image-wrapper.svg";
+    }, 20);
+}
+
+</script>"}<_**next**_>{"sha": "2cca3b4cae0eea0f586f1862cc50b21ee80a39ae", "filename": "third_party/WebKit/LayoutTests/http/tests/security/svg-image-with-css-import-expected.html", "status": "added", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/ee281f7cac9df44fe241a37f188b28be8845ded0/third_party/WebKit/LayoutTests/http/tests/security/svg-image-with-css-import-expected.html", "raw_url": "https://github.com/chromium/chromium/raw/ee281f7cac9df44fe241a37f188b28be8845ded0/third_party/WebKit/LayoutTests/http/tests/security/svg-image-with-css-import-expected.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/svg-image-with-css-import-expected.html?ref=ee281f7cac9df44fe241a37f188b28be8845ded0", "patch": "@@ -0,0 +1,6 @@
