{"sha": "44867ef8d4f51e1ee8a3c693bfae2135a54eeb51", "filename": "net/spdy/spdy_write_queue.cc", "status": "modified", "additions": 16, "deletions": 3, "changes": 19, "blob_url": "https://github.com/chromium/chromium/blob/2025798e133f9adc49b65d017dbb5cb2c5cc74c9/net/spdy/spdy_write_queue.cc", "raw_url": "https://github.com/chromium/chromium/raw/2025798e133f9adc49b65d017dbb5cb2c5cc74c9/net/spdy/spdy_write_queue.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/spdy/spdy_write_queue.cc?ref=2025798e133f9adc49b65d017dbb5cb2c5cc74c9", "patch": "@@ -5,8 +5,10 @@
