+<!DOCTYPE HTML PUBLIC "-//IETF//DTD HTML//EN">
+<html>
+<head>
+<script src="../../resources/js-test.js"></script>
+</head>
+<body id="body">
+
+<div id="console"></div>
+
+<script>
+
+    if (window.internals)
+        window.internals.enableMockSpeechSynthesizer(document);
+
+    description("This tests that there isn't a crash if the utterance object is garbage-collected before speaking finishes.");
+
+    if (window.testRunner)
+        testRunner.waitUntilDone();
+
+    window.jsTestIsAsync = true;
+
+    speechSynthesis.speak(new SpeechSynthesisUtterance(" "));
+    gc();
+
+    window.setInterval(function() {
+       if (!speechSynthesis.speaking)
+           finishJSTest();
+    }, 10);
+
+</script>
+
+</body>
+</html>"}<_**next**_>{"sha": "d5b5608d6e26ef6985239cf939dd9b99d8a532b8", "filename": "third_party/WebKit/Source/modules/speech/SpeechSynthesis.cpp", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/9a3dbf43f97aa7cb6b4399f9b11ce1de20f0680f/third_party/WebKit/Source/modules/speech/SpeechSynthesis.cpp", "raw_url": "https://github.com/chromium/chromium/raw/9a3dbf43f97aa7cb6b4399f9b11ce1de20f0680f/third_party/WebKit/Source/modules/speech/SpeechSynthesis.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/modules/speech/SpeechSynthesis.cpp?ref=9a3dbf43f97aa7cb6b4399f9b11ce1de20f0680f", "patch": "@@ -153,6 +153,10 @@ void SpeechSynthesis::handleSpeakingCompleted(SpeechSynthesisUtterance* utteranc
