+PASS if not crashed."}<_**next**_>{"sha": "35cece8d5318de3c9503a5832bdbcc0c8300ce9d", "filename": "third_party/WebKit/LayoutTests/fast/dom/HTMLBodyElement/body-inserting-iframe-crash.html", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/chromium/chromium/blob/d22bd7ecd1cc576a1a586ee59d5e08d7eee6cdf3/third_party/WebKit/LayoutTests/fast/dom/HTMLBodyElement/body-inserting-iframe-crash.html", "raw_url": "https://github.com/chromium/chromium/raw/d22bd7ecd1cc576a1a586ee59d5e08d7eee6cdf3/third_party/WebKit/LayoutTests/fast/dom/HTMLBodyElement/body-inserting-iframe-crash.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/dom/HTMLBodyElement/body-inserting-iframe-crash.html?ref=d22bd7ecd1cc576a1a586ee59d5e08d7eee6cdf3", "patch": "@@ -0,0 +1,25 @@
+<script>
+if (window.testRunner)
+    testRunner.dumpAsText();
+
+var iframe = null;
+
+function start() {
+    iframe = document.createElement('iframe');
+    iframe.setAttribute('marginwidth', 1);
+    document.body.appendChild(iframe);
+
+    var bodyInFrame = document.createElement('body');
+    bodyInFrame.addEventListener('DOMSubtreeModified', removeIframe);
+    iframe.contentDocument.documentElement.appendChild(bodyInFrame);
+    document.body.innerHTML = 'PASS if not crashed.';
+}
+
+function removeIframe() {
+    iframe.parentNode.removeChild(iframe);
+    iframe = null;
+    gc();
+}
+</script>
+<body onload="start()">
+</body>"}<_**next**_>{"sha": "f7e7f72afe349824fac5e92280fb4ffe020092a7", "filename": "third_party/WebKit/Source/core/html/HTMLBodyElement.cpp", "status": "modified", "additions": 18, "deletions": 16, "changes": 34, "blob_url": "https://github.com/chromium/chromium/blob/d22bd7ecd1cc576a1a586ee59d5e08d7eee6cdf3/third_party/WebKit/Source/core/html/HTMLBodyElement.cpp", "raw_url": "https://github.com/chromium/chromium/raw/d22bd7ecd1cc576a1a586ee59d5e08d7eee6cdf3/third_party/WebKit/Source/core/html/HTMLBodyElement.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/html/HTMLBodyElement.cpp?ref=d22bd7ecd1cc576a1a586ee59d5e08d7eee6cdf3", "patch": "@@ -155,22 +155,24 @@ void HTMLBodyElement::parseAttribute(const QualifiedName& name, const AtomicStri
 Node::InsertionNotificationRequest HTMLBodyElement::insertedInto(ContainerNode* insertionPoint)
 {
     HTMLElement::insertedInto(insertionPoint);
-    if (insertionPoint->inDocument()) {
-        // FIXME: It's surprising this is web compatible since it means a marginwidth
-        // and marginheight attribute can magically appear on the <body> of all documents
-        // embedded through <iframe> or <frame>.
-        Element* ownerElement = document().ownerElement();
-        if (isHTMLFrameElementBase(ownerElement)) {
-            HTMLFrameElementBase& ownerFrameElement = toHTMLFrameElementBase(*ownerElement);
-            int marginWidth = ownerFrameElement.marginWidth();
-            if (marginWidth != -1)
-                setIntegralAttribute(marginwidthAttr, marginWidth);
-            int marginHeight = ownerFrameElement.marginHeight();
-            if (marginHeight != -1)
-                setIntegralAttribute(marginheightAttr, marginHeight);
-        }
-    }
-    return InsertionDone;
+    return InsertionShouldCallDidNotifySubtreeInsertions;
+}
+
+void HTMLBodyElement::didNotifySubtreeInsertionsToDocument()
+{
+    // FIXME: It's surprising this is web compatible since it means a
+    // marginwidth and marginheight attribute can magically appear on the <body>
+    // of all documents embedded through <iframe> or <frame>.
+    Element* ownerElement = document().ownerElement();
+    if (!isHTMLFrameElementBase(ownerElement))
+        return;
+    HTMLFrameElementBase& ownerFrameElement = toHTMLFrameElementBase(*ownerElement);
+    int marginWidth = ownerFrameElement.marginWidth();
+    int marginHeight = ownerFrameElement.marginHeight();
+    if (marginWidth != -1)
+        setIntegralAttribute(marginwidthAttr, marginWidth);
+    if (marginHeight != -1)
