+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/browser/ui/webui/settings/settings_clear_browsing_data_handler.h"
+
+#include "base/metrics/histogram_macros.h"
+#include "base/metrics/sparse_histogram.h"
+#include "base/prefs/pref_service.h"
+#include "chrome/browser/browsing_data/browsing_data_helper.h"
+#include "chrome/common/pref_names.h"
+#include "content/public/browser/web_ui.h"
+
+namespace settings {
+
+ClearBrowsingDataHandler::ClearBrowsingDataHandler(content::WebUI* webui)
+    : remover_(NULL) {
+  PrefService* prefs = Profile::FromWebUI(webui)->GetPrefs();
+  clear_plugin_lso_data_enabled_.Init(prefs::kClearPluginLSODataEnabled, prefs);
+  pepper_flash_settings_enabled_.Init(prefs::kPepperFlashSettingsEnabled,
+                                      prefs);
+  allow_deleting_browser_history_.Init(
+      prefs::kAllowDeletingBrowserHistory, prefs,
+      base::Bind(&ClearBrowsingDataHandler::OnBrowsingHistoryPrefChanged,
+                 base::Unretained(this)));
+}
+
+ClearBrowsingDataHandler::~ClearBrowsingDataHandler() {
+  if (remover_)
+    remover_->RemoveObserver(this);
+}
+
+void ClearBrowsingDataHandler::RegisterMessages() {
+  web_ui()->RegisterMessageCallback(
+      "performClearBrowserData",
+      base::Bind(&ClearBrowsingDataHandler::HandleClearBrowserData,
+                 base::Unretained(this)));
+}
+
+void ClearBrowsingDataHandler::HandleClearBrowserData(
+    const base::ListValue* args) {
+  // We should never be called when the previous clearing has not yet finished.
+  CHECK(!remover_);
+
+  Profile* profile = Profile::FromWebUI(web_ui());
+  PrefService* prefs = profile->GetPrefs();
+
+  int site_data_mask = BrowsingDataRemover::REMOVE_SITE_DATA;
+  // Don't try to clear LSO data if it's not supported.
+  if (!*clear_plugin_lso_data_enabled_)
+    site_data_mask &= ~BrowsingDataRemover::REMOVE_PLUGIN_DATA;
+
+  int remove_mask = 0;
+  if (*allow_deleting_browser_history_) {
+    if (prefs->GetBoolean(prefs::kDeleteBrowsingHistory))
+      remove_mask |= BrowsingDataRemover::REMOVE_HISTORY;
+    if (prefs->GetBoolean(prefs::kDeleteDownloadHistory))
+      remove_mask |= BrowsingDataRemover::REMOVE_DOWNLOADS;
+  }
+
+  if (prefs->GetBoolean(prefs::kDeleteCache))
+    remove_mask |= BrowsingDataRemover::REMOVE_CACHE;
+
+  int origin_mask = 0;
+  if (prefs->GetBoolean(prefs::kDeleteCookies)) {
+    remove_mask |= site_data_mask;
+    origin_mask |= BrowsingDataHelper::UNPROTECTED_WEB;
+  }
+
+  if (prefs->GetBoolean(prefs::kDeletePasswords))
+    remove_mask |= BrowsingDataRemover::REMOVE_PASSWORDS;
+
+  if (prefs->GetBoolean(prefs::kDeleteFormData))
+    remove_mask |= BrowsingDataRemover::REMOVE_FORM_DATA;
+
+  // Clearing Content Licenses is only supported in Pepper Flash.
+  if (prefs->GetBoolean(prefs::kDeauthorizeContentLicenses) &&
+      *pepper_flash_settings_enabled_) {
+    remove_mask |= BrowsingDataRemover::REMOVE_CONTENT_LICENSES;
+  }
+
+  if (prefs->GetBoolean(prefs::kDeleteHostedAppsData)) {
+    remove_mask |= site_data_mask;
+    origin_mask |= BrowsingDataHelper::PROTECTED_WEB;
+  }
+
+  // Record the deletion of cookies and cache.
+  BrowsingDataRemover::CookieOrCacheDeletionChoice choice =
+      BrowsingDataRemover::NEITHER_COOKIES_NOR_CACHE;
+  if (prefs->GetBoolean(prefs::kDeleteCookies)) {
+    choice = prefs->GetBoolean(prefs::kDeleteCache)
+                 ? BrowsingDataRemover::BOTH_COOKIES_AND_CACHE
+                 : BrowsingDataRemover::ONLY_COOKIES;
+  } else if (prefs->GetBoolean(prefs::kDeleteCache)) {
+    choice = BrowsingDataRemover::ONLY_CACHE;
+  }
+
+  UMA_HISTOGRAM_ENUMERATION(
+      "History.ClearBrowsingData.UserDeletedCookieOrCacheFromDialog", choice,
+      BrowsingDataRemover::MAX_CHOICE_VALUE);
+
+  // Record the circumstances under which passwords are deleted.
+  if (prefs->GetBoolean(prefs::kDeletePasswords)) {
+    static const char* other_types[] = {
+        prefs::kDeleteBrowsingHistory,
+        prefs::kDeleteDownloadHistory,
+        prefs::kDeleteCache,
+        prefs::kDeleteCookies,
+        prefs::kDeleteFormData,
+        prefs::kDeleteHostedAppsData,
+        prefs::kDeauthorizeContentLicenses,
+    };
+    static size_t num_other_types = arraysize(other_types);
+    int checked_other_types = std::count_if(
+        other_types, other_types + num_other_types,
+        [prefs](const std::string& pref) { return prefs->GetBoolean(pref); });
+    UMA_HISTOGRAM_SPARSE_SLOWLY(
+        "History.ClearBrowsingData.PasswordsDeletion.AdditionalDatatypesCount",
+        checked_other_types);
+  }
+
+  // BrowsingDataRemover deletes itself when done.
+  int period_selected = prefs->GetInteger(prefs::kDeleteTimePeriod);
+  remover_ = BrowsingDataRemover::CreateForPeriod(
+      profile, static_cast<BrowsingDataRemover::TimePeriod>(period_selected));
+  remover_->AddObserver(this);
+  remover_->Remove(remove_mask, origin_mask);
+}
+
+void ClearBrowsingDataHandler::OnBrowsingDataRemoverDone() {
+  // No need to remove ourselves as an observer as BrowsingDataRemover deletes
+  // itself after we return.
+  remover_ = NULL;
+  web_ui()->CallJavascriptFunction("SettingsClearBrowserData.doneClearing");
+}
+
+void ClearBrowsingDataHandler::OnBrowsingHistoryPrefChanged() {
+  web_ui()->CallJavascriptFunction(
+      "SettingsClearBrowserData.setAllowDeletingHistory",
+      base::FundamentalValue(*allow_deleting_browser_history_));
+}
+
+}  // namespace settings"}<_**next**_>{"sha": "4b42e61da5170152653ccc82061e551cc80b54d8", "filename": "chrome/browser/ui/webui/settings/settings_clear_browsing_data_handler.h", "status": "added", "additions": 65, "deletions": 0, "changes": 65, "blob_url": "https://github.com/chromium/chromium/blob/31b2ef216cb19fb5cec60eb507d3b2b0d30cd648/chrome/browser/ui/webui/settings/settings_clear_browsing_data_handler.h", "raw_url": "https://github.com/chromium/chromium/raw/31b2ef216cb19fb5cec60eb507d3b2b0d30cd648/chrome/browser/ui/webui/settings/settings_clear_browsing_data_handler.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/ui/webui/settings/settings_clear_browsing_data_handler.h?ref=31b2ef216cb19fb5cec60eb507d3b2b0d30cd648", "patch": "@@ -0,0 +1,65 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef CHROME_BROWSER_UI_WEBUI_SETTINGS_SETTINGS_CLEAR_BROWSING_DATA_HANDLER_H_
+#define CHROME_BROWSER_UI_WEBUI_SETTINGS_SETTINGS_CLEAR_BROWSING_DATA_HANDLER_H_
+
+#include "base/macros.h"
+#include "base/memory/scoped_vector.h"
+#include "base/prefs/pref_member.h"
+#include "chrome/browser/browsing_data/browsing_data_remover.h"
+#include "chrome/browser/profiles/profile.h"
+#include "chrome/browser/ui/webui/settings/md_settings_ui.h"
+
+namespace base {
+class ListValue;
+}
+
+namespace content {
+class WebUI;
+}
+
+namespace settings {
+
+// Chrome browser startup settings handler.
+class ClearBrowsingDataHandler : public SettingsPageUIHandler,
+                                 public BrowsingDataRemover::Observer {
+ public:
+  explicit ClearBrowsingDataHandler(content::WebUI* webui);
+  ~ClearBrowsingDataHandler() override;
+
+  // OptionsPageUIHandler:
+  void RegisterMessages() override;
+
+ private:
+  // Javascript callback to start clearing data.
+  void HandleClearBrowserData(const base::ListValue* value);
+
+  // BrowsingDataRemover::Observer implementation.
+  // Re-enables clear button once all requested data has been removed.
+  void OnBrowsingDataRemoverDone() override;
+
+  // Updates UI when the pref to allow clearing history changes.
+  virtual void OnBrowsingHistoryPrefChanged();
+
+  // If non-null it means removal is in progress. BrowsingDataRemover takes care
+  // of deleting itself when done.
+  BrowsingDataRemover* remover_;
+
+  // Keeps track of whether clearing LSO data is supported.
+  BooleanPrefMember clear_plugin_lso_data_enabled_;
+
+  // Keeps track of whether Pepper Flash is enabled and thus Flapper-specific
+  // settings and removal options (e.g. Content Licenses) are available.
+  BooleanPrefMember pepper_flash_settings_enabled_;
+
+  // Keeps track of whether deleting browsing history and downloads is allowed.
+  BooleanPrefMember allow_deleting_browser_history_;
+
+  DISALLOW_COPY_AND_ASSIGN(ClearBrowsingDataHandler);
+};
+
+}  // namespace settings
+
+#endif  // CHROME_BROWSER_UI_WEBUI_SETTINGS_SETTINGS_CLEAR_BROWSING_DATA_HANDLER_H_"}<_**next**_>{"sha": "4a4222c930001a8f3136091e8712be670fc491cc", "filename": "chrome/chrome_browser_ui.gypi", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/31b2ef216cb19fb5cec60eb507d3b2b0d30cd648/chrome/chrome_browser_ui.gypi", "raw_url": "https://github.com/chromium/chromium/raw/31b2ef216cb19fb5cec60eb507d3b2b0d30cd648/chrome/chrome_browser_ui.gypi", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/chrome_browser_ui.gypi?ref=31b2ef216cb19fb5cec60eb507d3b2b0d30cd648", "patch": "@@ -1922,6 +1922,8 @@
