{"sha": "4ed8a4c72df7967a708e73ec9c53c3d075867714", "filename": "content/browser/frame_host/render_frame_host_impl.cc", "status": "modified", "additions": 21, "deletions": 0, "changes": 21, "blob_url": "https://github.com/chromium/chromium/blob/da9a32b9e282c1653bb6b5c1b8c89a1970905f21/content/browser/frame_host/render_frame_host_impl.cc", "raw_url": "https://github.com/chromium/chromium/raw/da9a32b9e282c1653bb6b5c1b8c89a1970905f21/content/browser/frame_host/render_frame_host_impl.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/frame_host/render_frame_host_impl.cc?ref=da9a32b9e282c1653bb6b5c1b8c89a1970905f21", "patch": "@@ -18,6 +18,7 @@
 #include "content/common/frame_messages.h"
 #include "content/common/input_messages.h"
 #include "content/common/inter_process_time_ticks_converter.h"
+#include "content/common/swapped_out_messages.h"
 #include "content/public/browser/browser_thread.h"
 #include "content/public/browser/content_browser_client.h"
 #include "content/public/browser/render_process_host.h"
@@ -228,6 +229,26 @@ bool RenderFrameHostImpl::Send(IPC::Message* message) {
 }

 bool RenderFrameHostImpl::OnMessageReceived(const IPC::Message &msg) {
+  // Filter out most IPC messages if this renderer is swapped out.
+  // We still want to handle certain ACKs to keep our state consistent.
+  // TODO(nasko): Only check RenderViewHost state, as this object's own state
+  // isn't yet properly updated. Transition this check once the swapped out
+  // state is correct in RenderFrameHost itself.
+  if (render_view_host_->IsSwappedOut()) {
+    if (!SwappedOutMessages::CanHandleWhileSwappedOut(msg)) {
+      // If this is a synchronous message and we decided not to handle it,
+      // we must send an error reply, or else the renderer will be stuck
+      // and won't respond to future requests.
+      if (msg.is_sync()) {
+        IPC::Message* reply = IPC::SyncMessage::GenerateReply(&msg);
+        reply->set_reply_error();
+        Send(reply);
+      }
+      // Don't continue looking for someone to handle it.
+      return true;
+    }
+  }
+
   if (delegate_->OnMessageReceived(this, msg))
     return true;
 "}

