+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef PaintChunk_h
+#define PaintChunk_h
+
+#include "platform/graphics/paint/PaintProperties.h"
+#include <iosfwd>
+
+namespace blink {
+
+// A contiguous sequence of drawings with common paint properties.
+//
+// This is expected to be owned by the paint artifact which also owns the
+// related drawings.
+//
+// This is a Slimming Paint v2 class.
+struct PaintChunk {
+    PaintChunk() : beginIndex(0), endIndex(0) { }
+    PaintChunk(unsigned begin, unsigned end, const PaintProperties& props)
+        : beginIndex(begin), endIndex(end), properties(props) { }
+
+    // Index of the first drawing in this chunk.
+    unsigned beginIndex;
+
+    // Index of the first drawing not in this chunk, so that there are
+    // |endIndex - beginIndex| drawings in the chunk.
+    unsigned endIndex;
+
+    // The paint properties which apply to this chunk.
+    PaintProperties properties;
+};
+
+inline bool operator==(const PaintChunk& a, const PaintChunk& b)
+{
+    return a.beginIndex == b.beginIndex
+        && a.endIndex == b.endIndex
+        && a.properties == b.properties;
+}
+
+inline bool operator!=(const PaintChunk& a, const PaintChunk& b)
+{
+    return !(a == b);
+}
+
+// Redeclared here to avoid ODR issues.
+// See platform/testing/PaintPrinters.h.
+void PrintTo(const PaintChunk&, std::ostream*);
+
+} // namespace blink
+
+#endif // PaintChunk_h"}<_**next**_>{"sha": "2616ccaef8dbd931ed3f7f535544cd743ad9600c", "filename": "third_party/WebKit/Source/platform/graphics/paint/PaintChunker.cpp", "status": "added", "additions": 67, "deletions": 0, "changes": 67, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintChunker.cpp", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintChunker.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/graphics/paint/PaintChunker.cpp?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,67 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "config.h"
+#include "platform/graphics/paint/PaintChunker.h"
+
+#include "platform/RuntimeEnabledFeatures.h"
+
+namespace blink {
+
+PaintChunker::PaintChunker()
+{
+}
+
+PaintChunker::~PaintChunker()
+{
+}
+
+void PaintChunker::updateCurrentPaintProperties(const PaintProperties& properties)
+{
+    ASSERT(RuntimeEnabledFeatures::slimmingPaintV2Enabled());
+
+    m_currentProperties = properties;
+}
+
+void PaintChunker::incrementDisplayItemIndex()
+{
+    ASSERT(RuntimeEnabledFeatures::slimmingPaintV2Enabled());
+
+    if (m_chunks.isEmpty()) {
+        PaintChunk newChunk(0, 1, m_currentProperties);
+        m_chunks.append(newChunk);
+        return;
+    }
+
+    auto& lastChunk = m_chunks.last();
+    if (m_currentProperties == lastChunk.properties) {
+        lastChunk.endIndex++;
+        return;
+    }
+
+    PaintChunk newChunk(lastChunk.endIndex, lastChunk.endIndex + 1, m_currentProperties);
+    m_chunks.append(newChunk);
+}
+
+void PaintChunker::decrementDisplayItemIndex()
+{
+    ASSERT(RuntimeEnabledFeatures::slimmingPaintV2Enabled());
+    ASSERT(!m_chunks.isEmpty());
+
+    auto& lastChunk = m_chunks.last();
+    if ((lastChunk.endIndex - lastChunk.beginIndex) > 1)
+        lastChunk.endIndex--;
+    else
+        m_chunks.removeLast();
+}
+
+Vector<PaintChunk> PaintChunker::releasePaintChunks()
+{
+    Vector<PaintChunk> chunks;
+    chunks.swap(m_chunks);
+    m_currentProperties = PaintProperties();
+    return chunks;
+}
+
+} // namespace blink"}<_**next**_>{"sha": "33f5a7af3ef67a63ce6aebbd094950b6689fcace", "filename": "third_party/WebKit/Source/platform/graphics/paint/PaintChunker.h", "status": "added", "additions": 41, "deletions": 0, "changes": 41, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintChunker.h", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintChunker.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/graphics/paint/PaintChunker.h?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,41 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef PaintChunker_h
+#define PaintChunker_h
+
+#include "platform/PlatformExport.h"
+#include "platform/graphics/paint/PaintChunk.h"
+#include "platform/graphics/paint/PaintProperties.h"
+#include "wtf/Vector.h"
+
+namespace blink {
+
+// Accepts information about changes to |PaintProperties| as drawings are
+// accumulated, and produces a series of paint chunks: contiguous ranges of the
+// display list with identical |PaintProperties|.
+class PLATFORM_EXPORT PaintChunker {
+public:
+    PaintChunker();
+    ~PaintChunker();
+
+    bool isInInitialState() const { return m_chunks.isEmpty() && m_currentProperties == PaintProperties(); }
+
+    void updateCurrentPaintProperties(const PaintProperties&);
+
+    void incrementDisplayItemIndex();
+    void decrementDisplayItemIndex();
+
+    // Releases the generated paint chunk list and resets the state of this
+    // object.
+    Vector<PaintChunk> releasePaintChunks();
+
+private:
+    Vector<PaintChunk> m_chunks;
+    PaintProperties m_currentProperties;
+};
+
+} // namespace blink
+
+#endif // PaintChunker_h"}<_**next**_>{"sha": "38be4a4e2c804612d0a7c9e67f5c6d0b1b98715b", "filename": "third_party/WebKit/Source/platform/graphics/paint/PaintChunkerTest.cpp", "status": "added", "additions": 85, "deletions": 0, "changes": 85, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintChunkerTest.cpp", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintChunkerTest.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/graphics/paint/PaintChunkerTest.cpp?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,85 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "config.h"
+#include "platform/graphics/paint/PaintChunker.h"
+
+#include "platform/RuntimeEnabledFeatures.h"
+#include <gmock/gmock.h>
+#include <gtest/gtest.h>
+
+using testing::ElementsAre;
+
+namespace blink {
+namespace {
+
+static PaintProperties samplePaintProperties() { return PaintProperties(); }
+
+class PaintChunkerTest : public testing::Test {
+protected:
+    void SetUp() override
+    {
+        RuntimeEnabledFeatures::setSlimmingPaintV2Enabled(true);
+    }
+
+    void TearDown() override
+    {
+        m_featuresBackup.restore();
+    }
+
+private:
+    RuntimeEnabledFeatures::Backup m_featuresBackup;
+};
+
+TEST_F(PaintChunkerTest, Empty)
+{
+    Vector<PaintChunk> chunks = PaintChunker().releasePaintChunks();
+    ASSERT_TRUE(chunks.isEmpty());
+}
+
+TEST_F(PaintChunkerTest, SingleNonEmptyRange)
+{
+    PaintChunker chunker;
+    chunker.updateCurrentPaintProperties(samplePaintProperties());
+    chunker.incrementDisplayItemIndex();
+    chunker.incrementDisplayItemIndex();
+    Vector<PaintChunk> chunks = chunker.releasePaintChunks();
+
+    EXPECT_THAT(chunks, ElementsAre(
+        PaintChunk(0, 2, samplePaintProperties())));
+}
+
+TEST_F(PaintChunkerTest, SamePropertiesTwiceCombineIntoOneChunk)
+{
+    PaintChunker chunker;
+    chunker.updateCurrentPaintProperties(samplePaintProperties());
+    chunker.incrementDisplayItemIndex();
+    chunker.incrementDisplayItemIndex();
+    chunker.updateCurrentPaintProperties(samplePaintProperties());
+    chunker.incrementDisplayItemIndex();
+    Vector<PaintChunk> chunks = chunker.releasePaintChunks();
+
+    EXPECT_THAT(chunks, ElementsAre(
+        PaintChunk(0, 3, samplePaintProperties())));
+}
+
+TEST_F(PaintChunkerTest, CanRewindDisplayItemIndex)
+{
+    PaintChunker chunker;
+    chunker.updateCurrentPaintProperties(samplePaintProperties());
+    chunker.incrementDisplayItemIndex();
+    chunker.incrementDisplayItemIndex();
+    chunker.decrementDisplayItemIndex();
+    chunker.incrementDisplayItemIndex();
+    Vector<PaintChunk> chunks = chunker.releasePaintChunks();
+
+    EXPECT_THAT(chunks, ElementsAre(
+        PaintChunk(0, 2, samplePaintProperties())));
+}
+
+// TODO(jbroman): Add more tests one it is possible for there to be two distinct
+// PaintProperties.
+
+} // namespace
+} // namespace blink"}<_**next**_>{"sha": "69a6651de7ed9dc39f562fcb2b79e711512dbbb6", "filename": "third_party/WebKit/Source/platform/graphics/paint/PaintProperties.h", "status": "added", "additions": 36, "deletions": 0, "changes": 36, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintProperties.h", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/PaintProperties.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/graphics/paint/PaintProperties.h?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,36 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef PaintProperties_h
+#define PaintProperties_h
+
+#include <iosfwd>
+
+namespace blink {
+
+// The set of paint properties applying to a |PaintChunk|.
+// In particular, this does not mean properties like background-color, but
+// rather the hierarchy of transforms, clips, effects, etc. that apply to a
+// contiguous chunk of drawings.
+struct PaintProperties {
+    // TODO(jbroman): Add actual properties.
+};
+
+inline bool operator==(const PaintProperties&, const PaintProperties&)
+{
+    return true;
+}
+
+inline bool operator!=(const PaintProperties& a, const PaintProperties& b)
+{
+    return !(a == b);
+}
+
+// Redeclared here to avoid ODR issues.
+// See platform/testing/PaintPrinters.h.
+void PrintTo(const PaintProperties&, std::ostream*);
+
+} // namespace blink
+
+#endif // PaintProperties_h"}<_**next**_>{"sha": "2de5acaa676fe4971a447ad98f86edca862c1216", "filename": "third_party/WebKit/Source/platform/graphics/paint/README.md", "status": "added", "additions": 115, "deletions": 0, "changes": 115, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/README.md", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/graphics/paint/README.md", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/graphics/paint/README.md?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,115 @@
+# Platform paint code
+
+This directory contains the implementation of display lists and display
+list-based painting, except for code which requires knowledge of `core/`
+concepts, such as DOM elements and layout objects.
+
+This code is owned by the [paint team][paint-team-site].
+
+Slimming Paint v2 is currently being implemented. Unlike Slimming Paint v1, SPv2
+represents its paint artifact not as a flat display list, but as a list of
+drawings, and a list of paint chunks, stored together.
+
+This document explains the SPv2 world as it develops, not the SPv1 world it
+replaces.
+
+[paint-team-site]: https://www.chromium.org/developers/paint-team
+
+## Paint artifact
+
+The SPv2 paint artifact consists of a list of display items (ideally mostly or
+all drawings), partitioned into *paint chunks* which define certain *paint
+properties* which affect how the content should be drawn or composited.
+
+## Paint properties
+
+Paint properties define characteristics of how a paint chunk should be drawn,
+such as the transform it should be drawn with. To enable efficient updates,
+a chunk's paint properties are described hierarchically. For instance, each
+chunk is associated with a transform node, whose matrix should be multiplied by
+its ancestor transform nodes in order to compute the final transformation matrix
+to the screen.
+
+*** note
+Support for all paint properties has yet to be implemented in SPv2.
+***
+
+*** aside
+TODO(jbroman): Explain the semantics of transforms, clips, scrolls and effects
+as support for them is added to SPv2.
+***
+
+## Display items
+
+A display item is the smallest unit of a display list in Blink. Each display
+item is identified by an ID consisting of:
+
+* an opaque pointer to the *display item client* that produced it
+* a type (from the `DisplayItem::Type` enum)
+* a scope number
+
+*** aside
+TODO(jbroman): Explain scope numbers.
+***
+
+In practice, display item clients are generally subclasses of `LayoutObject`,
+but can be other Blink objects which get painted, such as inline boxes and drag
+images.
+
+*** note
+It is illegal for there to be two drawings with the same ID in a display item
+list.
+***
+
+Generally, clients of this code should use stack-allocated recorder classes to
+emit display items to a `DisplayItemList` (using `GraphicsContext`).
+
+### Standalone display items
+
+#### [CachedDisplayItem](CachedDisplayItem.h)
+
+The type `DisplayItem::CachedSubsequence` indicates that the previous frame's
+display item list contains a contiguous sequence of display items which should
+be reused in place of this `CachedDisplayItem`.
+
+*** note
+Support for cached subsequences for SPv2 is planned, but not yet fully
+implemented.
+***
+
+Other cached display items refer to a single `DrawingDisplayItem` with a
+corresponding type which should be reused in place of this `CachedDisplayItem`.
+
+#### [DrawingDisplayItem](DrawingDisplayItem.h)
+
+Holds an `SkPicture` which contains the Skia commands required to draw some atom
+of content.
+
+### Paired begin/end display items
+
+*** aside
+TODO(jbroman): Describe how these work, once we've worked out what happens to
+them in SPv2.
+***
+
+## Display item list
+
+Callers use `GraphicsContext` (via its drawing methods, and its
+`displayItemList()` accessor) and scoped recorder classes, which emit items into
+a `DisplayItemList`.
+
+`DisplayItemList` is responsible for producing the paint artifact. It contains
+the *current* paint artifact, which is always complete (i.e. it has no
+`CachedDisplayItem` objects), and *new* display items and paint chunks, which
+are added as content is painted.
+
+When the new display items have been populated, clients call
+`commitNewDisplayItems`, which merges the previous artifact with the new data,
+producing a new paint artifact, where `CachedDisplayItem` objects have been
+replaced with the cached content from the previous artifact.
+
+At this point, the paint artifact is ready to be drawn or composited.
+
+*** aside
+TODO(jbroman): Explain invalidation.
+***"}<_**next**_>{"sha": "16d4667e2333eda925e94af0267a608abcb5cbe9", "filename": "third_party/WebKit/Source/platform/testing/PaintPrinters.cpp", "status": "added", "additions": 28, "deletions": 0, "changes": 28, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/testing/PaintPrinters.cpp", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/testing/PaintPrinters.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/testing/PaintPrinters.cpp?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,28 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "config.h"
+#include "platform/testing/PaintPrinters.h"
+
+#include "platform/graphics/paint/PaintChunk.h"
+#include "platform/graphics/paint/PaintProperties.h"
+#include <ostream> // NOLINT
+
+namespace blink {
+
+void PrintTo(const PaintChunk& chunk, std::ostream* os)
+{
+    *os << "PaintChunk(begin=" << chunk.beginIndex
+        << ", end=" << chunk.endIndex
+        << ", props=";
+    PrintTo(chunk.properties, os);
+    *os << ")";
+}
+
+void PrintTo(const PaintProperties& properties, std::ostream* os)
+{
+    *os << "PaintProperties()";
+}
+
+} // namespace blink"}<_**next**_>{"sha": "31f7ddcc41b7d2ed9198817fd91d7655c24a5b2a", "filename": "third_party/WebKit/Source/platform/testing/PaintPrinters.h", "status": "added", "additions": 31, "deletions": 0, "changes": 31, "blob_url": "https://github.com/chromium/chromium/blob/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/testing/PaintPrinters.h", "raw_url": "https://github.com/chromium/chromium/raw/55136969558bd7d8b3456cd1447442a5425fd9df/third_party/WebKit/Source/platform/testing/PaintPrinters.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/platform/testing/PaintPrinters.h?ref=55136969558bd7d8b3456cd1447442a5425fd9df", "patch": "@@ -0,0 +1,31 @@
+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef PaintPrinters_h
+#define PaintPrinters_h
+
+#include <iosfwd>
+
+namespace blink {
+
+struct PaintChunk;
+struct PaintProperties;
+
+// GTest print support for platform paint classes.
+//
+// To avoid ODR violations, these should also be declared in the respective
+// headers defining these types. This is required because otherwise a template
+// instantiation may be instantiated differently, depending on whether this
+// declaration is found.
+//
+// As a result, it is not necessary to include this file in tests in order to
+// use these printers. If, however, you get a link error about these symbols,
+// you need to make sure the blink_platform_test_support target is linked in
+// your unit test binary.
+void PrintTo(const PaintChunk&, std::ostream*);
+void PrintTo(const PaintProperties&, std::ostream*);
+
+} // namespace blink
+
+#endif // PaintPrinters_h"}

