{"sha": "36b146290b63fb972ff8b1d6d9fad1d7e9022cb4", "filename": "third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent-expected.txt", "status": "added", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/chromium/chromium/blob/1842dcb929820618efbc5fabda7c82d08846c25a/third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/1842dcb929820618efbc5fabda7c82d08846c25a/third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent-expected.txt?ref=1842dcb929820618efbc5fabda7c82d08846c25a", "patch": "@@ -0,0 +1,9 @@
+
+PASS: targetWindow.dispatchEvent(new CustomEvent("click")); should have thrown an exception, and did: SecurityError: Blocked a frame with origin "http://127.0.0.1:8000" from accessing a cross-origin frame.
+PASS: window.dispatchEvent.call(targetWindow, new CustomEvent("click")); should have thrown an exception, and did: SecurityError: Failed to execute 'dispatchEvent' on 'EventTarget': Blocked a frame with origin "http://127.0.0.1:8000" from accessing a cross-origin frame.
+
+
+--------
+Frame: '<!--framePath //<!--frame0-->-->'
+--------
+"}<_**next**_>{"sha": "08af109fed54e6c65fc13ccf5c8a91a98157c59b", "filename": "third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent.html", "status": "added", "additions": 33, "deletions": 0, "changes": 33, "blob_url": "https://github.com/chromium/chromium/blob/1842dcb929820618efbc5fabda7c82d08846c25a/third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent.html", "raw_url": "https://github.com/chromium/chromium/raw/1842dcb929820618efbc5fabda7c82d08846c25a/third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/cross-frame-access-dispatchEvent.html?ref=1842dcb929820618efbc5fabda7c82d08846c25a", "patch": "@@ -0,0 +1,33 @@
+<!DOCTYPE html>
+<html>
+<head>
+    <script src="resources/cross-frame-access.js"></script>
+    <script>
+        if (window.testRunner) {
+            testRunner.dumpAsText();
+            testRunner.dumpChildFramesAsText();
+            testRunner.waitUntilDone();
+        }
+
+        receiver = function(e) {
+            if (e.data == "LOADED")
+                deleteTest();
+        };
+
+        var targetWindow;
+        addEventListener('message', function () {
+            targetWindow = document.querySelector('iframe').contentWindow;
+            shouldThrowException('targetWindow.dispatchEvent(new CustomEvent("click"));');
+            shouldThrowException('window.dispatchEvent.call(targetWindow, new CustomEvent("click"));');
+            
+            if (window.testRunner)
+                testRunner.notifyDone();
+        });
+
+    </script>
+</head>
+<body>
+    <iframe src="http://localhost:8000/security/resources/cross-frame-iframe-for-delete-test.html"></iframe>
+    <pre id="console"></pre>
+</body>
+</html>"}<_**next**_>{"sha": "6031191a8d251bea16f17aab8e9cad35657bb40d", "filename": "third_party/WebKit/Source/bindings/scripts/code_generator_v8.pm", "status": "modified", "additions": 10, "deletions": 5, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/1842dcb929820618efbc5fabda7c82d08846c25a/third_party/WebKit/Source/bindings/scripts/code_generator_v8.pm", "raw_url": "https://github.com/chromium/chromium/raw/1842dcb929820618efbc5fabda7c82d08846c25a/third_party/WebKit/Source/bindings/scripts/code_generator_v8.pm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/bindings/scripts/code_generator_v8.pm?ref=1842dcb929820618efbc5fabda7c82d08846c25a", "patch": "@@ -2468,6 +2468,7 @@ sub GenerateFunction
