+<!DOCTYPE html>
+<html>
+This test passes if it does not crash and 'PASS' is printed.<br/>
+<img id="crash" src="resources/draw-image-crash.svg"></img>
+<script>
+if (window.testRunner)
+  testRunner.waitUntilDone();
+
+setTimeout(function() {
+  if (location.hash == '#done') {
+    document.write('PASS');
+    if (window.testRunner) {
+      testRunner.notifyDone();
+      testRunner.dumpAsText();
+    }
+  } else {
+    location.hash = 'done';
+    window.location.reload();
+  }
+}, 0);
+</script>
+</html>
+"}<_**next**_>{"sha": "cbdbb3ad97dbd3b9e2e2e9e88383291b764cd338", "filename": "third_party/WebKit/LayoutTests/svg/custom/resources/draw-image-crash.svg", "status": "added", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/cace1e6998293b9b025d4bbdaf5cb5b6a1c2efb4/third_party/WebKit/LayoutTests/svg/custom/resources/draw-image-crash.svg", "raw_url": "https://github.com/chromium/chromium/raw/cace1e6998293b9b025d4bbdaf5cb5b6a1c2efb4/third_party/WebKit/LayoutTests/svg/custom/resources/draw-image-crash.svg", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/svg/custom/resources/draw-image-crash.svg?ref=cace1e6998293b9b025d4bbdaf5cb5b6a1c2efb4", "patch": "@@ -0,0 +1,4 @@
