+CONSOLE ERROR: Blocked alert('hello world!') during beforeunload.
+Test that alert() inside a document.write() during a beforeunload handler does not confuse the modal dialog blocker. This test passes if no alert() dialogs are seen. "}<_**next**_>{"sha": "061ec0e021d709a4102581e540831763bffb92e7", "filename": "third_party/WebKit/LayoutTests/fast/events/alert-in-beforeunload-document-write.html", "status": "added", "additions": 20, "deletions": 0, "changes": 20, "blob_url": "https://github.com/chromium/chromium/blob/e1e0c4301aaa8228e362f2409dbde2d4d1896866/third_party/WebKit/LayoutTests/fast/events/alert-in-beforeunload-document-write.html", "raw_url": "https://github.com/chromium/chromium/raw/e1e0c4301aaa8228e362f2409dbde2d4d1896866/third_party/WebKit/LayoutTests/fast/events/alert-in-beforeunload-document-write.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/events/alert-in-beforeunload-document-write.html?ref=e1e0c4301aaa8228e362f2409dbde2d4d1896866", "patch": "@@ -0,0 +1,20 @@
+<!DOCTYPE html>
+<html>
+<script>
+function runTest()
+{
+    if (window.testRunner) {
+        testRunner.waitUntilDone();
+        testRunner.dumpAsText();
+        document.querySelector('iframe').onload = function () { testRunner.notifyDone(); };
+    }
+    window[0].onbeforeunload = function() { window[0].document.write("<script>alert('hello world!');</scr" + "ipt>"); }
+    window[0].location = 'data:text/plain,Done!';
+}
+</script>
+<body onload="runTest()">
+<p>Test that alert() inside a document.write() during a beforeunload handler does not confuse the modal dialog blocker. This test passes if no alert() dialogs are seen.
+<iframe>
+</iframe>
+</body>
+</html>"}<_**next**_>{"sha": "99ba96c6edf07a8c0ce6eaced95d3ddc54de6035", "filename": "third_party/WebKit/Source/core/dom/Document.cpp", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/e1e0c4301aaa8228e362f2409dbde2d4d1896866/third_party/WebKit/Source/core/dom/Document.cpp", "raw_url": "https://github.com/chromium/chromium/raw/e1e0c4301aaa8228e362f2409dbde2d4d1896866/third_party/WebKit/Source/core/dom/Document.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/dom/Document.cpp?ref=e1e0c4301aaa8228e362f2409dbde2d4d1896866", "patch": "@@ -2373,7 +2373,7 @@ void Document::open()

