{"sha": "33498c65e8f765bcee40a7cb1dc8afec1174389d", "filename": "third_party/WebKit/Source/core/page/PageSerializer.cpp", "status": "modified", "additions": 23, "deletions": 3, "changes": 26, "blob_url": "https://github.com/chromium/chromium/blob/a81593e7f162428585832ac8f6e71f75592b53e7/third_party/WebKit/Source/core/page/PageSerializer.cpp", "raw_url": "https://github.com/chromium/chromium/raw/a81593e7f162428585832ac8f6e71f75592b53e7/third_party/WebKit/Source/core/page/PageSerializer.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/page/PageSerializer.cpp?ref=a81593e7f162428585832ac8f6e71f75592b53e7", "patch": "@@ -253,9 +253,7 @@ void LinkChangeSerializerMarkupAccumulator::appendElement(StringBuilder& result,
         // Add MOTW (Mark of the Web) declaration before html tag.
         // See http://msdn2.microsoft.com/en-us/library/ms537628(VS.85).aspx.
         result.append('\n');
-        MarkupFormatter::appendComment(result, String::format(" saved from url=(%04d)%s ",
-            static_cast<int>(document().url().string().utf8().length()),
-            document().url().string().utf8().data()));
+        MarkupFormatter::appendComment(result, PageSerializer::markOfTheWebDeclaration(document().url()));
         result.append('\n');
     }

@@ -577,4 +575,26 @@ PageSerializer::Delegate* PageSerializer::delegate()
     return m_delegate.get();
 }

+// Returns MOTW (Mark of the Web) declaration before html tag which is in
+// HTML comment, e.g. "<!-- saved from url=(%04d)%s -->"
+// See http://msdn2.microsoft.com/en-us/library/ms537628(VS.85).aspx.
+String PageSerializer::markOfTheWebDeclaration(const KURL& url)
+{
+    StringBuilder builder;
+    bool emitsMinus = false;
+    CString orignalUrl = url.string().ascii();
+    for (const char* string = orignalUrl.data(); *string; ++string) {
+        const char ch = *string;
+        if (ch == '-' && emitsMinus) {
+            builder.append("%2D");
+            emitsMinus = false;
+            continue;
+        }
+        emitsMinus = ch == '-';
+        builder.append(ch);
+    }
+    CString escapedUrl = builder.toString().ascii();
+    return String::format("saved from url=(%04d)%s", static_cast<int>(escapedUrl.length()), escapedUrl.data());
+}
+
 } // namespace blink"}<_**next**_>{"sha": "86d17ba5a0164c796af32682e491b3e64d3b4858", "filename": "third_party/WebKit/Source/core/page/PageSerializer.h", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/a81593e7f162428585832ac8f6e71f75592b53e7/third_party/WebKit/Source/core/page/PageSerializer.h", "raw_url": "https://github.com/chromium/chromium/raw/a81593e7f162428585832ac8f6e71f75592b53e7/third_party/WebKit/Source/core/page/PageSerializer.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/page/PageSerializer.h?ref=a81593e7f162428585832ac8f6e71f75592b53e7", "patch": "@@ -84,6 +84,8 @@ class CORE_EXPORT PageSerializer final {

