+// Copyright 2015 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+var requests = [];
+chrome.webRequest.onBeforeRequest.addListener(function(details) {
+  // Show the query string of the request. If this is absent for some
+  // reason (probably an error), show the full URL.
+  requests.push(new URL(details.url).search || details.url);
+}, {
+  types: ['xmlhttprequest'],
+  urls: ['*://*/*']
+});
+
+chrome.test.sendMessage('web_request_status1', echoRequestStatus);
+chrome.test.sendMessage('web_request_status2', echoRequestStatus);
+
+function echoRequestStatus() {
+  if (requests.length === 0) {
+    chrome.test.sendMessage('Did not intercept any requests.');
+  } else {
+    chrome.test.sendMessage('Intercepted requests: ' + requests.join(', '));
+  }
+  requests.length = 0;
+}"}<_**next**_>{"sha": "e102cfe659ca0ddd0170493ff7c6a1385dbe747d", "filename": "chrome/test/data/extensions/api_test/webrequest_extensions/main/manifest.json", "status": "added", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/86154b409eed6ea7f9177f6bf576e76533ab2f7b/chrome/test/data/extensions/api_test/webrequest_extensions/main/manifest.json", "raw_url": "https://github.com/chromium/chromium/raw/86154b409eed6ea7f9177f6bf576e76533ab2f7b/chrome/test/data/extensions/api_test/webrequest_extensions/main/manifest.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/webrequest_extensions/main/manifest.json?ref=86154b409eed6ea7f9177f6bf576e76533ab2f7b", "patch": "@@ -0,0 +1,13 @@
