+
+</body>
+</html>"}<_**next**_>{"sha": "2d6147e31f2c122ca37fe993083b15aed01e57f7", "filename": "third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/gc.js", "status": "added", "additions": 21, "deletions": 0, "changes": 21, "blob_url": "https://github.com/chromium/chromium/blob/6be50e67f9f812d412eace7fad217d5eac16ca94/third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/gc.js", "raw_url": "https://github.com/chromium/chromium/raw/6be50e67f9f812d412eace7fad217d5eac16ca94/third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/gc.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/gc.js?ref=6be50e67f9f812d412eace7fad217d5eac16ca94", "patch": "@@ -0,0 +1,21 @@
+// This file was copied from third_party/WebKit/LayoutTests/resources/gc.js
+// If there is no window.gc() already defined, define one using the best
+// method we can find.
+// The slow fallback should not hit in the actual test environment.
+if (!window.gc)
+{
+    window.gc = function()
+    {
+        if (window.GCController)
+            return GCController.collectAll();
+        function gcRec(n) {
+            if (n < 1)
+                return {};
+            var temp = {i: "ab" + i + (i / 100000)};
+            temp += "foo";
+            gcRec(n-1);
+        }
+        for (var i = 0; i < 10000; i++)
+            gcRec(10);
+    }
+}"}<_**next**_>{"sha": "768963fc8693ce78e15ee05376295054f05e9e46", "filename": "third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/long-script-page.html", "status": "added", "additions": 23, "deletions": 0, "changes": 23, "blob_url": "https://github.com/chromium/chromium/blob/6be50e67f9f812d412eace7fad217d5eac16ca94/third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/long-script-page.html", "raw_url": "https://github.com/chromium/chromium/raw/6be50e67f9f812d412eace7fad217d5eac16ca94/third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/long-script-page.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/devtools/network/resources/long-script-page.html?ref=6be50e67f9f812d412eace7fad217d5eac16ca94", "patch": "@@ -0,0 +1,23 @@
