+  logo_service()->cached_logo->metadata.on_click_url =
+      GURL("https://www.chromium.org");
+  logo_service()->cached_logo->metadata.alt_text = "Chromium";
+
+  logo_service()->fresh_reason = LogoCallbackReason::REVALIDATED;
+
+  // Open a new blank tab, then go to NTP and listen for console messages.
+  content::WebContents* active_tab = OpenNewTab(browser(), GURL("about:blank"));
+  content::ConsoleObserverDelegate console_observer(active_tab, "*");
+  active_tab->SetDelegate(&console_observer);
+  ui_test_utils::NavigateToURL(browser(), GURL(chrome::kChromeUINewTabURL));
+
+  EXPECT_THAT(GetComputedStyle(active_tab, "logo-default", "opacity"),
+              Eq<std::string>("0"));
+  EXPECT_THAT(GetComputedStyle(active_tab, "logo-doodle", "opacity"),
+              Eq<std::string>("1"));
+  EXPECT_THAT(console_observer.message(), IsEmpty());
+}"}<_**next**_>{"sha": "2c1a900c95a41b40646d678b597889963bdd8072", "filename": "components/search_provider_logos/BUILD.gn", "status": "modified", "additions": 3, "deletions": 1, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/deaa07bec5d105ffc546d37eba3da4cba341fc03/components/search_provider_logos/BUILD.gn", "raw_url": "https://github.com/chromium/chromium/raw/deaa07bec5d105ffc546d37eba3da4cba341fc03/components/search_provider_logos/BUILD.gn", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/components/search_provider_logos/BUILD.gn?ref=deaa07bec5d105ffc546d37eba3da4cba341fc03", "patch": "@@ -16,6 +16,8 @@ static_library("search_provider_logos") {
