+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "media/base/video_color_space.h"
+
+namespace media {
+
+VideoColorSpace::PrimaryID VideoColorSpace::GetPrimaryID(int primary) {
+  if (primary < 1 || primary > 22 || primary == 3)
+    return PrimaryID::INVALID;
+  if (primary > 12 && primary < 22)
+    return PrimaryID::INVALID;
+  return static_cast<PrimaryID>(primary);
+}
+
+VideoColorSpace::TransferID VideoColorSpace::GetTransferID(int transfer) {
+  if (transfer < 1 || transfer > 18 || transfer == 3)
+    return TransferID::INVALID;
+  return static_cast<TransferID>(transfer);
+}
+
+VideoColorSpace::MatrixID VideoColorSpace::GetMatrixID(int matrix) {
+  if (matrix < 0 || matrix > 11 || matrix == 3)
+    return MatrixID::INVALID;
+  return static_cast<MatrixID>(matrix);
+}
+
+VideoColorSpace::VideoColorSpace() {}
+
+VideoColorSpace::VideoColorSpace(PrimaryID primaries,
+                                 TransferID transfer,
+                                 MatrixID matrix,
+                                 gfx::ColorSpace::RangeID range)
+    : primaries(primaries), transfer(transfer), matrix(matrix), range(range) {}
+
+VideoColorSpace::VideoColorSpace(int primaries,
+                                 int transfer,
+                                 int matrix,
+                                 gfx::ColorSpace::RangeID range)
+    : primaries(GetPrimaryID(primaries)),
+      transfer(GetTransferID(transfer)),
+      matrix(GetMatrixID(matrix)),
+      range(range) {}
+
+gfx::ColorSpace VideoColorSpace::ToGfxColorSpace() const {
+  // TODO(hubbe): Make this type-safe.
+  return gfx::ColorSpace::CreateVideo(static_cast<int>(primaries),
+                                      static_cast<int>(transfer),
+                                      static_cast<int>(matrix), range);
+}
+
+VideoColorSpace VideoColorSpace::BT709() {
+  return VideoColorSpace(PrimaryID::BT709, TransferID::BT709, MatrixID::BT709,
+                         gfx::ColorSpace::RangeID::LIMITED);
+}
+
+}  // namespace"}<_**next**_>{"sha": "c8a6a0ce4f728c0e5d82e6307d56de4c95f4f369", "filename": "media/base/video_color_space.h", "status": "added", "additions": 102, "deletions": 0, "changes": 102, "blob_url": "https://github.com/chromium/chromium/blob/2fb4f2c9c461551d43fdfa28ef4c960da81a47dd/media/base/video_color_space.h", "raw_url": "https://github.com/chromium/chromium/raw/2fb4f2c9c461551d43fdfa28ef4c960da81a47dd/media/base/video_color_space.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/media/base/video_color_space.h?ref=2fb4f2c9c461551d43fdfa28ef4c960da81a47dd", "patch": "@@ -0,0 +1,102 @@
+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef MEDIA_BASE_VIDEO_COLOR_SPACE_H_
+#define MEDIA_BASE_VIDEO_COLOR_SPACE_H_
+
+#include "media/base/media_export.h"
+#include "ui/gfx/color_space.h"
+
+namespace media {
+
+// Described in ISO 23001-8:2016
+class MEDIA_EXPORT VideoColorSpace {
+ public:
+  // Table 2
+  enum class PrimaryID : uint8_t {
+    INVALID = 0,
+    BT709 = 1,
+    UNSPECIFIED = 2,
+    BT470M = 4,
+    BT470BG = 5,
+    SMPTE170M = 6,
+    SMPTE240M = 7,
+    FILM = 8,
+    BT2020 = 9,
+    SMPTEST428_1 = 10,
+    SMPTEST431_2 = 11,
+    SMPTEST432_1 = 12,
+    EBU_3213_E = 22
+  };
+
+  // Table 3
+  enum class TransferID : uint8_t {
+    INVALID = 0,
+    BT709 = 1,
+    UNSPECIFIED = 2,
+    GAMMA22 = 4,
+    GAMMA28 = 5,
+    SMPTE170M = 6,
+    SMPTE240M = 7,
+    LINEAR = 8,
+    LOG = 9,
+    LOG_SQRT = 10,
+    IEC61966_2_4 = 11,
+    BT1361_ECG = 12,
+    IEC61966_2_1 = 13,
+    BT2020_10 = 14,
+    BT2020_12 = 15,
+    SMPTEST2084 = 16,
+    SMPTEST428_1 = 17,
+
+    // Not yet standardized
+    ARIB_STD_B67 = 18,  // AKA hybrid-log gamma, HLG.
+  };
+
+  // Table 4
+  enum class MatrixID : uint8_t {
+    RGB = 0,
+    BT709 = 1,
+    UNSPECIFIED = 2,
+    FCC = 4,
+    BT470BG = 5,
+    SMPTE170M = 6,
+    SMPTE240M = 7,
+    YCOCG = 8,
+    BT2020_NCL = 9,
+    BT2020_CL = 10,
+    YDZDX = 11,
+    INVALID = 255,
+  };
+
+  VideoColorSpace();
+  VideoColorSpace(int primaries,
+                  int transfer,
+                  int matrix,
+                  gfx::ColorSpace::RangeID range);
+  VideoColorSpace(PrimaryID primaries,
+                  TransferID transfer,
+                  MatrixID matrix,
+                  gfx::ColorSpace::RangeID range);
+
+  // These will return INVALID if the number you give it
+  // is not a valid enum value.
+  static PrimaryID GetPrimaryID(int primary);
+  static TransferID GetTransferID(int transfer);
+  static MatrixID GetMatrixID(int matrix);
+
+  static VideoColorSpace BT709();
+
+  gfx::ColorSpace ToGfxColorSpace() const;
+
+  // Note, these are public variables.
+  PrimaryID primaries = PrimaryID::INVALID;
+  TransferID transfer = TransferID::INVALID;
+  MatrixID matrix = MatrixID::INVALID;
+  gfx::ColorSpace::RangeID range = gfx::ColorSpace::RangeID::INVALID;
+};
+
+}  // namespace media
+
+#endif"}

