+PASS Correctly found some non-zero values.
+PASS successfullyParsed is true
+
+TEST COMPLETE
+"}<_**next**_>{"sha": "ce2dbb8cd351a3640d29dc9521a9ca2cf4155618", "filename": "third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin-allowed.html", "status": "added", "additions": 46, "deletions": 0, "changes": 46, "blob_url": "https://github.com/chromium/chromium/blob/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin-allowed.html", "raw_url": "https://github.com/chromium/chromium/raw/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin-allowed.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin-allowed.html?ref=6834289784ed45b5524de0fb7ef43ae283b0d6d3", "patch": "@@ -0,0 +1,46 @@
+<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN">
+<html>
+  <head>
+    <script src="resources/webaudio/compatibility.js"></script>
+    <script src="resources/webaudio/media-element-audio-source-node-test.js"></script>
+    <script src="resources/webaudio/js-test.js"></script>
+  </head>
+
+  <body>
+    <div id="description"></div>
+    <div id="console"></div>
+
+    <script>
+      description("MediaElementAudioSourceNode with cross-origin source");
+
+      var data;
+
+      function checkResult (e) {
+        data = e.renderedBuffer.getChannelData(0);
+        var count = 0;
+
+        // Count the number of non-zero values. Since this is a cross-origin source that is allowed,
+        // there should be at least one non-zero value.
+        for (var k = 0; k < data.length; ++k) {
+            if (data[k] != 0) {
+                ++count;
+            }
+        }
+        if (count > 0) {
+            testPassed("Correctly found some non-zero values.");
+        } else {
+            testFailed("All samples incorrectly zeroed.");
+        }
+      }
+
+      function testFunction() {
+        audio.crossOrigin = "anonymous";
+        audio.src =
+        "http://localhost:8000/security/resources/webaudio/media-element-cross-origin-allow.php";
+      }
+
+      runTest(null, checkResult, testFunction);
+
+    </script>
+  </body>
