+<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN">
+<html>
+  <head>
+    <script src="resources/webaudio/compatibility.js"></script>
+    <script src="resources/webaudio/media-element-audio-source-node-test.js"></script>
+    <script src="resources/webaudio/js-test.js"></script>
+  </head>
+
+  <body>
+    <div id="description"></div>
+    <div id="console"></div>
+
+    <script>
+      description("MediaElementAudioSourceNode with cross-origin source with credentials");
+
+      var data;
+
+      function checkResult (e) {
+        data = e.renderedBuffer.getChannelData(0);
+        var count = 0;
+
+        // Count the number of non-zero values. Since this is a cross-origin source that is allowed
+        // with credentials, there should be at least one non-zero value.
+        for (var k = 0; k < data.length; ++k) {
+            if (data[k] != 0) {
+                ++count;
+            }
+        }
+        if (count > 0) {
+            testPassed("Correctly found some non-zero values.");
+        } else {
+            testFailed("All samples incorrectly zeroed.");
+        }
+      }
+
+      function testFunction() {
+        audio.crossOrigin = "use-credentials";
+        audio.src =
+        "http://localhost:8000/security/resources/webaudio/media-element-cross-origin-allow.php?with_credentials";
+      }
+
+      runTest(null, checkResult, testFunction);
+
+    </script>
+  </body>
+</html>"}<_**next**_>{"sha": "2a4bb662e8626aec72a34148e64540ff38c407fd", "filename": "third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin.html", "status": "added", "additions": 41, "deletions": 0, "changes": 41, "blob_url": "https://github.com/chromium/chromium/blob/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin.html", "raw_url": "https://github.com/chromium/chromium/raw/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-cross-origin.html?ref=6834289784ed45b5524de0fb7ef43ae283b0d6d3", "patch": "@@ -0,0 +1,41 @@
+<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN">
+<html>
+  <head>
+    <script src="resources/webaudio/compatibility.js"></script>
+    <script src="resources/webaudio/media-element-audio-source-node-test.js"></script>
+    <script src="resources/webaudio/js-test.js"></script>
+  </head>
+
+  <body>
+    <div id="description"></div>
+    <div id="console"></div>
+
+    <script>
+      description("MediaElementAudioSourceNode with cross-origin source");
+
+      var src = "http://localhost:8000/security/resources/webaudio/laughter.wav";
+      var data;
+
+      function checkResult (e) {
+        data = e.renderedBuffer.getChannelData(0);
+        var count = 0;
+
+        // Count the number of non-zero values. Since this is a cross-origin source, all the values
+        // should be zero.
+        for (var k = 0; k < data.length; ++k) {
+            if (data[k] != 0) {
+                ++count;
+            }
+        }
+        if (count > 0) {
+            testFailed("Expected all zeros but found " + count + " non-zero values out of " + data.length + ".");
+        } else {
+            testPassed("All samples correctly zeroed.");
+        }
+      }
+
+      runTest(src, checkResult);
+
+    </script>
+  </body>
+</html>"}<_**next**_>{"sha": "b333b9dd178e41e0731f8d702bcd34d0712334d5", "filename": "third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-same-origin-expected.txt", "status": "added", "additions": 9, "deletions": 0, "changes": 9, "blob_url": "https://github.com/chromium/chromium/blob/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-same-origin-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-same-origin-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-same-origin-expected.txt?ref=6834289784ed45b5524de0fb7ef43ae283b0d6d3", "patch": "@@ -0,0 +1,9 @@
