+// We want to be able to run these tests with chrome that only supports the prefixed
+// AudioContext. This is useful in case a regression has occurred.
+
+if (window.hasOwnProperty('webkitAudioContext') &&
+    !window.hasOwnProperty('AudioContext')) {
+    window.AudioContext = webkitAudioContext;
+    window.OfflineAudioContext = webkitOfflineAudioContext;
+    console.log("Using deprecated prefixed AudioContext or OfflineAudioContext");
+}"}<_**next**_>{"sha": "45fa85dcfd7865479fd9aca4638b80cd37038399", "filename": "third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/js-test.js", "status": "added", "additions": 822, "deletions": 0, "changes": 822, "blob_url": "https://github.com/chromium/chromium/blob/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/js-test.js", "raw_url": "https://github.com/chromium/chromium/raw/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/js-test.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/js-test.js?ref=6834289784ed45b5524de0fb7ef43ae283b0d6d3", "patch": "@@ -0,0 +1,822 @@
+// svg/dynamic-updates tests set enablePixelTesting=true, as we want to dump text + pixel results
