+// Test MediaStreamAudioSourceNode's with different URLs.
+//
+var context = 0;
+var lengthInSeconds = 1;
+var sampleRate = 44100;
+var source = 0;
+var audio = 0;
+
+// Create an MediaElementSource node with the given |url| and connect it to webaudio.
+// |oncomplete| is given the completion event to check the result.
+function runTest (url, oncomplete, tester)
+{
+    if (window.testRunner) {
+        testRunner.dumpAsText();
+        testRunner.waitUntilDone();
+    }
+
+    window.jsTestIsAsync = true;
+
+    context = new OfflineAudioContext(1, sampleRate * lengthInSeconds, sampleRate);
+
+    audio = document.createElement('audio');
+
+    if (tester) {
+        tester();
+    } else {
+        audio.src = url;
+    }
+
+    source = context.createMediaElementSource(audio);
+    source.connect(context.destination);
+
+    audio.addEventListener("playing", function(e) {
+            context.startRendering();
+        });
+
+    context.oncomplete = function(e) {
+        checkResult(e);
+        finishJSTest();
+    }
+
+    audio.play();
+}"}<_**next**_>{"sha": "3fa058ceeb005431eff7e2e25aa1c5a24663ba98", "filename": "third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/media-element-cross-origin-allow.php", "status": "added", "additions": 18, "deletions": 0, "changes": 18, "blob_url": "https://github.com/chromium/chromium/blob/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/media-element-cross-origin-allow.php", "raw_url": "https://github.com/chromium/chromium/raw/6834289784ed45b5524de0fb7ef43ae283b0d6d3/third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/media-element-cross-origin-allow.php", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/resources/webaudio/media-element-cross-origin-allow.php?ref=6834289784ed45b5524de0fb7ef43ae283b0d6d3", "patch": "@@ -0,0 +1,18 @@
