+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef IOS_CHROME_BROWSER_FIND_IN_PAGE_FIND_TAB_HELPER_H_
+#define IOS_CHROME_BROWSER_FIND_IN_PAGE_FIND_TAB_HELPER_H_
+
+#include "base/macros.h"
+#include "ios/web/public/web_state/web_state_observer.h"
+#import "ios/web/public/web_state/web_state_user_data.h"
+
+@class FindInPageController;
+@protocol FindInPageControllerDelegate;
+
+// Adds support for the "Find in page" feature.
+class FindTabHelper : public web::WebStateObserver,
+                      public web::WebStateUserData<FindTabHelper> {
+ public:
+  // Creates a FindTabHelper and attaches it to the given |web_state|.
+  // |controller_delegate| can be nil.
+  static void CreateForWebState(
+      web::WebState* web_state,
+      id<FindInPageControllerDelegate> controller_delegate);
+
+  // Returns the find in page controller.
+  FindInPageController* GetController();
+
+ private:
+  FindTabHelper(web::WebState* web_state,
+                id<FindInPageControllerDelegate> controller_delegate);
+  ~FindTabHelper() override;
+
+  // web::WebStateObserver.
+  void NavigationItemCommitted(
+      const web::LoadCommittedDetails& load_details) override;
+  void WebStateDestroyed() override;
+
+  // The ObjC find in page controller.
+  FindInPageController* controller_;
+
+  DISALLOW_COPY_AND_ASSIGN(FindTabHelper);
+};
+
+#endif  // IOS_CHROME_BROWSER_FIND_IN_PAGE_FIND_TAB_HELPER_H_"}<_**next**_>{"sha": "9892712a9bfd8e3ad43c91c8bd96df6d5ca0d5b8", "filename": "ios/chrome/browser/find_in_page/find_tab_helper.mm", "status": "added", "additions": 47, "deletions": 0, "changes": 47, "blob_url": "https://github.com/chromium/chromium/blob/b2bf3cb69cae29c1dc85f23a18f2f36587290c1e/ios/chrome/browser/find_in_page/find_tab_helper.mm", "raw_url": "https://github.com/chromium/chromium/raw/b2bf3cb69cae29c1dc85f23a18f2f36587290c1e/ios/chrome/browser/find_in_page/find_tab_helper.mm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ios/chrome/browser/find_in_page/find_tab_helper.mm?ref=b2bf3cb69cae29c1dc85f23a18f2f36587290c1e", "patch": "@@ -0,0 +1,47 @@
+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#import "ios/chrome/browser/find_in_page/find_tab_helper.h"
+
+#import "ios/chrome/browser/find_in_page/find_in_page_controller.h"
+
+#if !defined(__has_feature) || !__has_feature(objc_arc)
+#error "This file requires ARC support."
+#endif
+
+DEFINE_WEB_STATE_USER_DATA_KEY(FindTabHelper);
+
+// static
+void FindTabHelper::CreateForWebState(
+    web::WebState* web_state,
+    id<FindInPageControllerDelegate> controller_delegate) {
+  DCHECK(web_state);
+  if (!FromWebState(web_state)) {
+    web_state->SetUserData(UserDataKey(),
+                           new FindTabHelper(web_state, controller_delegate));
+  }
+}
+
+FindTabHelper::FindTabHelper(
+    web::WebState* web_state,
+    id<FindInPageControllerDelegate> controller_delegate) {
+  controller_ =
+      [[FindInPageController alloc] initWithWebState:web_state
+                                            delegate:controller_delegate];
+}
+
+FindTabHelper::~FindTabHelper() {}
+
+FindInPageController* FindTabHelper::GetController() {
+  return controller_;
+}
+
+void FindTabHelper::NavigationItemCommitted(
+    const web::LoadCommittedDetails& load_details) {
+  [controller_ disableFindInPageWithCompletionHandler:nil];
+}
+
+void FindTabHelper::WebStateDestroyed() {
+  [controller_ detachFromWebState];
+}"}<_**next**_>{"sha": "414d8ad1e175b0a50d191b912dea3878c92542a5", "filename": "ios/chrome/browser/find_in_page/find_tab_helper_unittest.mm", "status": "added", "additions": 31, "deletions": 0, "changes": 31, "blob_url": "https://github.com/chromium/chromium/blob/b2bf3cb69cae29c1dc85f23a18f2f36587290c1e/ios/chrome/browser/find_in_page/find_tab_helper_unittest.mm", "raw_url": "https://github.com/chromium/chromium/raw/b2bf3cb69cae29c1dc85f23a18f2f36587290c1e/ios/chrome/browser/find_in_page/find_tab_helper_unittest.mm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ios/chrome/browser/find_in_page/find_tab_helper_unittest.mm?ref=b2bf3cb69cae29c1dc85f23a18f2f36587290c1e", "patch": "@@ -0,0 +1,31 @@
