{"sha": "0425296a9e94ffd2707086c0e8a6381c9f8dd32f", "filename": "chrome/browser/android/ntp/content_suggestions_notifier_service.cc", "status": "modified", "additions": 39, "deletions": 0, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/59512d1ea20d8e85555ecb743ee29ba90016656d/chrome/browser/android/ntp/content_suggestions_notifier_service.cc", "raw_url": "https://github.com/chromium/chromium/raw/59512d1ea20d8e85555ecb743ee29ba90016656d/chrome/browser/android/ntp/content_suggestions_notifier_service.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/android/ntp/content_suggestions_notifier_service.cc?ref=59512d1ea20d8e85555ecb743ee29ba90016656d", "patch": "@@ -61,6 +61,37 @@ bool ShouldNotifyInState(base::android::ApplicationState state) {
   return false;
 }

+int DayAsYYYYMMDD() {
+  base::Time::Exploded now{};
+  base::Time::Now().LocalExplode(&now);
+  return (now.year * 10000) + (now.month * 100) + now.day_of_month;
+}
+
+bool HaveQuotaForToday(PrefService* prefs) {
+  int today = DayAsYYYYMMDD();
+  int limit = variations::GetVariationParamByFeatureAsInt(
+      kContentSuggestionsNotificationsFeature,
+      kContentSuggestionsNotificationsDailyLimit,
+      kContentSuggestionsNotificationsDefaultDailyLimit);
+  int sent =
+      prefs->GetInteger(prefs::kContentSuggestionsNotificationsSentDay) == today
+          ? prefs->GetInteger(prefs::kContentSuggestionsNotificationsSentCount)
+          : 0;
+  return sent < limit;
+}
+
+void ConsumeQuota(PrefService* prefs) {
+  int sent =
+      prefs->GetInteger(prefs::kContentSuggestionsNotificationsSentCount);
+  int today = DayAsYYYYMMDD();
+  if (prefs->GetInteger(prefs::kContentSuggestionsNotificationsSentDay) !=
+      today) {
+    prefs->SetInteger(prefs::kContentSuggestionsNotificationsSentDay, today);
+    sent = 0;  // Reset on day change.
+  }
+  prefs->SetInteger(prefs::kContentSuggestionsNotificationsSentCount, sent + 1);
+}
+
 }  // namespace

 class ContentSuggestionsNotifierService::NotifyingObserver
@@ -82,6 +113,9 @@ class ContentSuggestionsNotifierService::NotifyingObserver
                    profile_)) {
       DVLOG(1) << "Suppressed notification due to opt-out";
       return;
+    } else if (!HaveQuotaForToday(profile_->GetPrefs())) {
+      DVLOG(1) << "Notification suppressed due to daily limit";
