+<!DOCTYPE html>
+<div id="console"></div>
+<script>
+if (window.testRunner) {
+      testRunner.dumpAsText();
+      testRunner.waitUntilDone();
+}
+
+var iframe = document.body.appendChild(document.createElement("iframe"));
+var o = undefined;
+
+function test() {
+    var win = iframe.contentWindow;
+    function recurse() {
+        try { recurse(); } catch(e) {}
+        try { win.location; } catch(e) { 
+            o = e; 
