+<!DOCTYPE html>
+<html>
+<body>
+<script src="../resources/testharness.js"></script>
+<script src="../resources/testharnessreport.js"></script>
+<script src="../resources/mojo-helpers.js"></script>
+<script src="resources/presentation-service-mock.js"></script>
+<button>click me</button>
+<script>
+
+var button = document.querySelector('button');
+var receiverConnectionClosed = false;
+var connection = null;
+
+async_test(t => {
+  presentationServiceMock.then(service => {
+    // This is receiving the user gesture and runs the callback.
+    waitForClick(() => {
+      new PresentationRequest("https://example.com/").start().then(
+        theConnection => {
+          connection = theConnection;
+          connection.onclose = (closeEvent) => {
+            assert_equals(closeEvent.reason, "closed");
+            assert_equals(closeEvent.message, "");
+            assert_equals(connection.state, "closed");
+            assert_true(receiverConnectionClosed);
+            t.done();
+          };
+          connection.onconnect = () => {
+            // Open a receiver page and pass controller connection's
+            // controllerConnectionPtr and receiverConnectionRequest to it.
+            w = window.open("resources/presentation-receiver-close-connection.html");
+            w.controllerConnectionPtr = service.getControllerConnectionPtr();
+            w.receiverConnectionRequest = service.getReceiverConnectionRequest();
+            w.shouldCallClose = false;
+          };
+        });
+    }, button);
+  });
+
+  window.addEventListener("message", t.step_func(e => {
+    if (e.data == "receiver connection closed") {
+      receiverConnectionClosed = true;
+    } else if (e.data == "receiver connection ready") {
+      assert_not_equals(connection, null);
+      connection.close();
+    }
+  }));
+}, "controller connection.close() should fire both controller's and receiver's onclose event handler");
+
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "77020d1b6880b750195d6a755f7c7afb98c862d8", "filename": "third_party/WebKit/LayoutTests/presentation/presentation-controller-connection-closed-by-receiver.html", "status": "added", "additions": 48, "deletions": 0, "changes": 48, "blob_url": "https://github.com/chromium/chromium/blob/0c08ed56a3e5089b3cc4094e83daae196a6300c4/third_party/WebKit/LayoutTests/presentation/presentation-controller-connection-closed-by-receiver.html", "raw_url": "https://github.com/chromium/chromium/raw/0c08ed56a3e5089b3cc4094e83daae196a6300c4/third_party/WebKit/LayoutTests/presentation/presentation-controller-connection-closed-by-receiver.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/presentation/presentation-controller-connection-closed-by-receiver.html?ref=0c08ed56a3e5089b3cc4094e83daae196a6300c4", "patch": "@@ -0,0 +1,48 @@
+<!DOCTYPE html>
+<html>
+<body>
+<script src="../resources/testharness.js"></script>
+<script src="../resources/testharnessreport.js"></script>
+<script src="../resources/mojo-helpers.js"></script>
+<script src="resources/presentation-service-mock.js"></script>
+<button>click me</button>
+<script>
+
+var button = document.querySelector('button');
+var controllerConnectionClosed = false;
+
+async_test(t => {
+  presentationServiceMock.then(service => {
+    // This is receiving the user gesture and runs the callback.
+    waitForClick(() => {
+      new PresentationRequest("https://example.com/").start().then(
+        connection => {
+          connection.onclose = (closeEvent) => {
+            assert_equals(closeEvent.reason, "closed");
+            assert_equals(closeEvent.message, "");
+            assert_equals(connection.state, "closed");
+            controllerConnectionClosed = true;
+          };
+          connection.onconnect = () => {
+            // Open a receiver page and pass controller connection's
+            // controllerConnectionPtr and receiverConnectionRequest to it.
+            w = window.open("resources/presentation-receiver-close-connection.html");
+            w.controllerConnectionPtr = service.getControllerConnectionPtr();
+            w.receiverConnectionRequest = service.getReceiverConnectionRequest();
+            w.shouldCallClose = true;
+          };
+        });
+    }, button);
+  });
+
+  window.addEventListener("message", t.step_func(e => {
+      if (e.data == "receiver connection closed") {
+      assert_true(controllerConnectionClosed);
+      t.done();
+    }
+  }));
+}, "receiver connection.close() should fire both controller's and receiver's onclose event handler");
+
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "1bf738a981a222cab81da4baa5a19f0b533610d1", "filename": "third_party/WebKit/LayoutTests/presentation/resources/presentation-receiver-close-connection.html", "status": "added", "additions": 45, "deletions": 0, "changes": 45, "blob_url": "https://github.com/chromium/chromium/blob/0c08ed56a3e5089b3cc4094e83daae196a6300c4/third_party/WebKit/LayoutTests/presentation/resources/presentation-receiver-close-connection.html", "raw_url": "https://github.com/chromium/chromium/raw/0c08ed56a3e5089b3cc4094e83daae196a6300c4/third_party/WebKit/LayoutTests/presentation/resources/presentation-receiver-close-connection.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/presentation/resources/presentation-receiver-close-connection.html?ref=0c08ed56a3e5089b3cc4094e83daae196a6300c4", "patch": "@@ -0,0 +1,45 @@
+<!DOCTYPE html>
+<html>
+<body>
+<script src="../../resources/testharness.js"></script>
+<script src="../../resources/mojo-helpers.js"></script>
+<script src="presentation-service-mock.js"></script>
+<script>
+
+// Parent window sets parameter for this page.
+assert_not_equals(controllerConnectionPtr, null);
+assert_not_equals(receiverConnectionRequest, null);
+assert_not_equals(shouldCallClose, null);
+
+internals.settings.setPresentationReceiver(true);
+
+presentationServiceMock.then(mockService => {
+  const url = 'http://example.com/a.html';
+  const id = 'fakeSessionId';
+
+  mockService.onSetClient = () => {
+    mockService.onReceiverConnectionAvailable(
+        url, id, controllerConnectionPtr, receiverConnectionRequest);
+  };
+
+  navigator.presentation.receiver.connectionList.then(list => {
+    assert_equals(list.connections.length, 1);
+    const connection = list.connections[0];
+    connection.onclose = () => {
+      assert_equals(connection.state, 'closed');
+      opener.postMessage('receiver connection closed', '*');
+    };
+    opener.postMessage('receiver connection ready', '*');
+    if (shouldCallClose) {
+      connection.close();
+    }
+  });
+});
+
+window.onunload = () => {
+  internals.settings.setPresentationReceiver(false);
+};
+
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "a9b1c76bdb19d24a78e94478ff020bb16ed598a3", "filename": "third_party/WebKit/LayoutTests/presentation/resources/presentation-service-mock.js", "status": "modified", "additions": 29, "deletions": 9, "changes": 38, "blob_url": "https://github.com/chromium/chromium/blob/0c08ed56a3e5089b3cc4094e83daae196a6300c4/third_party/WebKit/LayoutTests/presentation/resources/presentation-service-mock.js", "raw_url": "https://github.com/chromium/chromium/raw/0c08ed56a3e5089b3cc4094e83daae196a6300c4/third_party/WebKit/LayoutTests/presentation/resources/presentation-service-mock.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/presentation/resources/presentation-service-mock.js?ref=0c08ed56a3e5089b3cc4094e83daae196a6300c4", "patch": "@@ -25,6 +25,8 @@ let presentationServiceMock = loadMojoModules(
