+// Copyright 2018 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "components/metrics/cpu_metrics_provider.h"
+
+#include "base/cpu.h"
+#include "base/system/sys_info.h"
+#include "third_party/metrics_proto/system_profile.pb.h"
+
+namespace metrics {
+
+CPUMetricsProvider::CPUMetricsProvider() {}
+
+CPUMetricsProvider::~CPUMetricsProvider() {}
+
+void CPUMetricsProvider::ProvideSystemProfileMetrics(
+    SystemProfileProto* system_profile) {
+  SystemProfileProto::Hardware::CPU* cpu =
+      system_profile->mutable_hardware()->mutable_cpu();
+  // All the CPU information is generated in the constructor.
+  base::CPU cpu_info;
+  cpu->set_vendor_name(cpu_info.vendor_name());
+  cpu->set_signature(cpu_info.signature());
+  cpu->set_num_cores(base::SysInfo::NumberOfProcessors());
+}
+
+}  // namespace metrics"}<_**next**_>{"sha": "067822bd2bf6cbe2e10e99adaff70a9c2184f67e", "filename": "components/metrics/cpu_metrics_provider.h", "status": "added", "additions": 30, "deletions": 0, "changes": 30, "blob_url": "https://github.com/chromium/chromium/blob/19b8593007150b9a78da7d13f6e5f8feb10881a7/components/metrics/cpu_metrics_provider.h", "raw_url": "https://github.com/chromium/chromium/raw/19b8593007150b9a78da7d13f6e5f8feb10881a7/components/metrics/cpu_metrics_provider.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/components/metrics/cpu_metrics_provider.h?ref=19b8593007150b9a78da7d13f6e5f8feb10881a7", "patch": "@@ -0,0 +1,30 @@
