+}"}<_**next**_>{"sha": "ac6611077db2c19ab9bc9b150087e0121535a0eb", "filename": "net/data/proxy_resolver_v8_tracing_unittest/dns_depending_on_url.js", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/data/proxy_resolver_v8_tracing_unittest/dns_depending_on_url.js", "raw_url": "https://github.com/chromium/chromium/raw/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/data/proxy_resolver_v8_tracing_unittest/dns_depending_on_url.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/data/proxy_resolver_v8_tracing_unittest/dns_depending_on_url.js?ref=183f4bcddd821b4af3f6234ad2e8c371694a9ffb", "patch": "@@ -0,0 +1,17 @@
+// Copyright 2016 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// This proxy script has different DNS dependencies based on whether the URL
+// contains "UseMyIpAddress". The final proxy list however is the same.
+function FindProxyForURL(url, host) {
+  if (url.indexOf("UseMyIpAddress") == -1) {
+    if (!myIpAddress())
+      return null;
+  } else {
+    if (!dnsResolve(host))
+      return null;
+  }
+
+  return "PROXY foopy:47";
+}"}<_**next**_>{"sha": "42256ebc66e777333848e661e4b185952fda1027", "filename": "net/data/proxy_resolver_v8_tracing_unittest/error_depending_on_url.js", "status": "added", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/data/proxy_resolver_v8_tracing_unittest/error_depending_on_url.js", "raw_url": "https://github.com/chromium/chromium/raw/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/data/proxy_resolver_v8_tracing_unittest/error_depending_on_url.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/data/proxy_resolver_v8_tracing_unittest/error_depending_on_url.js?ref=183f4bcddd821b4af3f6234ad2e8c371694a9ffb", "patch": "@@ -0,0 +1,13 @@
+// Copyright 2016 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// This proxy script throws an error if the URL does not contain the substring
+// "DontThrowError".
+function FindProxyForURL(url, host) {
+  if (url.indexOf("DontThrowError") == -1) {
+    ErrorUndefinedFunction();
+    return -1;
+  }
+  return "PROXY foopy:42";
+}"}<_**next**_>{"sha": "fad3c85aabb33a446e197b2bc61c1c426e0b01d6", "filename": "net/data/proxy_resolver_v8_tracing_unittest/return_url_as_proxy.js", "status": "added", "additions": 16, "deletions": 0, "changes": 16, "blob_url": "https://github.com/chromium/chromium/blob/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/data/proxy_resolver_v8_tracing_unittest/return_url_as_proxy.js", "raw_url": "https://github.com/chromium/chromium/raw/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/data/proxy_resolver_v8_tracing_unittest/return_url_as_proxy.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/data/proxy_resolver_v8_tracing_unittest/return_url_as_proxy.js?ref=183f4bcddd821b4af3f6234ad2e8c371694a9ffb", "patch": "@@ -0,0 +1,16 @@
+// Copyright 2016 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// This proxy script returns a proxy list that encodes the URL that was passed
+// in.
+
+function convertUrlToHostname(url) {
+  // Turn the URL into something that resembles a hostname.
+  var result = encodeURIComponent(url);
+  return result.replace(/%/g, "x");
+}
+
+function FindProxyForURL(url, host) {
+  return "PROXY " + convertUrlToHostname(url) + ":99";
+}"}<_**next**_>{"sha": "a9fdeeb771db19ae5e9ea4dbbcb83c0bdbac3b95", "filename": "net/proxy/proxy_resolver_v8_tracing.cc", "status": "modified", "additions": 142, "deletions": 0, "changes": 142, "blob_url": "https://github.com/chromium/chromium/blob/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/proxy/proxy_resolver_v8_tracing.cc", "raw_url": "https://github.com/chromium/chromium/raw/183f4bcddd821b4af3f6234ad2e8c371694a9ffb/net/proxy/proxy_resolver_v8_tracing.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/proxy/proxy_resolver_v8_tracing.cc?ref=183f4bcddd821b4af3f6234ad2e8c371694a9ffb", "patch": "@@ -9,8 +9,10 @@
