{"sha": "a37b89267680e36409e7256cbbe06f8299511d5c", "filename": "third_party/WebKit/LayoutTests/fast/dom/NodeIterator/NodeIterator-attr.html", "status": "added", "additions": 31, "deletions": 0, "changes": 31, "blob_url": "https://github.com/chromium/chromium/blob/eb750a539e4856ba9042abdf39ae9da58fa3ae63/third_party/WebKit/LayoutTests/fast/dom/NodeIterator/NodeIterator-attr.html", "raw_url": "https://github.com/chromium/chromium/raw/eb750a539e4856ba9042abdf39ae9da58fa3ae63/third_party/WebKit/LayoutTests/fast/dom/NodeIterator/NodeIterator-attr.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/dom/NodeIterator/NodeIterator-attr.html?ref=eb750a539e4856ba9042abdf39ae9da58fa3ae63", "patch": "@@ -0,0 +1,31 @@
+<!DOCTYPE html>
+<html>
+<head>
+<title>NodeIterator: Attr crash test</title>
+<script src="../../../resources/testharness.js"></script>
+<script src="../../../resources/testharnessreport.js"></script>
+<link rel="stylesheet" href="../../../resources/testharness.css">
+</head>
+<body>
+<script>
+
+test(function() {
+    var div = document.createElement("div");
+    div.setAttribute('align', 'right');
+    var detachedAttr = div.attributes[0];
+    div.removeAttribute(detachedAttr.name);
+
+    document.createNodeIterator(detachedAttr);
+    gc();
+
+    // Try migrating an element to other document.
+    // This invokes blink::Document::moveNodeIteratorsToNewDocument(),
+    // which will choke unless node iterators book-keeping is correct.
+    var otherDocument = document.implementation.createDocument('', null);
+    var div2 = document.createElement("div");
+    otherDocument.appendChild(div2);
+}, "NodeIterator targetting detached attr node shouldn't crash.");
+
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "c3a7d06af683f096d2b6b5f6cb28c1e5ed8387eb", "filename": "third_party/WebKit/Source/core/dom/NodeIterator.cpp", "status": "modified", "additions": 6, "deletions": 2, "changes": 8, "blob_url": "https://github.com/chromium/chromium/blob/eb750a539e4856ba9042abdf39ae9da58fa3ae63/third_party/WebKit/Source/core/dom/NodeIterator.cpp", "raw_url": "https://github.com/chromium/chromium/raw/eb750a539e4856ba9042abdf39ae9da58fa3ae63/third_party/WebKit/Source/core/dom/NodeIterator.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/dom/NodeIterator.cpp?ref=eb750a539e4856ba9042abdf39ae9da58fa3ae63", "patch": "@@ -25,6 +25,7 @@
