+void GpuFence::Wait() {
+  switch (type_) {
+    case GpuFenceHandleType::kEmpty:
+      break;
+    case GpuFenceHandleType::kAndroidNativeFenceSync:
+#if defined(OS_LINUX) || defined(OS_ANDROID)
+      static const int kInfiniteSyncWaitTimeout = -1;
+      DCHECK_GE(owned_fd_.get(), 0);
