+  button()->set_focus_in_child_widget(true);
+  widget()->set_active(true);
+  button()->AcceleratorPressed(ui::Accelerator(ui::VKEY_RETURN, ui::EF_NONE));
+  EXPECT_TRUE(button()->notified());
