+We pass if we don't crash. "}<_**next**_>{"sha": "e5f7c75cce009a40af613662ad34d645323b5c69", "filename": "third_party/WebKit/LayoutTests/http/tests/navigation/start-load-during-provisional-loader-detach.html", "status": "added", "additions": 27, "deletions": 0, "changes": 27, "blob_url": "https://github.com/chromium/chromium/blob/1948aefa8901dca0ccb993753fca00b15d2a6e25/third_party/WebKit/LayoutTests/http/tests/navigation/start-load-during-provisional-loader-detach.html", "raw_url": "https://github.com/chromium/chromium/raw/1948aefa8901dca0ccb993753fca00b15d2a6e25/third_party/WebKit/LayoutTests/http/tests/navigation/start-load-during-provisional-loader-detach.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/navigation/start-load-during-provisional-loader-detach.html?ref=1948aefa8901dca0ccb993753fca00b15d2a6e25", "patch": "@@ -0,0 +1,27 @@
+<body>
+We pass if we don't crash.
+<script>
+if (window.testRunner)
+    testRunner.dumpAsText();
+
+var child = document.body.appendChild(document.createElement('iframe'));
+child.contentDocument.open();
+var grandchild = child.contentDocument.appendChild(document.createElement('iframe'));
+
+child.contentWindow.onload = function() {
+    var a = grandchild.contentDocument.createElement('a');
+    a.href = 'data:text/xml,';
+    a.click();
+}
+
+var a = grandchild.contentDocument.createElement('a');
+a.href = 'data:text/xml,';
+a.click();
+
+child.contentDocument.close();
+
+a = grandchild.contentDocument.createElement('a');
+a.href = 'data:text/html,';
+a.click();
+</script>
+</body>"}<_**next**_>{"sha": "013a74ed548e954b81d09d1a9a5978c645690013", "filename": "third_party/WebKit/Source/core/html/HTMLAnchorElement.cpp", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/1948aefa8901dca0ccb993753fca00b15d2a6e25/third_party/WebKit/Source/core/html/HTMLAnchorElement.cpp", "raw_url": "https://github.com/chromium/chromium/raw/1948aefa8901dca0ccb993753fca00b15d2a6e25/third_party/WebKit/Source/core/html/HTMLAnchorElement.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/html/HTMLAnchorElement.cpp?ref=1948aefa8901dca0ccb993753fca00b15d2a6e25", "patch": "@@ -362,6 +362,8 @@ void HTMLAnchorElement::handleClick(Event* event)
