{"sha": "415df578a399613e1813db6c890218bfdb6bc49e", "filename": "third_party/WebKit/LayoutTests/fast/css/fontfaceset-cross-frame.html", "status": "added", "additions": 35, "deletions": 0, "changes": 35, "blob_url": "https://github.com/chromium/chromium/blob/0cd7a9f853e3cb7c035b4ab9e07a503552267f9d/third_party/WebKit/LayoutTests/fast/css/fontfaceset-cross-frame.html", "raw_url": "https://github.com/chromium/chromium/raw/0cd7a9f853e3cb7c035b4ab9e07a503552267f9d/third_party/WebKit/LayoutTests/fast/css/fontfaceset-cross-frame.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/css/fontfaceset-cross-frame.html?ref=0cd7a9f853e3cb7c035b4ab9e07a503552267f9d", "patch": "@@ -0,0 +1,35 @@
+<!DOCTYPE html>
+<script src="../../resources/testharness.js"></script>
+<script src="../../resources/testharnessreport.js"></script>
+<body>
+<script>
+
+test(function () {
+  var i = document.createElement("iframe");
+
+  document.body.appendChild(i);
+
+  var d = i.contentDocument.open();
+
+  d.write("<style>@font-face { font-family: f1; src: url(); } @font-face { font-family: f2; src: url(); }</style>");
+  d.close();
+
+  var frame_FontFace = i.contentWindow.FontFace;
+
+  var c = 0;
+  d.fonts.forEach(function (f) {
+    assert_equals(f.constructor, frame_FontFace, "constructed in frame context");
+
+    if (++c == 1) {
+      // First iteration: navigate the frame to about:blank. The second
+      // iteration's |f| should still be created with the prototype.
+
+      var a = d.createElement("a");
+      a.href = "about:blank";
+      a.click();
+    }
+  });
+}, "objects created with correct creation context");
+
+</script>
+</body>"}<_**next**_>{"sha": "782f14c362ee80931126065d3ac18088c5de1a77", "filename": "third_party/WebKit/Source/bindings/core/v8/Iterable.h", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/0cd7a9f853e3cb7c035b4ab9e07a503552267f9d/third_party/WebKit/Source/bindings/core/v8/Iterable.h", "raw_url": "https://github.com/chromium/chromium/raw/0cd7a9f853e3cb7c035b4ab9e07a503552267f9d/third_party/WebKit/Source/bindings/core/v8/Iterable.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/bindings/core/v8/Iterable.h?ref=0cd7a9f853e3cb7c035b4ab9e07a503552267f9d", "patch": "@@ -46,7 +46,7 @@ class Iterable {
