         v8::TryCatch tryCatch(isolate);

-        v8::Local<v8::Object> creationContext(scriptState->context()->Global());
+        v8::Local<v8::Object> creationContext(thisValue.v8Value().As<v8::Object>());
         v8::Local<v8::Function> v8Callback(callback.v8Value().As<v8::Function>());
         v8::Local<v8::Value> v8ThisArg(thisArg.v8Value());
         v8::Local<v8::Value> args[3];"}

{"sha": "937bc786e535363209b45ff0b1b01c21b415b42a", "filename": "ios/web/navigation/navigation_manager_impl_unittest.mm", "status": "modified", "additions": 120, "deletions": 0, "changes": 120, "blob_url": "https://github.com/chromium/chromium/blob/3847be90de19869704f4865331e5f9baff7ae5f0/ios/web/navigation/navigation_manager_impl_unittest.mm", "raw_url": "https://github.com/chromium/chromium/raw/3847be90de19869704f4865331e5f9baff7ae5f0/ios/web/navigation/navigation_manager_impl_unittest.mm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ios/web/navigation/navigation_manager_impl_unittest.mm?ref=3847be90de19869704f4865331e5f9baff7ae5f0", "patch": "@@ -1957,6 +1957,126 @@ GURL rewritten_url4(
