+<!doctype html>
+<html>
+<body>
+This is a body
+<span id="status"></span>
+</body>
+<script>
+var error = '';
+var addError = function(newError) {
+  error += newError;
+  var status = error.length == 0 ? 'success' : error;
+  document.getElementById('status').textContent = status;
+};
+
+Object.defineProperty(Object.prototype,
+                      'handleResponse',
+                      {configurable: true, set: function(v) {
+  addError('Intercepted handleResponse\n');
+  Object.defineProperty(
+      this, "handleResponse", {configurable: true, value: v});
+}});
+
+Object.defineProperty(Object.prototype,
+                      "$set",
+                      {configurable: true, set: function(v) {
+  addError('Intercepted $set\n');
+  Object.defineProperty(this, "$set", {configurable: true, value: v});
+}});
+
+Object.defineProperty(Object.prototype,
+                      "clear",
+                      {configurable: true, set: function(v) {
+  addError('Intercepted clear\n');
+  Object.defineProperty(this, 'clear', {configurable: true, value: v});
+}});
+
+// Bindings are lazily initialized. Poke it.
+chrome.runtime;
+// If the runtime bindings aren't created, we didn't test anything.
+if (!chrome.runtime)
+  addError('chrome.runtime was not created.\n');
+
+addError('');
+</script>"}<_**next**_>{"sha": "03158926eb457c05f35dc9c5c9e1f4ce21425722", "filename": "extensions/renderer/api_test_base.cc", "status": "modified", "additions": 8, "deletions": 7, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/83a4b3aa72d98fe4176b4a54c8cea227ed966570/extensions/renderer/api_test_base.cc", "raw_url": "https://github.com/chromium/chromium/raw/83a4b3aa72d98fe4176b4a54c8cea227ed966570/extensions/renderer/api_test_base.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/extensions/renderer/api_test_base.cc?ref=83a4b3aa72d98fe4176b4a54c8cea227ed966570", "patch": "@@ -140,17 +140,18 @@ void ApiTestEnvironment::RegisterModules() {
