-      {"upgradingMessage", IDS_CROSTINI_UPGRADER_UPGRADING},
-      {"succeededMessage", IDS_CROSTINI_UPGRADER_SUCCEEDED},
-      {"cancelingMessage", IDS_CROSTINI_UPGRADER_CANCELING},
