{"sha": "0d4a1117633be14b6680a5a66e632878560c4b99", "filename": "third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/report-strips-fragment.html", "status": "added", "additions": 20, "deletions": 0, "changes": 20, "blob_url": "https://github.com/chromium/chromium/blob/fea16c8b60ff3d0756d5eb392394963b647bc41a/third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/report-strips-fragment.html", "raw_url": "https://github.com/chromium/chromium/raw/fea16c8b60ff3d0756d5eb392394963b647bc41a/third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/report-strips-fragment.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/report-strips-fragment.html?ref=fea16c8b60ff3d0756d5eb392394963b647bc41a", "patch": "@@ -0,0 +1,20 @@
+<!DOCTYPE html>
+<script src="/resources/testharness.js"></script>
+<script src="/resources/testharnessreport.js"></script>
+<script src="./resources/testharness-helper.js"></script>
+
+<meta http-equiv="Content-Security-Policy" content="img-src 'none'">
+<script>
+  async_test(t => {
+    waitUntilCSPEventForURL(t, "https://evil.com/img.png")
+      .then(t.step_func_done(e => {
+        var u = new URL(e.documentURI);
+        assert_equals(u.hash, "");
