+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/browser/printing/print_view_manager.h"
+#include "chrome/browser/printing/print_preview_test.h"
+#include "chrome/browser/ui/browser_commands.h"
+#include "chrome/browser/ui/tabs/tab_strip_model.h"
+#include "content/public/test/test_renderer_host.h"
+
+namespace printing {
+
+using PrintViewManagerTest = PrintPreviewTest;
+
+TEST_F(PrintViewManagerTest, PrintSubFrameAndDestroy) {
+  chrome::NewTab(browser());
+  content::WebContents* web_contents =
+      browser()->tab_strip_model()->GetActiveWebContents();
+  ASSERT_TRUE(web_contents);
+
+  content::RenderFrameHost* sub_frame =
+      content::RenderFrameHostTester::For(web_contents->GetMainFrame())
+          ->AppendChild("child");
+
+  PrintViewManager* print_view_manager =
+      PrintViewManager::FromWebContents(web_contents);
+  ASSERT_TRUE(print_view_manager);
+  EXPECT_FALSE(print_view_manager->print_preview_rfh());
+
+  print_view_manager->PrintPreviewNow(sub_frame, false);
+  EXPECT_TRUE(print_view_manager->print_preview_rfh());
+
+  content::RenderFrameHostTester::For(sub_frame)->Detach();
+  EXPECT_FALSE(print_view_manager->print_preview_rfh());
+}
+
+}  // namespace printing"}<_**next**_>{"sha": "7c1d1be1c2323a44721cf5af6de1747d334c40d6", "filename": "chrome/test/BUILD.gn", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/746da1cc6b2fbc2f725934542eedc49b41e5f17b/chrome/test/BUILD.gn", "raw_url": "https://github.com/chromium/chromium/raw/746da1cc6b2fbc2f725934542eedc49b41e5f17b/chrome/test/BUILD.gn", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/BUILD.gn?ref=746da1cc6b2fbc2f725934542eedc49b41e5f17b", "patch": "@@ -4358,6 +4358,7 @@ test("unit_tests") {
