+package org.chromium.components.module_installer;
+
+/** Dummy fallback of ModuleInstaller for APK builds. */
+public class ModuleInstallerImpl implements ModuleInstaller {
+    /** A valid singleton instance is necessary for tests to swap it out. */
+    private static ModuleInstaller sInstance = new ModuleInstallerImpl();
+
+    /** Returns the singleton instance. */
+    public static ModuleInstaller getInstance() {
+        return sInstance;
+    }
+
+    public static void setInstanceForTesting(ModuleInstaller moduleInstaller) {
+        sInstance = moduleInstaller;
+    }
+
+    @Override
+    public void install(String moduleName, OnModuleInstallFinishedListener onFinishedListener) {
+        throw new UnsupportedOperationException("Cannot install module if APK");
+    }
+
+    @Override
+    public void installDeferred(String moduleName) {
+        throw new UnsupportedOperationException("Cannot deferred install module if APK");
+    }
+
+    private ModuleInstallerImpl() {}
+}"}<_**next**_>{"sha": "02b8519a6b2ac5b13a6d4503e923ca9b5d1b3b95", "filename": "components/module_installer/android/java/src-test/org/chromium/components/module_installer/ModuleInstaller.java", "status": "removed", "additions": 0, "deletions": 39, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/246f74b802ea0fc5e261f0d99d10bd09384f05a6/components/module_installer/android/java/src-test/org/chromium/components/module_installer/ModuleInstaller.java", "raw_url": "https://github.com/chromium/chromium/raw/246f74b802ea0fc5e261f0d99d10bd09384f05a6/components/module_installer/android/java/src-test/org/chromium/components/module_installer/ModuleInstaller.java", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/components/module_installer/android/java/src-test/org/chromium/components/module_installer/ModuleInstaller.java?ref=246f74b802ea0fc5e261f0d99d10bd09384f05a6", "patch": "@@ -1,39 +0,0 @@
