+// Copyright 2019 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+package org.chromium.components.module_installer;
+
+import org.junit.rules.ExternalResource;
+
+/**
+ * This rule allows the caller to specify their own {@link ModuleInstaller} for the duration of the
+ * test and resets it back to what it was before.
+ *
+ * TODO(wnwen): This should eventually become ModuleConfigRule.
+ */
+public class ModuleInstallerRule extends ExternalResource {
+    private ModuleInstaller mOldModuleInstaller;
+    private final ModuleInstaller mMockModuleInstaller;
+
+    public ModuleInstallerRule(ModuleInstaller mockModuleInstaller) {
+        mMockModuleInstaller = mockModuleInstaller;
+    }
+
+    @Override
+    protected void before() {
+        mOldModuleInstaller = ModuleInstaller.getInstance();
+        ModuleInstaller.setInstanceForTesting(mMockModuleInstaller);
+    }
+
+    @Override
+    protected void after() {
+        ModuleInstaller.setInstanceForTesting(mOldModuleInstaller);
+    }
+}"}

{"sha": "164fafe7203ad9b31eb6c63b98d21bb384f4fe95", "filename": "content/browser/frame_host/navigation_controller_impl.cc", "status": "modified", "additions": 35, "deletions": 0, "changes": 35, "blob_url": "https://github.com/chromium/chromium/blob/c32cd2069ae8062b52e5b7b1faf5936bd71a583a/content/browser/frame_host/navigation_controller_impl.cc", "raw_url": "https://github.com/chromium/chromium/raw/c32cd2069ae8062b52e5b7b1faf5936bd71a583a/content/browser/frame_host/navigation_controller_impl.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/frame_host/navigation_controller_impl.cc?ref=c32cd2069ae8062b52e5b7b1faf5936bd71a583a", "patch": "@@ -39,6 +39,7 @@

 #include "base/bind.h"
 #include "base/command_line.h"
+#include "base/debug/alias.h"
 #include "base/debug/dump_without_crashing.h"
 #include "base/logging.h"
 #include "base/memory/ptr_util.h"
@@ -164,6 +165,35 @@ bool ShouldTreatNavigationAsReload(const NavigationEntry* entry) {
   return false;
 }

+// TODO(estark): remove this DumpWithoutCrashing after investigating
+// https://crbug.com/688425.
+void MaybeDumpCopiedNonSameOriginEntry(
+    const std::string& navigation_description,
+    const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
+    bool is_in_page,
+    NavigationEntry* entry) {
+  if (!entry)
+    return;
+  if (url::Origin(entry->GetURL()).IsSameOriginWith(url::Origin(params.url)))
+    return;
+
+  std::string debug_info =
+      navigation_description + ": " +
+      std::string(is_in_page ? "Is in page, " : "Is not in page, ") +
+      std::string(params.nav_entry_id ? "has nav entry id, "
+                                      : "does not have nav entry id, ") +
+      std::string(params.did_create_new_entry ? "did create new entry, "
+                                              : "did not create new entry, ") +
+      std::string(params.should_replace_current_entry
+                      ? "should replace current entry, "
+                      : "should not replace current entry, ") +
+      entry->GetURL().spec() + " -> " + params.url.spec();
+  char debug_buf[2000];
+  base::strlcpy(debug_buf, debug_info.c_str(), arraysize(debug_buf));
+  base::debug::Alias(&debug_buf);
+  base::debug::DumpWithoutCrashing();
+}
+
 }  // namespace

 // NavigationControllerImpl ----------------------------------------------------
@@ -1107,6 +1137,9 @@ void NavigationControllerImpl::RendererDidNavigateToNewPage(
     CHECK(frame_entry->HasOneRef());

     update_virtual_url = new_entry->update_virtual_url_with_url();
+
+    MaybeDumpCopiedNonSameOriginEntry("New page navigation", params, is_in_page,
+                                      GetLastCommittedEntry());
   }

   // Only make a copy of the pending entry if it is appropriate for the new page
@@ -1212,6 +1245,8 @@ void NavigationControllerImpl::RendererDidNavigateToExistingPage(
     // meanwhile and no new page was created. We are stuck at the last committed
     // entry.
     entry = GetLastCommittedEntry();
+    MaybeDumpCopiedNonSameOriginEntry("Existing page navigation", params,
+                                      is_in_page, entry);
   } else if (params.nav_entry_id) {
     // This is a browser-initiated navigation (back/forward/reload).
     entry = GetEntryWithUniqueID(params.nav_entry_id);"}

