+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with false if the system does ' +
+    'not have an adapter.';
+
+bluetooth_test(async () => {
+  await navigator.bluetooth.test.simulateCentral({state: 'absent'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_false(
+      availability,
+      'getAvailability() resolves promise with false when adapter is absent.');
+}, test_desc);"}<_**next**_>{"sha": "d5e9d1f2b6ffbb009b03d0cde8155144aeee630b", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js", "status": "added", "additions": 24, "deletions": 0, "changes": 24, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,24 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with true after adapter is ' +
+    'inserted into a system with a platform that supports Bluetooth LE.';
+
+bluetooth_test(async () => {
+  const fake_central =
+      await navigator.bluetooth.test.simulateCentral({state: 'absent'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_false(
+      availability,
+      'getAvailability() resolves promise with false when adapter is absent.');
+
+  await fake_central.setState('powered-on');
+  availability = await navigator.bluetooth.getAvailability();
+  assert_true(
+      availability,
+      'getAvailability() resolves promise with true after Bluetooth LE ' +
+          'capable adapter has been has been added.');
+}, test_desc);"}<_**next**_>{"sha": "8fe9265a46ed22a9bb0e0480f045135b323565f0", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,17 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with true if the Bluetooth ' +
+    'radio is powered off, but the platform that supports Bluetooth LE.';
+
+bluetooth_test(async () => {
+  await navigator.bluetooth.test.simulateCentral({state: 'powered-off'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_true(
+      availability,
+      'getAvailability() resolves promise with true when adapter is powered ' +
+          'off.');
+}, test_desc);"}<_**next**_>{"sha": "8b9256a4c35680722ad2ee00784de6649b703611", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-getAvailability.https.window.js", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,17 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with true if the Bluetooth ' +
+    'radio is powered on and the platform supports Bluetooth LE.';
+
+bluetooth_test(async () => {
+  await navigator.bluetooth.test.simulateCentral({state: 'powered-on'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_true(
+      availability,
+      'getAvailability() resolves promise with true when adapter is powered ' +
+          'on and it supports Bluetooth Low-Energy.');
+}, test_desc);"}<_**next**_>{"sha": "b8b49121fc0170eb9dc95614b5c3b19ef16bd02b", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-off-on-getAvailability.https.window.js", "status": "added", "additions": 38, "deletions": 0, "changes": 38, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-off-on-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-off-on-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-on-off-on-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,38 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() is not affected by the powered state of ' +
+    'the adapter.';
+
+bluetooth_test(async () => {
+  const fake_central =
+      await navigator.bluetooth.test.simulateCentral({state: 'powered-on'});
+  {
+    const availability = await navigator.bluetooth.getAvailability();
+    assert_true(
+        availability,
+        'getAvailability() resolves promise with true when adapter is ' +
+            'powered on and it supports Bluetooth Low-Energy.');
+  }
+
+  {
+    await fake_central.setState('powered-off');
+    const availability = await navigator.bluetooth.getAvailability();
+    assert_true(
+        availability,
+        'getAvailability() resolves promise with true after adapter powered ' +
+            'off.');
+  }
+
+  {
+    await fake_central.setState('powered-on');
+    const availability = await navigator.bluetooth.getAvailability();
+    assert_true(
+        availability,
+        'getAvailability() resolves promise with true when adapter is ' +
+            'powered back on.');
+  }
+}, test_desc);"}<_**next**_>{"sha": "cc2c33d1d4c2bf2cdad0cd0874a739b462ff90ec", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,25 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with false after the powered ' +
+    'on adapter is removed.';
+
+bluetooth_test(async () => {
+  const fake_central =
+      await navigator.bluetooth.test.simulateCentral({state: 'powered-on'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_true(
+      availability,
+      'getAvailability() resolves promise with true when adapter is powered ' +
+          'on and it supports Bluetooth Low-Energy.');
+
+  await fake_central.setState('absent');
+  availability = await navigator.bluetooth.getAvailability();
+  assert_false(
+      availability,
+      'getAvailability() resolves promise with false after adapter has been ' +
+          'has been removed.');
+}, test_desc);"}<_**next**_>{"sha": "bf5e4226e08d44e521b533f020c0deaa95851983", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/cross-origin-iframe-getAvailability.sub.https.window.js", "status": "added", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/cross-origin-iframe-getAvailability.sub.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/cross-origin-iframe-getAvailability.sub.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/cross-origin-iframe-getAvailability.sub.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,32 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with false if called from a ' +
+    'unique origin';
+const cross_origin_src = 'https://{{domains[www]}}:{{ports[https][0]}}' +
+    '/bluetooth/resources/health-thermometer-iframe.html'
+let iframe = document.createElement('iframe');
+
+bluetooth_test(async () => {
+  await navigator.bluetooth.test.simulateCentral({state: 'powered-on'});
+  await new Promise(resolve => {
+    iframe.src = cross_origin_src;
+    document.body.appendChild(iframe);
+    iframe.addEventListener('load', resolve);
+  });
+  await new Promise(resolve => {
+    callWithTrustedClick(
+        () => iframe.contentWindow.postMessage({type: 'GetAvailability'}, '*'));
+
+    window.onmessage = messageEvent => {
+      assert_equals(
+          messageEvent.data, false,
+          'getAvailability resolves to false when called from a unique ' +
+              'origin.');
+      resolve();
+    };
+  });
+}, test_desc);"}<_**next**_>{"sha": "f1827c946b4909af8e25a3b90f2b6fcb8b21874f", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/idl/idlharness.tentative.https.window-expected.txt", "status": "modified", "additions": 3, "deletions": 3, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/idl/idlharness.tentative.https.window-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/idl/idlharness.tentative.https.window-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/idl/idlharness.tentative.https.window-expected.txt?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -1,5 +1,5 @@
