{"sha": "a4f1c9826fab0f0d564d861855dc36de99b1cbbc", "filename": "third_party/WebKit/LayoutTests/fast/dom/location-toprimitive.html", "status": "added", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/chromium/chromium/blob/1f959adce3efa86d7d9560f9642c6ae816f8d81c/third_party/WebKit/LayoutTests/fast/dom/location-toprimitive.html", "raw_url": "https://github.com/chromium/chromium/raw/1f959adce3efa86d7d9560f9642c6ae816f8d81c/third_party/WebKit/LayoutTests/fast/dom/location-toprimitive.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/dom/location-toprimitive.html?ref=1f959adce3efa86d7d9560f9642c6ae816f8d81c", "patch": "@@ -0,0 +1,32 @@
+<!DOCTYPE html>
+<script src="../../resources/testharness.js"></script>
+<script src="../../resources/testharnessreport.js"></script>
+<script>
+test(function() {
+  // The property descriptor of location[Symbol.toPrimitive] must be
+  //   {configurable: false, enumerable: false, writable: false,
+  //    value: undefined}.
+  assert_own_property(location, Symbol.toPrimitive,
+                      "location does not have Symbol.toPrimitive property.");
+  var pd = Object.getOwnPropertyDescriptor(location, Symbol.toPrimitive);
+  assert_false(pd.configurable,
+               "location's Symbol.toPrimitive is configurable.");
+  assert_false(pd.enumerable, "location's Symbol.toPrimitive is enumerable.");
+  assert_false(pd.writable, "location's Symbol.toPrimitive is writable.");
+  assert_true('value' in pd,
+              "location's Symbol.toPrimitive is not a data property.");
+  assert_equals(pd.value, undefined,
+                "The value of location's Symbol.toPrimitive is not undefined.");
+
+  // location's Symbol.toPrimitive supersedes Object.prototype's one.
+  // https://crbug.com/680409
+  Object.prototype[Symbol.toPrimitive] = function() { return "hacked"; };
+  assert_equals(String({}), "hacked",
+                "Object.prototype doesn't have a hacked Symbol.toPrimitive " +
+                "property.");
+  assert_not_equals(String(location), "hacked",
+                    "location's Symbol.toPrimitive gets hacked.");
+}, "Location objects must have Symbol.toPrimitive property defined.");
+
+done();
+</script>"}<_**next**_>{"sha": "4b49ba394c7a821a1770788fd7d5611a6f7e0c42", "filename": "third_party/WebKit/Source/bindings/templates/interface_base.cpp.tmpl", "status": "modified", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/1f959adce3efa86d7d9560f9642c6ae816f8d81c/third_party/WebKit/Source/bindings/templates/interface_base.cpp.tmpl", "raw_url": "https://github.com/chromium/chromium/raw/1f959adce3efa86d7d9560f9642c6ae816f8d81c/third_party/WebKit/Source/bindings/templates/interface_base.cpp.tmpl", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/bindings/templates/interface_base.cpp.tmpl?ref=1f959adce3efa86d7d9560f9642c6ae816f8d81c", "patch": "@@ -528,6 +528,17 @@ static void install{{v8_class}}Template(v8::Isolate* isolate, const DOMWrapperWo
   {% endfilter %}
   {% endif %}

+  {% if interface_name == 'Location' %}
+  // Symbol.toPrimitive
+  // Prevent author scripts to inject Symbol.toPrimitive property into location
+  // objects, also prevent the look-up of Symbol.toPrimitive through the
+  // prototype chain.
+  instanceTemplate->Set(v8::Symbol::GetToPrimitive(isolate),
+                        v8::Undefined(isolate),
+                        static_cast<v8::PropertyAttribute>(
+                            v8::ReadOnly | v8::DontEnum | v8::DontDelete));
+  {% endif %}
+
   {% if legacy_caller and not is_partial %}
   instanceTemplate->SetCallAsFunctionHandler({{cpp_class_or_partial}}V8Internal::{{legacy_caller.name}}MethodCallback);
   {% elif has_custom_legacy_call_as_function and not is_partial %}"}

