{"sha": "6613d290c9a5c4ee91e18caf7e3c424830b1934a", "filename": "third_party/blink/renderer/core/layout/ng/ng_column_layout_algorithm.cc", "status": "modified", "additions": 34, "deletions": 5, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/f85716d839636e0814d3309ce1d8f8a2cd1fb9a8/third_party/blink/renderer/core/layout/ng/ng_column_layout_algorithm.cc", "raw_url": "https://github.com/chromium/chromium/raw/f85716d839636e0814d3309ce1d8f8a2cd1fb9a8/third_party/blink/renderer/core/layout/ng/ng_column_layout_algorithm.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/core/layout/ng/ng_column_layout_algorithm.cc?ref=f85716d839636e0814d3309ce1d8f8a2cd1fb9a8", "patch": "@@ -27,6 +27,37 @@ inline bool NeedsColumnBalancing(LayoutUnit block_size,
          style.GetColumnFill() == EColumnFill::kBalance;
 }

+LayoutUnit CalculateColumnContentBlockSize(
+    const NGPhysicalContainerFragment& fragment,
+    bool multicol_is_horizontal_writing_mode) {
+  // TODO(mstensho): Once LayoutNG is capable of calculating overflow on its
+  // own, we should probably just move over to relying on that machinery,
+  // instead of doing all this on our own.
+  LayoutUnit total_size;
+  for (const auto& child : fragment.Children()) {
+    LayoutUnit size;
+    LayoutUnit offset;
+    if (multicol_is_horizontal_writing_mode) {
+      offset = child.Offset().top;
+      size = child->Size().height;
+    } else {
+      offset = child.Offset().left;
+      size = child->Size().width;
+    }
+    if (child->IsContainer()) {
+      LayoutUnit children_size = CalculateColumnContentBlockSize(
+          To<NGPhysicalContainerFragment>(*child),
+          multicol_is_horizontal_writing_mode);
+      if (size < children_size)
+        size = children_size;
+    }
+    LayoutUnit block_end = offset + size;
+    if (total_size < block_end)
+      total_size = block_end;
+  }
+  return total_size;
+}
+
 }  // namespace

