+     "chrome-devtools://devtools/bundled/devtools.html"
+          "?v8only=true&experiments=true&debugFrontend=true"
+          "&can_dock=true&isSharedWorker=true&remoteFrontend=true"},
+    {"chrome-devtools://devtools/?ws=any-value-is-fine",
