+<!doctype html>
+<html>
+<head>
+<script type="text/javascript" src="../../http/tests/inspector-protocol/inspector-protocol-test.js"></script>
+<script>
+function appendIframe()
+{
+    var frame = document.createElement("iframe");
+    frame.src = "resources/console-log-navigate.html";
+    document.body.appendChild(frame);
+    return new Promise((resolve) => frame.onload = resolve);
+}
+
+function createIframeAndRunTest()
+{
+    var frame = document.createElement("iframe");
+    frame.id = "iframe";
+    frame.src = "resources/console-log-navigate-on-load.html";
+    frame.onload = () => runTest();
+    document.body.appendChild(frame);
+}
+
+function test()
+{
+    InspectorTest.sendCommandPromise("Runtime.enable", {})
+        .then(() => checkExpression("logArray()"))
+        .then(() => checkExpression("logDate()"))
+        .then(() => checkExpression("logDateWithArg()"))
+        .then(() => InspectorTest.completeTest());
+
+    function checkExpression(expression)
+    {
+        var contextId;
+        InspectorTest.waitForEventPromise("Runtime.executionContextCreated")
+            .then((result) => contextId = result.params.context.id);
+        return InspectorTest.sendCommandPromise("Runtime.evaluate", { expression: "appendIframe()", awaitPromise: true})
+            .then(() => InspectorTest.sendCommandPromise("Runtime.evaluate", { expression: expression, contextId: contextId }))
+            .then((r) => logObject(r));
+    }
+
+    function logObject(result)
+    {
+        result.id = 0;
+        InspectorTest.logObject(result);
+    }
+}
+</script>
+</head>
+<body onload="createIframeAndRunTest()">
+This tests how navigation is handled from inside debugger code (console.log).
+</body>
+</html>"}<_**next**_>{"sha": "4c3601bef17391f868830383bc59a71da87e4f90", "filename": "third_party/WebKit/LayoutTests/inspector-protocol/runtime/runtime-console-log-handle-navigate.txt", "status": "added", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/37faa2db833127ac9b6d461d8bc49952e557c743/third_party/WebKit/LayoutTests/inspector-protocol/runtime/runtime-console-log-handle-navigate.txt", "raw_url": "https://github.com/chromium/chromium/raw/37faa2db833127ac9b6d461d8bc49952e557c743/third_party/WebKit/LayoutTests/inspector-protocol/runtime/runtime-console-log-handle-navigate.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/inspector-protocol/runtime/runtime-console-log-handle-navigate.txt?ref=37faa2db833127ac9b6d461d8bc49952e557c743", "patch": "@@ -0,0 +1,4 @@
