{"sha": "ffc31d6a0e987abc3687ad4a1664eedc2fd5f191", "filename": "third_party/WebKit/LayoutTests/fast/dom/shadow/link-without-rel-crash.html", "status": "added", "additions": 22, "deletions": 0, "changes": 22, "blob_url": "https://github.com/chromium/chromium/blob/2f8e481c12c9e8de107b73508b6c283569d4df5b/third_party/WebKit/LayoutTests/fast/dom/shadow/link-without-rel-crash.html", "raw_url": "https://github.com/chromium/chromium/raw/2f8e481c12c9e8de107b73508b6c283569d4df5b/third_party/WebKit/LayoutTests/fast/dom/shadow/link-without-rel-crash.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/dom/shadow/link-without-rel-crash.html?ref=2f8e481c12c9e8de107b73508b6c283569d4df5b", "patch": "@@ -0,0 +1,22 @@
+<!DOCTYPE html>
+<script src="../../../resources/testharness.js"></script>
+<script src="../../../resources/testharnessreport.js"></script>
+<script>
+
+let t = async_test('Setting rel=stylesheet on link in shadow root does not crash');
+
+function run() {
+  t.step(() => {
+    let link = document.createElement('link');
+    link.setAttribute('href', 'empty.css');
+    let div = document.createElement('div');
+    let shadowRoot = div.attachShadow({mode: 'open'});
+    document.body.append(div);
+    shadowRoot.append(link);
+    link.setAttribute('rel','stylesheet');
+  });
+  t.done();
+}
+
+</script>
+<body onload="run()"></body>
