{"sha": "e820f90f9128ffdd0b88dd0d0f9a862c4166f7d0", "filename": "chrome/android/java/src/org/chromium/chrome/browser/omnibox/UrlBar.java", "status": "modified", "additions": 30, "deletions": 7, "changes": 37, "blob_url": "https://github.com/chromium/chromium/blob/18c10ae06ccb39b4ff6edc4c40f11127239c4f63/chrome/android/java/src/org/chromium/chrome/browser/omnibox/UrlBar.java", "raw_url": "https://github.com/chromium/chromium/raw/18c10ae06ccb39b4ff6edc4c40f11127239c4f63/chrome/android/java/src/org/chromium/chrome/browser/omnibox/UrlBar.java", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/android/java/src/org/chromium/chrome/browser/omnibox/UrlBar.java?ref=18c10ae06ccb39b4ff6edc4c40f11127239c4f63", "patch": "@@ -694,20 +694,43 @@ private void scrollToTLD() {
         Editable url = getText();
         int measuredWidth = getMeasuredWidth() - (getPaddingLeft() + getPaddingRight());

+        Layout textLayout = getLayout();
