+<!-- This tests that navigating a main window to a local scheme preserves the current CSP.
+     We need to test this in a main window with no parent/opener so we use
+     a link with target=_blank and rel=noopener. -->
+<body>
+    <script>
+      const a = document.createElement("a")
+      a.href = "support/navigate-self-to-blob.html?csp=script-src%20%27nonce-abc%27&report_id={{$id:uuid()}}";
+      a.target = "_blank"
+      a.rel = "noopener"
+      a.click()
+    </script>
+    <script async defer src='../support/checkReport.sub.js?reportField=violated-directive&reportValue=script-src%20%27nonce-abc%27&reportID={{$id}}'></script>
+</body>
+
+</html>"}<_**next**_>{"sha": "9ea069969cafff022e94fef3de535feafaca1de7", "filename": "third_party/WebKit/LayoutTests/external/wpt/content-security-policy/inheritance/support/navigate-self-to-blob.html", "status": "added", "additions": 6, "deletions": 0, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/d683fb12566eaec180ee0e0506288f46cc7a43e7/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/inheritance/support/navigate-self-to-blob.html", "raw_url": "https://github.com/chromium/chromium/raw/d683fb12566eaec180ee0e0506288f46cc7a43e7/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/inheritance/support/navigate-self-to-blob.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/inheritance/support/navigate-self-to-blob.html?ref=d683fb12566eaec180ee0e0506288f46cc7a43e7", "patch": "@@ -0,0 +1,6 @@
