+// Check which URLs an empty ProxyBypassRules matches.
+TEST(ProxyBypassRulesTest, DefaultImplicitRules) {
+  ProxyBypassRules rules;
+
+  EXPECT_EQ("", rules.ToString());
+
+  // Should bypass all localhost and loopback names.
