{"sha": "6979a2f11f33c11ef6f8604a458da917ccd8586a", "filename": "content/browser/frame_host/navigation_controller_impl_browsertest.cc", "status": "modified", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/4f8104c528f0147c7527718d5aa7c9c38c8220d0/content/browser/frame_host/navigation_controller_impl_browsertest.cc", "raw_url": "https://github.com/chromium/chromium/raw/4f8104c528f0147c7527718d5aa7c9c38c8220d0/content/browser/frame_host/navigation_controller_impl_browsertest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/frame_host/navigation_controller_impl_browsertest.cc?ref=4f8104c528f0147c7527718d5aa7c9c38c8220d0", "patch": "@@ -6013,6 +6013,21 @@ IN_PROC_BROWSER_TEST_F(NavigationControllerBrowserTest,
   EXPECT_EQ(0, controller.GetCurrentEntryIndex());
 }

+// Make sure that a 304 response to a navigation aborts the navigation.
+IN_PROC_BROWSER_TEST_F(NavigationControllerBrowserTest, NavigateTo304) {
+  // URL that just returns a blank page.
+  GURL initial_url = embedded_test_server()->GetURL("/set-header");
+  // URL that returns a response with a 304 status code.
+  GURL not_modified_url = embedded_test_server()->GetURL("/echo?status=304");
+
+  EXPECT_TRUE(NavigateToURL(shell(), initial_url));
+  EXPECT_EQ(initial_url, shell()->web_contents()->GetVisibleURL());
+
+  // The navigation should be aborted.
+  EXPECT_FALSE(NavigateToURL(shell(), not_modified_url));
+  EXPECT_EQ(initial_url, shell()->web_contents()->GetVisibleURL());
+}
+
 // Ensure that we do not corrupt a NavigationEntry's PageState if two forward
 // navigations compete in different frames.  See https://crbug.com/623319.
