{"sha": "b864cdedb906dddfa91ba42a017864ee3da11a8d", "filename": "third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe-expected.txt", "status": "added", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe-expected.txt?ref=5fe74f831fddb92afa5ddfe46490bb49f083132b", "patch": "@@ -0,0 +1,12 @@
+ALERT: Going back.
+Tests that subsequent navigation in an iframe restored from history does not report resource timing.
+
+On success, you will see a series of "PASS" messages, followed by "TEST COMPLETE".
+
+
+PASS resources.length is 1
+PASS resources[0].name is "http://127.0.0.1:8000/js-test-resources/js-test.js"
+PASS successfullyParsed is true
+
+TEST COMPLETE
+"}<_**next**_>{"sha": "14a559dc6f43dc3e2d53d8359958e0a8f3197ee9", "filename": "third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe.html", "status": "added", "additions": 30, "deletions": 0, "changes": 30, "blob_url": "https://github.com/chromium/chromium/blob/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe.html", "raw_url": "https://github.com/chromium/chromium/raw/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/misc/resource-timing-navigation-in-restored-iframe.html?ref=5fe74f831fddb92afa5ddfe46490bb49f083132b", "patch": "@@ -0,0 +1,30 @@
+<!DOCTYPE html>
+<script src="/js-test-resources/js-test.js"></script>
+<script>
+description('Tests that subsequent navigation in an iframe restored from history does not report resource timing.');
+window.jsTestIsAsync = true;
+
+function runTest() {
+    if (!sessionStorage.didNav) {
+        sessionStorage.didNav = true;
+        // Navigate a timeout to make sure we generate a history entry that we can go back to.
+        setTimeout(function() {
+            location.href = 'resources/alert-then-back.html';
+        }, 0);
+    } else {
+        delete sessionStorage.didNav;
+        window.addEventListener('message', (event) => {
+            resources = performance.getEntriesByType('resource');
+            shouldBe('resources.length', '1');
+            shouldBeEqualToString('resources[0].name', 'http://127.0.0.1:8000/js-test-resources/js-test.js');
+            if (window.testRunner)
+                finishJSTest();
+        });
+        document.getElementById('target-iframe').contentWindow.postMessage('navigate', '*');
+    }
+}
+
+window.onload = runTest;
+
+</script>
+<iframe id="target-iframe" src="http://localhost:8080/misc/resources/navigate-on-message.html"></iframe>"}<_**next**_>{"sha": "d41066830664e460f15524f58bffed09522e7ebc", "filename": "third_party/WebKit/LayoutTests/http/tests/misc/resources/navigate-on-message.html", "status": "added", "additions": 8, "deletions": 0, "changes": 8, "blob_url": "https://github.com/chromium/chromium/blob/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resources/navigate-on-message.html", "raw_url": "https://github.com/chromium/chromium/raw/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resources/navigate-on-message.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/misc/resources/navigate-on-message.html?ref=5fe74f831fddb92afa5ddfe46490bb49f083132b", "patch": "@@ -0,0 +1,8 @@
+<!DOCTYPE html>
+<script>
+function handleMessage() {
+    window.location = 'post-message-to-parent.html';
+}
+
+window.addEventListener("message", handleMessage);
+</script>"}<_**next**_>{"sha": "136a5a50e394b99dd624011601c7cff3307c898d", "filename": "third_party/WebKit/LayoutTests/http/tests/misc/resources/post-message-to-parent.html", "status": "added", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resources/post-message-to-parent.html", "raw_url": "https://github.com/chromium/chromium/raw/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/WebKit/LayoutTests/http/tests/misc/resources/post-message-to-parent.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/misc/resources/post-message-to-parent.html?ref=5fe74f831fddb92afa5ddfe46490bb49f083132b", "patch": "@@ -0,0 +1,4 @@
+<!DOCTYPE html>
+<script>
+  window.parent.postMessage('navigated', '*');
+</script>"}<_**next**_>{"sha": "f14e8bf372acef1776500c288605610d312a4b18", "filename": "third_party/blink/renderer/core/frame/local_frame.h", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/blink/renderer/core/frame/local_frame.h", "raw_url": "https://github.com/chromium/chromium/raw/5fe74f831fddb92afa5ddfe46490bb49f083132b/third_party/blink/renderer/core/frame/local_frame.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/core/frame/local_frame.h?ref=5fe74f831fddb92afa5ddfe46490bb49f083132b", "patch": "@@ -325,8 +325,8 @@ class CORE_EXPORT LocalFrame final : public Frame,
