{"sha": "240db09c875c0feec486756132d1ea70e847bceb", "filename": "third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/test-helpers.js", "status": "modified", "additions": 12, "deletions": 0, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/test-helpers.js", "raw_url": "https://github.com/chromium/chromium/raw/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/test-helpers.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/test-helpers.js?ref=ec96e9da29ec26491de4be2464e0735404546e62", "patch": "@@ -210,3 +210,15 @@ function login(test, local, remote) {
                           'password2' + suffix, 'cookie2');
       });
 }
+
+function wait_for_port_message(port, handler) {
+  return new Promise((resolve, reject) => {
+    port.onmessage = (e) => {
+      try {
+        resolve(handler(e));
+      } catch (e) {
+        reject(e);
+      }
+    };
+  });
+}"}<_**next**_>{"sha": "0eeb28683756d68d68d64927f670ae6b20c75765", "filename": "third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/update-no-controllee-worker.js", "status": "added", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/chromium/chromium/blob/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/update-no-controllee-worker.js", "raw_url": "https://github.com/chromium/chromium/raw/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/update-no-controllee-worker.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/serviceworker/resources/update-no-controllee-worker.js?ref=ec96e9da29ec26491de4be2464e0735404546e62", "patch": "@@ -0,0 +1,32 @@
+const rejectAfter = (timeout) => {
+  return new Promise((resolve, reject) => {
+    setTimeout(() => reject(), timeout);
+  });
+}
+
+const startUpdate = () => {
+  let p = [];
+  for (let i = 0; i < 10; i++) {
+    p.push(self.registration.update());
+  }
+  return Promise.all(p);
+};
+
+const update = () => {
+  // update() rejects in one of these cases:
+  //   1. at least one update() rejects, or
+  //   2. at least one update() does not resolve after 15 seconds.
+  return Promise.race([startUpdate(), rejectAfter(150000)]);
+};
+
+self.addEventListener('message', (e) => {
+  const port = e.data;
+
+  port.onmessage = (e) => {
+    update().then(() => {
+      port.postMessage('success');
+    }).catch((e) => {
+      port.postMessage('failure');
+    });
+  };
+});"}<_**next**_>{"sha": "3e0ec4bd05559f2781c837dfea89a8513dd0e041", "filename": "third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https-expected.txt", "status": "added", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https-expected.txt?ref=ec96e9da29ec26491de4be2464e0735404546e62", "patch": "@@ -0,0 +1,4 @@
+This is a testharness.js-based test.
+FAIL Verify multiple updates from service workers without controllees do not resolve immediately assert_equals: update should not have succeeded expected "failure" but got "success"
+Harness: the test ran to completion.
+"}<_**next**_>{"sha": "40740c6f3ce35262fb3fc27d949e9f9ea271521b", "filename": "third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https.html", "status": "added", "additions": 45, "deletions": 0, "changes": 45, "blob_url": "https://github.com/chromium/chromium/blob/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https.html", "raw_url": "https://github.com/chromium/chromium/raw/ec96e9da29ec26491de4be2464e0735404546e62/third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/serviceworker/update-no-controllee.https.html?ref=ec96e9da29ec26491de4be2464e0735404546e62", "patch": "@@ -0,0 +1,45 @@
+<!DOCTYPE html>
+<!-- This is not a WPT test because it tests non-specified Chrome-specific behavior. It tests that self-updating service workers eventually fail to update. -->
+<title>Service Worker: update no controllee</title>
+<script src="/resources/testharness.js"></script>
+<script src="/resources/testharnessreport.js"></script>
+<script src="resources/test-helpers.js"></script>
+<body>
+<script>
+promise_test(async (t) => {
+  // Set up ServiceWorker and wait until it's |activated|.
+  const url = 'resources/update-no-controllee-worker.js';
+  const scope = 'resources/blank.html';
+  const registration = await service_worker_unregister_and_register(t, url, scope);
+  await wait_for_state(t, registration.installing, 'activated');
+
+  const frame = await with_iframe(scope);
+
+  const w = frame.contentWindow;
+  const sw = w.navigator.serviceWorker;
+  assert_true(sw.controller instanceof w.ServiceWorker,
+              'controller should be a ServiceWorker object');
+
+  const channel = new MessageChannel();
+  sw.controller.postMessage(channel.port1, [channel.port1]);
+
+  // Remove frame so our worker has no controller.
+  frame.remove();
+  assert_equals(
+      sw.controller, null, 'disconnected frame should not be controlled');
+
+  // Send a message to the worker to start updating and wait for its response.
+  // We expect at least one of the updates, and therefore the complete proccess,
+  // to fail immediately because the delay is too long.
+  const result = wait_for_port_message(channel.port2, (e) => {
+    assert_equals(e.data, 'failure', 'update should not have succeeded');
+  });
+  channel.port2.postMessage('');
+  await result;
+
+  // Cleanup.
+  await registration.unregister();
+}, 'Verify multiple updates from service workers without controllees ' +
+       'do not resolve immediately');
+</script>
+</body>"}

{"sha": "7c6b7da1c70f4071d071d2f111be90a01b1233b3", "filename": "pdf/pdfium/pdfium_engine.cc", "status": "modified", "additions": 8, "deletions": 2, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/01c9a7e71ca435651723e8cbcab0b3ad4c5351e2/pdf/pdfium/pdfium_engine.cc", "raw_url": "https://github.com/chromium/chromium/raw/01c9a7e71ca435651723e8cbcab0b3ad4c5351e2/pdf/pdfium/pdfium_engine.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/pdf/pdfium/pdfium_engine.cc?ref=01c9a7e71ca435651723e8cbcab0b3ad4c5351e2", "patch": "@@ -1405,9 +1405,15 @@ bool PDFiumEngine::HandleEvent(const pp::InputEvent& event) {

