 "}<_**next**_>{"sha": "7459f592861bee94ea55c66b080de46afc0a6b7a", "filename": "third_party/WebKit/LayoutTests/external/wpt/workers/data-url-shared-window.html", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/chromium/chromium/blob/018bb6d300c11acb953d51ef3cbec4cdcaf4a652/third_party/WebKit/LayoutTests/external/wpt/workers/data-url-shared-window.html", "raw_url": "https://github.com/chromium/chromium/raw/018bb6d300c11acb953d51ef3cbec4cdcaf4a652/third_party/WebKit/LayoutTests/external/wpt/workers/data-url-shared-window.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/workers/data-url-shared-window.html?ref=018bb6d300c11acb953d51ef3cbec4cdcaf4a652", "patch": "@@ -0,0 +1,25 @@
+<!DOCTYPE html>
+<head>
+<title>data URL shared worker</title>
+</head>
+<body>
+<script>
+onmessage = event => {
+  const port = event.ports[0];
+  // This shared worker counts the total number of connected documents and
+  // notifies the connector of it.
+  const kScript =
+      "onconnect = e => {" +
+      "  if (self.count === undefined)" +
+      "    self.count = 0;" +
+      "  self.count++;" +
+      "  e.ports[0].postMessage(self.count);" +
+      "};";
+  const worker = new SharedWorker('data:application/javascript,' + kScript);
+  worker.port.onmessage = e => port.postMessage(e.data);
+};
+
+window.opener.postMessage('LOADED', '*');
+</script>
+</body>
