     DownloadItem* download) {
   if (!download->CanShowInFolder())"}<_**next**_>{"sha": "089756dc129dae9ce456cf7e274c08e6527f805d", "filename": "chrome/browser/download/chrome_download_manager_delegate.h", "status": "modified", "additions": 2, "deletions": 0, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/a8d6ae61d266d8bc44c3dd2d08bda32db701e359/chrome/browser/download/chrome_download_manager_delegate.h", "raw_url": "https://github.com/chromium/chromium/raw/a8d6ae61d266d8bc44c3dd2d08bda32db701e359/chrome/browser/download/chrome_download_manager_delegate.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/download/chrome_download_manager_delegate.h?ref=a8d6ae61d266d8bc44c3dd2d08bda32db701e359", "patch": "@@ -85,6 +85,8 @@ class ChromeDownloadManagerDelegate
