+    expectMockedTabNavigationEvents(remoteFrontendUrl);
+    navigateAndWait(remoteFrontendUrl);
+  },
+]);"}<_**next**_>{"sha": "f9d53765ed95651874287ba6e32cb26079fbee34", "filename": "extensions/browser/api/extensions_api_client.cc", "status": "modified", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/chromium/chromium/blob/2649de11c562aa96d336c06136a1a20c01711be0/extensions/browser/api/extensions_api_client.cc", "raw_url": "https://github.com/chromium/chromium/raw/2649de11c562aa96d336c06136a1a20c01711be0/extensions/browser/api/extensions_api_client.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/extensions/browser/api/extensions_api_client.cc?ref=2649de11c562aa96d336c06136a1a20c01711be0", "patch": "@@ -44,6 +44,11 @@ bool ExtensionsAPIClient::ShouldHideResponseHeader(
