{"sha": "700349a8a1da3a2c461a70389684c3d2a7f9f96b", "filename": "third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html", "status": "added", "additions": 39, "deletions": 0, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/209f225b2d51334eaf69ffdf002e25eaa1e0d448/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html", "raw_url": "https://github.com/chromium/chromium/raw/209f225b2d51334eaf69ffdf002e25eaa1e0d448/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html?ref=209f225b2d51334eaf69ffdf002e25eaa1e0d448", "patch": "@@ -0,0 +1,39 @@
+<!DOCTYPE HTML>
+<html>
+<head>
+  <!-- This tests a bug that can occur when content layer CSP is not told
+       about the CSP inherited from the parent document which leads to it not
+       applying it to content layer CSP checks (such as frame-src with
+       PlzNavigate on).
+       Also see crbug.com/778658. -->
+  <script src='/resources/testharness.js'></script>
+  <script src='/resources/testharnessreport.js'></script>
+</head>
+<body>
+  <script>
+    var t = async_test("iframe still inherits correct CSP");
+  </script>
+
+  <iframe id="x" srcdoc="<a href='about:blank'>123</a>"></iframe>
+
+  <script>
+    window.onmessage = t.step_func_done(function(e) {
+      assert_equals(e.data, "frame-src");
+    });
+
+    x = document.getElementById('x');
+    x.location = "";
+
+    // While document.write is deprecated I did not find another way to reproduce
+    // the original exploit.
+    x.contentDocument.write(
+      '<script>window.addEventListener("securitypolicyviolation", function(e) {' +
+      '  window.top.postMessage(e.violatedDirective, "*");' +
+      '});</scr' + 'ipt>' +
+      '<iframe src="../support/fail.html"></iframe>'
+    );
+    x.contentDocument.close();
+  </script>
+  <script async defer src='../support/checkReport.sub.js?reportField=violated-directive&reportValue=frame-src%20%27none%27''></script>
+</body>
+</html>
\ No newline at end of file"}<_**next**_>{"sha": "64653e3bf1a1a40e3c88e9b628fa94d5bf22403e", "filename": "third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html.sub.headers", "status": "added", "additions": 5, "deletions": 0, "changes": 5, "blob_url": "https://github.com/chromium/chromium/blob/209f225b2d51334eaf69ffdf002e25eaa1e0d448/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html.sub.headers", "raw_url": "https://github.com/chromium/chromium/raw/209f225b2d51334eaf69ffdf002e25eaa1e0d448/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html.sub.headers", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/content-security-policy/generic/policy-inherited-correctly-by-plznavigate.html.sub.headers?ref=209f225b2d51334eaf69ffdf002e25eaa1e0d448", "patch": "@@ -0,0 +1,5 @@
+Expires: Mon, 26 Jul 1997 05:00:00 GMT
