{"sha": "478a7ce6fe6aa13e54dfaa3eb493bdaad7753c38", "filename": "third_party/WebKit/LayoutTests/external/wpt/referrer-policy/generic/iframe-inheritance.html", "status": "added", "additions": 39, "deletions": 0, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/931711135c90568f677cf42d94f2591a7eeced2e/third_party/WebKit/LayoutTests/external/wpt/referrer-policy/generic/iframe-inheritance.html", "raw_url": "https://github.com/chromium/chromium/raw/931711135c90568f677cf42d94f2591a7eeced2e/third_party/WebKit/LayoutTests/external/wpt/referrer-policy/generic/iframe-inheritance.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/referrer-policy/generic/iframe-inheritance.html?ref=931711135c90568f677cf42d94f2591a7eeced2e", "patch": "@@ -0,0 +1,39 @@
+<!DOCTYPE html>
+<html>
+  <head>
+    <title>Referrer Policy: iframes correctly inherit the ancestor's referrer</title>
+    <link rel="author" title="Jochen Eisinger" href="mailto:jochen@chromium.org">
+    <link rel="help" href="https://www.w3.org/TR/referrer-policy/#referrer-policy-delivery-nested">
+    <script src="/resources/testharness.js"></script>
+    <script src="/resources/testharnessreport.js"></script>
+    <!-- Common global functions for referrer-policy tests. -->
+    <script src="/referrer-policy/generic/common.js"></script>
+    <meta name="referrer" content="origin">
+  </head>
+  <body onload="runTest()">
+    <h1>Referrer Policy: iframes correctly inherit the ancestor's referrer</h1>
+    <script>
+      var test = async_test("iframes correctly inherit the ancestor's referrer");
+      window.addEventListener("message", test.step_func((msg) => {
+        assert_equals(msg.data.referrer, document.location.origin + "/");
+        test.done();
+      }));
+
+      function runTest() {
+        var iframe = document.createElement("iframe");
+        iframe.src = "about:blank";
+        document.body.appendChild(iframe);
+        iframe.contentDocument.write(`
+            <script src = "/referrer-policy/generic/common.js"></` + `script>
+            <script>
+              var urlPath = "/referrer-policy/generic/subresource/xhr.py";
+              var url = "${location.protocol}//www1.${location.hostname}:${location.port}" + urlPath;
+              queryXhr(url, (msg) => {
+                  parent.postMessage({referrer: msg.referrer}, "*")});
+            </` + "script>");
+        }
+      </script>
+
+    <div id="log"></div>
+  </body>
+</html>"}<_**next**_>{"sha": "9f79c61fe5515d8b56ae30e621b9479b57e7f890", "filename": "third_party/WebKit/Source/core/dom/Document.cpp", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/931711135c90568f677cf42d94f2591a7eeced2e/third_party/WebKit/Source/core/dom/Document.cpp", "raw_url": "https://github.com/chromium/chromium/raw/931711135c90568f677cf42d94f2591a7eeced2e/third_party/WebKit/Source/core/dom/Document.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/dom/Document.cpp?ref=931711135c90568f677cf42d94f2591a7eeced2e", "patch": "@@ -2925,6 +2925,7 @@ void Document::open(Document* entered_document,
       KURL new_url = entered_document->Url();
       new_url.SetFragmentIdentifier(String());
       SetURL(new_url);
+      SetReferrerPolicy(entered_document->GetReferrerPolicy());
     }

     cookie_url_ = entered_document->CookieURL();"}

{"sha": "94a0cee272f87a02fcfd9a3fb83cb4bb4a3e6c05", "filename": "chrome/browser/ui/views/permission_bubble/permission_prompt_impl.cc", "status": "modified", "additions": 22, "deletions": 0, "changes": 22, "blob_url": "https://github.com/chromium/chromium/blob/56762260ca8ef62578fa4718b7d47711f7e120dc/chrome/browser/ui/views/permission_bubble/permission_prompt_impl.cc", "raw_url": "https://github.com/chromium/chromium/raw/56762260ca8ef62578fa4718b7d47711f7e120dc/chrome/browser/ui/views/permission_bubble/permission_prompt_impl.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/ui/views/permission_bubble/permission_prompt_impl.cc?ref=56762260ca8ef62578fa4718b7d47711f7e120dc", "patch": "@@ -5,6 +5,8 @@
 #include "chrome/browser/ui/views/permission_bubble/permission_prompt_impl.h"

 #include <stddef.h>
+#include <memory>
+#include <utility>

 #include "base/strings/string16.h"
 #include "build/build_config.h"
@@ -80,6 +82,7 @@ class PermissionsBubbleDialogDelegateView
   bool Cancel() override;
   bool Accept() override;
   bool Close() override;
+  void AddedToWidget() override;
   int GetDefaultDialogButton() const override;
   int GetDialogButtons() const override;
   base::string16 GetDialogButtonLabel(ui::DialogButton button) const override;
@@ -168,6 +171,25 @@ void PermissionsBubbleDialogDelegateView::CloseBubble() {
   GetWidget()->Close();
 }

+void PermissionsBubbleDialogDelegateView::AddedToWidget() {
+  std::unique_ptr<views::Label> title =
+      views::BubbleFrameView::CreateDefaultTitleLabel(GetWindowTitle());
+
+  // Elide from head in order to keep the most significant part of the origin
+  // and avoid spoofing. Note that in English, GetWindowTitle() returns a string
+  // "$ORIGIN wants to", so the "wants to" will not be elided. In other
+  // languages, the non-origin part may appear fully or partly before the origin
+  // (e.g., in Filipino, "Gusto ng $ORIGIN na"), which means it may be elided.
+  // This is not optimal, but it is necessary to avoid origin spoofing. See
+  // crbug.com/774438.
+  title->SetElideBehavior(gfx::ELIDE_HEAD);
+
+  // Multiline breaks elision, which would mean a very long origin gets
+  // truncated from the least significant side. Explicitly disable multiline.
+  title->SetMultiLine(false);
+  GetBubbleFrameView()->SetTitleView(std::move(title));
+}
+
 ui::AXRole PermissionsBubbleDialogDelegateView::GetAccessibleWindowRole()
     const {
   return ui::AX_ROLE_ALERT_DIALOG;"}

