+Error code: -28 (net::ERR_BLOCKED_BY_XSS_AUDITOR)"}<_**next**_>{"sha": "ca8a315df359e6b57849c3d798aa87496719b89f", "filename": "third_party/WebKit/LayoutTests/http/tests/security/xssAuditor/report-script-tag-cross-origin.html", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/chromium/chromium/blob/0da6dcdbe8e34740133773d20cc466b89d399d0a/third_party/WebKit/LayoutTests/http/tests/security/xssAuditor/report-script-tag-cross-origin.html", "raw_url": "https://github.com/chromium/chromium/raw/0da6dcdbe8e34740133773d20cc466b89d399d0a/third_party/WebKit/LayoutTests/http/tests/security/xssAuditor/report-script-tag-cross-origin.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/xssAuditor/report-script-tag-cross-origin.html?ref=0da6dcdbe8e34740133773d20cc466b89d399d0a", "patch": "@@ -0,0 +1,25 @@
