{"sha": "65eeab7e3847c6faf3998984649b992476e065b3", "filename": "net/disk_cache/backend_unittest.cc", "status": "modified", "additions": 32, "deletions": 0, "changes": 32, "blob_url": "https://github.com/chromium/chromium/blob/df5b1e1f88e013bc96107cc52c4a4f33a8238444/net/disk_cache/backend_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/df5b1e1f88e013bc96107cc52c4a4f33a8238444/net/disk_cache/backend_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/disk_cache/backend_unittest.cc?ref=df5b1e1f88e013bc96107cc52c4a4f33a8238444", "patch": "@@ -4311,3 +4311,35 @@ TEST_F(DiskCacheBackendTest, SimpleFdLimit) {
