+// Copyright 2018 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+var seenPathsByServiceWorker = [];
+
+// Called by mime_handler.js at the end of the test:
+chrome.runtime.onMessage.addListener(function(msg) {
+  chrome.test.assertEq('finish test by checking SW URLs', msg);
+  chrome.test.assertEq([
+    '/page_with_embed.html',
+    // "/well-known-mime.ics" is loaded by page_with_embed.html, but it should
+    // not have dispatched the "fetch" event in the Service Worker because it is
+    // a plugin resource.
+    '/mime_handler.html',
+    '/mime_handler.js',
+  ], seenPathsByServiceWorker, 'expected extension URLs');
+  chrome.test.notifyPass();
+});
+
+navigator.serviceWorker.addEventListener('message', function(event) {
+  seenPathsByServiceWorker.push(event.data.replace(location.origin, ''));
+  event.ports[0].postMessage('ACK');
+});
+
+navigator.serviceWorker.register('sw.js').then(function() {
+  return navigator.serviceWorker.ready;
+}).then(function() {
+  chrome.tabs.create({
+    url: chrome.extension.getURL('page_with_embed.html'),
+  });
+}).catch(function(e) {
+  chrome.test.fail('Unexpected error: ' + e);
+});"}<_**next**_>{"sha": "240176f11dcf5f8703705f50176a4ff4ce82acd5", "filename": "chrome/test/data/extensions/api_test/service_worker/mime_handler_view/manifest.json", "status": "added", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/e89b9003df8c7bd7822e5b6c0a76e726a6ed1505/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/manifest.json", "raw_url": "https://github.com/chromium/chromium/raw/e89b9003df8c7bd7822e5b6c0a76e726a6ed1505/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/manifest.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/manifest.json?ref=e89b9003df8c7bd7822e5b6c0a76e726a6ed1505", "patch": "@@ -0,0 +1,13 @@
