+The "ics" extension is hard-coded as "text/calendar" by net::MimeUtil.
+So, regardless of the platform's MIME type for the "ics" file extension,
+the resource will always be served as "text/calendar" and therefore be handled
+by the test extension.
+<embed src="well-known-mime.ics"></embed>"}<_**next**_>{"sha": "adc3b61f075f85410cd3ca684e9a05183728a44b", "filename": "chrome/test/data/extensions/api_test/service_worker/mime_handler_view/sw.js", "status": "added", "additions": 16, "deletions": 0, "changes": 16, "blob_url": "https://github.com/chromium/chromium/blob/e89b9003df8c7bd7822e5b6c0a76e726a6ed1505/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/sw.js", "raw_url": "https://github.com/chromium/chromium/raw/e89b9003df8c7bd7822e5b6c0a76e726a6ed1505/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/sw.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/sw.js?ref=e89b9003df8c7bd7822e5b6c0a76e726a6ed1505", "patch": "@@ -0,0 +1,16 @@
