+self.addEventListener('fetch', function(event) {
+  event.waitUntil(
+    chrome.runtime.getBackgroundClient().then(function(client) {
+      // Ensure that the "seenUrls" list in the background page is updated
+      // before the response is served.
+      return new Promise(function(resolve) {
+        var chan = new MessageChannel();
+        chan.port1.onmessage = resolve;
+        client.postMessage(event.request.url, [chan.port2]);
+      });
+    }));
+});"}<_**next**_>{"sha": "0952ba62cfaaddfa06d634ace358414552d142bb", "filename": "chrome/test/data/extensions/api_test/service_worker/mime_handler_view/well-known-mime.ics", "status": "added", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/e89b9003df8c7bd7822e5b6c0a76e726a6ed1505/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/well-known-mime.ics", "raw_url": "https://github.com/chromium/chromium/raw/e89b9003df8c7bd7822e5b6c0a76e726a6ed1505/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/well-known-mime.ics", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/service_worker/mime_handler_view/well-known-mime.ics?ref=e89b9003df8c7bd7822e5b6c0a76e726a6ed1505", "patch": "@@ -0,0 +1 @@
