+<!DOCTYPE html>
+<meta charset="utf-8">
+<title>iframe for embed-and-object-are-not-intercepted test</title>
+<body>
+<object type="image/png" data="/images/green.png"></embed>
+<script>
+// Our parent (the root frame of the test) will examine this to get the result.
+var test_promise = new Promise(resolve => {
+    if (!navigator.serviceWorker.controller)
+      resolve('FAIL: this iframe is not controlled');
+
+    const elem = document.querySelector('object');
+    elem.addEventListener('load', e => {
+        resolve('request was not intercepted');
+      });
+    elem.addEventListener('error', e => {
+        resolve('FAIL: request was intercepted');
+      });
+  });
+</script>
+</body>"}<_**next**_>{"sha": "116a70d5a6ad7f26d9e82f1c17eb8e82fa6d7c8d", "filename": "third_party/WebKit/Source/core/loader/ImageLoader.cpp", "status": "modified", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/59ad2dcbe6dd5c5d846944258e6cd26a700ade83/third_party/WebKit/Source/core/loader/ImageLoader.cpp", "raw_url": "https://github.com/chromium/chromium/raw/59ad2dcbe6dd5c5d846944258e6cd26a700ade83/third_party/WebKit/Source/core/loader/ImageLoader.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/core/loader/ImageLoader.cpp?ref=59ad2dcbe6dd5c5d846944258e6cd26a700ade83", "patch": "@@ -413,6 +413,16 @@ void ImageLoader::DoUpdateFromElement(BypassMainWorldBehavior bypass_behavior,
       resource_request.SetRequestContext(WebURLRequest::kRequestContextPing);
     }

+    // Plug-ins should not load via service workers as plug-ins may have their
+    // own origin checking logic that may get confused if service workers
+    // respond with resources from another origin.
+    // https://w3c.github.io/ServiceWorker/#implementer-concerns
+    if (GetElement()->IsHTMLElement() &&
+        ToHTMLElement(GetElement())->IsPluginElement()) {
+      resource_request.SetServiceWorkerMode(
+          WebURLRequest::ServiceWorkerMode::kNone);
+    }
+
     FetchParameters params(resource_request, resource_loader_options);
     ConfigureRequest(params, bypass_behavior, *element_,
                      document.GetClientHintsPreferences());"}

