{"sha": "f422c3901583b04892985c30b6f3ee7e55534c94", "filename": "content/browser/devtools/devtools_http_handler.cc", "status": "modified", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/ba1513223e47b62ed53b61518b7f7b82ad1d8ccd/content/browser/devtools/devtools_http_handler.cc", "raw_url": "https://github.com/chromium/chromium/raw/ba1513223e47b62ed53b61518b7f7b82ad1d8ccd/content/browser/devtools/devtools_http_handler.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/devtools/devtools_http_handler.cc?ref=ba1513223e47b62ed53b61518b7f7b82ad1d8ccd", "patch": "@@ -41,6 +41,7 @@
