@@ -101,6 +102,16 @@ constexpr net::NetworkTrafficAnnotationTag
           "Not implemented, only used in Devtools and is behind a switch."
       })");

+bool RequestIsSafeToServe(const net::HttpServerRequestInfo& info) {
+  // For browser-originating requests, serve only those that are coming from
+  // pages loaded off localhost or fixed IPs.
+  std::string header = info.headers["host"];
+  if (header.empty())
+    return true;
+  GURL url = GURL("http://" + header);
+  return url.HostIsIPAddress() || net::IsLocalHostname(url.host(), nullptr);
+}
+
 }  // namespace

 // ServerWrapper -------------------------------------------------------------
@@ -399,6 +410,12 @@ static std::string GetMimeType(const std::string& filename) {

 void ServerWrapper::OnHttpRequest(int connection_id,
                                   const net::HttpServerRequestInfo& info) {
+  if (!RequestIsSafeToServe(info)) {
+    Send500(connection_id,
+            "Host header is specified and is not an IP address or localhost.");
+    return;
+  }
+
   server_->SetSendBufferSize(connection_id, kSendBufferSizeForDevTools);

   if (base::StartsWith(info.path, "/json", base::CompareCase::SENSITIVE)) {"}

{"sha": "15cac623eb0000b3fd39627755a4c2e676ad354f", "filename": "components/url_formatter/idn_spoof_checker.cc", "status": "modified", "additions": 6, "deletions": 6, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/d52b8375cfe5b56194d3df09c18e7b64e5838369/components/url_formatter/idn_spoof_checker.cc", "raw_url": "https://github.com/chromium/chromium/raw/d52b8375cfe5b56194d3df09c18e7b64e5838369/components/url_formatter/idn_spoof_checker.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/components/url_formatter/idn_spoof_checker.cc?ref=d52b8375cfe5b56194d3df09c18e7b64e5838369", "patch": "@@ -155,13 +155,13 @@ IDNSpoofChecker::IDNSpoofChecker() {
   // Supplement the Unicode confusable list by the following mapping.
   //   - {U+00FE (þ), U+03FC (ϼ), U+048F (ҏ)} => p
   //   - {U+0127 (ħ), U+043D (н), U+045B (ћ), U+04A3 (ң), U+04A5 (ҥ),
-  //      U+04C8 (ӈ), U+0527 (ԧ), U+0529 (ԩ)} => h
+  //      U+04C8 (ӈ), U+04CA (ӊ), U+0527 (ԧ), U+0529 (ԩ)} => h
   //   - {U+0138 (ĸ), U+03BA (κ), U+043A (к), U+049B (қ), U+049D (ҝ),
   //      U+049F (ҟ), U+04A1(ҡ), U+04C4 (ӄ), U+051F (ԟ)} => k
   //   - {U+014B (ŋ), U+043F (п)} => n
   //   - {U+0167 (ŧ), U+0442 (т), U+04AD (ҭ)} => t
   //   - {U+0185 (ƅ), U+044C (ь), U+048D (ҍ), U+0432 (в)} => b
-  //   - {U+03C9 (ω), U+0448 (ш), U+0449 (щ)} => w
+  //   - {U+03C9 (ω), U+0448 (ш), U+0449 (щ), U+0E1F (ฟ)} => w
