 #include <va/va.h>

+#include "base/logging.h"
 #include "media/gpu/vaapi/vaapi_wrapper.h"

 namespace media {

+namespace {
+
+VAProfile ConvertToVAProfile(VaapiImageDecoder::Type type) {
+  switch (type) {
+    case VaapiImageDecoder::Type::kJpeg:
+      return VAProfileJPEGBaseline;
+    case VaapiImageDecoder::Type::kWebP:
+      return VAProfileVP8Version0_3;
+    default:
+      NOTREACHED() << "Undefined Type value";
+      return VAProfileNone;
+  }
+}
+
+}  // namespace
+
 VaapiImageDecoder::VaapiImageDecoder()
     : va_surface_id_(VA_INVALID_SURFACE), va_rt_format_(kInvalidVaRtFormat) {}

 VaapiImageDecoder::~VaapiImageDecoder() = default;

+bool VaapiImageDecoder::Initialize(const base::RepeatingClosure& error_uma_cb) {
+  const VAProfile va_profile = ConvertToVAProfile(GetType());
+  vaapi_wrapper_ =
+      VaapiWrapper::Create(VaapiWrapper::kDecode, va_profile, error_uma_cb);
+  return !!vaapi_wrapper_;
+}
+
 }  // namespace media"}<_**next**_>{"sha": "68eaf26e7e53f695f831bf805696d423cb2da451", "filename": "media/gpu/vaapi/vaapi_image_decoder.h", "status": "modified", "additions": 12, "deletions": 3, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/f283cdf7c850f3db923a5303c7e01bd929d4117f/media/gpu/vaapi/vaapi_image_decoder.h", "raw_url": "https://github.com/chromium/chromium/raw/f283cdf7c850f3db923a5303c7e01bd929d4117f/media/gpu/vaapi/vaapi_image_decoder.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/media/gpu/vaapi/vaapi_image_decoder.h?ref=f283cdf7c850f3db923a5303c7e01bd929d4117f", "patch": "@@ -50,11 +50,17 @@ enum class VaapiImageDecodeStatus : uint32_t {
