{"sha": "66de94e42694aca9e882196b53a2d5035840234c", "filename": "content/browser/manifest/manifest_browsertest.cc", "status": "modified", "additions": 30, "deletions": 0, "changes": 30, "blob_url": "https://github.com/chromium/chromium/blob/ffac0ee4b8b00944e2ddf23f7f4f55daff3c117e/content/browser/manifest/manifest_browsertest.cc", "raw_url": "https://github.com/chromium/chromium/raw/ffac0ee4b8b00944e2ddf23f7f4f55daff3c117e/content/browser/manifest/manifest_browsertest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/browser/manifest/manifest_browsertest.cc?ref=ffac0ee4b8b00944e2ddf23f7f4f55daff3c117e", "patch": "@@ -659,4 +659,34 @@ IN_PROC_BROWSER_TEST_F(ManifestBrowserTest, NoUseCredentialsNoCookies) {
   EXPECT_TRUE(base::EqualsASCII(manifest().name.string(), "no cookies"));
 }

+// This tests that fetching a Manifest from a unique origin always fails,
+// regardless of the CORS headers on the manifest. It also tests that no
+// manifest change notifications are reported when the origin is unique.
+IN_PROC_BROWSER_TEST_F(ManifestBrowserTest, UniqueOrigin) {
+  GURL test_url = embedded_test_server()->GetURL("/manifest/sandboxed.html");
+
+  ASSERT_TRUE(NavigateToURL(shell(), test_url));
+  std::string manifest_link =
+      embedded_test_server()->GetURL("/manifest/dummy-manifest.json").spec();
+  ASSERT_TRUE(ExecuteScript(shell(), "setManifestTo('" + manifest_link + "')"));
+
+  // Same-origin manifest will not be fetched from a unique origin, regardless
+  // of CORS headers.
+  GetManifestAndWait();
+  EXPECT_TRUE(manifest().IsEmpty());
+  EXPECT_TRUE(manifest_url().is_empty());
+  EXPECT_EQ(0, GetConsoleErrorCount());
+  EXPECT_EQ(0u, reported_manifest_urls().size());
+
+  manifest_link =
+      embedded_test_server()->GetURL("/manifest/manifest-cors.json").spec();
+  ASSERT_TRUE(ExecuteScript(shell(), "setManifestTo('" + manifest_link + "')"));
+
+  GetManifestAndWait();
+  EXPECT_TRUE(manifest().IsEmpty());
+  EXPECT_TRUE(manifest_url().is_empty());
+  EXPECT_EQ(0, GetConsoleErrorCount());
+  EXPECT_EQ(0u, reported_manifest_urls().size());
+}
+
