+}"}<_**next**_>{"sha": "1eb8e02b99e9bfe3bd64ebc1030794f2f0c9ba62", "filename": "chrome/browser/android/chrome_entry_point_for_test.cc", "status": "added", "additions": 43, "deletions": 0, "changes": 43, "blob_url": "https://github.com/chromium/chromium/blob/9d81094d7b0bfc8be6bba2f5084e790677e527c8/chrome/browser/android/chrome_entry_point_for_test.cc", "raw_url": "https://github.com/chromium/chromium/raw/9d81094d7b0bfc8be6bba2f5084e790677e527c8/chrome/browser/android/chrome_entry_point_for_test.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/android/chrome_entry_point_for_test.cc?ref=9d81094d7b0bfc8be6bba2f5084e790677e527c8", "patch": "@@ -0,0 +1,43 @@
+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "base/android/jni_android.h"
+#include "base/android/jni_utils.h"
+#include "base/android/library_loader/library_loader_hooks.h"
+#include "base/bind.h"
+#include "base/test/test_support_android.h"
+#include "chrome/app/android/chrome_jni_onload.h"
+#include "chrome/browser/android/chrome_jni_for_test_registration.h"
+
+namespace {
+
+bool NativeInit() {
+  return android::OnJNIOnLoadInit();
+}
+
+}  // namespace
+
+// This is called by the VM when the shared library is first loaded.
+JNI_EXPORT jint JNI_OnLoad(JavaVM* vm, void* reserved) {
+  // By default, all JNI methods are registered. However, since render processes
+  // don't need very much Java code, we enable selective JNI registration on the
+  // Java side and only register a subset of JNI methods.
+  base::android::InitVM(vm);
+  JNIEnv* env = base::android::AttachCurrentThread();
+
+  if (!base::android::IsSelectiveJniRegistrationEnabled(env) &&
+      !RegisterNonMainDexNatives(env)) {
+    return -1;
+  }
+
+  if (!RegisterMainDexNatives(env)) {
+    return -1;
+  }
+
+  if (!android::OnJNIOnLoadRegisterJNI(env)) {
+    return -1;
+  }
+  base::android::SetNativeInitializationHook(NativeInit);
+  return JNI_VERSION_1_4;
+}"}<_**next**_>{"sha": "9d7dbf3ddc1b24cb886f59af4739c3fd030d2591", "filename": "chrome/browser/profiling_host/BUILD.gn", "status": "modified", "additions": 41, "deletions": 0, "changes": 41, "blob_url": "https://github.com/chromium/chromium/blob/9d81094d7b0bfc8be6bba2f5084e790677e527c8/chrome/browser/profiling_host/BUILD.gn", "raw_url": "https://github.com/chromium/chromium/raw/9d81094d7b0bfc8be6bba2f5084e790677e527c8/chrome/browser/profiling_host/BUILD.gn", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/profiling_host/BUILD.gn?ref=9d81094d7b0bfc8be6bba2f5084e790677e527c8", "patch": "@@ -8,6 +8,8 @@ if (!is_android) {

