+#include "jni/TestAndroidShim_jni.h"
+
+using base::android::JavaParamRef;
+using base::android::ScopedJavaLocalRef;
+
+static jlong Init(JNIEnv* env, const JavaParamRef<jobject>& obj) {
+  TestAndroidShim* profiler = new TestAndroidShim(env, obj);
+  return reinterpret_cast<intptr_t>(profiler);
+}
+
+TestAndroidShim::TestAndroidShim(JNIEnv* env, jobject obj) {}
+
+TestAndroidShim::~TestAndroidShim() {}
+
+void TestAndroidShim::Destroy(JNIEnv* env, const JavaParamRef<jobject>& obj) {
+  delete this;
+}
+
+jboolean TestAndroidShim::RunTestForMode(
+    JNIEnv* env,
+    const base::android::JavaParamRef<jobject>& obj,
+    const base::android::JavaParamRef<jstring>& mode) {
+  profiling::ProfilingTestDriver driver;
+  profiling::ProfilingTestDriver::Options options;
+  options.mode = profiling::ProfilingProcessHost::ConvertStringToMode(
+      base::android::ConvertJavaStringToUTF8(mode));
+  options.profiling_already_started = true;
+  return driver.RunTest(options);
+}"}<_**next**_>{"sha": "de6dd736477fd6beb1a8c02c96f66333f397a932", "filename": "chrome/browser/profiling_host/test_android_shim.h", "status": "added", "additions": 30, "deletions": 0, "changes": 30, "blob_url": "https://github.com/chromium/chromium/blob/9d81094d7b0bfc8be6bba2f5084e790677e527c8/chrome/browser/profiling_host/test_android_shim.h", "raw_url": "https://github.com/chromium/chromium/raw/9d81094d7b0bfc8be6bba2f5084e790677e527c8/chrome/browser/profiling_host/test_android_shim.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/profiling_host/test_android_shim.h?ref=9d81094d7b0bfc8be6bba2f5084e790677e527c8", "patch": "@@ -0,0 +1,30 @@
