{"sha": "5843f88307233e9326c84106f460039baf09162e", "filename": "third_party/WebKit/LayoutTests/external/wpt/resource-timing/resource_subframe_self_navigation.html", "status": "added", "additions": 53, "deletions": 0, "changes": 53, "blob_url": "https://github.com/chromium/chromium/blob/fa17c9878dbeebf991b25ac0deb2b4635d85f1b6/third_party/WebKit/LayoutTests/external/wpt/resource-timing/resource_subframe_self_navigation.html", "raw_url": "https://github.com/chromium/chromium/raw/fa17c9878dbeebf991b25ac0deb2b4635d85f1b6/third_party/WebKit/LayoutTests/external/wpt/resource-timing/resource_subframe_self_navigation.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/resource-timing/resource_subframe_self_navigation.html?ref=fa17c9878dbeebf991b25ac0deb2b4635d85f1b6", "patch": "@@ -0,0 +1,53 @@
+<!DOCTYPE html>
+<script src="/resources/testharness.js"></script>
+<script src="/resources/testharnessreport.js"></script>
+<body>
+<script>
+function numberOfDownloads(url) {
+    let absoluteURL = new URL(url, location.href).href;
+    return performance.getEntriesByName(absoluteURL).length;
+}
+
+function waitForSubFrameLoad() {
+    return new Promise((resolve) => {
+        window.subFrameLoaded = () => {
+            window.subFrameLoaded = null;
+            resolve();
+        };
+    });
+}
+
+function runTest(type) {
+    performance.clearResourceTimings();
+    let elem = document.createElement(type);
+    if (type === 'object')
+        elem.data = 'resources/self_navigation.html?' + type;
+    else
+        elem.src = 'resources/self_navigation.html?' + type;
+    document.body.appendChild(elem);
+    return waitForSubFrameLoad().then(() => {
+        let resources = performance.getEntriesByType('resource');
+        assert_equals(numberOfDownloads('resources/self_navigation.html?' + type), 1);
+        assert_equals(numberOfDownloads('resources/notify_parent.html?redirected'), 0);
+        document.body.removeChild(elem);
+    });
+}
+
+promise_test(
+    () => runTest('iframe'),
+    "Subsequent <iframe> navigations don't appear in the resource-timing buffer.");
+
+promise_test(
+    () => runTest('frame'),
+    "Subsequent <frame> navigations don't appear in the resource-timing buffer.");
+
+promise_test(
+    () => runTest('embed'),
+    "Subsequent <embed> navigations don't appear in the resource-timing buffer.");
+
+promise_test(
+    () => runTest('object'),
+    "Subsequent <object> navigations don't appear in the resource-timing buffer.");
+
+</script>
+</body>"}<_**next**_>{"sha": "c104f3c8f0695a96646cf24a730eef0342f95876", "filename": "third_party/WebKit/LayoutTests/external/wpt/resource-timing/resources/notify_parent.html", "status": "added", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/fa17c9878dbeebf991b25ac0deb2b4635d85f1b6/third_party/WebKit/LayoutTests/external/wpt/resource-timing/resources/notify_parent.html", "raw_url": "https://github.com/chromium/chromium/raw/fa17c9878dbeebf991b25ac0deb2b4635d85f1b6/third_party/WebKit/LayoutTests/external/wpt/resource-timing/resources/notify_parent.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/resource-timing/resources/notify_parent.html?ref=fa17c9878dbeebf991b25ac0deb2b4635d85f1b6", "patch": "@@ -0,0 +1,4 @@
