{"sha": "0e76edd65b7baf5316fc9d0c4da59a3502e4c27a", "filename": "third_party/WebKit/LayoutTests/http/tests/wasm_streaming/resources/blank.html", "status": "added", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/c5a59182a8406f67333c283a31f257714f082b7d/third_party/WebKit/LayoutTests/http/tests/wasm_streaming/resources/blank.html", "raw_url": "https://github.com/chromium/chromium/raw/c5a59182a8406f67333c283a31f257714f082b7d/third_party/WebKit/LayoutTests/http/tests/wasm_streaming/resources/blank.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/wasm_streaming/resources/blank.html?ref=c5a59182a8406f67333c283a31f257714f082b7d", "patch": "@@ -0,0 +1 @@
+<!DOCTYPE html>"}<_**next**_>{"sha": "0e3e69afa1b2b28c3b8ae4844ddd102917ed8717", "filename": "third_party/WebKit/LayoutTests/http/tests/wasm_streaming/wasm_streaming_xss.https.html", "status": "added", "additions": 51, "deletions": 0, "changes": 51, "blob_url": "https://github.com/chromium/chromium/blob/c5a59182a8406f67333c283a31f257714f082b7d/third_party/WebKit/LayoutTests/http/tests/wasm_streaming/wasm_streaming_xss.https.html", "raw_url": "https://github.com/chromium/chromium/raw/c5a59182a8406f67333c283a31f257714f082b7d/third_party/WebKit/LayoutTests/http/tests/wasm_streaming/wasm_streaming_xss.https.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/wasm_streaming/wasm_streaming_xss.https.html?ref=c5a59182a8406f67333c283a31f257714f082b7d", "patch": "@@ -0,0 +1,51 @@
+<!DOCTYPE html>
+<script src="../../../resources/testharness.js"></script>
+<script src="../../../resources/testharnessreport.js"></script>
+<script src="../resources/get-host-info.js"></script>
+<body>
+ <script>
+  var other_origin = get_host_info().UNAUTHENTICATED_ORIGIN + "wasm_streaming/resources/blank.html";
+  promise_test(() => {
+    return new Promise((resolve, reject) => {
+      frame = document.body.appendChild(document.createElement("iframe"));
+      frame.src = other_origin;
+      frame.onload = () => {
+        var wnd = frame.contentWindow;
+        var promise = WebAssembly.compileStreaming.call(wnd);
+        var objConstructor = promise.__proto__.__proto__.constructor;
+        var promiseConstructor = Promise.__proto__.__proto__.constructor;
+        promise.catch(e => {
+          assert_true(e instanceof TypeError);
+          if (objConstructor === promiseConstructor) {
+            resolve();
+          } else {
+            reject();
+          };
+       });
+     }
+    });
+  }, "wasm compileStreaming does not leak foreign contexts");
+
+    promise_test(() => {
+    return new Promise((resolve, reject) => {
+      frame = document.body.appendChild(document.createElement("iframe"));
+      frame.src = other_origin;
+      frame.onload = () => {
+        var wnd = frame.contentWindow;
+        var promise = WebAssembly.instantiateStreaming.call(wnd);
+        var objConstructor = promise.__proto__.__proto__.constructor;
+        var promiseConstructor = Promise.__proto__.__proto__.constructor;
+        promise.catch(e => {
+          assert_true(e instanceof TypeError);
+          if (objConstructor === promiseConstructor) {
+            resolve();
+          } else {
+            reject();
+          };
+       });
+     }
+    });
+  }, "wasm instantiateStreaming does not leak foreign contexts");
+
+</script>
+</body>"}<_**next**_>{"sha": "a57fa980b31c9c37dfb269aa1a5ef84efaf61317", "filename": "third_party/WebKit/Source/bindings/modules/v8/wasm/WasmResponseExtensions.cpp", "status": "modified", "additions": 3, "deletions": 3, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/c5a59182a8406f67333c283a31f257714f082b7d/third_party/WebKit/Source/bindings/modules/v8/wasm/WasmResponseExtensions.cpp", "raw_url": "https://github.com/chromium/chromium/raw/c5a59182a8406f67333c283a31f257714f082b7d/third_party/WebKit/Source/bindings/modules/v8/wasm/WasmResponseExtensions.cpp", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/Source/bindings/modules/v8/wasm/WasmResponseExtensions.cpp?ref=c5a59182a8406f67333c283a31f257714f082b7d", "patch": "@@ -129,7 +129,7 @@ void CompileFromResponseCallback(
