{"sha": "f6f5ef3af0c84f621a6f8b2f1c41523803f9d60c", "filename": "net/quic/core/quic_client_promised_info.cc", "status": "modified", "additions": 5, "deletions": 1, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/7a6484fa7b7f86ea06749bfc9d10bb67b145140b/net/quic/core/quic_client_promised_info.cc", "raw_url": "https://github.com/chromium/chromium/raw/7a6484fa7b7f86ea06749bfc9d10bb67b145140b/net/quic/core/quic_client_promised_info.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/quic/core/quic_client_promised_info.cc?ref=7a6484fa7b7f86ea06749bfc9d10bb67b145140b", "patch": "@@ -43,7 +43,11 @@ void QuicClientPromisedInfo::OnPromiseHeaders(const SpdyHeaderBlock& headers) {
   // RFC7540, Section 8.2, requests MUST be safe [RFC7231], Section
   // 4.2.1.  GET and HEAD are the methods that are safe and required.
   SpdyHeaderBlock::const_iterator it = headers.find(kHttp2MethodHeader);
-  DCHECK(it != headers.end());
+  if (it == headers.end()) {
+    QUIC_DVLOG(1) << "Promise for stream " << id_ << " has no method";
