     QUIC_DVLOG(1) << "Promise for stream " << id_ << " has invalid method "
                   << it->second;"}<_**next**_>{"sha": "9d5d758cdaa965e2b521c7f0a1e17e0d835c54a2", "filename": "net/quic/core/quic_client_promised_info_test.cc", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/7a6484fa7b7f86ea06749bfc9d10bb67b145140b/net/quic/core/quic_client_promised_info_test.cc", "raw_url": "https://github.com/chromium/chromium/raw/7a6484fa7b7f86ea06749bfc9d10bb67b145140b/net/quic/core/quic_client_promised_info_test.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/net/quic/core/quic_client_promised_info_test.cc?ref=7a6484fa7b7f86ea06749bfc9d10bb67b145140b", "patch": "@@ -154,6 +154,19 @@ TEST_F(QuicClientPromisedInfoTest, PushPromiseInvalidMethod) {
   EXPECT_EQ(session_.GetPromisedByUrl(promise_url_), nullptr);
 }

+TEST_F(QuicClientPromisedInfoTest, PushPromiseMissingMethod) {
+  // Promise with a missing method
+  push_promise_.erase(":method");
+
+  EXPECT_CALL(*connection_,
+              SendRstStream(promise_id_, QUIC_INVALID_PROMISE_METHOD, 0));
+  ReceivePromise(promise_id_);
+
+  // Verify that the promise headers were ignored
+  EXPECT_EQ(session_.GetPromisedById(promise_id_), nullptr);
+  EXPECT_EQ(session_.GetPromisedByUrl(promise_url_), nullptr);
+}
+
 TEST_F(QuicClientPromisedInfoTest, PushPromiseInvalidUrl) {
   // Remove required header field to make URL invalid
   push_promise_.erase(":authority");"}

