       return false;
   }

+  // If there are no extensions associated with either url, we check if the new
+  // url points to an extension origin. If it does, fork - extension
+  // installation should not be a factor.
+  if (!old_url_extension && !new_url_extension) {
+    // Hypothetically, we could also do an origin check here to make sure that
+    // the two urls point two different extensions, but it's not really
+    // necesary since we know there wasn't an associated extension with the old
+    // url.
+    return new_url.SchemeIs(kExtensionScheme);
+  }
+
   return old_url_extension != new_url_extension;
 }
 "}<_**next**_>{"sha": "33bf77e2d85ff6a05029a01fcb3f2302396877e8", "filename": "chrome/common/extensions/extension_process_policy_unittest.cc", "status": "added", "additions": 63, "deletions": 0, "changes": 63, "blob_url": "https://github.com/chromium/chromium/blob/f1afce25b3f94d8bddec69b08ffbc29b989ad844/chrome/common/extensions/extension_process_policy_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/f1afce25b3f94d8bddec69b08ffbc29b989ad844/chrome/common/extensions/extension_process_policy_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/common/extensions/extension_process_policy_unittest.cc?ref=f1afce25b3f94d8bddec69b08ffbc29b989ad844", "patch": "@@ -0,0 +1,63 @@
+// Copyright 2017 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#include "chrome/common/extensions/extension_process_policy.h"
+
+#include "components/crx_file/id_util.h"
+#include "extensions/common/extension_builder.h"
+#include "extensions/common/extension_set.h"
+#include "extensions/common/value_builder.h"
+#include "testing/gtest/include/gtest/gtest.h"
+
+namespace extensions {
+
+namespace {
+
+scoped_refptr<const Extension> CreateExtension(const std::string& id_seed) {
+  std::unique_ptr<base::DictionaryValue> manifest =
+      DictionaryBuilder()
+          .Set("name", "test")
+          .Set("version", "1.0")
+          .Set("manifest_version", 2)
+          .Build();
+  return ExtensionBuilder()
+      .SetManifest(std::move(manifest))
+      .SetID(crx_file::id_util::GenerateId(id_seed))
+      .Build();
+}
+
+}  // namespace
+
+TEST(CrossesExtensionBoundaryTest, InstalledExtensions) {
+  ExtensionSet extensions;
+  scoped_refptr<const Extension> extension1 = CreateExtension("a");
+  scoped_refptr<const Extension> extension2 = CreateExtension("b");
+  extensions.Insert(extension1);
+  extensions.Insert(extension2);
+
+  GURL web_url("https://example.com");
+
+  EXPECT_TRUE(CrossesExtensionProcessBoundary(extensions, web_url,
+                                              extension1->url(), false));
+  EXPECT_TRUE(CrossesExtensionProcessBoundary(extensions, extension1->url(),
+                                              extension2->url(), false));
+  EXPECT_TRUE(CrossesExtensionProcessBoundary(extensions, extension1->url(),
+                                              web_url, false));
+}
+
+TEST(CrossesExtensionBoundaryTest, UninstalledExtensions) {
+  ExtensionSet extensions;
+  scoped_refptr<const Extension> extension1 = CreateExtension("a");
+  extensions.Insert(extension1);
+  GURL web_url("https://example.com");
+  GURL non_existent_extension_url("chrome-extension://" + std::string(32, 'a') +
+                                  "/foo");
+
+  EXPECT_TRUE(CrossesExtensionProcessBoundary(
+      extensions, web_url, non_existent_extension_url, false));
+  EXPECT_TRUE(CrossesExtensionProcessBoundary(
+      extensions, extension1->url(), non_existent_extension_url, false));
+}
+
+}  // namespace extensions"}<_**next**_>{"sha": "9e827dc582240be2f249bfd67eb40a85b452c084", "filename": "chrome/test/BUILD.gn", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/f1afce25b3f94d8bddec69b08ffbc29b989ad844/chrome/test/BUILD.gn", "raw_url": "https://github.com/chromium/chromium/raw/f1afce25b3f94d8bddec69b08ffbc29b989ad844/chrome/test/BUILD.gn", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/BUILD.gn?ref=f1afce25b3f94d8bddec69b08ffbc29b989ad844", "patch": "@@ -4180,6 +4180,7 @@ test("unit_tests") {
