sh-hc/virtual/controls-refresh/color-scheme/time-picker/time-picker-appearance-expected.png?ref=d3196799aca6bb9f79beba2484fcdfeed5295d4f"}<_**next**_>{"sha": "9169b4ac1a390e3526a72c53265c7a137cab80b8", "filename": "third_party/blink/web_tests/virtual/controls-refresh/time-picker/time-picker-wheel.html", "status": "added", "additions": 38, "deletions": 0, "changes": 38, "blob_url": "https://github.com/chromium/chromium/blob/d3196799aca6bb9f79beba2484fcdfeed5295d4f/third_party/blink/web_tests/virtual/controls-refresh/time-picker/time-picker-wheel.html", "raw_url": "https://github.com/chromium/chromium/raw/d3196799aca6bb9f79beba2484fcdfeed5295d4f/third_party/blink/web_tests/virtual/controls-refresh/time-picker/time-picker-wheel.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/virtual/controls-refresh/time-picker/time-picker-wheel.html?ref=d3196799aca6bb9f79beba2484fcdfeed5295d4f", "patch": "@@ -0,0 +1,38 @@
+<!DOCTYPE html>
+<script>
+if (window.internals)
+    internals.settings.setLangAttributeAwareFormControlUIEnabled(true);
+</script>
+<script src="../../../resources/testharness.js"></script>
+<script src="../../../resources/testharnessreport.js"></script>
+<script src="../../../fast/forms/resources/common.js"></script>
+<script src="../../../fast/forms/resources/picker-common.js"></script>
+<script src="../../../fast/forms/calendar-picker/resources/calendar-picker-common.js"></script>
+<script src="../../../fast/forms/resources/common-wheel-event.js"></script>
+<input type="time" id="time" value="14:15" lang="ru">
+<script>
+let t = async_test('Test scrolling in time picker.');
+
+function test1() {
+  let hourColumn = popupWindow.global.picker.timeColumns.firstChild;
+  const scrollHourTopBeforeWheelEvent = hourColumn.scrollTop;
+  // scroll up by 2 ticks ~ 2 cells
+  dispatchWheelEvent(hourColumn, 0, 2);
+
+  let minuteColumn = hourColumn.nextSibling;
+  const scrollMinuteTopBeforeWheelEvent = minuteColumn.scrollTop;
+  // scroll up by 3 ticks ~ 3 cells
+  dispatchWheelEvent(minuteColumn, 0, 3);
+
+  t.step_timeout(function() {
+    // verify that both columns have been scrolled up.
+    assert_true(scrollHourTopBeforeWheelEvent > hourColumn.scrollTop);
+    assert_true(scrollMinuteTopBeforeWheelEvent > minuteColumn.scrollTop);
+    t.done();
+  }, 200);
+}
+
+openPicker(document.getElementById('time'), t.step_func(test1), t.step_func_done(() => {
+    assert_false(internals.runtimeFlags.formControlsRefreshEnabled, "Popup did not open.");
+  }));
+</script>
\ No newline at end of file"}

