+const fail = chrome.test.callbackFail;
+const pass = chrome.test.callbackPass;

 var testUrl = 'http://www.a.com:PORT' +
     '/extensions/api_test/page_capture/google.html';

 function waitForCurrentTabLoaded(callback) {
