+<!DOCTYPE html>
+<title>ServiceWorker FetchEvent issued from workers in an iframe sandboxed via CSP HTTP response header.</title>
+<script src="/resources/testharness.js"></script>
+<script src="/resources/testharnessreport.js"></script>
+<script src="resources/test-helpers.sub.js"></script>
+<body>
+<script>
+let lastCallbackId = 0;
+let callbacks = {};
+function doTest(frame, type) {
+  return new Promise(function(resolve) {
+    var id = ++lastCallbackId;
+    callbacks[id] = resolve;
+    frame.contentWindow.postMessage({id: id, type: type}, '*');
+  });
+}
+
+// Asks the service worker for data about requests and clients seen. The
+// worker posts a message back with |data| where:
+// |data.requests|: the requests the worker received FetchEvents for
+// |data.clients|: the URLs of all the worker's clients
+// The worker clears its data after responding.
+function getResultsFromWorker(worker) {
+  return new Promise(resolve => {
+    let channel = new MessageChannel();
+    channel.port1.onmessage = msg => {
+      resolve(msg.data);
+    };
+    worker.postMessage({port: channel.port2}, [channel.port2]);
+  });
+}
+
+window.onmessage = function (e) {
+  message = e.data;
+  let id = message['id'];
+  let callback = callbacks[id];
+  delete callbacks[id];
+  callback(message['result']);
+};
+
+const SCOPE = 'resources/sandboxed-iframe-fetch-event-iframe.py';
+const SCRIPT = 'resources/sandboxed-iframe-fetch-event-worker.js';
+const expected_base_url = new URL(SCOPE, location.href);
+// A service worker controlling |SCOPE|.
+let worker;
+// An iframe whose response header has
+// 'Content-Security-Policy: allow-scripts'.
+// This should NOT be controlled by a service worker.
+let sandboxed_frame_by_header;
+// An iframe whose response header has
+// 'Content-Security-Policy: allow-scripts allow-same-origin'.
+// This should be controlled by a service worker.
+let sandboxed_same_origin_frame_by_header;
+
+promise_test(t => {
+  return service_worker_unregister_and_register(t, SCRIPT, SCOPE)
+    .then(function(registration) {
+      add_completion_callback(() => registration.unregister());
+      worker = registration.installing;
+      return wait_for_state(t, registration.installing, 'activated');
+    });
+}, 'Prepare a service worker.');
+
+promise_test(t => {
+  const iframe_full_url = expected_base_url + '?sandbox=allow-scripts&' +
+                          'sandboxed-frame-by-header';
+  return with_iframe(iframe_full_url)
+    .then(f => {
+      sandboxed_frame_by_header = f;
+      add_completion_callback(() => f.remove());
+      return getResultsFromWorker(worker);
+    })
+    .then(data => {
+      let requests = data.requests;
+      assert_equals(requests.length, 1,
+                    'Service worker should provide the response');
+      assert_equals(requests[0], iframe_full_url);
+      assert_false(data.clients.includes(iframe_full_url),
+                   'Service worker should NOT control the sandboxed page');
+    });
+}, 'Prepare an iframe sandboxed by CSP HTTP header with allow-scripts.');
+
+promise_test(t => {
+  const iframe_full_url =
+    expected_base_url + '?sandbox=allow-scripts%20allow-same-origin&' +
+    'sandboxed-iframe-same-origin-by-header';
+  return with_iframe(iframe_full_url)
+    .then(f => {
+      sandboxed_same_origin_frame_by_header = f;
+      add_completion_callback(() => f.remove());
+      return getResultsFromWorker(worker);
+    })
+    .then(data => {
+      let requests = data.requests;
+      assert_equals(requests.length, 1);
+      assert_equals(requests[0], iframe_full_url);
+      assert_true(data.clients.includes(iframe_full_url));
+    })
+}, 'Prepare an iframe sandboxed by CSP HTTP header with allow-scripts and ' +
+   'allow-same-origin.');
+
+promise_test(t => {
+  let frame = sandboxed_frame_by_header;
+  return doTest(frame, 'fetch-from-worker')
+    .then(result => {
+      assert_equals(result, 'done');
+      return getResultsFromWorker(worker);
+    })
+    .then(data => {
+      assert_equals(data.requests.length, 0,
+                    'The request should NOT be handled by SW.');
+    });
+}, 'Fetch request from a worker in iframe sandboxed by CSP HTTP header ' +
+   'allow-scripts flag');
+
+promise_test(t => {
+  let frame = sandboxed_same_origin_frame_by_header;
+  return doTest(frame, 'fetch-from-worker')
+    .then(result => {
+      assert_equals(result, 'done');
+      return getResultsFromWorker(worker);
+    })
+    .then(data => {
+      let requests = data.requests;
+      assert_equals(requests.length, 1,
+                    'The request should be handled by SW.');
+      assert_equals(requests[0], frame.src + '&test=fetch-from-worker');
+    });
+}, 'Fetch request from a worker in iframe sandboxed by CSP HTTP header ' +
+   'with allow-scripts and allow-same-origin flag');
+</script>
+</body>"}

{"sha": "e962a552f67418c33975297cbb428dae8a0abafd", "filename": "ios/chrome/browser/ui/toolbar/adaptive_toolbar_view_controller.mm", "status": "modified", "additions": 25, "deletions": 10, "changes": 35, "blob_url": "https://github.com/chromium/chromium/blob/b40348af225a6c6bbbc85317437a315df6554f76/ios/chrome/browser/ui/toolbar/adaptive_toolbar_view_controller.mm", "raw_url": "https://github.com/chromium/chromium/raw/b40348af225a6c6bbbc85317437a315df6554f76/ios/chrome/browser/ui/toolbar/adaptive_toolbar_view_controller.mm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ios/chrome/browser/ui/toolbar/adaptive_toolbar_view_controller.mm?ref=b40348af225a6c6bbbc85317437a315df6554f76", "patch": "@@ -150,7 +150,7 @@ - (void)setLoadingState:(BOOL)loading {
   } else if (self.view.progressBar.hidden &&
              !IsRegularXRegularSizeClass(self) && !self.isNTP) {
     [self.view.progressBar setProgress:0];
-    [self.view.progressBar setHidden:NO animated:YES completion:nil];
+    [self updateProgressBarVisibility];
     // Layout if needed the progress bar to avoid having the progress bar going
     // backward when opening a page from the NTP.
     [self.view.progressBar layoutIfNeeded];
@@ -227,16 +227,12 @@ - (void)setScrollProgressForTabletOmnibox:(CGFloat)progress {
 #pragma mark - Protected

 - (void)stopProgressBar {
-  __weak MDCProgressView* weakProgressBar = self.view.progressBar;
   __weak AdaptiveToolbarViewController* weakSelf = self;
-  [self.view.progressBar
-      setProgress:1
-         animated:YES
-       completion:^(BOOL finished) {
-         if (!weakSelf.loading) {
-           [weakProgressBar setHidden:YES animated:YES completion:nil];
-         }
-       }];
+  [self.view.progressBar setProgress:1
+                            animated:YES
+                          completion:^(BOOL finished) {
+                            [weakSelf updateProgressBarVisibility];
+                          }];
 }

 #pragma mark - PopupMenuUIUpdating
@@ -315,6 +311,25 @@ - (void)makeViewAccessibilityTraitsContainer {

 #pragma mark - Private

+// Makes sure that the visibility of the progress bar is matching the one which
+// is expected.
+- (void)updateProgressBarVisibility {
+  __weak __typeof(self) weakSelf = self;
+  if (self.loading && self.view.progressBar.hidden) {
+    [self.view.progressBar setHidden:NO
+                            animated:YES
+                          completion:^(BOOL finished) {
+                            [weakSelf updateProgressBarVisibility];
+                          }];
+  } else if (!self.loading && !self.view.progressBar.hidden) {
+    [self.view.progressBar setHidden:YES
+                            animated:YES
+                          completion:^(BOOL finished) {
+                            [weakSelf updateProgressBarVisibility];
+                          }];
+  }
+}
+
 // Updates all buttons visibility to match any recent WebState or SizeClass
 // change.
 - (void)updateAllButtonsVisibility {"}

{"sha": "c932536734a92464a3f658c8a2d296dd6efdae50", "filename": "third_party/blink/web_tests/http/tests/canvas/resources/abe.png", "status": "added", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/chromium/chromium/blob/e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6/third_party/blink/web_tests/http/tests/canvas/resources/abe.png", "raw_url": "https://github.com/chromium/chromium/raw/e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6/third_party/blink/web_tests/http/tests/canvas/resources/abe.png", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/http/tests/canvas/resources/abe.png?ref=e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6"}<_**next**_>{"sha": "a58300a780e852992d805fe002bccab3543f8c62", "filename": "third_party/blink/web_tests/http/tests/canvas/toDataURL-clean-canvas.html", "status": "added", "additions": 39, "deletions": 0, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6/third_party/blink/web_tests/http/tests/canvas/toDataURL-clean-canvas.html", "raw_url": "https://github.com/chromium/chromium/raw/e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6/third_party/blink/web_tests/http/tests/canvas/toDataURL-clean-canvas.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/http/tests/canvas/toDataURL-clean-canvas.html?ref=e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6", "patch": "@@ -0,0 +1,39 @@
+<!DOCTYPE HTML>
+<html>
+<head>
+  <script src="../../../resources/testharness.js"></script>
+  <script src="../../../resources/testharnessreport.js"></script>
+</head>
+<body>
+  <script>
+    async_test((t) => {
+      var img = new Image();
+      img.src = "resources/abe.png";
+
+      img.onload = function() {
+        var canvas2d = document.createElement("canvas");
+        canvas2d.width = img.width;
+        canvas2d.height = img.height;
+        var context2d = canvas2d.getContext("2d");
+        context2d.drawImage(img, 0, 0);
+        var data2d = canvas2d.toDataURL();
+        assert_greater_than(data2d.length, 0, "toDataURL should work for local images");
+
+        createImageBitmap(img, 0, 0, img.width, img.height).then(function(bitmap) {
+          var canvasBitmap = document.createElement("canvas");
+          canvasBitmap.width = img.width;
+          canvasBitmap.height = img.height;
+          var contextBitmap = canvasBitmap.getContext("bitmaprenderer");
+          contextBitmap.transferFromImageBitmap(bitmap);
+          var dataBitmap = canvasBitmap.toDataURL();
+
+          assert_equals(data2d, dataBitmap);
+          assert_greater_than(dataBitmap.length, 0, "toDataURL should work for local images");
+
+          t.done();
+        });
+      };
+    });
+  </script>
+</body>
+</html>
\ No newline at end of file"}<_**next**_>{"sha": "4a873ecef70de94182c22a4e4ff06fbbcb513f47", "filename": "third_party/blink/web_tests/http/tests/canvas/toDataURL-xorigin-canvas.html", "status": "added", "additions": 36, "deletions": 0, "changes": 36, "blob_url": "https://github.com/chromium/chromium/blob/e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6/third_party/blink/web_tests/http/tests/canvas/toDataURL-xorigin-canvas.html", "raw_url": "https://github.com/chromium/chromium/raw/e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6/third_party/blink/web_tests/http/tests/canvas/toDataURL-xorigin-canvas.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/http/tests/canvas/toDataURL-xorigin-canvas.html?ref=e29b67156925d6a5d28f9a020cc8ffab8cfdfbb6", "patch": "@@ -0,0 +1,36 @@
+<!DOCTYPE HTML>
+<html>
+<head>
+  <script src="../../../resources/testharness.js"></script>
+  <script src="../../../resources/testharnessreport.js"></script>
+</head>
+<body>
+  <script>
+    async_test((t) => {
+      var img = new Image();
+      // Use a cross-origin URL.
+      img.src = "http://localhost:8000/resources/square.png";
+
+      img.onload = function() {
+        var canvas2d = document.createElement("canvas");
+        var context2d = canvas2d.getContext("2d");
+        context2d.drawImage(img, 0, 0);
+        assert_throws("SecurityError", () => {
+          canvas2d.toDataURL();
+        }, "x-origin image should prevent calls to toDataURL() in 2d canvas");
+
+        createImageBitmap(img, 0, 0, img.width, img.height).then(function(bitmap) {
+          var canvasBitmap = document.createElement("canvas");
+          var contextBitmap = canvasBitmap.getContext("bitmaprenderer");
+          contextBitmap.transferFromImageBitmap(bitmap);
+          assert_throws("SecurityError", () => {
+            canvasBitmap.toDataURL();
+          }, `x-origin image should prevent calls to toDataURL()
+              in bitmaprenderer canvas`);
+          t.done();
+        });
+      };
+    });
+  </script>
+</body>
+</html>
\ No newline at end of file"}

