{"sha": "5bff3e24e623e2f22b4fc2db17e54c8911112e3d", "filename": "chrome/browser/download/download_browsertest.cc", "status": "modified", "additions": 61, "deletions": 0, "changes": 61, "blob_url": "https://github.com/chromium/chromium/blob/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/browser/download/download_browsertest.cc", "raw_url": "https://github.com/chromium/chromium/raw/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/browser/download/download_browsertest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/download/download_browsertest.cc?ref=2f81d000fdb5331121cba7ff81dfaaec25b520a5", "patch": "@@ -3563,6 +3563,67 @@ IN_PROC_BROWSER_TEST_F(DownloadTest, FileExistenceCheckOpeningDownloadsPage) {
       .WaitForEvent();
 }

+// Checks that the navigation resulting from a cross origin download navigates
+// the correct iframe.
+IN_PROC_BROWSER_TEST_F(DownloadTest, CrossOriginDownloadNavigatesIframe) {
+  EmbeddedTestServer origin_one;
+  EmbeddedTestServer origin_two;
+  EmbeddedTestServer origin_three;
+
+  origin_one.ServeFilesFromDirectory(GetTestDataDirectory());
+  origin_two.ServeFilesFromDirectory(GetTestDataDirectory());
+  origin_three.ServeFilesFromDirectory(GetTestDataDirectory());
+  ASSERT_TRUE(origin_one.InitializeAndListen());
+  ASSERT_TRUE(origin_two.InitializeAndListen());
+  ASSERT_TRUE(origin_three.InitializeAndListen());
+
+  // We load a page on origin_one which iframes a page from origin_two which
+  // downloads a file that redirects to origin_three.
+  GURL download_url =
+      origin_two.GetURL(std::string("/redirect?") +
+                        origin_three.GetURL("/downloads/message.html").spec());
+  GURL referrer_url = origin_two.GetURL(
+      std::string("/downloads/download-attribute.html?target=") +
+      download_url.spec());
+  GURL main_url =
+      origin_one.GetURL(std::string("/downloads/page-with-frame.html?url=") +
+                        referrer_url.spec());
+
+  origin_two.RegisterRequestHandler(
+      base::BindRepeating(&ServerRedirectRequestHandler));
+
+  origin_one.StartAcceptingConnections();
+  origin_two.StartAcceptingConnections();
+  origin_three.StartAcceptingConnections();
+
+  ui_test_utils::NavigateToURL(browser(), main_url);
+
+  WebContents* web_contents =
+      browser()->tab_strip_model()->GetActiveWebContents();
+  ASSERT_TRUE(web_contents != NULL);
+  content::RenderFrameHost* render_frame_host = web_contents->GetMainFrame();
+  ASSERT_TRUE(render_frame_host != NULL);
+
+  // Clicking the <a download> in the iframe should navigate the iframe,
+  // not the main frame.
+  base::string16 expected_title(base::UTF8ToUTF16("Loaded as iframe"));
+  base::string16 failed_title(base::UTF8ToUTF16("Loaded as main frame"));
+  content::TitleWatcher title_watcher(web_contents, expected_title);
+  title_watcher.AlsoWaitForTitle(failed_title);
+  render_frame_host->ExecuteJavaScriptForTests(
+      base::ASCIIToUTF16("runTest();"));
+  ASSERT_EQ(expected_title, title_watcher.WaitAndGetTitle());
+
+  // Also verify that there's no download.
+  std::vector<DownloadItem*> downloads;
+  DownloadManagerForBrowser(browser())->GetAllDownloads(&downloads);
+  ASSERT_EQ(0u, downloads.size());
+
+  ASSERT_TRUE(origin_one.ShutdownAndWaitUntilComplete());
+  ASSERT_TRUE(origin_two.ShutdownAndWaitUntilComplete());
+  ASSERT_TRUE(origin_three.ShutdownAndWaitUntilComplete());
+}
+
 #if defined(FULL_SAFE_BROWSING)

 namespace {"}<_**next**_>{"sha": "e0ac090ac4ca89e4be41e4712716e1d071459300", "filename": "chrome/test/data/downloads/download-attribute.html", "status": "added", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/test/data/downloads/download-attribute.html", "raw_url": "https://github.com/chromium/chromium/raw/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/test/data/downloads/download-attribute.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/downloads/download-attribute.html?ref=2f81d000fdb5331121cba7ff81dfaaec25b520a5", "patch": "@@ -0,0 +1,11 @@
+<!doctype html>
+<a download>link</a>
+<script>
+  var anchorElement = document.querySelector('a[download]');
+  url = window.location.href;
+  anchorElement.href = url.substr(url.indexOf('=') + 1);
+
+  window.addEventListener('message', function (evt) {
+    anchorElement.click();
+  }, false);
+</script>"}<_**next**_>{"sha": "8dc7bea3ab4eb9b7bde62ab95ecd7ef76bbb8e65", "filename": "chrome/test/data/downloads/message.html", "status": "added", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/chromium/chromium/blob/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/test/data/downloads/message.html", "raw_url": "https://github.com/chromium/chromium/raw/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/test/data/downloads/message.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/downloads/message.html?ref=2f81d000fdb5331121cba7ff81dfaaec25b520a5", "patch": "@@ -0,0 +1,7 @@
+<!doctype html>
+<script>
+if (window.parent === window)
+  document.title = "Loaded as main frame";
+else
+  window.parent.postMessage('Loaded as iframe', '*');
+</script>"}<_**next**_>{"sha": "287a7ffe6348269cd7d1e83b606aca1171373dda", "filename": "chrome/test/data/downloads/page-with-frame.html", "status": "added", "additions": 19, "deletions": 0, "changes": 19, "blob_url": "https://github.com/chromium/chromium/blob/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/test/data/downloads/page-with-frame.html", "raw_url": "https://github.com/chromium/chromium/raw/2f81d000fdb5331121cba7ff81dfaaec25b520a5/chrome/test/data/downloads/page-with-frame.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/downloads/page-with-frame.html?ref=2f81d000fdb5331121cba7ff81dfaaec25b520a5", "patch": "@@ -0,0 +1,19 @@
+<!doctype html>
+<html>
+<body>
+<script>
+  var iframeElement = document.createElement('iframe');
+  url = window.location.href;
+  iframeElement.src = url.substr(url.indexOf('=') + 1);
+  document.body.appendChild(iframeElement);
+
+  function runTest() {
+    iframeElement.contentWindow.postMessage('', '*');
+  }
+
+  window.addEventListener('message', function (evt) {
+    document.title = evt.data;
+  }, false);
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "c7c68976c83de1d2767cd292c3f25c911e0a96d3", "filename": "components/download/public/common/download_url_parameters.cc", "status": "modified", "additions": 1, "deletions": 0, "changes": 1, "blob_url": "https://github.com/chromium/chromium/blob/2f81d000fdb5331121cba7ff81dfaaec25b520a5/components/download/public/common/download_url_parameters.cc", "raw_url": "https://github.com/chromium/chromium/raw/2f81d000fdb5331121cba7ff81dfaaec25b520a5/components/download/public/common/download_url_parameters.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/components/download/public/common/download_url_parameters.cc?ref=2f81d000fdb5331121cba7ff81dfaaec25b520a5", "patch": "@@ -32,6 +32,7 @@ DownloadUrlParameters::DownloadUrlParameters(
