 "}<_**next**_>{"sha": "c7a097abe8e595669a62e12608e9fe36f5bcf0b7", "filename": "content/test/data/service_worker/request_navigate.html", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/e8bf23bbbc3976d6a3418a7298a39bbf35c7beb3/content/test/data/service_worker/request_navigate.html", "raw_url": "https://github.com/chromium/chromium/raw/e8bf23bbbc3976d6a3418a7298a39bbf35c7beb3/content/test/data/service_worker/request_navigate.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/content/test/data/service_worker/request_navigate.html?ref=e8bf23bbbc3976d6a3418a7298a39bbf35c7beb3", "patch": "@@ -0,0 +1,17 @@
+<!DOCTYPE html>
+<meta charset="utf-8">
+<title>Request navigate</title>
+<script>
+// Asks the service worker to call WindowClient.navigate() on us. It will
+// message back the result if it failed, or else we navigate away.
+async function requestToNavigate() {
+  const sawMessage = new Promise((resolve) => {
+    navigator.serviceWorker.onmessage = (event) => {
+      resolve(event.data);
+    };
+  });
+  const registration = await navigator.serviceWorker.ready;
+  registration.active.postMessage({command: 'navigate', url: 'empty.html'});
+  return await sawMessage;
+}
+</script>"}

