+ui::Layer* FindLayer(ui::Layer* root, ui::Layer* target) {
+  if (root == target)
+    return target;
+  for (auto* child : root->children()) {
+    auto* result = FindLayer(child, target);
+    if (result)
+      return result;
+  }
+  return nullptr;
+}
