+<!DOCTYPE html>
+<html>
+
+<head>
+    <script nonce="abc" src="/resources/testharness.js"></script>
+    <script nonce="abc" src="/resources/testharnessreport.js"></script>
+</head>
+
+<!-- This tests that navigating a main window to a local scheme preserves the current CSP.
+     We need to test this in a main window with no parent/opener so we use
+     a link with target=_blank and rel=noopener. -->
+<body>
+    <iframe src="support/navigate-self-to-blob.html?csp=script-src%20%27nonce-abc%27&report_id={{$id:uuid()}}"></iframe>
+    <script async defer src='../support/checkReport.sub.js?reportField=violated-directive&reportValue=script-src%20%27nonce-abc%27&reportID={{$id}}'></script>
+</body>
+
+</html>"}<_**next**_>{"sha": "3b54528d56a445e6ef723371f5bb7a858ee016c8", "filename": "third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/blob-url-in-main-window-self-navigate-inherits.sub.html", "status": "renamed", "additions": 0, "deletions": 0, "changes": 0, "blob_url": "https://github.com/chromium/chromium/blob/108147dfd1ea159fd3632ef92ccc4ab8952980c7/third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/blob-url-in-main-window-self-navigate-inherits.sub.html", "raw_url": "https://github.com/chromium/chromium/raw/108147dfd1ea159fd3632ef92ccc4ab8952980c7/third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/blob-url-in-main-window-self-navigate-inherits.sub.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/blob-url-in-main-window-self-navigate-inherits.sub.html?ref=108147dfd1ea159fd3632ef92ccc4ab8952980c7", "previous_filename": "third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/blob-url-self-navigate-inherits.sub.html"}<_**next**_>{"sha": "590fa7ec1a9caafc6f18e6821f100629688bd300", "filename": "third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/sandboxed-blob-scheme.html", "status": "added", "additions": 23, "deletions": 0, "changes": 23, "blob_url": "https://github.com/chromium/chromium/blob/108147dfd1ea159fd3632ef92ccc4ab8952980c7/third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/sandboxed-blob-scheme.html", "raw_url": "https://github.com/chromium/chromium/raw/108147dfd1ea159fd3632ef92ccc4ab8952980c7/third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/sandboxed-blob-scheme.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/content-security-policy/inheritance/sandboxed-blob-scheme.html?ref=108147dfd1ea159fd3632ef92ccc4ab8952980c7", "patch": "@@ -0,0 +1,23 @@
