       V8DOMActivityLogger::CurrentActivityLoggerIfIsolatedWorld();
   if (activity_logger) {"}<_**next**_>{"sha": "3a0641170ea26edfd998acc9105ccc3bad8b4f98", "filename": "third_party/blink/web_tests/external/wpt/content-security-policy/navigation/to-javascript-parent-initiated-parent-csp-disallow.html", "status": "added", "additions": 23, "deletions": 0, "changes": 23, "blob_url": "https://github.com/chromium/chromium/blob/0e3b0c22a5c596bdc24a391b3f02952c1c3e4f1b/third_party/blink/web_tests/external/wpt/content-security-policy/navigation/to-javascript-parent-initiated-parent-csp-disallow.html", "raw_url": "https://github.com/chromium/chromium/raw/0e3b0c22a5c596bdc24a391b3f02952c1c3e4f1b/third_party/blink/web_tests/external/wpt/content-security-policy/navigation/to-javascript-parent-initiated-parent-csp-disallow.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/content-security-policy/navigation/to-javascript-parent-initiated-parent-csp-disallow.html?ref=0e3b0c22a5c596bdc24a391b3f02952c1c3e4f1b", "patch": "@@ -0,0 +1,23 @@
+<!DOCTYPE html>
+<head>
+<meta http-equiv="content-security-policy" content="script-src 'self' 'nonce-abc'">
+<script src="/resources/testharness.js"></script>
+<script src="/resources/testharnessreport.js"></script>
+</head>
+<body>
+<iframe src="support/frame-with-csp.sub.html?csp=script-src%20'self'%20'unsafe-inline'"></iframe>
+<script nonce='abc'>
+  var t = async_test("Should not have executed the javascript url");
+  const iframe = document.querySelector("iframe");
+  iframe.addEventListener('load', () => {
+    window.onmessage = t.step_func(function(e) {
+      if (e.data == "executed")
+        assert_true(false, "Javascript url executed");
+    });
+    window.addEventListener('securitypolicyviolation', t.step_func_done(function(e) {
+      assert_equals(e.blockedURI, 'inline');
+    }));
+    iframe.contentWindow.location.href = 'javascript:parent.postMessage(\'executed\', \'*\')'
+  });
+</script>
+</body>"}

{"sha": "7c7b6c5343bb05ebea63212a0c00fdfbd675efc7", "filename": "chrome/install_static/install_util.cc", "status": "modified", "additions": 4, "deletions": 2, "changes": 6, "blob_url": "https://github.com/chromium/chromium/blob/08965161257ab9aeef9a3548c1cd1a44525dc562/chrome/install_static/install_util.cc", "raw_url": "https://github.com/chromium/chromium/raw/08965161257ab9aeef9a3548c1cd1a44525dc562/chrome/install_static/install_util.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/install_static/install_util.cc?ref=08965161257ab9aeef9a3548c1cd1a44525dc562", "patch": "@@ -847,13 +847,15 @@ std::vector<std::wstring> TokenizeCommandLineToArray(

 std::wstring GetSwitchValueFromCommandLine(const std::wstring& command_line,
                                            const std::wstring& switch_name) {
+  static constexpr wchar_t kSwitchTerminator[] = L"--";
   assert(!command_line.empty());
   assert(!switch_name.empty());

   std::vector<std::wstring> as_array = TokenizeCommandLineToArray(command_line);
   std::wstring switch_with_equal = L"--" + switch_name + L"=";
-  for (size_t i = 1; i < as_array.size(); ++i) {
-    const std::wstring& arg = as_array[i];
+  auto end = std::find(as_array.cbegin(), as_array.cend(), kSwitchTerminator);
+  for (auto scan = as_array.cbegin(); scan != end; ++scan) {
+    const std::wstring& arg = *scan;
     if (arg.compare(0, switch_with_equal.size(), switch_with_equal) == 0)
       return arg.substr(switch_with_equal.size());
   }"}<_**next**_>{"sha": "27a55e3bd94ca5a377ca300fe5240874f4efdcf5", "filename": "chrome/install_static/install_util.h", "status": "modified", "additions": 4, "deletions": 3, "changes": 7, "blob_url": "https://github.com/chromium/chromium/blob/08965161257ab9aeef9a3548c1cd1a44525dc562/chrome/install_static/install_util.h", "raw_url": "https://github.com/chromium/chromium/raw/08965161257ab9aeef9a3548c1cd1a44525dc562/chrome/install_static/install_util.h", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/install_static/install_util.h?ref=08965161257ab9aeef9a3548c1cd1a44525dc562", "patch": "@@ -275,9 +275,10 @@ std::vector<std::wstring> TokenizeString16(const std::wstring& str,
