-// value of the |switch_name| passed in.
+// Returns the value of a switch of the form "--<switch name>=<switch value>" in
+// |command_line|. An empty switch in |command_line| ("--") denotes the end of
+// switches and the beginning of args. Anything of the form --<switch
+// name>=<switch value> following "--" is ignored.
 std::wstring GetSwitchValueFromCommandLine(const std::wstring& command_line,
                                            const std::wstring& switch_name);
 "}<_**next**_>{"sha": "a05794655ddd653123941c14ce20076e5c07c79d", "filename": "chrome/install_static/install_util_unittest.cc", "status": "modified", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/08965161257ab9aeef9a3548c1cd1a44525dc562/chrome/install_static/install_util_unittest.cc", "raw_url": "https://github.com/chromium/chromium/raw/08965161257ab9aeef9a3548c1cd1a44525dc562/chrome/install_static/install_util_unittest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/install_static/install_util_unittest.cc?ref=08965161257ab9aeef9a3548c1cd1a44525dc562", "patch": "@@ -96,6 +96,10 @@ TEST(InstallStaticTest, GetSwitchValueFromCommandLineTest) {
