{"sha": "5e4041d0f8d4668fa1516758743a64b4e9cfb666", "filename": "third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https-expected.txt", "status": "added", "additions": 4, "deletions": 0, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/48d01db7e4858ad06cebaea89aa55575ee1bdd42/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/48d01db7e4858ad06cebaea89aa55575ee1bdd42/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https-expected.txt?ref=48d01db7e4858ad06cebaea89aa55575ee1bdd42", "patch": "@@ -0,0 +1,4 @@
+This is a testharness.js-based test.
+FAIL canvas is tainted after writing both a non-opaque image and an opaque image from the same URL assert_throws: function "() => { canvas.toDataURL(); }" did not throw
+Harness: the test ran to completion.
+"}<_**next**_>{"sha": "4e233053729c42c1f8ac49d9554f3035c8f04728", "filename": "third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https.html", "status": "added", "additions": 57, "deletions": 0, "changes": 57, "blob_url": "https://github.com/chromium/chromium/blob/48d01db7e4858ad06cebaea89aa55575ee1bdd42/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https.html", "raw_url": "https://github.com/chromium/chromium/raw/48d01db7e4858ad06cebaea89aa55575ee1bdd42/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/fetch-canvas-tainting-double-write.https.html?ref=48d01db7e4858ad06cebaea89aa55575ee1bdd42", "patch": "@@ -0,0 +1,57 @@
+<!DOCTYPE html>
+<script src="/resources/testharness.js"></script>
+<script src="/resources/testharnessreport.js"></script>
+<script src="/common/get-host-info.sub.js"></script>
+<script src="resources/test-helpers.sub.js"></script>
+<meta charset="utf-8">
+<title>canvas tainting when written twice</title>
+<script>
+function loadImage(doc, url) {
+  return new Promise((resolve, reject) => {
+    const image = doc.createElement('img');
+    image.onload = () => { resolve(image); }
+    image.onerror = () => { reject('failed to load: ' + url); };
+    image.src = url;
+  });
+}
+
+// Tests that a canvas is tainted after it's written to with both a clear image
+// and opaque image from the same URL. A bad implementation might cache the
+// info of the clear image and assume the opaque image is also clear because
+// it's from the same URL. See https://crbug.com/907047 for details.
+promise_test(async (t) => {
+  // Set up a service worker and a controlled iframe.
+  const script = 'resources/fetch-canvas-tainting-double-write-worker.js';
+  const scope = 'resources/fetch-canvas-tainting-double-write-iframe.html';
+  const registration = await service_worker_unregister_and_register(
+      t, script, scope);
+  t.add_cleanup(() => registration.unregister());
+  await wait_for_state(t, registration.installing, 'activated');
+  const iframe = await with_iframe(scope);
+  t.add_cleanup(() => iframe.remove());
+
+  // Load the same cross-origin image URL through the controlled iframe and
+  // this uncontrolled frame. The service worker responds with a same-origin
+  // image for the controlled iframe, so it is cleartext.
+  const imagePath = base_path() + 'resources/fetch-access-control.py?PNGIMAGE';
+  const imageUrl = get_host_info()['HTTPS_REMOTE_ORIGIN'] + imagePath;
+  const clearImage = await loadImage(iframe.contentDocument, imageUrl);
+  const opaqueImage = await loadImage(document, imageUrl);
+
+  // Set up a canvas for testing tainting.
+  const canvas = document.createElement('canvas');
+  const context = canvas.getContext('2d');
+  canvas.width = clearImage.width;
+  canvas.height = clearImage.height;
+
+  // The clear image and the opaque image have the same src URL. But...
+
+  // ... the clear image doesn't taint the canvas.
+  context.drawImage(clearImage, 0, 0);
+  assert_true(canvas.toDataURL().length > 0);
+
+  // ... the opaque image taints the canvas.
+  context.drawImage(opaqueImage, 0, 0);
+  assert_throws('SecurityError', () => { canvas.toDataURL(); });
+}, 'canvas is tainted after writing both a non-opaque image and an opaque image from the same URL');
+</script>"}<_**next**_>{"sha": "17723dcdda2f2fadb9ab0ab4a00b28c24b815234", "filename": "third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/fetch-canvas-tainting-double-write-worker.js", "status": "added", "additions": 7, "deletions": 0, "changes": 7, "blob_url": "https://github.com/chromium/chromium/blob/48d01db7e4858ad06cebaea89aa55575ee1bdd42/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/fetch-canvas-tainting-double-write-worker.js", "raw_url": "https://github.com/chromium/chromium/raw/48d01db7e4858ad06cebaea89aa55575ee1bdd42/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/fetch-canvas-tainting-double-write-worker.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/fetch-canvas-tainting-double-write-worker.js?ref=48d01db7e4858ad06cebaea89aa55575ee1bdd42", "patch": "@@ -0,0 +1,7 @@
+self.addEventListener('fetch', (event) => {
+  url = new URL(event.request.url);
+  if (url.search == '?PNGIMAGE') {
+    localUrl = new URL(url.pathname + url.search, self.location);
+    event.respondWith(fetch(localUrl));
+  }
+});"}

