+א		1
+
+Test passes if it does not crash."}<_**next**_>{"sha": "530dc4af9d87f2aa89ffe149ae5c4b466672f9ba", "filename": "third_party/blink/web_tests/fast/text/international/ar_tab_selection_crash.html", "status": "added", "additions": 35, "deletions": 0, "changes": 35, "blob_url": "https://github.com/chromium/chromium/blob/8c7054864ea9b70015351b17376b8515296efb8f/third_party/blink/web_tests/fast/text/international/ar_tab_selection_crash.html", "raw_url": "https://github.com/chromium/chromium/raw/8c7054864ea9b70015351b17376b8515296efb8f/third_party/blink/web_tests/fast/text/international/ar_tab_selection_crash.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/fast/text/international/ar_tab_selection_crash.html?ref=8c7054864ea9b70015351b17376b8515296efb8f", "patch": "@@ -0,0 +1,35 @@
+<!DOCTYPE html>
+<html>
+    <head>
+        <meta charset="utf-8">
+        <title>Test handling of selection with arabic and tab characters</title>
+    </head>
+    <body>
+        <pre>א		1</pre>
+        <p>
+            Test passes if it does not crash.
+        </p>
+        <script>
+            if (window.testRunner) {
+                testRunner.dumpAsText();
+            }
+
+            var testElement = document.getElementsByTagName('pre')[0];
+            var range = document.createRange();
+            range.setStart(testElement.firstChild, 1);
+            range.setEnd(testElement.firstChild, 3);
+            window.getSelection().addRange(range);
+
+            if (window.eventSender) {
+                var elementBounds = testElement.getBoundingClientRect();
+                var rangeBounds = range.getBoundingClientRect();
+                var x = (elementBounds.right - rangeBounds.right) / 2;
+                var y = (elementBounds.bottom - elementBounds.top) / 2;
+                eventSender.mouseMoveTo(0, 0);
+                eventSender.mouseMoveTo(x, y);
+                eventSender.mouseDown();
+                eventSender.mouseUp();
+            }
+        </script>
+    </body>
+</html>"}

