+"}<_**next**_>{"sha": "075848bd12469903d2bef5cbfac27063c191d893", "filename": "third_party/WebKit/LayoutTests/http/tests/devtools/network/request-preview-uri-escaping.js", "status": "added", "additions": 19, "deletions": 0, "changes": 19, "blob_url": "https://github.com/chromium/chromium/blob/0238c6b5064859f39ff5f6d3265712093934b2a7/third_party/WebKit/LayoutTests/http/tests/devtools/network/request-preview-uri-escaping.js", "raw_url": "https://github.com/chromium/chromium/raw/0238c6b5064859f39ff5f6d3265712093934b2a7/third_party/WebKit/LayoutTests/http/tests/devtools/network/request-preview-uri-escaping.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/devtools/network/request-preview-uri-escaping.js?ref=0238c6b5064859f39ff5f6d3265712093934b2a7", "patch": "@@ -0,0 +1,19 @@
+// Copyright 2018 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+(async function() {
+  TestRunner.addResult(`Verifies that RequestHTMLView's iframe src is URI encoded`);
+  await TestRunner.loadModule('network_test_runner');
+  await TestRunner.showPanel('network');
+
+  const dataUrl = `data:text/html,<body><p>hello world!<p>%3Cp%3EURI%20encoded%20tag!%3C%2Fp%3E</body>`;
+  const requestHtmlView = new Network.RequestHTMLView(dataUrl);
+  requestHtmlView.wasShown();
+  const iframe = requestHtmlView.contentElement.firstChild;
+
+  TestRunner.addResult('iframe.src: ' + iframe.src);
+  TestRunner.addResult('decoded iframe.src: ' + decodeURIComponent(iframe.src));
+
+  TestRunner.completeTest();
+})();"}<_**next**_>{"sha": "e2b85ba9af8c625e8a73ebb42d6a9c92455fa498", "filename": "third_party/blink/renderer/devtools/front_end/network/RequestHTMLView.js", "status": "modified", "additions": 1, "deletions": 1, "changes": 2, "blob_url": "https://github.com/chromium/chromium/blob/0238c6b5064859f39ff5f6d3265712093934b2a7/third_party/blink/renderer/devtools/front_end/network/RequestHTMLView.js", "raw_url": "https://github.com/chromium/chromium/raw/0238c6b5064859f39ff5f6d3265712093934b2a7/third_party/blink/renderer/devtools/front_end/network/RequestHTMLView.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/devtools/front_end/network/RequestHTMLView.js?ref=0238c6b5064859f39ff5f6d3265712093934b2a7", "patch": "@@ -63,7 +63,7 @@ Network.RequestHTMLView = class extends UI.VBox {
