+Content-Type: image/png
+Access-Control-Allow-Origin: *"}<_**next**_>{"sha": "79f08991174cb50735f8bc0631876c22b3359be1", "filename": "third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/worker-fetching-cross-origin.js", "status": "added", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/01b42e2bc2aac531b17596729ae4e5c223ae7124/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/worker-fetching-cross-origin.js", "raw_url": "https://github.com/chromium/chromium/raw/01b42e2bc2aac531b17596729ae4e5c223ae7124/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/worker-fetching-cross-origin.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/external/wpt/service-workers/service-worker/resources/worker-fetching-cross-origin.js?ref=01b42e2bc2aac531b17596729ae4e5c223ae7124", "patch": "@@ -0,0 +1,10 @@
+importScripts('/common/get-host-info.sub.js');
+importScripts('test-helpers.sub.js');
+
+self.addEventListener('fetch', event => {
+  const host_info = get_host_info();
+  // The sneaky Service Worker changes the same-origin 'square' request for a cross-origin image.
+  if (event.request.url.indexOf('square') != -1) {
+    event.respondWith(fetch(host_info['HTTPS_REMOTE_ORIGIN'] + base_path() + 'square.png', {mode: 'cors'}));
+  }
+});"}<_**next**_>{"sha": "1f011dd6b307bc804fbcbfe190c060e7b8893c9f", "filename": "third_party/blink/renderer/core/timing/performance.cc", "status": "modified", "additions": 4, "deletions": 1, "changes": 5, "blob_url": "https://github.com/chromium/chromium/blob/01b42e2bc2aac531b17596729ae4e5c223ae7124/third_party/blink/renderer/core/timing/performance.cc", "raw_url": "https://github.com/chromium/chromium/raw/01b42e2bc2aac531b17596729ae4e5c223ae7124/third_party/blink/renderer/core/timing/performance.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/core/timing/performance.cc?ref=01b42e2bc2aac531b17596729ae4e5c223ae7124", "patch": "@@ -275,8 +275,11 @@ bool Performance::PassesTimingAllowCheck(
     const SecurityOrigin& initiator_security_origin,
     const AtomicString& original_timing_allow_origin,
     ExecutionContext* context) {
+  const KURL& response_url = response.WasFetchedViaServiceWorker()
+                                 ? response.OriginalURLViaServiceWorker()
+                                 : response.Url();
   scoped_refptr<const SecurityOrigin> resource_origin =
-      SecurityOrigin::Create(response.Url());
+      SecurityOrigin::Create(response_url);
   if (resource_origin->IsSameSchemeHostPort(&initiator_security_origin))
     return true;
 "}

{"sha": "700df1fe4b5c652c26e8cdd7b093243094c4e1ee", "filename": "ios/web/web_state/ui/crw_web_controller.mm", "status": "modified", "additions": 12, "deletions": 1, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/c12ce092c44a325d78baaa9679ecfe7370fd1fe3/ios/web/web_state/ui/crw_web_controller.mm", "raw_url": "https://github.com/chromium/chromium/raw/c12ce092c44a325d78baaa9679ecfe7370fd1fe3/ios/web/web_state/ui/crw_web_controller.mm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ios/web/web_state/ui/crw_web_controller.mm?ref=c12ce092c44a325d78baaa9679ecfe7370fd1fe3", "patch": "@@ -3170,14 +3170,25 @@ - (void)runJavaScriptDialogOfType:(web::JavaScriptDialogType)type
                       defaultText:(NSString*)defaultText
                        completion:(void (^)(BOOL, NSString*))completionHandler {
   DCHECK(completionHandler);
+
+  // JavaScript dialogs should not be presented if there is no information about
+  // the requesting page's URL.
+  GURL requestURL = net::GURLWithNSURL(frame.request.URL);
+  if (!requestURL.is_valid()) {
+    completionHandler(NO, nil);
+    return;
+  }
+
+  // If dialogs have been explicitly suppressed using WebState's
+  // SetShouldSuppressDialogs(), suppress the dialog and notify observers.
   if (self.shouldSuppressDialogs) {
     _webStateImpl->OnDialogSuppressed();
     completionHandler(NO, nil);
     return;
   }

   self.webStateImpl->RunJavaScriptDialog(
-      net::GURLWithNSURL(frame.request.URL), type, message, defaultText,
+      requestURL, type, message, defaultText,
       base::BindBlockArc(^(bool success, NSString* input) {
         completionHandler(success, input);
       }));"}

{"sha": "c1ba686c56301cb050a5eedac0be7f9b70fe4314", "filename": "third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect-expected.txt", "status": "added", "additions": 11, "deletions": 0, "changes": 11, "blob_url": "https://github.com/chromium/chromium/blob/761c75d2d607638ff53c764b4925bcca9be601d8/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect-expected.txt", "raw_url": "https://github.com/chromium/chromium/raw/761c75d2d607638ff53c764b4925bcca9be601d8/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect-expected.txt", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect-expected.txt?ref=761c75d2d607638ff53c764b4925bcca9be601d8", "patch": "@@ -0,0 +1,11 @@
+CONSOLE WARNING: line 21: The Web Audio autoplay policy will be re-enabled in Chrome 70 (October 2018). Please check that your website is compatible with it. https://goo.gl/7K7WLu
+CONSOLE MESSAGE: MediaElementAudioSource outputs zeroes due to CORS access restrictions for http://127.0.0.1:8000/serviceworker/resources/redirect.php?Redirect=http://localhost:8000/security/resources/webaudio/laughter.wav
+MediaElementAudioSourceNode with redirection
+
+On success, you will see a series of "PASS" messages, followed by "TEST COMPLETE".
+
+PASS All samples correctly zeroed.
+PASS successfullyParsed is true
+
+TEST COMPLETE
+"}<_**next**_>{"sha": "a166ec87bd5f0e88de34dc25d8f05e13aad4e92a", "filename": "third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect.html", "status": "added", "additions": 41, "deletions": 0, "changes": 41, "blob_url": "https://github.com/chromium/chromium/blob/761c75d2d607638ff53c764b4925bcca9be601d8/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect.html", "raw_url": "https://github.com/chromium/chromium/raw/761c75d2d607638ff53c764b4925bcca9be601d8/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/media-element-audio-source-node-redirect.html?ref=761c75d2d607638ff53c764b4925bcca9be601d8", "patch": "@@ -0,0 +1,41 @@
+<!doctype html>
+<html>
+  <head>
+    <script src="resources/webaudio/compatibility.js"></script>
+    <script src="resources/webaudio/media-element-audio-source-node-test.js"></script>
+    <script src="/js-test-resources/js-test.js"></script>
+  </head>
+
+  <body>
+    <div id="description"></div>
+    <div id="console"></div>
+
+    <script>
+      description("MediaElementAudioSourceNode with redirection");
+
+      var src = "/serviceworker/resources/redirect.php?Redirect=http://localhost:8000/security/resources/webaudio/laughter.wav";
+      var data;
+
+      function checkResult (e) {
+        data = e.getChannelData(0);
+        var count = 0;
+
+        // Count the number of non-zero values. Since this is a cross-origin source, all the values
+        // should be zero.
+        for (var k = 0; k < data.length; ++k) {
+            if (data[k] != 0) {
+                ++count;
+            }
+        }
+        if (count > 0) {
+            testFailed("Expected all zeros but found " + count + " non-zero values out of " + data.length + ".");
+        } else {
+            testPassed("All samples correctly zeroed.");
+        }
+      }
+
+      runTest(src, checkResult);
+
