         "../browser/extensions/gpu_browsertest.cc",
         "../browser/extensions/isolated_app_browsertest.cc",
         "../browser/extensions/lazy_background_page_apitest.cc","}<_**next**_>{"sha": "5224df6d68117a6a6bb548f28a0f01780e41f83e", "filename": "chrome/test/data/extensions/api_test/active_tab_file_urls/file_iframe.html", "status": "added", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/f020de9f4788d81c05f0a4947dabfdb777604cc6/chrome/test/data/extensions/api_test/active_tab_file_urls/file_iframe.html", "raw_url": "https://github.com/chromium/chromium/raw/f020de9f4788d81c05f0a4947dabfdb777604cc6/chrome/test/data/extensions/api_test/active_tab_file_urls/file_iframe.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/active_tab_file_urls/file_iframe.html?ref=f020de9f4788d81c05f0a4947dabfdb777604cc6", "patch": "@@ -0,0 +1,10 @@
+<!DOCTYPE html>
+<html>
+<head>
+  <title></title>
+  <script type="text/javascript" src="window_onload.js"></script>
+</head>
+<body>
+  <iframe src="file:///" name="file_iframe" id="file_iframe"></iframe>
+</body>
