+window.onload = function() {
+  var iframe = document.getElementById('file_iframe');
+  try {
+    var url = iframe.contentWindow.location.href
+    if (url === 'about:blank')
+      chrome.test.sendMessage('denied');
+  } catch (e) {
+    var expectedError =
+        `Blocked a frame with origin "${window.location.origin}" from ` +
+        `accessing a cross-origin frame.`;
+    if (e.message === expectedError)
+      chrome.test.sendMessage('allowed');
+  }
+};"}<_**next**_>{"sha": "5224df6d68117a6a6bb548f28a0f01780e41f83e", "filename": "chrome/test/data/extensions/file_iframe/background.html", "status": "added", "additions": 10, "deletions": 0, "changes": 10, "blob_url": "https://github.com/chromium/chromium/blob/f020de9f4788d81c05f0a4947dabfdb777604cc6/chrome/test/data/extensions/file_iframe/background.html", "raw_url": "https://github.com/chromium/chromium/raw/f020de9f4788d81c05f0a4947dabfdb777604cc6/chrome/test/data/extensions/file_iframe/background.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/file_iframe/background.html?ref=f020de9f4788d81c05f0a4947dabfdb777604cc6", "patch": "@@ -0,0 +1,10 @@
