+  <iframe src="file:///" name="file_iframe" id="file_iframe"></iframe>
+</body>
+</html>"}<_**next**_>{"sha": "eafa3627a2c777af7f73df78df14451652034adf", "filename": "chrome/test/data/extensions/file_iframe/window_onload.js", "status": "added", "additions": 14, "deletions": 0, "changes": 14, "blob_url": "https://github.com/chromium/chromium/blob/f020de9f4788d81c05f0a4947dabfdb777604cc6/chrome/test/data/extensions/file_iframe/window_onload.js", "raw_url": "https://github.com/chromium/chromium/raw/f020de9f4788d81c05f0a4947dabfdb777604cc6/chrome/test/data/extensions/file_iframe/window_onload.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/file_iframe/window_onload.js?ref=f020de9f4788d81c05f0a4947dabfdb777604cc6", "patch": "@@ -0,0 +1,14 @@
+window.onload = function() {
+  var iframe = document.getElementById('file_iframe');
+  try {
+    var url = iframe.contentWindow.location.href
+    if (url === 'about:blank')
+      chrome.test.sendMessage('denied');
+  } catch (e) {
+    var expectedError =
+        `Blocked a frame with origin "${window.location.origin}" from ` +
+        `accessing a cross-origin frame.`;
