{"sha": "7349b0fc0853ca460981b86740588afb514442f9", "filename": "third_party/WebKit/LayoutTests/fast/dom/shadow/style-change-tree-scope.html", "status": "added", "additions": 33, "deletions": 0, "changes": 33, "blob_url": "https://github.com/chromium/chromium/blob/2bf635c28effa427a270f4fc45df84ed344f411c/third_party/WebKit/LayoutTests/fast/dom/shadow/style-change-tree-scope.html", "raw_url": "https://github.com/chromium/chromium/raw/2bf635c28effa427a270f4fc45df84ed344f411c/third_party/WebKit/LayoutTests/fast/dom/shadow/style-change-tree-scope.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/fast/dom/shadow/style-change-tree-scope.html?ref=2bf635c28effa427a270f4fc45df84ed344f411c", "patch": "@@ -0,0 +1,33 @@
+<!DOCTYPE html>
+<script src="../../../resources/testharness.js"></script>
+<script src="../../../resources/testharnessreport.js"></script>
+<div id="shadowHost"></div>
+<style id="style"></style>
+<script>
+function moveAndReentrantlyAppendToStyleElement() {
+  let sr = shadowHost.createShadowRoot();
+  let script = document.createElement('script');
+  sr.appendChild(script);
+
+  let scriptText = `
+    let s = shadowHost.shadowRoot.querySelector('style');
+    let text = document.createTextNode('div { background-color: skyblue; }');
+    s.appendChild(text);`;
+
+  // Appending scriptText and style in the same call is important here. This way
+  // scriptText will be evaluated synchronously while in script.append.
+  // Having that script execute before the tree-scope-move was fully completed
+  // is what caused a crash previously.
+  script.append(scriptText, style);
+}
+
+test(function () {
+  try {
+    moveAndReentrantlyAppendToStyleElement();
+  } catch (e) {}
+  let bg = shadowHost.shadowRoot.styleSheets[0].cssRules[0].styleMap
+    .get('background-color').toString();
+  assert_equals(bg, 'skyblue'); // Don't crash.
+}, 'Reentrantly appending to style element while changing tree scope does not crash');
+
+</script>"}<_**next**_>{"sha": "9822de602626ef19a8298936b42cb7463de8137e", "filename": "third_party/blink/renderer/core/html/html_style_element.cc", "status": "modified", "additions": 8, "deletions": 8, "changes": 16, "blob_url": "https://github.com/chromium/chromium/blob/2bf635c28effa427a270f4fc45df84ed344f411c/third_party/blink/renderer/core/html/html_style_element.cc", "raw_url": "https://github.com/chromium/chromium/raw/2bf635c28effa427a270f4fc45df84ed344f411c/third_party/blink/renderer/core/html/html_style_element.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/core/html/html_style_element.cc?ref=2bf635c28effa427a270f4fc45df84ed344f411c", "patch": "@@ -77,21 +77,21 @@ void HTMLStyleElement::FinishParsingChildren() {
