+
+class CSSPaintValueTest : public RenderingTest {
+ public:
+  void LoadTestData(const std::string& file_name) {
+    String testing_path = test::BlinkRootDir();
+    testing_path.append("/renderer/core/css/test_data/");
+    WebURL url = URLTestHelpers::RegisterMockedURLLoadFromBase(
+        WebString::FromUTF8(base_url_), testing_path,
+        WebString::FromUTF8(file_name));
+    FrameTestHelpers::LoadFrame(helper_.GetWebView()->MainFrameImpl(),
+                                base_url_ + file_name);
+    ForceFullCompositingUpdate();
+    URLTestHelpers::RegisterMockedURLUnregister(url);
+  }
+
+  void ForceFullCompositingUpdate() {
+    helper_.GetWebView()->UpdateAllLifecyclePhases();
+  }
+
+  LocalFrame* GetFrame() const { return helper_.LocalMainFrame()->GetFrame(); }
+
+ private:
+  void SetUp() override {
+    RenderingTest::SetUp();
+    EnableCompositing();
+    helper_.Initialize(nullptr, nullptr, nullptr);
+    base_url_ = "https://www.test.com/";
+  }
+  FrameTestHelpers::WebViewHelper helper_;
+  std::string base_url_;
+};
+
+void CheckTargetObject(Document* document) {
+  LayoutObject* target_layout_object =
+      document->getElementById("target")->GetLayoutObject();
+  EXPECT_NE(target_layout_object, nullptr);
+  EXPECT_NE(target_layout_object->Style()->InsideLink(),
+            EInsideLink::kNotInsideLink);
+
+  CSSPaintValue* css_paint_value =
+      CSSPaintValue::Create(CSSCustomIdentValue::Create("linkpainter"));
+  EXPECT_EQ(css_paint_value->GetImage(*target_layout_object, *document,
+                                      target_layout_object->StyleRef(),
+                                      FloatSize(100.0f, 100.0f)),
+            nullptr);
+}
+
+// Regression test for https://crbug.com/835589.
+TEST_F(CSSPaintValueTest, CSSPaintDoNotPaintForLink) {
+  LoadTestData("csspaint-do-not-paint-for-link.html");
+  Document* document = GetFrame()->GetDocument();
+  CheckTargetObject(document);
+}
+
+// Regression test for https://crbug.com/835589.
+TEST_F(CSSPaintValueTest, CSSPaintDoNotPaintWhenParentHasLink) {
+  LoadTestData("csspaint-do-not-paint-for-link-descendant.html");
+  Document* document = GetFrame()->GetDocument();
+  CheckTargetObject(document);
+}
+
+}  // namespace blink"}<_**next**_>{"sha": "958ea8f4638e44921cd610c92504606b661c78d0", "filename": "third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link-descendant.html", "status": "added", "additions": 39, "deletions": 0, "changes": 39, "blob_url": "https://github.com/chromium/chromium/blob/67d9b414fa64448abc398ae9fc57c3ddf5de5998/third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link-descendant.html", "raw_url": "https://github.com/chromium/chromium/raw/67d9b414fa64448abc398ae9fc57c3ddf5de5998/third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link-descendant.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link-descendant.html?ref=67d9b414fa64448abc398ae9fc57c3ddf5de5998", "patch": "@@ -0,0 +1,39 @@
+<!DOCTYPE html>
+<html>
+<head>
+<style>
+a {
+  width: 200px;
+  height: 200px;
+}
+b {
+  background-image: paint(linkpainter);
+  width: 100px;
+  height: 100px;
+}
+</style>
+</head>
+<body>
+  <a id="ancestor">
+    <b id="target"></b>
+  </a>
+<script>
+function addPaintletFromSource (src) {
+  var uri = 'data:application/javascript;charset=utf-8;base64,' + btoa(src);
+  CSS.paintWorklet.addModule(uri).then();
+}
+
+addPaintletFromSource(`
+  class LinkPainter {
+    paint(ctx, geom) {
+      ctx.fillStyle = 'black';
+      ctx.fillRect(0, 0, geom.width, geom.height);
+    }
+  }
+  registerPaint('linkpainter', LinkPainter);
+`);
+
+ancestor.href = 'https://cs.chromium.org';
+</script>
+</body>
+</html>"}<_**next**_>{"sha": "1d78b530ef889768c3cd7b24e92a337f7ab8e201", "filename": "third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link.html", "status": "added", "additions": 33, "deletions": 0, "changes": 33, "blob_url": "https://github.com/chromium/chromium/blob/67d9b414fa64448abc398ae9fc57c3ddf5de5998/third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link.html", "raw_url": "https://github.com/chromium/chromium/raw/67d9b414fa64448abc398ae9fc57c3ddf5de5998/third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/renderer/core/css/test_data/csspaint-do-not-paint-for-link.html?ref=67d9b414fa64448abc398ae9fc57c3ddf5de5998", "patch": "@@ -0,0 +1,33 @@
