+// Copyright 2018 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#ifndef UI_BASE_COCOA_SECURE_PASSWORD_INPUT_H_
+#define UI_BASE_COCOA_SECURE_PASSWORD_INPUT_H_
+
+#include "base/macros.h"
+#include "ui/base/ui_base_export.h"
+
+namespace ui {
+
+// Enables the secure password input mode while in scope.
+class UI_BASE_EXPORT ScopedPasswordInputEnabler {
+ public:
+  ScopedPasswordInputEnabler();
+  ~ScopedPasswordInputEnabler();
+
+  // Returns true if the password input mode is currently enabled. Useful for
+  // unit tests.
+  static bool IsPasswordInputEnabled();
+
+ private:
+  DISALLOW_COPY_AND_ASSIGN(ScopedPasswordInputEnabler);
+};
+
+}  // namespace ui
+
+#endif  // UI_BASE_COCOA_SECURE_PASSWORD_INPUT_H_"}<_**next**_>{"sha": "d0345336d4c13f89693329d447d76ad5c70e412a", "filename": "ui/base/cocoa/secure_password_input.mm", "status": "added", "additions": 63, "deletions": 0, "changes": 63, "blob_url": "https://github.com/chromium/chromium/blob/f1574f25e1402e748bf2bd7e28ce3dd96ceb1ca4/ui/base/cocoa/secure_password_input.mm", "raw_url": "https://github.com/chromium/chromium/raw/f1574f25e1402e748bf2bd7e28ce3dd96ceb1ca4/ui/base/cocoa/secure_password_input.mm", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ui/base/cocoa/secure_password_input.mm?ref=f1574f25e1402e748bf2bd7e28ce3dd96ceb1ca4", "patch": "@@ -0,0 +1,63 @@
+// Copyright 2018 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+#import "ui/base/cocoa/secure_password_input.h"
+
+#import <Carbon/Carbon.h>
+
+#include "base/logging.h"
+
+namespace {
+
+// Used to protect from out-of-order calls to enabling/disabling functions.
+int g_password_input_counter = 0;
+
+// SetPasswordInputEnabled() is copied from
+// enableSecureTextInput() and disableSecureTextInput() functions in
+// third_party/WebKit/WebCore/platform/SecureTextInput.cpp
+//
+// The following technote describes proper EnableSecureEventInput() usage:
+// https://developer.apple.com/library/content/technotes/tn2150/_index.html
+void SetPasswordInputEnabled(bool enabled) {
+  if (enabled) {
+    DCHECK(!IsSecureEventInputEnabled());
+    EnableSecureEventInput();
+
+    CFArrayRef inputSources = TISCreateASCIICapableInputSourceList();
+    TSMSetDocumentProperty(0, kTSMDocumentEnabledInputSourcesPropertyTag,
+                           sizeof(CFArrayRef), &inputSources);
+    CFRelease(inputSources);
+  } else {
+    DCHECK(IsSecureEventInputEnabled());
+    TSMRemoveDocumentProperty(0, kTSMDocumentEnabledInputSourcesPropertyTag);
+
+    DisableSecureEventInput();
+  }
+}
+
+}  // namespace
+
+namespace ui {
+
+ScopedPasswordInputEnabler::ScopedPasswordInputEnabler() {
+  if (!g_password_input_counter) {
+    SetPasswordInputEnabled(true);
+  }
+  ++g_password_input_counter;
+}
+
+ScopedPasswordInputEnabler::~ScopedPasswordInputEnabler() {
+  --g_password_input_counter;
+  DCHECK_LE(0, g_password_input_counter);
+  if (!g_password_input_counter) {
+    SetPasswordInputEnabled(false);
+  }
+}
+
+// static
+bool ScopedPasswordInputEnabler::IsPasswordInputEnabled() {
+  return g_password_input_counter > 0;
+}
+
+}  // namespace ui"}<_**next**_>{"sha": "cff3298c4c683c77234a0586a31a92116d74f502", "filename": "ui/views/controls/textfield/textfield.cc", "status": "modified", "additions": 13, "deletions": 0, "changes": 13, "blob_url": "https://github.com/chromium/chromium/blob/f1574f25e1402e748bf2bd7e28ce3dd96ceb1ca4/ui/views/controls/textfield/textfield.cc", "raw_url": "https://github.com/chromium/chromium/raw/f1574f25e1402e748bf2bd7e28ce3dd96ceb1ca4/ui/views/controls/textfield/textfield.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/ui/views/controls/textfield/textfield.cc?ref=f1574f25e1402e748bf2bd7e28ce3dd96ceb1ca4", "patch": "@@ -75,6 +75,10 @@
