+
+// Creates a new div element with specified inline style |cssText|.
+// The created element is deleted during test cleanup.
+function createDivWithStyle(test, cssText) {
+  let element = document.createElement('div');
+  element.style = cssText || '';
+  document.body.appendChild(element);
+  test.add_cleanup(() => {
+    element.remove();
+  });
+  return element;
+}
+
+// Creates a new div element with inline style |cssText| and returns
+// its inline style property map.
+function createInlineStyleMap(test, cssText) {
+  return createDivWithStyle(test, cssText).attributeStyleMap;
+}
+
+// Creates a new div element with inline style |cssText| and returns
+// its computed style property map.
+function createComputedStyleMap(test, cssText) {
+  return createDivWithStyle(test, cssText).computedStyleMap();
+}"}<_**next**_>{"sha": "3b3e4c0b79d9853725e6332938ea0d782d7c827b", "filename": "third_party/WebKit/LayoutTests/typedcssom/stylevalue-normalization/normalize-ident.html", "status": "modified", "additions": 3, "deletions": 2, "changes": 5, "blob_url": "https://github.com/chromium/chromium/blob/fbf25ea941bf9f15aa1558c9606d25ef87fd2cfe/third_party/WebKit/LayoutTests/typedcssom/stylevalue-normalization/normalize-ident.html", "raw_url": "https://github.com/chromium/chromium/raw/fbf25ea941bf9f15aa1558c9606d25ef87fd2cfe/third_party/WebKit/LayoutTests/typedcssom/stylevalue-normalization/normalize-ident.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/typedcssom/stylevalue-normalization/normalize-ident.html?ref=fbf25ea941bf9f15aa1558c9606d25ef87fd2cfe", "patch": "@@ -5,6 +5,7 @@
