{"sha": "387576f78c9594f291a0b3d98392fb7d0088d19d", "filename": "chrome/browser/extensions/extension_bindings_apitest.cc", "status": "modified", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/chromium/chromium/blob/75b803b1c81ed9fa5513cbff550232b4fb915e7b/chrome/browser/extensions/extension_bindings_apitest.cc", "raw_url": "https://github.com/chromium/chromium/raw/75b803b1c81ed9fa5513cbff550232b4fb915e7b/chrome/browser/extensions/extension_bindings_apitest.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/browser/extensions/extension_bindings_apitest.cc?ref=75b803b1c81ed9fa5513cbff550232b4fb915e7b", "patch": "@@ -183,5 +183,30 @@ IN_PROC_BROWSER_TEST_F(ExtensionBindingsApiTest, HandlerFunctionTypeChecking) {
