 }  // namespace
 }  // namespace extensions"}<_**next**_>{"sha": "07342ca5180c027f9527179fd8a407e1dabe5697", "filename": "chrome/test/data/extensions/api_test/bindings/function_interceptions.html", "status": "added", "additions": 56, "deletions": 0, "changes": 56, "blob_url": "https://github.com/chromium/chromium/blob/75b803b1c81ed9fa5513cbff550232b4fb915e7b/chrome/test/data/extensions/api_test/bindings/function_interceptions.html", "raw_url": "https://github.com/chromium/chromium/raw/75b803b1c81ed9fa5513cbff550232b4fb915e7b/chrome/test/data/extensions/api_test/bindings/function_interceptions.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/bindings/function_interceptions.html?ref=75b803b1c81ed9fa5513cbff550232b4fb915e7b", "patch": "@@ -0,0 +1,56 @@
+<body>
+<script>
+
+window.testStatus = '';
+var objects = ['runtime', 'require', 'test', 'binding'];
+var leaked = [];
+
+function intercept(objectKey) {
+  Object.defineProperty(Object.prototype, objectKey, {
+    get: function () {
+      leaked.push({name: objectKey, obj: this});
+    },
+    set: function (v) {
+      Object.defineProperty(this, objectKey, {
+        value: v,
+        configurable: true,
+        enumerable: true,
+        writable: true
+      });
+    },
+    configurable: true,
+  });
+}
+
+// Set up interceptors.
+for (let objectKey of objects)
+  intercept(objectKey);
+
+// Poke chrome.runtime and chrome.app.
+try {
+  chrome.runtime;
+} catch (e) {}
+try {
+  chrome.app;
+} catch (e) {}
+
+// Cleanup - we don't want to be triggering our own interceptors.
+for (let objKey of objects)
+  delete Object.prototype[objKey];
+
+// Check what we intercepted.
+var keysToCheck = ['utils', 'binding'];
+for (let nameAndObj of leaked) {
+  for (let key of keysToCheck) {
+    if (!!nameAndObj.obj[key]) {
+      window.testStatus +=
+          'Failed: Found ' + key + ' on ' + nameAndObj.name + '\n';
+    }
+  }
+}
+
+if (window.testStatus === '')
+  window.testStatus = 'success';
+
+</script>
+</body>"}<_**next**_>{"sha": "f02741324ae3fd361d4e0fde487b6673d78f182c", "filename": "extensions/renderer/module_system.cc", "status": "modified", "additions": 2, "deletions": 2, "changes": 4, "blob_url": "https://github.com/chromium/chromium/blob/75b803b1c81ed9fa5513cbff550232b4fb915e7b/extensions/renderer/module_system.cc", "raw_url": "https://github.com/chromium/chromium/raw/75b803b1c81ed9fa5513cbff550232b4fb915e7b/extensions/renderer/module_system.cc", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/extensions/renderer/module_system.cc?ref=75b803b1c81ed9fa5513cbff550232b4fb915e7b", "patch": "@@ -251,12 +251,12 @@ v8::Local<v8::Value> ModuleSystem::RequireForJsInner(

