+"}<_**next**_>{"sha": "ba630374160037b637e9a76b263334e867d7d960", "filename": "third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/service-worker-blocked.html", "status": "added", "additions": 15, "deletions": 0, "changes": 15, "blob_url": "https://github.com/chromium/chromium/blob/5289a5d4c98681e9a0f2d28da0c7aa35e282db57/third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/service-worker-blocked.html", "raw_url": "https://github.com/chromium/chromium/raw/5289a5d4c98681e9a0f2d28da0c7aa35e282db57/third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/service-worker-blocked.html", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/WebKit/LayoutTests/http/tests/security/contentSecurityPolicy/service-worker-blocked.html?ref=5289a5d4c98681e9a0f2d28da0c7aa35e282db57", "patch": "@@ -0,0 +1,15 @@
+<!DOCTYPE html>
